CREATE OR REPLACE FUNCTION "public"."accept_payment_document_extraction"("p_extraction_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_extraction public.payment_document_extractions%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_fingerprint text;
  v_company_bank_account_id uuid;
  v_company_bank_account_ids uuid[];
  v_operation_id uuid;
  v_event_id uuid;
  v_result jsonb;
  v_reviewed_at timestamptz;
begin
  select * into v_extraction
  from public.payment_document_extractions where id = p_extraction_id for update;
  if not found then raise exception 'payment_extraction_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_extraction.company_id);
  v_payload := jsonb_build_object(
    'expected_updated_at', p_expected_updated_at,
    'extraction_id', p_extraction_id,
    'operation', 'accept'
  );
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_extraction.company_id, 'payment_extraction.accept', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_extraction.updated_at is distinct from p_expected_updated_at then
    raise exception 'stale_payment_extraction';
  end if;
  if v_extraction.status <> 'review_required' then
    raise exception 'payment_extraction_not_reviewable';
  end if;
  if upper(btrim(v_extraction.bank_name)) <> 'BBVA'
     or lower(coalesce(v_extraction.bank_status, '')) <> 'operado'
     or v_extraction.application_date is null
     or v_extraction.amount_minor is null
     or v_extraction.currency is null
     or v_extraction.bank_unique_folio !~ '^[A-Z0-9-]{8,120}$'
     or v_extraction.source_account_hash is null then
    raise exception 'payment_extraction_not_conciliable';
  end if;
  perform 1
  from public.payment_ingestion_batches batch
  where batch.id = v_extraction.batch_id
    and batch.company_id = v_extraction.company_id
  for update;
  if not found then raise exception 'payment_batch_scope_mismatch'; end if;
  select coalesce(array_agg(matched.id order by matched.id), '{}'::uuid[])
    into v_company_bank_account_ids
  from (
    select account.id
    from public.company_bank_accounts account
    where account.company_id = v_extraction.company_id
      and coalesce(account.active, true)
      and public.payment_reconciliation_normalize_bank_name(account.bank_name) = 'BBVA'
      and case upper(btrim(account.currency)) when 'MXP' then 'MXN'
            else upper(btrim(account.currency)) end = v_extraction.currency
      and v_extraction.source_account_hash in (
        public.payment_reconciliation_account_hash(account.account_number),
        public.payment_reconciliation_account_hash(account.clabe)
      )
    order by account.id
    for share
  ) matched;
  if cardinality(v_company_bank_account_ids) = 0 then
    raise exception 'bank_payment_operation_company_account_mismatch';
  end if;
  if cardinality(v_company_bank_account_ids) <> 1 then
    raise exception 'bank_payment_operation_company_account_ambiguous';
  end if;
  v_company_bank_account_id := v_company_bank_account_ids[1];
  perform pg_advisory_xact_lock(hashtextextended(
    'bbva_folio:' || v_extraction.company_id::text || ':' || v_extraction.bank_unique_folio,
    32032
  ));
  v_fingerprint := public.payment_operation_fingerprint_v1(
    v_extraction.company_id, v_extraction.bank_name, v_extraction.bank_unique_folio,
    v_extraction.application_date, v_extraction.amount_minor, v_extraction.currency,
    v_extraction.source_account_hash, v_extraction.destination_account_hash
  );
  if exists (
    select 1 from public.bank_payment_operations operation
    where operation.company_id = v_extraction.company_id
      and operation.bank_unique_folio = v_extraction.bank_unique_folio
  ) then
    raise exception 'bank_payment_operation_folio_duplicate';
  end if;
  if exists (
    select 1 from public.bank_payment_operations operation
    where operation.operation_fingerprint = v_fingerprint
  ) then
    raise exception 'bank_payment_operation_duplicate';
  end if;
  v_reviewed_at := clock_timestamp();

  insert into public.bank_payment_operations(
    company_id, source_company_bank_account_id, extraction_id, bank_name,
    operation_fingerprint,
    bank_unique_folio, application_date, amount_minor, currency,
    source_account_hash, source_account_last4, destination_account_hash,
    destination_account_last4, beneficiary_name, payment_reason, reviewed_by,
    reviewed_at
  ) values (
    v_extraction.company_id, v_company_bank_account_id, v_extraction.id,
    v_extraction.bank_name, v_fingerprint,
    v_extraction.bank_unique_folio, v_extraction.application_date,
    v_extraction.amount_minor, v_extraction.currency, v_extraction.source_account_hash,
    v_extraction.source_account_last4, v_extraction.destination_account_hash,
    v_extraction.destination_account_last4, v_extraction.beneficiary_name,
    v_extraction.payment_reason, v_actor, v_reviewed_at
  ) returning id into v_operation_id;
  insert into public.payment_operation_documents(operation_id, document_id, page_number)
  values (v_operation_id, v_extraction.document_id, v_extraction.page_number);
  update public.payment_document_extractions
  set status = 'accepted', reviewed_by = v_actor, reviewed_at = v_reviewed_at,
      rejection_reason = null
  where id = v_extraction.id;
  update public.payment_ingestion_batches batch
  set operation_count = (
        select count(*) from public.bank_payment_operations operation
        join public.payment_document_extractions extraction on extraction.id = operation.extraction_id
        where extraction.batch_id = batch.id
      ),
      status = case when not exists (
        select 1 from public.payment_document_extractions pending
        where pending.batch_id = batch.id and pending.status in ('review_required', 'blocked')
      ) then 'ready' else 'review_required' end
  where batch.id = v_extraction.batch_id;
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_operation.ingested', 'bank_payment_operation', v_operation_id,
    v_extraction.company_id, v_actor,
    jsonb_build_object(
      'amount_minor', v_extraction.amount_minor,
      'application_date', v_extraction.application_date,
      'currency', v_extraction.currency,
      'destination_account_last4', v_extraction.destination_account_last4,
      'operation_id', v_operation_id
    ), v_extraction.batch_id, null
  );
  v_result := jsonb_build_object(
    'event_id', v_event_id,
    'extraction_id', v_extraction.id,
    'operation_id', v_operation_id,
    'status', 'accepted'
  );
  return public.payment_reconciliation_store_command(
    v_extraction.company_id, 'payment_extraction.accept', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$_$;


ALTER FUNCTION "public"."accept_payment_document_extraction"("p_extraction_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_extraordinary_authorization"("p_authorization_id" "uuid", "p_evidence_type" "text", "p_evidence_sha256" "text", "p_evidence_mime_type" "text", "p_evidence_size_bytes" bigint, "p_evidence_matches_request" boolean, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_request public.payment_requests%rowtype;
  v_policy public.extraordinary_payment_policies%rowtype;
  v_any_evidence boolean;
  v_all_evidence boolean;
  v_now timestamptz := clock_timestamp();
begin
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id
  for update;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;

  perform public.extraordinary_require_finance_for_company(
    v_authorization.company_id
  );
  if v_authorization.authorized_by <> v_actor then
    raise exception 'extraordinary_draft_owner_required';
  end if;

  v_any_evidence :=
    p_evidence_type is not null
    or p_evidence_sha256 is not null
    or p_evidence_mime_type is not null
    or p_evidence_size_bytes is not null
    or coalesce(p_evidence_matches_request, false);
  v_all_evidence :=
    nullif(btrim(coalesce(p_evidence_type, '')), '') is not null
    and nullif(btrim(coalesce(p_evidence_sha256, '')), '') is not null
    and nullif(btrim(coalesce(p_evidence_mime_type, '')), '') is not null
    and p_evidence_size_bytes is not null
    and coalesce(p_evidence_matches_request, false);

  if v_any_evidence and not v_all_evidence then
    raise exception 'optional_evidence_must_be_complete_when_present';
  end if;

  if v_all_evidence then
    return public.finalize_extraordinary_authorization(
      p_authorization_id,
      p_evidence_type,
      p_evidence_sha256,
      p_evidence_mime_type,
      p_evidence_size_bytes,
      p_evidence_matches_request,
      p_idempotency_key
    );
  end if;

  if v_authorization.status = 'active' then
    return jsonb_build_object(
      'authorization_id', v_authorization.id,
      'status', 'active',
      'evidence_optional', true,
      'idempotent_replay', true
    );
  end if;
  if v_authorization.status <> 'draft' then
    raise exception 'extraordinary_authorization_not_draft';
  end if;
  if nullif(btrim(coalesce(v_authorization.authorization_medium, '')), '') is null
     or nullif(btrim(coalesce(v_authorization.authorization_reference, '')), '') is null
     or not v_authorization.director_absence_confirmed
     or not v_authorization.cannot_wait_confirmed then
    raise exception 'extraordinary_governance_fields_incomplete';
  end if;

  select * into v_request
  from public.payment_requests
  where id = v_authorization.payment_request_id
  for update;
  select * into v_policy
  from public.extraordinary_payment_policies
  where company_id = v_authorization.company_id
  for share;

  if not found or not v_policy.enabled then
    raise exception 'extraordinary_policy_disabled';
  end if;
  if v_now >= v_authorization.valid_until
     or v_authorization.external_authorized_at <
       v_request.approval_material_updated_at then
    raise exception 'extraordinary_authorization_expired_or_stale';
  end if;
  if not public.extraordinary_profile_is_company_director(
    v_authorization.external_director_profile_id,
    v_authorization.company_id
  ) then
    raise exception 'external_director_not_active_for_company';
  end if;
  if v_request.currency <> 'MXN'
     or (
       v_policy.max_amount_mxn is not null
       and v_request.amount_requested > v_policy.max_amount_mxn
     )
     or v_authorization.category <> all(v_policy.allowed_categories) then
    raise exception 'extraordinary_policy_no_longer_matches';
  end if;
  if coalesce(
    public.approval_batch_budget_validation(v_request.id)->>'status',
    'bloqueado'
  ) <> 'aprobable' then
    raise exception 'budget_revalidation_required';
  end if;
  if public.approval_batch_request_has_any_execution_record(v_request.id)
     or exists (
       select 1 from public.payment_request_receipt_links link
       where link.payment_request_id = v_request.id
     ) then
    raise exception 'payment_request_already_executed';
  end if;

  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set status = 'active',
      updated_at = v_now
  where id = v_authorization.id
    and status = 'draft';
  if not found then raise exception 'extraordinary_authorization_changed'; end if;

  perform public.extraordinary_append_event(
    v_authorization.id,
    'authorization_activated',
    v_actor,
    'authorization-activated:' || v_authorization.id::text || ':' ||
      coalesce(nullif(btrim(p_idempotency_key), ''), 'without-evidence'),
    jsonb_build_object(
      'valid_until', v_authorization.valid_until,
      'evidence_optional', true,
      'evidence_present', false
    )
  );

  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'status', 'active',
    'valid_until', v_authorization.valid_until,
    'evidence_optional', true,
    'idempotent_replay', false
  );
end
$$;


ALTER FUNCTION "public"."activate_extraordinary_authorization"("p_authorization_id" "uuid", "p_evidence_type" "text", "p_evidence_sha256" "text", "p_evidence_mime_type" "text", "p_evidence_size_bytes" bigint, "p_evidence_matches_request" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_approver_assignment"("p_company_id" "uuid", "p_requester_id" "uuid", "p_approver_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;
  if p_requester_id = p_approver_id then
    raise exception 'requester_cannot_be_own_pool_approver';
  end if;
  if not public.has_active_company_membership(p_requester_id, p_company_id) then
    raise exception 'requester_company_membership_required';
  end if;
  if not public.has_active_company_membership(p_approver_id, p_company_id) then
    raise exception 'approver_company_membership_required';
  end if;
  if not exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = p_approver_id
      and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
  ) then
    raise exception 'approver_role_required';
  end if;

  insert into public.approver_assignments (
    company_id, requester_id, approver_id, active, created_by, updated_at
  ) values (
    p_company_id, p_requester_id, p_approver_id, true,
    public.current_profile_id(), now()
  )
  on conflict (company_id, requester_id, approver_id)
  do update set active = true, updated_at = now()
  where not approver_assignments.active
  returning id into v_id;

  if v_id is null then
    raise exception 'approver_already_configured';
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."add_approver_assignment"("p_company_id" "uuid", "p_requester_id" "uuid", "p_approver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_company_director_for_future_batches"("p_company_id" "uuid", "p_director_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_assignment_id uuid;
  v_changed boolean := false;
  v_now timestamptz := clock_timestamp();
begin
  if p_company_id is null or p_director_profile_id is null then
    raise exception 'company_and_director_required';
  end if;

  v_actor := public.approval_batch_require_finance();
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 21034));

  perform 1
  from public.companies company
  where company.id = p_company_id
    and coalesce(company.active, false)
  for update;

  if not found then
    raise exception 'company_not_found_or_inactive';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = p_director_profile_id
      and profile.active
  ) then
    raise exception 'director_profile_not_found_or_inactive';
  end if;

  if not exists (
    select 1
    from public.user_roles user_role
    join public.roles role on role.id = user_role.role_id
    where user_role.profile_id = p_director_profile_id
      and lower(btrim(role.name)) =
        any(public.approval_batch_direction_roles())
  ) then
    raise exception 'director_role_required';
  end if;

  if not exists (
    select 1
    from public.profile_company_memberships membership
    where membership.profile_id = p_director_profile_id
      and membership.company_id = p_company_id
      and membership.active
  ) then
    raise exception 'director_company_membership_required';
  end if;

  perform 1
  from public.company_directors director_assignment
  where director_assignment.company_id = p_company_id
  order by director_assignment.id
  for update;

  select director_assignment.id
    into v_assignment_id
  from public.company_directors director_assignment
  where director_assignment.company_id = p_company_id
    and director_assignment.director_profile_id = p_director_profile_id
  order by
    director_assignment.active desc,
    director_assignment.created_at desc,
    director_assignment.id desc
  limit 1
  for update;

  if v_assignment_id is null then
    insert into public.company_directors(
      company_id,
      director_profile_id,
      active,
      created_by,
      created_at,
      updated_at
    ) values (
      p_company_id,
      p_director_profile_id,
      true,
      v_actor,
      v_now,
      v_now
    )
    returning id into v_assignment_id;
    v_changed := true;
  else
    update public.company_directors director_assignment
    set active = true,
        updated_at = v_now
    where director_assignment.id = v_assignment_id
      and not director_assignment.active;
    v_changed := found;
  end if;

  if v_changed then
    insert into public.activity_log(
      entity_type,
      entity_id,
      action,
      old_values,
      new_values,
      performed_by,
      performed_at,
      notes
    ) values (
      'company',
      p_company_id,
      'future_batch_director_added',
      jsonb_build_object('active', false),
      jsonb_build_object(
        'director_profile_id', p_director_profile_id,
        'active', true
      ),
      v_actor,
      v_now,
      'Future-batch pool changed; existing and historical batch Director snapshots are unchanged.'
    );
  end if;

  return jsonb_build_object(
    'company_id', p_company_id,
    'director_assignment_id', v_assignment_id,
    'director_profile_id', p_director_profile_id,
    'active', true,
    'changed', v_changed,
    'changed_at', case when v_changed then v_now else null end
  );
end
$$;


