COMMENT ON FUNCTION "public"."add_company_director_for_future_batches"("p_company_id" "uuid", "p_director_profile_id" "uuid") IS 'Adds or reactivates one eligible Director in the future-batch pool without replacing any other Director or modifying batches.';



CREATE OR REPLACE FUNCTION "public"."add_provider_intake_note"("p_payment_intake_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_notes" "text", "p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor jsonb;
  v_actor_profile_id uuid;
  v_actor_type text;
  v_intake public.payment_intake%rowtype;
  v_notes text;
  v_action_fingerprint text;
  v_event_id uuid;
  v_existing_event record;
begin
  if p_payment_intake_id is null
     or p_expected_updated_at is null
     or p_action_id is null then
    raise exception 'provider_intake_note_fields_required';
  end if;

  v_actor := public.provider_intake_actor_context();
  v_actor_profile_id := (v_actor ->> 'profile_id')::uuid;
  v_actor_type := v_actor ->> 'actor_type';
  v_notes := nullif(btrim(coalesce(p_notes, '')), '');

  if v_notes is null or length(v_notes) < 3 or length(v_notes) > 2000 then
    raise exception 'provider_intake_note_length';
  end if;
  if v_notes ~ '[[:cntrl:]]' or v_notes ~ '<[^>]*>' then
    raise exception 'provider_intake_note_invalid';
  end if;

  v_action_fingerprint := public.provider_intake_action_fingerprint(
    2,
    'internal_note',
    p_payment_intake_id,
    v_actor_profile_id,
    null,
    p_expected_updated_at,
    null,
    v_notes
  );

  select *
    into v_intake
  from public.payment_intake
  where id = p_payment_intake_id
  for share;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  select
    pie.id,
    pie.actor_profile_id,
    pie.metadata ->> 'action_fingerprint' as action_fingerprint,
    pie.metadata ->> 'action_kind' as action_kind,
    pie.metadata ->> 'contract_version' as contract_version
    into v_existing_event
  from public.payment_intake_events pie
  where pie.payment_intake_id = p_payment_intake_id
    and pie.metadata ->> 'action_id' = p_action_id::text
  limit 1;

  if found then
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from 'internal_note'
       or v_existing_event.contract_version is distinct from '2'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;
    return jsonb_build_object(
      'payment_intake_id', v_intake.id,
      'event_id', v_existing_event.id,
      'idempotent', true
    );
  end if;

  if v_intake.updated_at is distinct from p_expected_updated_at then
    raise exception 'provider_intake_conflict';
  end if;

  insert into public.payment_intake_events (
    payment_intake_id,
    event_type,
    actor_profile_id,
    actor_type,
    from_status,
    to_status,
    notes,
    metadata
  ) values (
    v_intake.id,
    'internal_note',
    v_actor_profile_id,
    v_actor_type,
    v_intake.status,
    v_intake.status,
    v_notes,
    jsonb_build_object(
      'action_id', p_action_id,
      'action_fingerprint', v_action_fingerprint,
      'action_kind', 'internal_note',
      'contract_version', 2
    )
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'payment_intake_id', v_intake.id,
    'event_id', v_event_id,
    'idempotent', false
  );
exception
  when unique_violation then
    select
      pie.id,
      pie.actor_profile_id,
      pie.metadata ->> 'action_fingerprint' as action_fingerprint,
      pie.metadata ->> 'action_kind' as action_kind,
      pie.metadata ->> 'contract_version' as contract_version
      into v_existing_event
    from public.payment_intake_events pie
    where pie.payment_intake_id = p_payment_intake_id
      and pie.metadata ->> 'action_id' = p_action_id::text
    limit 1;

    if not found then
      raise;
    end if;
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from 'internal_note'
       or v_existing_event.contract_version is distinct from '2'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;

    return jsonb_build_object(
      'payment_intake_id', p_payment_intake_id,
      'event_id', v_existing_event.id,
      'idempotent', true
    );
end
$$;


ALTER FUNCTION "public"."add_provider_intake_note"("p_payment_intake_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_notes" "text", "p_action_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_provider_intake_note"("p_payment_intake_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_notes" "text", "p_action_id" "uuid") IS 'Append-only internal note with contract-v2 material idempotency; it never edits submitted payload or status.';



CREATE OR REPLACE FUNCTION "public"."add_request_to_approval_batch"("p_batch_id" "uuid", "p_payment_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_eligibility jsonb;
  v_previous record;
  v_review_sequence integer;
  v_item_id uuid;
  v_resubmission_note text;
begin
  v_actor := public.approval_batch_require_finance();
  select * into v_batch
  from public.approval_batches
  where id = p_batch_id
  for update;
  if not found then raise exception 'batch_not_found'; end if;
  if v_batch.status <> 'draft' then raise exception 'batch_must_be_draft'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_payment_request_id::text, 21021));
  v_eligibility := public.approval_batch_request_eligibility(p_payment_request_id, null);
  if not coalesce((v_eligibility ->> 'eligible')::boolean, false) then
    raise exception 'payment_request_not_batch_eligible:%', coalesce(v_eligibility ->> 'classification', 'unknown');
  end if;
  if not exists (
    select 1 from public.payment_requests pr
    where pr.id = p_payment_request_id and pr.company_id = v_batch.company_id
  ) then
    raise exception 'batch_request_company_mismatch';
  end if;

  select abi.id, abi.review_sequence, abi.director_status,
         abi.rebatch_status, abi.rebatch_release_note
    into v_previous
  from public.approval_batch_items abi
  where abi.payment_request_id = p_payment_request_id
    and abi.removed_at is null
  order by abi.review_sequence desc, abi.created_at desc, abi.id desc
  limit 1;

  select coalesce(max(abi.review_sequence), 0) + 1
    into v_review_sequence
  from public.approval_batch_items abi
  where abi.payment_request_id = p_payment_request_id
    and abi.removed_at is null;

  v_resubmission_note := case
    when v_previous.id is null then null
    when nullif(btrim(v_previous.rebatch_release_note), '') is not null
      then v_previous.rebatch_release_note
    else 'Nueva revision requerida por cambio material posterior a la decision anterior.'
  end;

  insert into public.approval_batch_items(
    batch_id,
    payment_request_id,
    finance_reviewed_by,
    finance_reviewed_at,
    previous_item_id,
    review_sequence,
    resubmitted_at,
    resubmitted_by,
    resubmission_note
  ) values (
    p_batch_id,
    p_payment_request_id,
    v_actor,
    now(),
    v_previous.id,
    v_review_sequence,
    case when v_previous.id is null then null else now() end,
    case when v_previous.id is null then null else v_actor end,
    v_resubmission_note
  )
  returning id into v_item_id;

  return jsonb_build_object(
    'item_id', v_item_id,
    'status', 'pending',
    'review_sequence', v_review_sequence,
    'previous_item_id', v_previous.id,
    'origin', v_eligibility ->> 'origin'
  );
end
$$;


ALTER FUNCTION "public"."add_request_to_approval_batch"("p_batch_id" "uuid", "p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_extraordinary_ratification_cut"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorization record;
begin
  if new.status <> 'closed'
     or old.status = 'closed'
     or new.closed_at is null then
    return new;
  end if;

  perform set_config('app.extraordinary_internal', 'on', true);
  for v_authorization in
    update public.payment_request_extraordinary_authorizations extraordinary_auth
    set ratification_cut_count = extraordinary_auth.ratification_cut_count + 1,
        ratification_first_cut_id = coalesce(
          extraordinary_auth.ratification_first_cut_id,
          new.id
        ),
        ratification_last_cut_id = new.id,
        ratification_overdue_at = case
          when extraordinary_auth.ratification_cut_count + 1 >= 2
            then coalesce(
              extraordinary_auth.ratification_overdue_at,
              new.closed_at
            )
          else extraordinary_auth.ratification_overdue_at
        end,
        updated_at = clock_timestamp()
    where extraordinary_auth.company_id = new.company_id
      and extraordinary_auth.status = 'consumed_pending_ratification'
      and extraordinary_auth.consumed_at < new.closed_at
      and extraordinary_auth.ratification_last_cut_id is distinct from new.id
    returning extraordinary_auth.id,
              extraordinary_auth.ratification_cut_count,
              extraordinary_auth.ratification_overdue_at
  loop
    if v_authorization.ratification_cut_count = 2 then
      perform public.extraordinary_append_event(
        v_authorization.id,
        'ratification_overdue',
        null,
        'ratification-overdue:' || v_authorization.id::text,
        jsonb_build_object(
          'actual_company_cuts_elapsed', 2,
          'cut_id', new.id
        )
      );
    end if;
  end loop;
  return new;
end
$$;


ALTER FUNCTION "public"."advance_extraordinary_ratification_cut"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."append_financial_outbox_event_internal"("p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_company_id" "uuid", "p_actor_profile_id" "uuid", "p_payload" "jsonb", "p_correlation_id" "uuid" DEFAULT NULL::"uuid", "p_causation_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_idempotency_key text := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    p_event_type || ':' || p_aggregate_id::text
  );
begin
  if char_length(v_idempotency_key) not between 8 and 200 then
    raise exception 'invalid_outbox_idempotency_key';
  end if;
  if p_payload::text ~* '(account|cuenta|clabe)[^,}]*[0-9]{5,}' then
    raise exception 'outbox_payload_contains_unmasked_bank_data';
  end if;
  insert into public.financial_outbox_events(
    event_type, event_version, aggregate_type, aggregate_id, company_id,
    actor_profile_id, correlation_id, causation_id, idempotency_key, payload,
    occurred_at
  ) values (
    p_event_type, 1, p_aggregate_type, p_aggregate_id, p_company_id,
    p_actor_profile_id, p_correlation_id, p_causation_id, v_idempotency_key,
    p_payload, clock_timestamp()
  ) returning id into v_id;
  return v_id;
end
$$;


