CREATE OR REPLACE FUNCTION "public"."approval_batch_payment_layout_candidates"("p_period_start" "date", "p_period_end" "date", "p_company_id" "uuid" DEFAULT NULL::"uuid", "p_company_bank_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("classification" "text", "classification_reason" "text", "payment_request_id" "uuid", "request_number" "text", "request_status" "text", "company_id" "uuid", "company_name" "text", "proveedor_id" "uuid", "provider_name" "text", "company_bank_account_id" "uuid", "source_account_number" "text", "destination_type" "text", "destination_value" "text", "beneficiary_name" "text", "amount" numeric, "currency" "text", "payment_reference" "text", "payment_concept" "text", "scheduled_payment_date" "date", "missing_fields" "text"[], "finance_approval_current" boolean, "direction_approval_current" boolean, "direction_decided_at" timestamp with time zone, "enforcement_required" boolean, "source_item_id" "uuid", "source_batch_id" "uuid", "source_batch_label" "text", "source_batch_status" "text", "director_status" "text", "reject_reason" "text", "rejected_by" "uuid", "rejected_by_name" "text", "rejected_at" timestamp with time zone, "rebatch_status" "text", "latest_correction_note" "text", "extraordinary_authorization_id" "uuid", "extraordinary_category" "text", "extraordinary_reason" "text", "extraordinary_authorized_by" "uuid", "extraordinary_authorized_by_name" "text", "extraordinary_authorized_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
