CREATE OR REPLACE FUNCTION "public"."approval_batch_request_base_eligible"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (public.approval_batch_request_eligibility(p_payment_request_id, null) ->> 'eligible')::boolean,
    false
  );
$$;


ALTER FUNCTION "public"."approval_batch_request_base_eligible"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_eligibility"("p_payment_request_id" "uuid", "p_exclude_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_latest record;
  v_budget jsonb;
  v_missing text[] := array[]::text[];
  v_classification text;
  v_reason text;
  v_origin text := 'new';
  v_review_sequence integer := 1;
  v_eligible boolean := false;
  v_payment_method text;
begin
  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id;
  if not found then
    return jsonb_build_object(
      'eligible', false,
      'classification', 'invalid_data',
      'reason', 'payment_request_not_found'
    );
  end if;

  select
    abi.id,
    abi.batch_id,
    ab.label as batch_label,
    ab.status as batch_status,
    abi.director_status,
    abi.director_reject_reason,
    abi.rebatch_status,
    abi.rebatch_release_note,
    abi.decided_at,
    abi.decided_by,
    abi.review_sequence
  into v_latest
  from public.approval_batch_items abi
  join public.approval_batches ab on ab.id = abi.batch_id
  where abi.payment_request_id = v_request.id
    and abi.removed_at is null
    and (p_exclude_batch_id is null or abi.batch_id <> p_exclude_batch_id)
  order by abi.review_sequence desc, abi.created_at desc, abi.id desc
  limit 1;

  if v_latest.id is not null then
    v_review_sequence := coalesce(v_latest.review_sequence, 1) + 1;
    if v_latest.director_status = 'rejected' and v_latest.rebatch_status = 'released' then
      v_origin := 'resubmission';
    elsif v_latest.director_status = 'approved'
          and coalesce(v_latest.decided_at < v_request.approval_material_updated_at, true) then
      v_origin := 'material_change_review';
    end if;
  end if;

  v_payment_method := coalesce(
    nullif(v_request.payment_method, ''),
    case when v_request.request_type::text in ('cash', 'check') then v_request.request_type::text else 'transfer' end
  );

  if v_request.company_id is null then v_missing := array_append(v_missing, 'company_id'); end if;
  if v_request.requested_by is null then v_missing := array_append(v_missing, 'requested_by'); end if;
  if v_request.proveedor_id is null and v_payment_method = 'transfer' then v_missing := array_append(v_missing, 'proveedor_id'); end if;
  if v_request.cost_center_id is null then v_missing := array_append(v_missing, 'cost_center_id'); end if;
  if v_request.budget_category_id is null then v_missing := array_append(v_missing, 'budget_category_id'); end if;
  if v_request.budget_month is null then v_missing := array_append(v_missing, 'budget_month'); end if;
  if coalesce(v_request.amount_requested, 0) <= 0 then v_missing := array_append(v_missing, 'amount_requested'); end if;
  if nullif(btrim(v_request.currency), '') is null then v_missing := array_append(v_missing, 'currency'); end if;

  if public.approval_batch_request_has_any_execution_record(v_request.id) then
    v_classification := 'already_executed';
    v_reason := 'payment_request_already_executed';
  elsif public.approval_batch_request_has_active_extraordinary(v_request.id) then
    v_classification := 'extraordinary';
    v_reason := 'extraordinary_authorization_active';
  elsif public.approval_batch_request_open_elsewhere(v_request.id, p_exclude_batch_id) then
    v_classification := 'already_in_open_batch';
    v_reason := 'payment_request_in_another_open_batch';
  elsif public.approval_batch_request_has_current_direction_approval(v_request.id) then
    v_classification := 'already_authorized';
    v_reason := 'direction_approval_already_current';
  elsif v_latest.director_status = 'rejected' and v_latest.rebatch_status = 'blocked' then
    v_classification := 'rejected_by_direction';
    v_reason := 'direction_rejection_requires_correction';
  elsif v_latest.director_status = 'approved'
        and v_latest.batch_status in ('approved', 'partially_approved')
        and coalesce(v_latest.decided_at >= v_request.approval_material_updated_at, false) then
    v_classification := 'pending_finance_close';
    v_reason := 'finance_close_required';
  elsif lower(v_request.request_type::text) in ('payroll', 'nomina') then
    v_classification := 'invalid_data';
    v_reason := 'payroll_uses_separate_flow';
  elsif cardinality(v_missing) > 0 then
    v_classification := 'invalid_data';
    v_reason := 'minimum_direction_data_missing';
  elsif v_request.status::text not in ('submitted', 'pending_approval', 'approved') then
    v_classification := 'invalid_data';
    v_reason := 'request_status_not_batch_eligible';
  else
    v_budget := public.approval_batch_budget_validation(v_request.id);
    if coalesce(v_budget ->> 'status', 'bloqueado') <> 'aprobable' then
      v_classification := case
        when v_budget ->> 'motivo' in ('sin_disponible', 'partida_no_presupuestada', 'sin_match_presupuesto')
          then 'budget_insufficient'
        else 'budget_validation_required'
      end;
      v_reason := coalesce(v_budget ->> 'motivo', 'budget_validation_required');
    else
      v_classification := 'ready_for_batch';
      v_reason := null;
      v_eligible := true;
    end if;
  end if;

  if v_budget is null then
    v_budget := public.approval_batch_budget_validation(v_request.id);
  end if;

  return jsonb_build_object(
    'eligible', v_eligible,
    'classification', v_classification,
    'reason', v_reason,
    'origin', v_origin,
    'review_sequence', v_review_sequence,
    'missing_fields', to_jsonb(v_missing),
    'budget_status', v_budget ->> 'status',
    'budget_reason', v_budget ->> 'motivo',
    'budget_available', nullif(v_budget ->> 'disponible_actual', '')::numeric,
    'budget_after', nullif(v_budget ->> 'disponible_despues', '')::numeric,
    'budget_shortfall', nullif(v_budget ->> 'faltante', '')::numeric,
    'previous_item_id', v_latest.id,
    'previous_batch_id', v_latest.batch_id,
    'previous_batch_label', v_latest.batch_label,
    'previous_director_status', v_latest.director_status,
    'previous_reject_reason', v_latest.director_reject_reason,
    'previous_correction_note', v_latest.rebatch_release_note,
    'previous_decided_at', v_latest.decided_at
  );
end
$$;


ALTER FUNCTION "public"."approval_batch_request_eligibility"("p_payment_request_id" "uuid", "p_exclude_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_has_active_extraordinary"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    where extraordinary_auth.payment_request_id = p_payment_request_id
      and extraordinary_auth.status = 'active'
      and public.extraordinary_authorization_is_ready(extraordinary_auth.id)
  );
$$;


ALTER FUNCTION "public"."approval_batch_request_has_active_extraordinary"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_has_any_execution_record"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    exists (
      select 1 from public.payment_layout_lines pll
      where pll.payment_request_id = p_payment_request_id
    )
    or exists (
      select 1 from public.cash_funds cf
      where cf.payment_request_id = p_payment_request_id
    )
    or exists (
      select 1 from public.payment_receipts prc
      where prc.payment_request_id = p_payment_request_id
    );
$$;


ALTER FUNCTION "public"."approval_batch_request_has_any_execution_record"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_has_current_direction_approval"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.payment_requests request
    join public.approval_batch_items item
      on item.payment_request_id = request.id
     and item.removed_at is null
     and item.director_status = 'approved'
     and item.finance_release_status = 'released'
    join public.approval_batches batch
      on batch.id = item.batch_id
     and batch.status = 'closed'
    where request.id = p_payment_request_id
      and item.decided_at is not null
      and item.decided_at >= request.approval_material_updated_at
      and batch.closed_at is not null
      and batch.closed_at >= item.decided_at
      and not exists (
        select 1
        from public.approval_batch_items later
        where later.payment_request_id = request.id
          and later.removed_at is null
          and later.director_status in ('pending', 'rejected')
          and coalesce(later.decided_at, later.created_at) > item.decided_at
      )
  );
$$;


ALTER FUNCTION "public"."approval_batch_request_has_current_direction_approval"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_has_current_finance_approval"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    public.approval_batch_latest_finance_approval_at(pr.id) >= pr.approval_material_updated_at,
    false
  )
  from public.payment_requests pr
  where pr.id = p_payment_request_id;
$$;


ALTER FUNCTION "public"."approval_batch_request_has_current_finance_approval"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_has_execution"("p_payment_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    exists (
      select 1
      from public.payment_layout_lines pll
      join public.payment_layouts pl on pl.id = pll.layout_id
      where pll.payment_request_id = p_payment_request_id
        and pll.status <> 'bank_rejected'
        and pl.status <> 'cancelled'
    )
    or exists (
      select 1 from public.cash_funds cf
      where cf.payment_request_id = p_payment_request_id
    )
    or exists (
      select 1 from public.payment_receipts prc
      where prc.payment_request_id = p_payment_request_id
    );
$$;


ALTER FUNCTION "public"."approval_batch_request_has_execution"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_request_open_elsewhere"("p_payment_request_id" "uuid", "p_exclude_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.approval_batch_items abi
    join public.approval_batches ab on ab.id = abi.batch_id
    where abi.payment_request_id = p_payment_request_id
      and abi.removed_at is null
      and ab.status in ('draft', 'submitted')
      and (p_exclude_batch_id is null or ab.id <> p_exclude_batch_id)
  );
$$;


ALTER FUNCTION "public"."approval_batch_request_open_elsewhere"("p_payment_request_id" "uuid", "p_exclude_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_require_active_direction"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
begin
  v_actor := public.approval_batch_require_actor();

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = v_actor
      and profile.active
  ) then
    raise exception 'director_profile_not_found_or_inactive';
  end if;

  if not public.current_user_has_role(
    public.approval_batch_direction_roles()
  ) then
    raise exception 'director_role_required';
  end if;

  return v_actor;
end
$$;


ALTER FUNCTION "public"."approval_batch_require_active_direction"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approval_batch_require_active_direction"() IS 'Requires an authenticated active Direction profile; intentionally does not depend on the future-batch Director pool.';



CREATE OR REPLACE FUNCTION "public"."approval_batch_require_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
begin
  v_actor := public.current_profile_id();
  if v_actor is null then
    raise exception 'not_authenticated';
  end if;
  return v_actor;
end
$$;


ALTER FUNCTION "public"."approval_batch_require_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_require_finance"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
begin
  v_actor := public.approval_batch_require_actor();
  if not public.current_user_has_role(public.flux_finance_roles()) then
    raise exception 'finance_role_required';
  end if;
  return v_actor;
end
$$;


ALTER FUNCTION "public"."approval_batch_require_finance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_batch_totals_by_currency"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'currency', totals.currency,
    'amount', totals.amount
  ) order by totals.currency), '[]'::jsonb)
  from (
    select coalesce(nullif(upper(btrim(pr.currency)), ''), 'MXN') as currency,
           sum(pr.amount_requested) as amount
    from public.approval_batch_items abi
    join public.payment_requests pr on pr.id = abi.payment_request_id
    where abi.batch_id = p_batch_id and abi.removed_at is null
    group by coalesce(nullif(upper(btrim(pr.currency)), ''), 'MXN')
  ) totals;
$$;


ALTER FUNCTION "public"."approval_batch_totals_by_currency"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_entire_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_count integer;
  v_rejected integer;
  v_final_status text;
begin
  v_actor := public.approval_batch_require_active_direction();

  select *
    into v_batch
  from public.approval_batches
  where id = p_batch_id
  for update;

  if not found then raise exception 'batch_not_found'; end if;
  if v_batch.director_id <> v_actor then
    raise exception 'batch_director_required';
  end if;
  if v_batch.status <> 'submitted' then
    raise exception 'batch_must_be_submitted';
  end if;

  update public.approval_batch_items
  set director_status = 'approved',
      director_reject_reason = null,
      rebatch_status = 'not_applicable',
      rebatch_released_by = null,
      rebatch_released_at = null,
      rebatch_release_note = null,
      decided_by = v_actor,
      decided_at = now()
  where batch_id = p_batch_id
    and removed_at is null
    and director_status = 'pending';
  get diagnostics v_count = row_count;

  if v_count = 0 then
    raise exception 'batch_has_no_pending_items';
  end if;

  select count(*)
    into v_rejected
  from public.approval_batch_items
  where batch_id = p_batch_id
    and removed_at is null
    and director_status = 'rejected';

  v_final_status := case
    when v_rejected > 0 then 'partially_approved'
    else 'approved'
  end;

  update public.approval_batches
  set status = v_final_status,
      decided_by = v_actor,
      decided_at = now()
  where id = p_batch_id;

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'status', v_final_status,
    'approved_items', v_count,
    'rejected_items', v_rejected,
    'approval_model', 'single_direction'
  );
end
$$;


ALTER FUNCTION "public"."approve_entire_batch"("p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_entire_batch"("p_batch_id" "uuid") IS 'Allows only the active Direction profile stored on the batch to approve it; future-pool membership is intentionally ignored.';



CREATE OR REPLACE FUNCTION "public"."assert_extraordinary_payment_confirmation_allowed"("p_payment_request_id" "uuid", "p_layout_id" "uuid" DEFAULT NULL::"uuid", "p_layout_line_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_request public.payment_requests%rowtype;
begin
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where payment_request_id = p_payment_request_id
    and idempotency_key is not null
  order by authorized_at desc
  limit 1;
  if not found then return; end if;

  if v_authorization.status <> 'ratified'
     or v_authorization.revoked_at is not null
     or v_authorization.disputed_at is not null then
    raise exception 'extraordinary_payment_confirmation_requires_ratification';
  end if;
  if p_layout_id is not null
     and v_authorization.consumed_layout_id <> p_layout_id then
    raise exception 'extraordinary_confirmation_layout_mismatch';
  end if;
  if p_layout_line_id is not null
     and v_authorization.consumed_layout_line_id <> p_layout_line_id then
    raise exception 'extraordinary_confirmation_layout_line_mismatch';
  end if;
  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id;
  if not found
     or v_authorization.payment_request_id <> v_request.id
     or v_authorization.company_id <> v_request.company_id
     or v_authorization.external_authorized_at <
       v_request.approval_material_updated_at then
    raise exception 'extraordinary_confirmation_material_mismatch';
  end if;
end
$$;


ALTER FUNCTION "public"."assert_extraordinary_payment_confirmation_allowed"("p_payment_request_id" "uuid", "p_layout_id" "uuid", "p_layout_line_id" "uuid") OWNER TO "postgres";


