CREATE OR REPLACE FUNCTION "public"."attach_provider_intake_files_internal"("p_payment_intake_id" "uuid", "p_files" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_intake record;
  v_item jsonb;
  v_file_id uuid;
  v_storage_path text;
  v_original_filename text;
  v_mime_type text;
  v_size_bytes bigint;
  v_file_kind text;
  v_sha256 text;
  v_expected_prefix text;
  v_inserted integer := 0;
  v_existing_count integer;
begin
  if p_payment_intake_id is null
     or p_files is null
     or jsonb_typeof(p_files) <> 'array'
     or jsonb_array_length(p_files) > 3 then
    raise exception 'provider_intake_invalid_files';
  end if;

  select
    pi.id,
    pi.status,
    il.max_file_mb,
    il.allowed_file_types
    into v_intake
  from public.payment_intake pi
  join public.intake_links il on il.id = pi.intake_link_id
  where pi.id = p_payment_intake_id
  for update of pi;

  if not found or v_intake.status <> 'received' then
    raise exception 'provider_intake_not_attachable';
  end if;

  select count(*)::integer
    into v_existing_count
  from public.payment_intake_files pif
  where pif.payment_intake_id = p_payment_intake_id;

  if v_existing_count + jsonb_array_length(p_files) > 3 then
    raise exception 'provider_intake_too_many_files';
  end if;

  for v_item in select value from jsonb_array_elements(p_files) loop
    begin
      v_file_id := (v_item ->> 'file_id')::uuid;
      v_storage_path := btrim(v_item ->> 'storage_path');
      v_original_filename := btrim(v_item ->> 'original_filename');
      v_mime_type := lower(btrim(v_item ->> 'mime_type'));
      v_size_bytes := (v_item ->> 'size_bytes')::bigint;
      v_file_kind := lower(btrim(v_item ->> 'file_kind'));
      v_sha256 := lower(btrim(v_item ->> 'sha256'));
    exception when others then
      raise exception 'provider_intake_invalid_file_metadata';
    end;

    v_expected_prefix := p_payment_intake_id::text || '/' || v_file_id::text;

    if v_storage_path !~ ('^' || v_expected_prefix || '(\.[a-z0-9]{1,10})?$')
       or nullif(v_original_filename, '') is null
       or position('/' in v_original_filename) > 0
       or position(chr(92) in v_original_filename) > 0
       or v_original_filename ~ '[[:cntrl:]]'
       or not (v_mime_type = any (v_intake.allowed_file_types))
       or v_size_bytes < 1
       or v_size_bytes > (v_intake.max_file_mb::bigint * 1048576)
       or v_file_kind not in ('invoice_pdf', 'invoice_xml', 'bank_document', 'support', 'other')
       or v_sha256 !~ '^[0-9a-f]{64}$' then
      raise exception 'provider_intake_invalid_file_metadata';
    end if;

    if exists (
      select 1
      from public.payment_intake_files pif
      where pif.storage_path = v_storage_path
        and (
          pif.payment_intake_id is distinct from p_payment_intake_id
          or pif.original_filename is distinct from v_original_filename
          or pif.mime_type is distinct from v_mime_type
          or pif.size_bytes is distinct from v_size_bytes
          or pif.file_kind is distinct from v_file_kind
          or pif.sha256 is distinct from v_sha256
        )
    ) then
      raise exception 'provider_intake_file_metadata_conflict';
    end if;

    if not exists (
      select 1
      from storage.objects o
      where o.bucket_id = 'intake-uploads'
        and o.name = v_storage_path
    ) then
      raise exception 'provider_intake_storage_object_missing';
    end if;

    insert into public.payment_intake_files (
      id,
      payment_intake_id,
      bucket_id,
      storage_path,
      original_filename,
      mime_type,
      size_bytes,
      file_kind,
      quarantine_status,
      sha256
    ) values (
      v_file_id,
      p_payment_intake_id,
      'intake-uploads',
      v_storage_path,
      v_original_filename,
      v_mime_type,
      v_size_bytes,
      v_file_kind,
      'pending',
      v_sha256
    )
    on conflict (storage_path) do nothing;

    if found then
      v_inserted := v_inserted + 1;
      insert into public.payment_intake_events (
        payment_intake_id,
        event_type,
        actor_type,
        from_status,
        to_status,
        metadata
      ) values (
        p_payment_intake_id,
        'file_uploaded',
        'public_provider',
        'received',
        'received',
        jsonb_build_object(
          'file_id', v_file_id,
          'file_kind', v_file_kind,
          'mime_type', v_mime_type,
          'size_bytes', v_size_bytes
        )
      );
    end if;
  end loop;

  return jsonb_build_object(
    'payment_intake_id', p_payment_intake_id,
    'inserted_files', v_inserted,
    'total_files', v_existing_count + v_inserted
  );
end
$_$;


ALTER FUNCTION "public"."attach_provider_intake_files_internal"("p_payment_intake_id" "uuid", "p_files" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_provider_intake_files_internal"("p_payment_intake_id" "uuid", "p_files" "jsonb") IS 'Service-only idempotent attachment of validated private file metadata and file_uploaded ledger events.';



CREATE OR REPLACE FUNCTION "public"."audit_payment_request_execution_data_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_changed_fields text[];
  v_completed_fields text[];
  v_missing_before text[];
  v_missing_after text[];
  v_now timestamptz := clock_timestamp();
begin
  v_changed_fields := array_remove(array[
    case
      when old.provider_bank_account_id is distinct from new.provider_bank_account_id
        then 'provider_bank_account_id'
    end,
    case
      when old.company_bank_account_id is distinct from new.company_bank_account_id
        then 'company_bank_account_id'
    end,
    case when old.due_date is distinct from new.due_date then 'due_date' end,
    case
      when old.scheduled_payment_date is distinct from new.scheduled_payment_date
        then 'scheduled_payment_date'
    end,
    case
      when old.payment_reference is distinct from new.payment_reference
        then 'payment_reference'
    end,
    case
      when old.payment_concept is distinct from new.payment_concept
        then 'payment_concept'
    end
  ]::text[], null);

  if cardinality(v_changed_fields) = 0 then
    return new;
  end if;

  v_actor := public.approval_batch_require_finance();
  v_missing_before := public.payment_request_layout_missing_fields(old);
  v_missing_after := public.payment_request_layout_missing_fields(new);

  select coalesce(
    array_agg(completed_field.field_name order by completed_field.field_name),
    array[]::text[]
  )
    into v_completed_fields
  from unnest(v_missing_before) as completed_field(field_name)
  where not (completed_field.field_name = any(v_missing_after));

  insert into public.activity_log(
    entity_type,
    entity_id,
    action,
    old_values,
    new_values,
    performed_by,
    performed_at,
    notes
  ) values (
    'payment_request',
    new.id,
    'payment_execution_data_updated',
    jsonb_build_object(
      'layout_data_complete', cardinality(v_missing_before) = 0,
      'missing_fields', to_jsonb(v_missing_before)
    ),
    jsonb_build_object(
      'changed_fields', to_jsonb(v_changed_fields),
      'completed_fields', to_jsonb(v_completed_fields),
      'layout_data_complete', cardinality(v_missing_after) = 0,
      'missing_fields', to_jsonb(v_missing_after)
    ),
    v_actor,
    v_now,
    'Operational execution-data audit; field values intentionally omitted.'
  );

  return new;
end
$$;


