ALTER FUNCTION "public"."authorize_payment_request_extraordinary"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_extraordinary_authorization"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text", "p_external_director_profile_id" "uuid", "p_external_authorized_at" timestamp with time zone, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_request public.payment_requests%rowtype;
  v_policy public.extraordinary_payment_policies%rowtype;
  v_existing public.payment_request_extraordinary_authorizations%rowtype;
  v_authorization_id uuid := gen_random_uuid();
  v_object_id uuid := gen_random_uuid();
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_now timestamptz := clock_timestamp();
  v_path text;
begin
  if p_payment_request_id is null then raise exception 'payment_request_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_payment_request_id::text, 37037));

  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then raise exception 'payment_request_not_found'; end if;

  v_actor := public.extraordinary_require_finance_for_company(v_request.company_id);
  if v_actor = p_external_director_profile_id then
    raise exception 'finance_actor_must_differ_from_external_director';
  end if;

  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'invalid_idempotency_key';
  end if;

  select * into v_existing
  from public.payment_request_extraordinary_authorizations
  where company_id = v_request.company_id
    and idempotency_key = v_key;
  if found then
    if v_existing.payment_request_id <> v_request.id
       or v_existing.authorized_by <> v_actor
       or v_existing.external_director_profile_id <>
         p_external_director_profile_id then
      raise exception 'idempotency_key_payload_mismatch';
    end if;
    return jsonb_build_object(
      'authorization_id', v_existing.id,
      'status', v_existing.status,
      'storage_bucket', v_existing.evidence_storage_bucket,
      'storage_path', v_existing.evidence_storage_path,
      'idempotent_replay', true
    );
  end if;

  select * into v_policy
  from public.extraordinary_payment_policies
  where company_id = v_request.company_id
  for share;
  if not found or not v_policy.enabled then
    raise exception 'extraordinary_policy_disabled';
  end if;
  if v_request.currency <> 'MXN'
     or (
       v_policy.max_amount_mxn is not null
       and v_request.amount_requested > v_policy.max_amount_mxn
     ) then
    raise exception 'extraordinary_amount_exceeds_policy';
  end if;
  if v_category <> all(v_policy.allowed_categories) then
    raise exception 'extraordinary_category_not_allowed';
  end if;
  if v_reason is null or char_length(v_reason) < 20 then
    raise exception 'extraordinary_reason_too_short';
  end if;
  if p_external_authorized_at is null
     or p_external_authorized_at > v_now + interval '5 minutes'
     or p_external_authorized_at < v_request.approval_material_updated_at
     or p_external_authorized_at +
       make_interval(hours => v_policy.authorization_valid_hours) <= v_now then
    raise exception 'external_authorization_time_invalid';
  end if;
  if not public.extraordinary_profile_is_company_director(
    p_external_director_profile_id,
    v_request.company_id
  ) then
    raise exception 'external_director_not_active_for_company';
  end if;
  if v_request.status::text not in (
    'submitted', 'pending_approval', 'approved'
  ) then
    raise exception 'payment_request_not_available_for_extraordinary';
  end if;
  if lower(v_request.request_type::text) in ('payroll', 'nomina') then
    raise exception 'payroll_extraordinary_not_supported';
  end if;
  if public.approval_batch_request_has_any_execution_record(v_request.id)
     or exists (
       select 1
       from public.payment_request_receipt_links receipt_link
       where receipt_link.payment_request_id = v_request.id
     ) then
    raise exception 'payment_request_already_executed';
  end if;
  if exists (
    select 1
    from public.approval_batch_items batch_item
    join public.approval_batches batch on batch.id = batch_item.batch_id
    where batch_item.payment_request_id = v_request.id
      and (
        (batch_item.removed_at is null and batch_item.director_status = 'rejected')
        or batch.status in ('draft', 'submitted')
      )
  ) then
    raise exception 'request_has_rejection_or_open_batch';
  end if;
  if exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    where extraordinary_auth.payment_request_id = v_request.id
      and extraordinary_auth.status in (
        'draft', 'active', 'consumed_pending_ratification'
      )
  ) then
    raise exception 'extraordinary_authorization_already_open';
  end if;
  if coalesce(
    public.approval_batch_budget_validation(v_request.id)->>'status',
    'bloqueado'
  ) <> 'aprobable' then
    raise exception 'budget_revalidation_required';
  end if;

  v_path := v_request.company_id::text || '/' ||
    v_authorization_id::text || '/evidence/' || v_object_id::text;
  perform set_config('app.extraordinary_internal', 'on', true);

  insert into public.payment_request_extraordinary_authorizations(
    id,
    payment_request_id,
    company_id,
    category,
    reason,
    status,
    authorized_by,
    authorized_at,
    external_director_profile_id,
    evidence_storage_bucket,
    evidence_storage_path,
    external_authorized_at,
    valid_until,
    ratification_due_at,
    idempotency_key
  ) values (
    v_authorization_id,
    v_request.id,
    v_request.company_id,
    v_category,
    v_reason,
    'draft',
    v_actor,
    v_now,
    p_external_director_profile_id,
    'extraordinary-authorizations',
    v_path,
    p_external_authorized_at,
    p_external_authorized_at +
      make_interval(hours => v_policy.authorization_valid_hours),
    p_external_authorized_at +
      make_interval(hours =>
        v_policy.authorization_valid_hours + v_policy.ratification_due_hours),
    v_key
  );

  perform public.extraordinary_append_event(
    v_authorization_id,
    'draft_created',
    v_actor,
    'draft-created:' || v_authorization_id::text,
    jsonb_build_object(
      'category', v_category,
      'amount_minor', round(v_request.amount_requested * 100)::bigint,
      'currency', v_request.currency,
      'external_director_profile_id', p_external_director_profile_id,
      'valid_until',
        p_external_authorized_at +
          make_interval(hours => v_policy.authorization_valid_hours)
    )
  );

  return jsonb_build_object(
    'authorization_id', v_authorization_id,
    'status', 'draft',
    'storage_bucket', 'extraordinary-authorizations',
    'storage_path', v_path,
    'allowed_mime_types', array[
      'application/pdf', 'image/jpeg', 'image/png', 'image/webp'
    ],
    'max_size_bytes', 5242880,
    'valid_until',
      p_external_authorized_at +
        make_interval(hours => v_policy.authorization_valid_hours),
    'idempotent_replay', false
  );
end
$$;


ALTER FUNCTION "public"."begin_extraordinary_authorization"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text", "p_external_director_profile_id" "uuid", "p_external_authorized_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_extraordinary_authorization"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text", "p_external_director_profile_id" "uuid", "p_external_authorized_at" timestamp with time zone, "p_idempotency_key" "text") IS 'Creates an idempotent evidence-upload draft; never activates without a private object.';



CREATE OR REPLACE FUNCTION "public"."begin_extraordinary_authorization"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text", "p_external_director_profile_id" "uuid", "p_external_authorized_at" timestamp with time zone, "p_idempotency_key" "text", "p_authorization_medium" "text", "p_authorization_reference" "text", "p_director_absence_confirmed" boolean, "p_cannot_wait_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_result jsonb;
  v_authorization_id uuid;
  v_medium text := nullif(btrim(coalesce(p_authorization_medium, '')), '');
  v_reference text := nullif(btrim(coalesce(p_authorization_reference, '')), '');
begin
  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then raise exception 'payment_request_not_found'; end if;
  if v_request.extraordinary_state <> 'extraordinary_requested' then
    raise exception 'extraordinary_intent_required_before_draft';
  end if;
  if not public.extraordinary_profile_has_explicit_faculty(
    public.current_profile_id(),
    v_request.company_id
  ) then
    raise exception 'explicit_extraordinary_faculty_required';
  end if;
  if v_medium is null or char_length(v_medium) > 100 then
    raise exception 'external_authorization_medium_required';
  end if;
  if v_reference is null or char_length(v_reference) < 8
     or char_length(v_reference) > 500 then
    raise exception 'external_authorization_reference_required';
  end if;
  if not coalesce(p_director_absence_confirmed, false) then
    raise exception 'director_absence_confirmation_required';
  end if;
  if not coalesce(p_cannot_wait_confirmed, false) then
    raise exception 'cannot_wait_confirmation_required';
  end if;

  v_result := public.begin_extraordinary_authorization(
    p_payment_request_id,
    p_category,
    p_reason,
    p_external_director_profile_id,
    p_external_authorized_at,
    p_idempotency_key
  );
  v_authorization_id := (v_result->>'authorization_id')::uuid;

  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set authorization_medium = v_medium,
      authorization_reference = v_reference,
      director_absence_confirmed = true,
      cannot_wait_confirmed = true,
      updated_at = clock_timestamp()
  where id = v_authorization_id
    and status = 'draft';

  return v_result || jsonb_build_object(
    'authorization_medium', v_medium,
    'evidence_optional', true,
    'creation_mark_was_intent_only', true
  );
end
$$;


ALTER FUNCTION "public"."begin_extraordinary_authorization"("p_payment_request_id" "uuid", "p_category" "text", "p_reason" "text", "p_external_director_profile_id" "uuid", "p_external_authorized_at" timestamp with time zone, "p_idempotency_key" "text", "p_authorization_medium" "text", "p_authorization_reference" "text", "p_director_absence_confirmed" boolean, "p_cannot_wait_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payment_allocation_plan"("p_plan_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_plan public.payment_allocation_plans%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_reservation public.payment_allocation_reservations%rowtype;
  v_actor uuid;
  v_reason text := public.payment_reconciliation_redact_free_text(p_reason, 500);
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_reservation_id uuid;
  v_event_id uuid;
  v_result jsonb;
  v_decided_at timestamptz;
begin
  select * into v_plan from public.payment_allocation_plans where id = p_plan_id for update;
  if not found then raise exception 'payment_allocation_plan_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_plan.company_id);
  v_payload := jsonb_build_object('plan_id', p_plan_id, 'reason', v_reason);
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_plan.company_id, 'payment_allocation.cancel', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_reason is null or char_length(v_reason) < 10 then raise exception 'cancel_reason_too_short'; end if;
  if v_plan.status not in ('draft', 'reserved') then raise exception 'payment_allocation_plan_not_cancellable'; end if;
  select * into v_operation
  from public.bank_payment_operations
  where id = v_plan.operation_id
  for update;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  select * into v_reservation
  from public.payment_allocation_reservations
  where plan_id = v_plan.id and status = 'active'
  for update;
  v_decided_at := clock_timestamp();
  if found and v_reservation.expires_at <= v_decided_at then
    raise exception 'payment_reservation_expired_use_expire';
  end if;
  update public.payment_allocation_reservations
  set status = 'cancelled', closed_by = v_actor, closed_at = v_decided_at, close_reason = v_reason
  where plan_id = v_plan.id and status = 'active'
  returning id into v_reservation_id;
  update public.payment_allocation_plans
  set status = 'cancelled', cancelled_by = v_actor, cancelled_at = v_decided_at, cancel_reason = v_reason
  where id = v_plan.id;
  update public.bank_payment_operations set status = 'available'
  where id = v_plan.operation_id and status = 'reserved';
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_allocation.cancelled', 'payment_allocation_plan', v_plan.id,
    v_plan.company_id, v_actor,
    jsonb_strip_nulls(jsonb_build_object(
      'operation_id', v_plan.operation_id, 'plan_id', v_plan.id,
      'reservation_id', v_reservation_id
    )), v_plan.operation_id, null
  );
  v_result := jsonb_build_object('event_id', v_event_id, 'plan_id', v_plan.id, 'status', 'cancelled');
  return public.payment_reconciliation_store_command(
    v_plan.company_id, 'payment_allocation.cancel', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."cancel_payment_allocation_plan"("p_plan_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payment_request_extraordinary_intent"("p_payment_request_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_request public.payment_requests%rowtype;
  v_draft public.payment_request_extraordinary_authorizations%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  if v_reason is null or char_length(v_reason) < 10 then
    raise exception 'extraordinary_intent_cancel_reason_required';
  end if;

  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then raise exception 'payment_request_not_found'; end if;
  if v_request.requested_by <> v_actor
     and not public.extraordinary_profile_has_explicit_faculty(
       v_actor,
       v_request.company_id
     ) then
    raise exception 'extraordinary_intent_cancel_not_allowed';
  end if;
  if v_request.extraordinary_state not in (
    'extraordinary_requested', 'extraordinary_draft'
  ) then
    raise exception 'extraordinary_intent_not_cancellable';
  end if;

  select * into v_draft
  from public.payment_request_extraordinary_authorizations
  where payment_request_id = p_payment_request_id
    and status = 'draft'
  order by authorized_at desc, id desc
  limit 1
  for update;

  if found then
    perform set_config('app.extraordinary_internal', 'on', true);
    update public.payment_request_extraordinary_authorizations
    set status = 'revoked',
        revoked_by = v_actor,
        revoked_at = clock_timestamp(),
        revoke_reason = v_reason,
        updated_at = clock_timestamp()
    where id = v_draft.id;
  end if;

  update public.payment_requests
  set extraordinary_state = 'normal',
      extraordinary_intent_cancelled_by = v_actor,
      extraordinary_intent_cancelled_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where id = p_payment_request_id;

  insert into public.payment_request_extraordinary_events(
    authorization_id,
    payment_request_id,
    company_id,
    event_type,
    actor_profile_id,
    idempotency_key,
    metadata
  ) values (
    case when v_draft.id is null then null else v_draft.id end,
    p_payment_request_id,
    v_request.company_id,
    'intent_cancelled',
    v_actor,
    'intent-cancelled:' || p_payment_request_id::text || ':' ||
      extract(epoch from clock_timestamp())::bigint::text,
    jsonb_build_object('reason', v_reason, 'returned_to_normal', true)
  );

  return jsonb_build_object(
    'payment_request_id', p_payment_request_id,
    'extraordinary_state', 'normal'
  );
end
$$;


ALTER FUNCTION "public"."cancel_payment_request_extraordinary_intent"("p_payment_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_external_notification_events_for_dispatcher"("p_limit" integer DEFAULT 1, "p_worker_id" "text" DEFAULT 'external-notification-dispatcher'::"text") RETURNS TABLE("id" "uuid", "event_type" "text", "source_table" "text", "source_id" "uuid", "source_folio" "text", "recipient_type" "text", "recipient_profile_id" "uuid", "recipient_email" "text", "channel" "text", "priority" "text", "subject" "text", "payload" "jsonb", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 1), 1), 1);
  v_worker_id text := left(
    coalesce(nullif(btrim(p_worker_id), ''), 'external-notification-dispatcher'),
    120
  );
  v_rollout record;
  v_daily_count integer;
begin
  select r.*
    into v_rollout
  from public.notification_external_rollouts r
  where r.mode in ('test_only', 'pilot')
    and r.cutoff_at is not null
    and cardinality(r.enabled_event_types) > 0
    and cardinality(r.recipient_allowlist_hashes) > 0
    and r.batch_size = 1
    and r.daily_cap > 0
    and exists (
      select 1
      from public.notification_events e
      join public.payment_intake_events pie on pie.id = e.source_id
      where e.rollout_id = r.id
        and e.audience = 'external'
        and e.status = 'pending'
        and e.event_type in (
          'provider_intake.received',
          'provider_intake.correction_requested',
          'provider_intake.rejected'
        )
        and public.notification_external_event_mode_allowed(e.event_type, r.mode)
        and e.event_type = any (r.enabled_event_types)
        and e.created_at >= r.cutoff_at
        and pie.created_at >= r.cutoff_at
        and coalesce(e.next_attempt_at, now()) <= now()
        and e.attempt_count < e.max_attempts
        and e.max_attempts = 3
        and e.recipient_email = lower(btrim(e.recipient_email))
        and e.recipient_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
        and encode(
          extensions.digest(
            convert_to(lower(btrim(e.recipient_email)), 'UTF8'),
            'sha256'
          ),
          'hex'
        ) = any (r.recipient_allowlist_hashes)
    )
  order by r.id
  for update of r skip locked
  limit 1;

  if not found then
    return;
  end if;

  select count(*)::integer
    into v_daily_count
  from public.notification_events daily_event
  where daily_event.audience = 'external'
    and daily_event.rollout_id = v_rollout.id
    and daily_event.status in ('processing', 'sent')
    and coalesce(
      daily_event.processed_at,
      daily_event.last_attempt_at,
      daily_event.created_at
    ) >= (
      date_trunc(
        'day',
        now() at time zone 'America/Mexico_City'
      ) at time zone 'America/Mexico_City'
    );

  if v_daily_count >= v_rollout.daily_cap then
    return;
  end if;

  return query
  with candidate as (
    select e.id
    from public.notification_events e
    join public.payment_intake_events pie on pie.id = e.source_id
    where e.rollout_id = v_rollout.id
      and e.audience = 'external'
      and e.status = 'pending'
      and e.event_type in (
        'provider_intake.received',
        'provider_intake.correction_requested',
        'provider_intake.rejected'
      )
      and public.notification_external_event_mode_allowed(
        e.event_type,
        v_rollout.mode
      )
      and e.event_type = any (v_rollout.enabled_event_types)
      and e.created_at >= v_rollout.cutoff_at
      and pie.created_at >= v_rollout.cutoff_at
      and coalesce(e.next_attempt_at, now()) <= now()
      and e.attempt_count < e.max_attempts
      and e.max_attempts = 3
      and e.recipient_email = lower(btrim(e.recipient_email))
      and e.recipient_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      and encode(
        extensions.digest(
          convert_to(lower(btrim(e.recipient_email)), 'UTF8'),
          'sha256'
        ),
        'hex'
      ) = any (v_rollout.recipient_allowlist_hashes)
    order by e.created_at, e.id
    for update of e skip locked
    limit v_limit
  ),
  claimed as (
    update public.notification_events e
       set status = 'processing',
           locked_at = now(),
           locked_by = v_worker_id,
           last_attempt_at = now(),
           updated_at = now()
      from candidate c
     where e.id = c.id
     returning
       e.id,
       e.event_type,
       e.source_table,
       e.source_id,
       e.source_folio,
       e.recipient_type,
       e.recipient_profile_id,
       e.recipient_email,
       e.channel,
       e.priority,
       e.subject,
       e.payload,
       e.attempt_count
  )
  select
    claimed.id,
    claimed.event_type,
    claimed.source_table,
    claimed.source_id,
    claimed.source_folio,
    claimed.recipient_type,
    claimed.recipient_profile_id,
    claimed.recipient_email,
    claimed.channel,
    claimed.priority,
    claimed.subject,
    claimed.payload,
    claimed.attempt_count
  from claimed
  order by claimed.id;
end;
$_$;


ALTER FUNCTION "public"."claim_external_notification_events_for_dispatcher"("p_limit" integer, "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_notification_events_for_dispatcher"("p_limit" integer DEFAULT 5, "p_worker_id" "text" DEFAULT 'edge-notification-dispatcher'::"text") RETURNS TABLE("id" "uuid", "event_type" "text", "source_table" "text", "source_id" "uuid", "source_folio" "text", "recipient_type" "text", "recipient_profile_id" "uuid", "recipient_email" "text", "channel" "text", "priority" "text", "subject" "text", "payload" "jsonb", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 5), 1), 5);
  v_worker_id text := left(coalesce(nullif(trim(p_worker_id), ''), 'edge-notification-dispatcher'), 120);
begin
  return query
  with candidate as (
    select e.id
    from public.notification_events e
    where e.audience = 'internal'
      and e.status in ('pending', 'failed')
      and coalesce(e.next_attempt_at, now()) <= now()
      and e.attempt_count < e.max_attempts
      and nullif(trim(coalesce(e.recipient_email, '')), '') is not null
      and coalesce(e.channel, 'email') = 'email'
    order by
      case e.priority
        when 'critical' then 1
        when 'high' then 2
        when 'normal' then 3
        when 'low' then 4
        else 5
      end,
      e.created_at,
      e.id
    for update skip locked
    limit v_limit
  ),
  claimed as (
    update public.notification_events e
       set status = 'processing',
           locked_at = now(),
           locked_by = v_worker_id,
           last_attempt_at = now(),
           updated_at = now()
      from candidate c
     where e.id = c.id
     returning
       e.id,
       e.event_type,
       e.source_table,
       e.source_id,
       e.source_folio,
       e.recipient_type,
       e.recipient_profile_id,
       e.recipient_email,
       e.channel,
       e.priority,
       e.subject,
       e.payload,
       e.attempt_count
  )
  select
    claimed.id,
    claimed.event_type,
    claimed.source_table,
    claimed.source_id,
    claimed.source_folio,
    claimed.recipient_type,
    claimed.recipient_profile_id,
    claimed.recipient_email,
    claimed.channel,
    claimed.priority,
    claimed.subject,
    claimed.payload,
    claimed.attempt_count
  from claimed
  order by
    case claimed.priority
      when 'critical' then 1
      when 'high' then 2
      when 'normal' then 3
      when 'low' then 4
      else 5
    end,
    claimed.id;
end;
$$;


ALTER FUNCTION "public"."claim_notification_events_for_dispatcher"("p_limit" integer, "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_notification_events_for_dispatcher_v2"("p_limit" integer DEFAULT 5, "p_worker_id" "text" DEFAULT 'edge-notification-dispatcher'::"text", "p_event_types" "text"[] DEFAULT NULL::"text"[], "p_created_at_from" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "event_type" "text", "source_table" "text", "source_id" "uuid", "source_folio" "text", "recipient_type" "text", "recipient_profile_id" "uuid", "recipient_email" "text", "channel" "text", "priority" "text", "subject" "text", "payload" "jsonb", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 5), 1), 5);
  v_worker_id text := left(
    coalesce(nullif(btrim(p_worker_id), ''), 'edge-notification-dispatcher'),
    120
  );
  v_event_types text[];
  v_allowed_event_types constant text[] := array[
    'payment_request.created',
    'payment_request.approved',
    'payment_request.rejected',
    'payment_request.changes_requested',
    'payment_request.exception_approved',
    'payment_request.exception_rejected',
    'approval_batch.submitted',
    'approval_batch.approved',
    'approval_batch.partially_approved',
    'approval_batch.item_rejected',
    'payment_request.extraordinary_authorized',
    'approval_batch.item_rebatched',
    'payment_receipt.linked'
  ]::text[];
begin
  select array_agg(
           distinct btrim(requested.event_type)
           order by btrim(requested.event_type)
         )
    into v_event_types
  from unnest(coalesce(p_event_types, array[]::text[])) as requested(event_type)
  where nullif(btrim(coalesce(requested.event_type, '')), '') is not null;

  if coalesce(cardinality(v_event_types), 0) = 0 then
    raise exception 'notification_dispatcher_event_types_required';
  end if;
  if p_created_at_from is null then
    raise exception 'notification_dispatcher_cutoff_required';
  end if;
  if exists (
    select 1
    from unnest(v_event_types) as requested(event_type)
    where not requested.event_type = any(v_allowed_event_types)
  ) then
    raise exception 'notification_dispatcher_event_type_not_allowed';
  end if;

  return query
  with candidate as (
    select event.id
    from public.notification_events event
    where event.event_type = any(v_event_types)
      and event.status in ('pending', 'failed')
      and event.created_at >= p_created_at_from
      and coalesce(event.next_attempt_at, now()) <= now()
      and event.attempt_count < event.max_attempts
      and nullif(btrim(coalesce(event.recipient_email, '')), '') is not null
      and coalesce(event.channel, 'email') = 'email'
    order by
      case event.priority
        when 'critical' then 1
        when 'high' then 2
        when 'normal' then 3
        when 'low' then 4
        else 5
      end,
      event.created_at,
      event.id
    for update skip locked
    limit v_limit
  ),
  claimed as (
    update public.notification_events event
       set status = 'processing',
           locked_at = now(),
           locked_by = v_worker_id,
           last_attempt_at = now(),
           updated_at = now()
      from candidate
     where event.id = candidate.id
     returning
       event.id,
       event.event_type,
       event.source_table,
       event.source_id,
       event.source_folio,
       event.recipient_type,
       event.recipient_profile_id,
       event.recipient_email,
       event.channel,
       event.priority,
       event.subject,
       event.payload,
       event.attempt_count
  )
  select
    claimed.id,
    claimed.event_type,
    claimed.source_table,
    claimed.source_id,
    claimed.source_folio,
    claimed.recipient_type,
    claimed.recipient_profile_id,
    claimed.recipient_email,
    claimed.channel,
    claimed.priority,
    claimed.subject,
    claimed.payload,
    claimed.attempt_count
  from claimed
  order by
    case claimed.priority
      when 'critical' then 1
      when 'high' then 2
      when 'normal' then 3
      when 'low' then 4
      else 5
    end,
    claimed.id;
end;
$$;


ALTER FUNCTION "public"."claim_notification_events_for_dispatcher_v2"("p_limit" integer, "p_worker_id" "text", "p_event_types" "text"[], "p_created_at_from" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_notification_events_for_dispatcher_v2"("p_limit" integer, "p_worker_id" "text", "p_event_types" "text"[], "p_created_at_from" timestamp with time zone) IS 'Service-only queue claim requiring an explicit event allowlist and temporal cutoff. Does not replay historical backlog.';



CREATE OR REPLACE FUNCTION "public"."claim_pending_notification_events"("p_limit" integer DEFAULT 25, "p_worker_id" "text" DEFAULT 'manual-dev'::"text") RETURNS TABLE("id" "uuid", "event_type" "text", "source_table" "text", "source_id" "uuid", "source_folio" "text", "recipient_type" "text", "recipient_profile_id" "uuid", "recipient_email" "text", "channel" "text", "priority" "text", "subject" "text", "payload" "jsonb", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 begin
   if not public.notification_current_user_has_role(array['admin', 'sysadmin']) then
     raise exception 'not_allowed_to_claim_notifications';
   end if;
 
   return query
   with candidate as (
     select e.id
     from public.notification_events e
     where e.audience = 'internal'
       and e.status in ('pending', 'failed')
       and coalesce(e.next_attempt_at, now()) <= now()
       and e.attempt_count < e.max_attempts
       and nullif(trim(coalesce(e.recipient_email, '')), '') is not null
     order by
       case e.priority
         when 'critical' then 1
         when 'high' then 2
         when 'normal' then 3
         when 'low' then 4
         else 5
       end,
       e.created_at
     for update skip locked
     limit greatest(coalesce(p_limit, 25), 1)
   ),
   claimed as (
     update public.notification_events e
     set
       status = 'processing',
       locked_at = now(),
       locked_by = coalesce(nullif(trim(p_worker_id), ''), 'manual-dev'),
       last_attempt_at = now(),
       updated_at = now()
     from candidate c
     where e.id = c.id
     returning
       e.id,
       e.event_type,
       e.source_table,
       e.source_id,
       e.source_folio,
       e.recipient_type,
       e.recipient_profile_id,
       e.recipient_email,
       e.channel,
       e.priority,
       e.subject,
       e.payload,
       e.attempt_count
   )
   select
     claimed.id,
     claimed.event_type,
     claimed.source_table,
     claimed.source_id,
     claimed.source_folio,
     claimed.recipient_type,
     claimed.recipient_profile_id,
     claimed.recipient_email,
     claimed.channel,
     claimed.priority,
     claimed.subject,
     claimed.payload,
     claimed.attempt_count
   from claimed
   order by
     case claimed.priority
       when 'critical' then 1
       when 'high' then 2
       when 'normal' then 3
       when 'low' then 4
       else 5
     end,
     claimed.id;
 end;
 $$;


