CREATE OR REPLACE FUNCTION "public"."close_approval_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_item record;
  v_reason text;
  v_now timestamptz := clock_timestamp();
  v_pending integer;
  v_released integer;
  v_blocked integer;
  v_rejected integer;
  v_totals jsonb;
  v_blocked_items jsonb;
begin
  v_actor := public.approval_batch_require_finance();
  select * into v_batch
  from public.approval_batches
  where id = p_batch_id
  for update;
  if not found then raise exception 'batch_not_found'; end if;

  if v_batch.status = 'closed' then
    select
      count(*) filter (where finance_release_status = 'released')::integer,
      count(*) filter (where finance_release_status = 'blocked')::integer,
      count(*) filter (where director_status = 'rejected')::integer
    into v_released, v_blocked, v_rejected
    from public.approval_batch_items
    where batch_id = p_batch_id and removed_at is null;
    return jsonb_build_object(
      'batch_id', p_batch_id,
      'status', 'closed',
      'approved_released_count', v_released,
      'blocked_count', v_blocked,
      'rejected_blocked_count', v_rejected,
      'idempotent_replay', true
    );
  end if;
  if v_batch.status not in ('approved', 'partially_approved') then
    raise exception 'batch_not_ready_to_close';
  end if;

  perform 1
  from public.approval_batch_items item
  where item.batch_id = p_batch_id
    and item.removed_at is null
  order by item.payment_request_id, item.id
  for update;

  select count(*)::integer into v_pending
  from public.approval_batch_items
  where batch_id = p_batch_id
    and removed_at is null
    and director_status = 'pending';
  if v_pending > 0 then raise exception 'batch_has_pending_items'; end if;

  for v_item in
    select item.id, item.director_status
    from public.approval_batch_items item
    where item.batch_id = p_batch_id
      and item.removed_at is null
    order by item.payment_request_id, item.id
  loop
    v_reason := public.approval_batch_item_release_block_reason(v_item.id);
    if v_item.director_status = 'approved' and v_reason is null then
      update public.approval_batch_items
      set finance_release_status = 'released',
          finance_release_reason = null,
          finance_released_by = v_actor,
          finance_released_at = v_now
      where id = v_item.id;
    else
      update public.approval_batch_items
      set finance_release_status = 'blocked',
          finance_release_reason = coalesce(v_reason, 'release_validation_failed'),
          finance_released_by = v_actor,
          finance_released_at = v_now
      where id = v_item.id;
    end if;
  end loop;

  select
    count(*) filter (where finance_release_status = 'released')::integer,
    count(*) filter (where finance_release_status = 'blocked')::integer,
    count(*) filter (where director_status = 'rejected')::integer
  into v_released, v_blocked, v_rejected
  from public.approval_batch_items
  where batch_id = p_batch_id and removed_at is null;
  if v_released = 0 then raise exception 'batch_no_releasable_items'; end if;

  update public.approval_batches
  set status = 'closed',
      closed_by = v_actor,
      closed_at = v_now
  where id = p_batch_id
    and status in ('approved', 'partially_approved');
  if not found then raise exception 'batch_concurrent_change'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'currency', totals.currency,
    'amount', totals.amount
  ) order by totals.currency), '[]'::jsonb)
  into v_totals
  from (
    select
      coalesce(nullif(upper(btrim(request.currency)), ''), 'MXN') as currency,
      sum(request.amount_requested) as amount
    from public.approval_batch_items item
    join public.payment_requests request
      on request.id = item.payment_request_id
    where item.batch_id = p_batch_id
      and item.removed_at is null
      and item.finance_release_status = 'released'
    group by coalesce(nullif(upper(btrim(request.currency)), ''), 'MXN')
  ) totals;

  select coalesce(jsonb_agg(jsonb_build_object(
    'item_id', item.id,
    'payment_request_id', item.payment_request_id,
    'request_number', request.request_number,
    'director_status', item.director_status,
    'reason', item.finance_release_reason
  ) order by request.request_number, item.id), '[]'::jsonb)
  into v_blocked_items
  from public.approval_batch_items item
  join public.payment_requests request
    on request.id = item.payment_request_id
  where item.batch_id = p_batch_id
    and item.removed_at is null
    and item.finance_release_status = 'blocked';

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'status', 'closed',
    'release_label', 'Liberado para pago',
    'approved_released_count', v_released,
    'blocked_count', v_blocked,
    'rejected_blocked_count', v_rejected,
    'blocked_items', v_blocked_items,
    'totals_by_currency', v_totals,
    'idempotent_replay', false
  );
end
$$;


ALTER FUNCTION "public"."close_approval_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_incident_charge"("p_incident_charge_id" "uuid", "p_invoice_id" "uuid", "p_payment_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_incident public.incident_charges%rowtype;
  v_invoice public.invoices%rowtype;
begin
  if p_incident_charge_id is null then
    raise exception 'incident_charge_required';
  end if;

  if p_invoice_id is null then
    raise exception 'invoice_required';
  end if;

  if p_payment_date is null then
    raise exception 'payment_date_required';
  end if;

  select *
  into v_incident
  from public.incident_charges
  where id = p_incident_charge_id
  for update;

  if not found then
    raise exception 'incident_charge_not_found';
  end if;

  select *
  into v_invoice
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'invoice_not_found';
  end if;

  if v_invoice.invoice_type <> 'incident' then
    raise exception 'invoice_not_incident_type';
  end if;

  if v_invoice.incident_charge_id <> v_incident.id then
    raise exception 'invoice_does_not_match_incident';
  end if;

  update public.incident_charges
  set status = 'paid',
      invoice_id = v_invoice.id,
      updated_at = now()
  where id = v_incident.id;

  update public.invoices
  set status = 'paid',
      payment_date = p_payment_date,
      updated_at = now()
  where id = v_invoice.id;

  return jsonb_build_object(
    'message', 'incident_charge_closed',
    'incident_charge_id', v_incident.id,
    'invoice_id', v_invoice.id,
    'status', 'paid'
  );
end;
$$;


ALTER FUNCTION "public"."close_incident_charge"("p_incident_charge_id" "uuid", "p_invoice_id" "uuid", "p_payment_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payment_request_layout_data"("p_payment_request_id" "uuid", "p_company_bank_account_id" "uuid" DEFAULT NULL::"uuid", "p_payment_reference" "text" DEFAULT NULL::"text", "p_payment_concept" "text" DEFAULT NULL::"text", "p_scheduled_payment_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
      declare
        v_actor uuid;
        v_request_before public.payment_requests%rowtype;
        v_request_after public.payment_requests%rowtype;
        v_reference text;
        v_concept text;
        v_account_id uuid;
        v_schedule date;
        v_material_before timestamptz;
        v_direction_was_current boolean;
        v_direction_is_current boolean;
        v_direction_reapproval_required boolean := false;
        v_changed_fields text[];
        v_completed_fields text[];
        v_missing_before text[];
        v_missing_after text[];
      begin
        if p_payment_request_id is null then
          raise exception 'payment_request_required';
        end if;

        v_actor := public.approval_batch_require_finance();
        perform pg_advisory_xact_lock(
          hashtextextended(p_payment_request_id::text, 21021)
        );

        select *
          into v_request_before
        from public.payment_requests payment_request
        where payment_request.id = p_payment_request_id
        for update;

        if not found then
          raise exception 'payment_request_not_found';
        end if;

        if v_request_before.status::text in ('paid', 'cancelled')
           or public.approval_batch_request_has_any_execution_record(
             v_request_before.id
           ) then
          raise exception 'payment_request_layout_data_locked';
        end if;

        if v_request_before.proveedor_id is null or not exists (
          select 1
          from public.proveedores provider
          where provider.id = v_request_before.proveedor_id
            and coalesce(provider.activo, false)
        ) then
          raise exception 'proveedor_not_found_or_inactive';
        end if;

        v_account_id := coalesce(
          p_company_bank_account_id,
          v_request_before.company_bank_account_id
        );

        if v_account_id is not null and not exists (
          select 1
          from public.company_bank_accounts company_account
          where company_account.id = v_account_id
            and company_account.company_id = v_request_before.company_id
            and coalesce(company_account.active, false)
            and nullif(btrim(company_account.account_number), '') is not null
        ) then
          raise exception
            'company_bank_account_not_found_inactive_or_company_mismatch';
        end if;

        v_reference := coalesce(
          nullif(
            regexp_replace(
              coalesce(p_payment_reference, ''),
              '[[:space:]]',
              '',
              'g'
            ),
            ''
          ),
          nullif(btrim(v_request_before.payment_reference), '')
        );

        if v_reference is not null and v_reference !~ '^[0-9]+$' then
          raise exception 'payment_reference_must_be_numeric';
        end if;

        if v_reference is not null and char_length(v_reference) > 5 then
          raise exception 'payment_reference_too_long';
        end if;

        if p_payment_concept is null then
          v_concept := v_request_before.payment_concept;
        else
          v_concept := nullif(btrim(p_payment_concept), '');
        end if;

        if v_concept is not null and char_length(v_concept) > 120 then
          raise exception 'payment_concept_too_long';
        end if;

        if v_concept is not null and v_concept ~ '[[:cntrl:]]' then
          raise exception 'payment_concept_invalid_characters';
        end if;

        v_schedule := coalesce(
          p_scheduled_payment_date,
          v_request_before.scheduled_payment_date,
          v_request_before.due_date
        );
        v_material_before := v_request_before.approval_material_updated_at;
        v_direction_was_current :=
          public.approval_batch_request_has_current_direction_approval(
            v_request_before.id
          );
        v_missing_before :=
          public.payment_request_layout_missing_fields(v_request_before);

        v_changed_fields := array_remove(array[
          case
            when v_request_before.company_bank_account_id is distinct from
                 v_account_id then 'company_bank_account_id'
          end,
          case
            when v_request_before.payment_reference is distinct from
                 v_reference then 'payment_reference'
          end,
          case
            when v_request_before.payment_concept is distinct from
                 v_concept then 'payment_concept'
          end,
          case
            when v_request_before.scheduled_payment_date is distinct from
                 v_schedule then 'scheduled_payment_date'
          end
        ]::text[], null);

        perform set_config(
          'flux.payment_execution_rpc',
          v_request_before.id::text,
          true
        );

        update public.payment_requests payment_request
        set company_bank_account_id = v_account_id,
            payment_reference = v_reference,
            payment_concept = v_concept,
            scheduled_payment_date = v_schedule,
            scheduled_by = case
              when v_schedule is distinct from
                   payment_request.scheduled_payment_date then v_actor
              else payment_request.scheduled_by
            end,
            scheduled_at = case
              when v_schedule is distinct from
                   payment_request.scheduled_payment_date then clock_timestamp()
              else payment_request.scheduled_at
            end,
            updated_at = clock_timestamp()
        where payment_request.id = v_request_before.id;

        select *
          into v_request_after
        from public.payment_requests payment_request
        where payment_request.id = v_request_before.id;

        if v_request_after.approval_material_updated_at is distinct from
           v_material_before then
          raise exception
            'operational_update_changed_approval_material_timestamp';
        end if;

        v_direction_is_current :=
          public.approval_batch_request_has_current_direction_approval(
            v_request_after.id
          );

        if v_direction_was_current and not v_direction_is_current then
          raise exception 'operational_update_invalidated_direction_approval';
        end if;

        v_missing_after :=
          public.payment_request_layout_missing_fields(v_request_after);

        select coalesce(
          array_agg(completed_field.field_name order by completed_field.field_name),
          array[]::text[]
        )
          into v_completed_fields
        from unnest(v_missing_before) as completed_field(field_name)
        where not (completed_field.field_name = any(v_missing_after));

        v_direction_reapproval_required := not v_direction_is_current and exists (
          select 1
          from public.approval_batch_items batch_item
          where batch_item.payment_request_id = v_request_after.id
            and batch_item.removed_at is null
            and batch_item.director_status = 'approved'
            and batch_item.decided_at is not null
            and batch_item.decided_at <
                v_request_after.approval_material_updated_at
        );

        return jsonb_build_object(
          'payment_request_id', v_request_after.id,
          'direction_was_current', v_direction_was_current,
          'direction_approval_current', v_direction_is_current,
          'direction_reapproval_required', v_direction_reapproval_required,
          'approval_preserved',
            v_direction_was_current and v_direction_is_current,
          'execution_data_updated', cardinality(v_changed_fields) > 0,
          'changed_fields', to_jsonb(v_changed_fields),
          'completed_fields', to_jsonb(v_completed_fields),
          'missing_fields', to_jsonb(v_missing_after),
          'history_preserved', true
        );
      end
      $_$;


ALTER FUNCTION "public"."complete_payment_request_layout_data"("p_payment_request_id" "uuid", "p_company_bank_account_id" "uuid", "p_payment_reference" "text", "p_payment_concept" "text", "p_scheduled_payment_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_payment_request_layout_data"("p_payment_request_id" "uuid", "p_company_bank_account_id" "uuid", "p_payment_reference" "text", "p_payment_concept" "text", "p_scheduled_payment_date" "date") IS 'Finance-only atomic completion of payment-execution data. A null concept preserves the stored material value exactly.';



CREATE OR REPLACE FUNCTION "public"."complete_provider_payment_execution_data"("p_proveedor_id" "uuid", "p_destination_type" "text" DEFAULT NULL::"text", "p_clabe" "text" DEFAULT NULL::"text", "p_cuenta_bancaria" "text" DEFAULT NULL::"text", "p_convenio_number" "text" DEFAULT NULL::"text", "p_beneficiary_name" "text" DEFAULT NULL::"text", "p_banco" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_provider_before public.proveedores%rowtype;
  v_provider_after public.proveedores%rowtype;
  v_destination_type text;
  v_clabe text;
  v_cuenta_bancaria text;
  v_convenio_number text;
  v_beneficiary_name text;
  v_banco text;
  v_changed_fields text[];
  v_completed_fields text[];
  v_missing_before text[];
  v_missing_after text[];
begin
  if p_proveedor_id is null then
    raise exception 'proveedor_required';
  end if;

  v_actor := public.approval_batch_require_finance();
  perform pg_advisory_xact_lock(
    hashtextextended(p_proveedor_id::text, 21034)
  );

  select *
    into v_provider_before
  from public.proveedores provider
  where provider.id = p_proveedor_id
  for update;

  if not found or not coalesce(v_provider_before.activo, false) then
    raise exception 'proveedor_not_found_or_inactive';
  end if;

  v_destination_type := coalesce(
    lower(nullif(btrim(p_destination_type), '')),
    lower(nullif(btrim(v_provider_before.destination_type), ''))
  );
  v_clabe := coalesce(
    nullif(
      regexp_replace(coalesce(p_clabe, ''), '[[:space:]-]', '', 'g'),
      ''
    ),
    v_provider_before.clabe
  );
  v_cuenta_bancaria := coalesce(
    nullif(
      regexp_replace(
        coalesce(p_cuenta_bancaria, ''),
        '[[:space:]-]',
        '',
        'g'
      ),
      ''
    ),
    v_provider_before.cuenta_bancaria
  );
  v_convenio_number := coalesce(
    nullif(btrim(p_convenio_number), ''),
    v_provider_before.convenio_number
  );
  v_beneficiary_name := coalesce(
    nullif(btrim(p_beneficiary_name), ''),
    v_provider_before.beneficiary_name
  );
  v_banco := coalesce(
    nullif(btrim(p_banco), ''),
    v_provider_before.banco
  );

  v_missing_before :=
    public.provider_payment_execution_missing_fields(v_provider_before);
  v_changed_fields := array_remove(array[
    case
      when v_provider_before.destination_type is distinct from v_destination_type
        then 'destination_type'
    end,
    case when v_provider_before.clabe is distinct from v_clabe then 'clabe' end,
    case
      when v_provider_before.cuenta_bancaria is distinct from v_cuenta_bancaria
        then 'cuenta_bancaria'
    end,
    case
      when v_provider_before.convenio_number is distinct from v_convenio_number
        then 'convenio_number'
    end,
    case
      when v_provider_before.beneficiary_name is distinct from v_beneficiary_name
        then 'beneficiary_name'
    end,
    case when v_provider_before.banco is distinct from v_banco then 'banco' end
  ]::text[], null);

  perform set_config(
    'flux.provider_payment_execution_rpc',
    v_provider_before.id::text,
    true
  );

  update public.proveedores provider
  set destination_type = v_destination_type,
      clabe = v_clabe,
      cuenta_bancaria = v_cuenta_bancaria,
      convenio_number = v_convenio_number,
      beneficiary_name = v_beneficiary_name,
      banco = v_banco
  where provider.id = v_provider_before.id;

  select *
    into v_provider_after
  from public.proveedores provider
  where provider.id = v_provider_before.id;

  v_missing_after :=
    public.provider_payment_execution_missing_fields(v_provider_after);

  select coalesce(
    array_agg(completed_field.field_name order by completed_field.field_name),
    array[]::text[]
  )
    into v_completed_fields
  from unnest(v_missing_before) as completed_field(field_name)
  where not (completed_field.field_name = any(v_missing_after));

  return jsonb_build_object(
    'proveedor_id', v_provider_after.id,
    'execution_data_updated', cardinality(v_changed_fields) > 0,
    'changed_fields', to_jsonb(v_changed_fields),
    'completed_fields', to_jsonb(v_completed_fields),
    'missing_fields', to_jsonb(v_missing_after),
    'history_preserved', true
  );
end
$$;


ALTER FUNCTION "public"."complete_provider_payment_execution_data"("p_proveedor_id" "uuid", "p_destination_type" "text", "p_clabe" "text", "p_cuenta_bancaria" "text", "p_convenio_number" "text", "p_beneficiary_name" "text", "p_banco" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_provider_payment_execution_data"("p_proveedor_id" "uuid", "p_destination_type" "text", "p_clabe" "text", "p_cuenta_bancaria" "text", "p_convenio_number" "text", "p_beneficiary_name" "text", "p_banco" "text") IS 'Finance-only completion of banking data for the same legacy provider; returns field names but never banking values.';



CREATE OR REPLACE FUNCTION "public"."confirm_payment_layout"("p_layout_id" "uuid", "p_payment_date" "date", "p_registered_by" "uuid", "p_bank_reference" "text" DEFAULT NULL::"text", "p_storage_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_layout public.payment_layouts%rowtype;
  v_previous_status text;
  v_paid_count integer := 0;
  v_total_paid numeric := 0;
begin
  if p_payment_date is null then
    raise exception 'payment_date_required';
  end if;

  select *
  into v_layout
  from public.payment_layouts
  where id = p_layout_id
  for update;

  if not found then
    raise exception 'layout_not_found';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_registered_by
      and coalesce(active, true) = true
  ) then
    raise exception 'profile_not_found';
  end if;

  v_previous_status := v_layout.status;

  if v_layout.status = 'confirmed' then
    raise exception 'layout_already_confirmed';
  end if;

  if v_layout.status = 'cancelled' then
    raise exception 'layout_cancelled';
  end if;

  if v_layout.status not in ('uploaded', 'generated') then
    raise exception 'invalid_layout_status_for_confirmation';
  end if;

  select
    count(*),
    coalesce(sum(amount), 0)
  into
    v_paid_count,
    v_total_paid
  from public.payment_layout_lines
  where layout_id = p_layout_id
    and status = 'included';

  if v_paid_count = 0 then
    raise exception 'no_included_lines_to_confirm';
  end if;

  -- Crear comprobantes por cada línea incluida
  insert into public.payment_receipts (
    payment_request_id,
    layout_id,
    payment_date,
    amount,
    bank_reference,
    storage_path,
    registered_by
  )
  select
    pll.payment_request_id,
    p_layout_id,
    p_payment_date,
    pll.amount,
    p_bank_reference,
    p_storage_path,
    p_registered_by
  from public.payment_layout_lines pll
  where pll.layout_id = p_layout_id
    and pll.status = 'included';

  -- Marcar líneas como pagadas
  update public.payment_layout_lines
  set
    status = 'paid',
    updated_at = now()
  where layout_id = p_layout_id
    and status = 'included';

  -- Marcar solicitudes como pagadas
  update public.payment_requests pr
  set
    status = 'paid'::public.payment_request_status,
    paid_by = p_registered_by,
    paid_at = now(),
    updated_at = now()
  where pr.id in (
    select pll.payment_request_id
    from public.payment_layout_lines pll
    where pll.layout_id = p_layout_id
      and pll.status = 'paid'
  );

  -- Marcar layout como confirmado
  update public.payment_layouts
  set
    status = 'confirmed',
    updated_at = now()
  where id = p_layout_id;

  return jsonb_build_object(
    'layout_id', p_layout_id,
    'previous_status', v_previous_status,
    'new_status', 'confirmed',
    'paid_count', v_paid_count,
    'total_paid', v_total_paid,
    'payment_date', p_payment_date,
    'message', 'payment_layout_confirmed'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_payment_layout"("p_layout_id" "uuid", "p_payment_date" "date", "p_registered_by" "uuid", "p_bank_reference" "text", "p_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_payment_document_extraction"("p_extraction_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_application_date" "date", "p_amount_minor" bigint, "p_currency" "text", "p_bank_unique_folio" "text", "p_beneficiary_name" "text", "p_payment_reason" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_extraction public.payment_document_extractions%rowtype;
  v_actor uuid;
  v_currency text;
  v_folio text;
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_corrected_at timestamptz;
  v_result jsonb;
begin
  select * into v_extraction
  from public.payment_document_extractions
  where id = p_extraction_id
  for update;
  if not found then raise exception 'payment_extraction_not_found'; end if;

  v_actor := public.payment_reconciliation_require_finance(v_extraction.company_id);
  v_currency := public.payment_reconciliation_normalize_currency(p_currency);
  v_folio := upper(btrim(coalesce(p_bank_unique_folio, '')));
  v_payload := jsonb_build_object(
    'application_date', p_application_date,
    'amount_minor', p_amount_minor,
    'beneficiary_name', nullif(btrim(p_beneficiary_name), ''),
    'currency', v_currency,
    'extraction_id', p_extraction_id,
    'payment_reason', nullif(btrim(p_payment_reason), ''),
    'reason', nullif(btrim(p_reason), ''),
    'reference', v_folio
  );
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_extraction.company_id,
    'payment_extraction.correct',
    p_idempotency_key,
    v_payload_hash,
    v_actor
  );
  if v_replay is not null then return v_replay; end if;

  if v_extraction.updated_at is distinct from p_expected_updated_at then
    raise exception 'stale_payment_extraction';
  end if;
  if v_extraction.status not in ('review_required', 'blocked') then
    raise exception 'payment_extraction_not_correctable';
  end if;
  if p_application_date is null
     or p_amount_minor is null
     or p_amount_minor not between 1 and 9007199254740991
     or v_currency is null
     or v_folio !~ '^[A-Z0-9-]{8,120}$'
     or nullif(btrim(p_beneficiary_name), '') is null
     or char_length(btrim(p_beneficiary_name)) > 180
     or char_length(btrim(coalesce(p_payment_reason, ''))) > 500
     or char_length(btrim(coalesce(p_reason, ''))) not between 10 and 500 then
    raise exception 'invalid_payment_extraction_correction';
  end if;

  v_corrected_at := clock_timestamp();
  insert into public.payment_extraction_corrections(
    company_id, extraction_id, previous_values, corrected_values,
    reason, corrected_by, corrected_at
  ) values (
    v_extraction.company_id,
    v_extraction.id,
    jsonb_build_object(
      'application_date', v_extraction.application_date,
      'amount_minor', v_extraction.amount_minor,
      'bank_unique_folio', v_extraction.bank_unique_folio,
      'beneficiary_name', v_extraction.beneficiary_name,
      'currency', v_extraction.currency,
      'payment_reason', v_extraction.payment_reason
    ),
    v_payload - 'extraction_id' - 'reason',
    btrim(p_reason),
    v_actor,
    v_corrected_at
  );

  update public.payment_document_extractions
  set application_date = p_application_date,
      amount_minor = p_amount_minor,
      currency = v_currency,
      bank_unique_folio = v_folio,
      beneficiary_name = btrim(p_beneficiary_name),
      payment_reason = nullif(btrim(p_payment_reason), ''),
      status = 'review_required',
      reviewed_by = null,
      reviewed_at = null,
      rejection_reason = null,
      updated_at = v_corrected_at
  where id = v_extraction.id;

  perform public.append_financial_outbox_event_internal(
    'payment_extraction.corrected',
    'payment_document_extraction',
    v_extraction.id,
    v_extraction.company_id,
    v_actor,
    jsonb_build_object(
      'corrected_fields',
      jsonb_build_array(
        'application_date', 'amount_minor', 'currency',
        'bank_unique_folio', 'beneficiary_name', 'payment_reason'
      ),
      'extraction_id', v_extraction.id
    ),
    v_extraction.batch_id,
    null,
    'extraction-corrected:' || v_payload_hash
  );

  v_result := jsonb_build_object(
    'extraction_id', v_extraction.id,
    'status', 'review_required',
    'updated_at', v_corrected_at
  );
  return public.payment_reconciliation_store_command(
    v_extraction.company_id,
    'payment_extraction.correct',
    p_idempotency_key,
    v_payload_hash,
    v_actor,
    v_result
  );
end
$_$;


