CREATE OR REPLACE FUNCTION "public"."create_approval_batch"("p_company_id" "uuid", "p_label" "text" DEFAULT NULL::"text", "p_period_start" "date" DEFAULT NULL::"date", "p_period_end" "date" DEFAULT NULL::"date", "p_director_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_period_end date;
  v_period_start date;
  v_company_name text;
  v_label text;
  v_id uuid;
begin
  v_actor := public.approval_batch_require_finance();

  if p_director_id is null then
    raise exception 'company_director_selection_required';
  end if;

  select coalesce(nullif(btrim(company.legal_name), ''), company.name)
    into v_company_name
  from public.companies company
  where company.id = p_company_id
    and coalesce(company.active, false);

  if v_company_name is null then
    raise exception 'company_not_found_or_inactive';
  end if;

  if not exists (
    select 1
    from public.company_directors director_assignment
    join public.profiles director_profile
      on director_profile.id = director_assignment.director_profile_id
    where director_assignment.company_id = p_company_id
      and director_assignment.director_profile_id = p_director_id
      and director_assignment.active
      and director_profile.active
      and exists (
        select 1
        from public.user_roles user_role
        join public.roles role on role.id = user_role.role_id
        where user_role.profile_id = director_assignment.director_profile_id
          and lower(btrim(role.name)) =
            any(public.approval_batch_direction_roles())
      )
      and exists (
        select 1
        from public.profile_company_memberships membership
        where membership.profile_id = director_assignment.director_profile_id
          and membership.company_id = director_assignment.company_id
          and membership.active
      )
  ) then
    raise exception 'company_director_not_active_or_ineligible';
  end if;

  v_period_end := coalesce(
    p_period_end,
    current_date + mod(3 - extract(isodow from current_date)::integer + 7, 7)
  );
  v_period_start := coalesce(p_period_start, v_period_end - 6);

  if v_period_start > v_period_end then
    raise exception 'invalid_batch_period';
  end if;

  v_label := coalesce(
    nullif(btrim(p_label), ''),
    'Corte ' || v_company_name || ' ' ||
      to_char(v_period_end, 'IYYY-"W"IW')
  );

  insert into public.approval_batches(
    company_id,
    label,
    period_start,
    period_end,
    director_id,
    created_by,
    notes
  ) values (
    p_company_id,
    v_label,
    v_period_start,
    v_period_end,
    p_director_id,
    v_actor,
    nullif(btrim(coalesce(p_notes, '')), '')
  )
  returning id into v_id;

  return jsonb_build_object(
    'batch_id', v_id,
    'status', 'draft',
    'label', v_label,
    'director_id', p_director_id
  );
end
$$;


ALTER FUNCTION "public"."create_approval_batch"("p_company_id" "uuid", "p_label" "text", "p_period_start" "date", "p_period_end" "date", "p_director_id" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_approval_batch"("p_company_id" "uuid", "p_label" "text", "p_period_start" "date", "p_period_end" "date", "p_director_id" "uuid", "p_notes" "text") IS 'Creates one batch with exactly one explicitly selected active and eligible company Director.';



CREATE OR REPLACE FUNCTION "public"."create_cash_fund"("p_payment_request_id" "uuid", "p_responsible_profile_id" "uuid", "p_due_date" "date", "p_delivery_method" "text", "p_delivered_by" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_fund_id uuid;
  v_delivery_method text;
  v_request_payment_method text;
  v_readiness jsonb;
  v_cash_fund_block_reason text;
begin
  perform public.approval_batch_require_finance();

  if p_payment_request_id is null then
    raise exception 'payment_request_required';
  end if;
  if p_responsible_profile_id is null then
    raise exception 'responsible_profile_required';
  end if;
  if p_due_date is null then
    raise exception 'due_date_required';
  end if;

  v_delivery_method := lower(nullif(btrim(coalesce(p_delivery_method, '')), ''));
  if v_delivery_method not in ('cash', 'check') then
    raise exception 'invalid_delivery_method';
  end if;

  select *
    into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then
    raise exception 'payment_request_not_found';
  end if;

  v_request_payment_method := lower(
    coalesce(
      nullif(btrim(v_request.payment_method), ''),
      nullif(btrim(v_request.request_type::text), '')
    )
  );
  v_request_payment_method := case v_request_payment_method
    when 'efectivo' then 'cash'
    when 'cheque' then 'check'
    else v_request_payment_method
  end;

  if v_request_payment_method not in ('cash', 'check') then
    raise exception 'payment_request_must_be_cash_or_check';
  end if;
  if v_delivery_method <> v_request_payment_method then
    raise exception 'delivery_method_must_match_payment_request';
  end if;
  if coalesce(v_request.amount_requested, 0) <= 0 then
    raise exception 'invalid_request_amount';
  end if;
  if not exists (
    select 1
    from public.profiles
    where id = p_responsible_profile_id
      and coalesce(active, true) = true
  ) then
    raise exception 'responsible_profile_not_found';
  end if;
  if p_delivered_by is not null and not exists (
    select 1
    from public.profiles
    where id = p_delivered_by
      and coalesce(active, true) = true
  ) then
    raise exception 'delivered_by_profile_not_found';
  end if;
  if exists (
    select 1
    from public.cash_funds
    where payment_request_id = p_payment_request_id
  ) then
    raise exception 'cash_fund_already_exists';
  end if;

  v_readiness := public.get_payment_request_execution_readiness(v_request.id);
  if not coalesce((v_readiness ->> 'can_create_cash_fund')::boolean, false) then
    v_cash_fund_block_reason := coalesce(
      v_readiness ->> 'cash_fund_block_reason',
      'cash_fund_execution_not_authorized'
    );
    raise exception '%', v_cash_fund_block_reason;
  end if;

  insert into public.cash_funds (
    company_id,
    payment_request_id,
    responsible_profile_id,
    assigned_amount,
    verified_amount,
    assignment_date,
    due_date,
    status,
    delivery_method,
    delivered_by,
    delivered_at,
    notes
  ) values (
    v_request.company_id,
    p_payment_request_id,
    p_responsible_profile_id,
    v_request.amount_requested,
    0,
    current_date,
    p_due_date,
    'pending_receipt',
    v_delivery_method,
    p_delivered_by,
    case when p_delivered_by is not null then now() else null end,
    p_notes
  )
  returning id into v_fund_id;

  update public.payment_requests
  set operational_comments = concat_ws(
        E'\n',
        nullif(operational_comments, ''),
        'Fondo de ' || v_delivery_method || ' creado. Pendiente de comprobacion.'
      ),
      updated_at = now()
  where id = p_payment_request_id;

  return jsonb_build_object(
    'message', 'cash_fund_created',
    'cash_fund_id', v_fund_id,
    'payment_request_id', p_payment_request_id,
    'responsible_profile_id', p_responsible_profile_id,
    'assigned_amount', v_request.amount_requested,
    'due_date', p_due_date,
    'delivery_method', v_delivery_method,
    'status', 'pending_receipt'
  );
end
$$;


ALTER FUNCTION "public"."create_cash_fund"("p_payment_request_id" "uuid", "p_responsible_profile_id" "uuid", "p_due_date" "date", "p_delivery_method" "text", "p_delivered_by" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_cash_fund"("p_payment_request_id" "uuid", "p_responsible_profile_id" "uuid", "p_due_date" "date", "p_delivery_method" "text", "p_delivered_by" "uuid", "p_notes" "text") IS 'Creates one cash/check fund for Finance when canonical closed-batch, current-extraordinary or compatible legacy readiness permits execution.';



CREATE OR REPLACE FUNCTION "public"."create_cash_reconciliation"("p_cash_fund_id" "uuid", "p_submitted_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_fund public.cash_funds%rowtype;
  v_reconciliation_id uuid;
begin
  if p_cash_fund_id is null then
    raise exception 'cash_fund_required';
  end if;

  if p_submitted_by is null then
    raise exception 'submitted_by_required';
  end if;

  select *
  into v_fund
  from public.cash_funds
  where id = p_cash_fund_id
  for update;

  if not found then
    raise exception 'cash_fund_not_found';
  end if;

  if v_fund.status in ('closed', 'cancelled', 'verified') then
    raise exception 'cash_fund_not_open_for_reconciliation';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_submitted_by
      and coalesce(active, true) = true
  ) then
    raise exception 'submitted_by_profile_not_found';
  end if;

  if p_submitted_by <> v_fund.responsible_profile_id
     and not public.current_user_has_role(array[
       'admin',
       'finance',
       'finanzas',
       'approver_2',
       'aprobador_2'
     ])
  then
    raise exception 'not_allowed_to_create_reconciliation';
  end if;

  if exists (
    select 1
    from public.cash_reconciliations
    where cash_fund_id = p_cash_fund_id
      and status in ('draft', 'submitted', 'correction_requested')
  ) then
    raise exception 'open_reconciliation_already_exists';
  end if;

  insert into public.cash_reconciliations (
    cash_fund_id,
    submitted_by,
    status
  )
  values (
    p_cash_fund_id,
    p_submitted_by,
    'draft'
  )
  returning id into v_reconciliation_id;

  return jsonb_build_object(
    'message', 'cash_reconciliation_created',
    'reconciliation_id', v_reconciliation_id,
    'cash_fund_id', p_cash_fund_id,
    'status', 'draft'
  );
end;
$$;


ALTER FUNCTION "public"."create_cash_reconciliation"("p_cash_fund_id" "uuid", "p_submitted_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_incident_charge"("p_member_id" "uuid" DEFAULT NULL::"uuid", "p_external_name" "text" DEFAULT NULL::"text", "p_external_rfc" "text" DEFAULT NULL::"text", "p_referred_by_member_id" "uuid" DEFAULT NULL::"uuid", "p_company_id" "uuid" DEFAULT NULL::"uuid", "p_cost_center_id" "uuid" DEFAULT NULL::"uuid", "p_budget_category_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_incident_date" "date" DEFAULT NULL::"date", "p_registered_by" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member public.members%rowtype;
  v_referred_member public.members%rowtype;
  v_incident_id uuid;
  v_receiver_type text;
  v_receiver_name text;
begin
  if p_member_id is null and nullif(trim(coalesce(p_external_name, '')), '') is null then
    raise exception 'incident_receiver_required';
  end if;

  if p_member_id is not null and nullif(trim(coalesce(p_external_name, '')), '') is not null then
    raise exception 'incident_receiver_must_be_member_or_external';
  end if;

  if nullif(trim(coalesce(p_description, '')), '') is null then
    raise exception 'description_required';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'invalid_incident_amount';
  end if;

  if p_incident_date is null then
    raise exception 'incident_date_required';
  end if;

  if p_member_id is not null then
    select *
    into v_member
    from public.members
    where id = p_member_id;

    if not found then
      raise exception 'member_not_found';
    end if;

    v_receiver_type := 'member';
    v_receiver_name := v_member.full_name;
  else
    v_receiver_type := 'external';
    v_receiver_name := trim(p_external_name);
  end if;

  if p_referred_by_member_id is not null then
    select *
    into v_referred_member
    from public.members
    where id = p_referred_by_member_id;

    if not found then
      raise exception 'referred_member_not_found';
    end if;
  end if;

  insert into public.incident_charges (
    member_id,
    external_name,
    external_rfc,
    referred_by_member_id,
    company_id,
    cost_center_id,
    budget_category_id,
    description,
    amount,
    incident_date,
    status,
    registered_by,
    notes
  )
  values (
    p_member_id,
    nullif(trim(coalesce(p_external_name, '')), ''),
    nullif(trim(coalesce(p_external_rfc, '')), ''),
    p_referred_by_member_id,
    p_company_id,
    p_cost_center_id,
    p_budget_category_id,
    trim(p_description),
    p_amount,
    p_incident_date,
    'open',
    p_registered_by,
    p_notes
  )
  returning id into v_incident_id;

  return jsonb_build_object(
    'message', 'incident_charge_created',
    'incident_charge_id', v_incident_id,
    'receiver_type', v_receiver_type,
    'receiver_name', v_receiver_name,
    'amount', p_amount,
    'status', 'open'
  );
end;
$$;


ALTER FUNCTION "public"."create_incident_charge"("p_member_id" "uuid", "p_external_name" "text", "p_external_rfc" "text", "p_referred_by_member_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_description" "text", "p_amount" numeric, "p_incident_date" "date", "p_registered_by" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_invoice_record"("p_invoice_type" "text", "p_reference_id" "uuid", "p_fiscal_uuid" "text" DEFAULT NULL::"text", "p_series_folio" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_issue_date" "date" DEFAULT NULL::"date", "p_storage_path_xml" "text" DEFAULT NULL::"text", "p_storage_path_pdf" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_receiver jsonb;
  v_charge public.maintenance_fee_charges%rowtype;
  v_incident public.incident_charges%rowtype;
  v_invoice_id uuid;
begin
  if p_invoice_type not in ('maintenance_fee', 'incident') then
    raise exception 'invalid_invoice_type';
  end if;

  if p_reference_id is null then
    raise exception 'invoice_reference_required';
  end if;

  if p_amount is null or p_amount < 0 then
    raise exception 'invalid_invoice_amount';
  end if;

  if p_issue_date is null then
    raise exception 'issue_date_required';
  end if;

  if p_invoice_type = 'maintenance_fee' then
    select *
    into v_charge
    from public.maintenance_fee_charges
    where id = p_reference_id
    for update;

    if not found then
      raise exception 'charge_not_found';
    end if;

    v_receiver := public.resolve_invoice_receiver(
      p_charge_id => v_charge.id,
      p_incident_charge_id => null
    );

    insert into public.invoices (
      invoice_type,
      member_id,
      external_name,
      receiver_rfc,
      charge_id,
      incident_charge_id,
      fiscal_uuid,
      series_folio,
      amount,
      issue_date,
      status,
      storage_path_xml,
      storage_path_pdf
    )
    values (
      'maintenance_fee',
      (v_receiver ->> 'member_id')::uuid,
      null,
      v_receiver ->> 'rfc',
      v_charge.id,
      null,
      p_fiscal_uuid,
      p_series_folio,
      p_amount,
      p_issue_date,
      'issued',
      p_storage_path_xml,
      p_storage_path_pdf
    )
    returning id into v_invoice_id;

    update public.maintenance_fee_charges
    set invoice_id = v_invoice_id,
        updated_at = now()
    where id = v_charge.id;

  else
    select *
    into v_incident
    from public.incident_charges
    where id = p_reference_id
    for update;

    if not found then
      raise exception 'incident_charge_not_found';
    end if;

    v_receiver := public.resolve_invoice_receiver(
      p_charge_id => null,
      p_incident_charge_id => v_incident.id
    );

    insert into public.invoices (
      invoice_type,
      member_id,
      external_name,
      receiver_rfc,
      charge_id,
      incident_charge_id,
      fiscal_uuid,
      series_folio,
      amount,
      issue_date,
      status,
      storage_path_xml,
      storage_path_pdf
    )
    values (
      'incident',
      nullif(v_receiver ->> 'member_id', '')::uuid,
      v_receiver ->> 'external_name',
      v_receiver ->> 'rfc',
      null,
      v_incident.id,
      p_fiscal_uuid,
      p_series_folio,
      p_amount,
      p_issue_date,
      'issued',
      p_storage_path_xml,
      p_storage_path_pdf
    )
    returning id into v_invoice_id;

    update public.incident_charges
    set invoice_id = v_invoice_id,
        status = 'invoiced',
        updated_at = now()
    where id = v_incident.id;
  end if;

  return jsonb_build_object(
    'message', 'invoice_record_created',
    'invoice_id', v_invoice_id,
    'invoice_type', p_invoice_type,
    'reference_id', p_reference_id,
    'status', 'issued',
    'amount', p_amount
  );
end;
$$;


ALTER FUNCTION "public"."create_invoice_record"("p_invoice_type" "text", "p_reference_id" "uuid", "p_fiscal_uuid" "text", "p_series_folio" "text", "p_amount" numeric, "p_issue_date" "date", "p_storage_path_xml" "text", "p_storage_path_pdf" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payable_snapshot_internal"("p_payment_request_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_status" "text", "p_authorized_by" "uuid", "p_authorized_at" timestamp with time zone, "p_materialized_by" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_existing public.payable_snapshots%rowtype;
  v_currency text;
  v_amount_minor bigint;
  v_version integer;
  v_id uuid;
  v_readiness jsonb;
  v_expected_authorization_source text;
begin
  if p_source_type not in ('approval_batch_item', 'extraordinary_authorization', 'legacy_backfill')
     or p_source_id is null or p_authorized_by is null or p_authorized_at is null
     or p_materialized_by is null then
    raise exception 'invalid_snapshot_source';
  end if;
  select * into v_request
  from public.payment_requests pr
  where pr.id = p_payment_request_id
  for update;
  if not found or v_request.company_id is null then
    raise exception 'payment_request_not_found';
  end if;

  if p_source_type = 'approval_batch_item' then
    if p_source_status is distinct from 'closed' or not exists (
      select 1
      from public.approval_batch_items item
      join public.approval_batches batch on batch.id = item.batch_id
      where item.id = p_source_id
        and item.payment_request_id = v_request.id
        and item.removed_at is null
        and item.director_status = 'approved'
        and item.decided_by = p_authorized_by
        and item.decided_at is not distinct from p_authorized_at
        and batch.status = 'closed'
        and batch.closed_by = p_materialized_by
        and batch.closed_at is not null
    ) then
      raise exception 'invalid_closed_batch_snapshot_source';
    end if;
    v_expected_authorization_source := 'closed_batch';
  elsif p_source_type = 'extraordinary_authorization' then
    if p_source_status is distinct from 'active' or not exists (
      select 1
      from public.payment_request_extraordinary_authorizations extraordinary_authorization
      where extraordinary_authorization.id = p_source_id
        and extraordinary_authorization.payment_request_id = v_request.id
        and extraordinary_authorization.status = 'active'
        and extraordinary_authorization.authorized_by = p_authorized_by
        and extraordinary_authorization.authorized_at is not distinct from p_authorized_at
        and p_materialized_by = extraordinary_authorization.authorized_by
    ) then
      raise exception 'invalid_extraordinary_snapshot_source';
    end if;
    v_expected_authorization_source := 'extraordinary';
  else
    raise exception 'legacy_snapshot_backfill_not_enabled';
  end if;

  v_readiness := public.get_payment_request_execution_readiness(v_request.id);
  if not coalesce((v_readiness->>'can_execute')::boolean, false)
     or v_readiness->>'authorization_source' is distinct from v_expected_authorization_source
     or p_authorized_at < v_request.approval_material_updated_at then
    raise exception 'snapshot_source_not_currently_payable';
  end if;
  v_currency := public.payment_reconciliation_normalize_currency(v_request.currency);
  v_amount_minor := public.payment_amount_to_minor(v_request.amount_requested, v_currency);

  select * into v_existing
  from public.payable_snapshots snapshot
  where snapshot.source_type = p_source_type and snapshot.source_id = p_source_id;
  if found then
    if v_existing.payment_request_id <> p_payment_request_id
       or v_existing.amount_minor <> v_amount_minor
       or v_existing.currency <> v_currency
       or v_existing.authorized_by <> p_authorized_by
       or v_existing.authorized_at <> p_authorized_at then
      raise exception 'payable_snapshot_source_conflict';
    end if;
    return v_existing.id;
  end if;

  if exists (
    select 1
    from public.payment_allocation_reservations reservation
    join public.payment_allocation_items item on item.plan_id = reservation.plan_id
    join public.payable_snapshots snapshot on snapshot.id = item.snapshot_id
    where snapshot.payment_request_id = p_payment_request_id
      and reservation.status = 'active' and reservation.expires_at > now()
  ) then
    raise exception 'payable_snapshot_reapproval_blocked_by_active_reservation';
  end if;
  if exists (
    select 1
    from public.payment_allocation_movements movement
    join public.payable_snapshots snapshot on snapshot.id = movement.snapshot_id
    where snapshot.payment_request_id = p_payment_request_id
    group by movement.snapshot_id
    having sum(case movement.movement_type when 'confirmation' then movement.amount_minor else -movement.amount_minor end) <> 0
  ) then
    raise exception 'payable_snapshot_reapproval_blocked_by_confirmed_allocations';
  end if;

  select coalesce(max(snapshot.version), 0) + 1 into v_version
  from public.payable_snapshots snapshot
  where snapshot.payment_request_id = p_payment_request_id;

  insert into public.payable_snapshots(
    payment_request_id, company_id, version, amount_minor, currency,
    source_type, source_id, source_status, source_approval_material_updated_at,
    authorized_by, authorized_at, materialized_by, materialized_at, reason
  ) values (
    v_request.id, v_request.company_id, v_version, v_amount_minor, v_currency,
    p_source_type, p_source_id, p_source_status, v_request.approval_material_updated_at,
    p_authorized_by, p_authorized_at, p_materialized_by, clock_timestamp(),
    nullif(btrim(p_reason), '')
  ) returning id into v_id;
  perform public.append_financial_outbox_event_internal(
    'payable_snapshot.created',
    'payable_snapshot',
    v_id,
    v_request.company_id,
    p_materialized_by,
    jsonb_build_object(
      'amount_minor', v_amount_minor,
      'currency', v_currency,
      'payment_request_id', v_request.id,
      'snapshot_id', v_id,
      'source_id', p_source_id,
      'source_type', p_source_type,
      'version', v_version
    ),
    v_request.id,
    p_source_id,
    'payable_snapshot.created:' || p_source_type || ':' || p_source_id::text
  );
  return v_id;
end
$$;


ALTER FUNCTION "public"."create_payable_snapshot_internal"("p_payment_request_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_source_status" "text", "p_authorized_by" "uuid", "p_authorized_at" timestamp with time zone, "p_materialized_by" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_ingestion_batch"("p_company_id" "uuid", "p_file_name" "text", "p_file_size_bytes" bigint, "p_document_sha256" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := public.payment_reconciliation_require_finance(p_company_id);
  v_sha text := lower(btrim(p_document_sha256));
  v_file_name text := public.payment_reconciliation_redact_free_text(p_file_name, 255);
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_existing record;
  v_batch_id uuid := gen_random_uuid();
  v_document_id uuid := gen_random_uuid();
  v_storage_path text;
  v_result jsonb;
begin
  v_payload := jsonb_build_object(
    'company_id', p_company_id,
    'document_sha256', v_sha,
    'file_name', v_file_name,
    'file_size_bytes', p_file_size_bytes
  );
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    p_company_id, 'payment_batch.create', p_idempotency_key, v_payload_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;

  if v_sha !~ '^[0-9a-f]{64}$' then raise exception 'invalid_document_sha256'; end if;
  if v_file_name is null or char_length(v_file_name) not between 1 and 255
     or v_file_name ~ '[/\\]' or v_file_name ~ '[[:cntrl:]]'
     or lower(v_file_name) !~ '\.pdf$' then
    raise exception 'invalid_pdf_file_name';
  end if;
  if p_file_size_bytes is null or p_file_size_bytes not between 1 and 26214400 then
    raise exception 'invalid_pdf_file_size';
  end if;

  select batch.id, batch.status, document.id as document_id, document.storage_bucket, document.storage_path
    into v_existing
  from public.payment_ingestion_batches batch
  join public.payment_documents document on document.batch_id = batch.id
  where batch.company_id = p_company_id and batch.document_sha256 = v_sha;
  if found then
    v_result := jsonb_build_object(
      'batch_id', v_existing.id,
      'document_id', v_existing.document_id,
      'storage_bucket', v_existing.storage_bucket,
      'storage_path', v_existing.storage_path,
      'status', v_existing.status,
      'duplicate', true
    );
    return public.payment_reconciliation_store_command(
      p_company_id, 'payment_batch.create', p_idempotency_key, v_payload_hash, v_actor, v_result
    );
  end if;

  v_storage_path := p_company_id::text || '/' || v_batch_id::text || '/source.pdf';
  insert into public.payment_ingestion_batches(
    id, company_id, document_sha256, original_file_name, file_size_bytes,
    idempotency_key, created_by
  ) values (
    v_batch_id, p_company_id, v_sha, v_file_name, p_file_size_bytes,
    p_idempotency_key, v_actor
  );
  insert into public.payment_documents(
    id, batch_id, company_id, storage_path, sha256, file_size_bytes
  ) values (
    v_document_id, v_batch_id, p_company_id, v_storage_path, v_sha,
    p_file_size_bytes
  );
  v_result := jsonb_build_object(
    'batch_id', v_batch_id,
    'document_id', v_document_id,
    'storage_bucket', 'payment-batch-documents',
    'storage_path', v_storage_path,
    'duplicate', false
  );
  return public.payment_reconciliation_store_command(
    p_company_id, 'payment_batch.create', p_idempotency_key, v_payload_hash, v_actor, v_result
  );
end
$_$;


ALTER FUNCTION "public"."create_payment_ingestion_batch"("p_company_id" "uuid", "p_file_name" "text", "p_file_size_bytes" bigint, "p_document_sha256" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_layout"("p_period_start" "date", "p_period_end" "date", "p_generated_by" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_company_id" "uuid" DEFAULT NULL::"uuid", "p_company_bank_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_layout_id uuid;
  v_layout_number text;
  v_layout_name text;
  v_request_id uuid;
  v_locked_request_ids uuid[] := array[]::uuid[];
  v_candidates jsonb := '[]'::jsonb;
  v_payment_count integer := 0;
  v_company_count integer := 0;
  v_total_amount numeric := 0;
  v_regular_count integer := 0;
  v_extraordinary_count integer := 0;
  v_legacy_count integer := 0;
  v_rejected_count integer := 0;
  v_pending_close_count integer := 0;
  v_pending_director_count integer := 0;
  v_direction_reapproval_count integer := 0;
  v_invalid_count integer := 0;
  v_already_executed_count integer := 0;
  v_invalid_requests jsonb := '[]'::jsonb;
begin
  v_actor := public.approval_batch_require_finance();
  if p_generated_by is not null and p_generated_by <> v_actor then
    raise exception 'generated_by_must_match_authenticated_actor';
  end if;
  if p_period_start is null or p_period_end is null then
    raise exception 'period_dates_required';
  end if;
  if p_period_start > p_period_end then
    raise exception 'invalid_period_range';
  end if;
  if p_company_id is not null and not exists (
    select 1 from public.companies c where c.id = p_company_id
  ) then
    raise exception 'company_not_found';
  end if;
  if p_company_bank_account_id is not null and not exists (
    select 1 from public.company_bank_accounts cba
    where cba.id = p_company_bank_account_id
      and coalesce(cba.active, true)
      and (p_company_id is null or cba.company_id = p_company_id)
  ) then
    raise exception 'company_bank_account_not_found_or_inactive';
  end if;

  for v_request_id in
    select distinct c.payment_request_id
    from public.approval_batch_payment_layout_candidates(
      p_period_start,
      p_period_end,
      p_company_id,
      p_company_bank_account_id
    ) c
    order by c.payment_request_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_request_id::text, 21021));
    perform 1
    from public.payment_requests pr
    where pr.id = v_request_id
    for update;
    if found then
      v_locked_request_ids := array_append(v_locked_request_ids, v_request_id);
    end if;
  end loop;

  select coalesce(jsonb_agg(to_jsonb(c) order by c.payment_request_id), '[]'::jsonb)
    into v_candidates
  from public.approval_batch_payment_layout_candidates(
    p_period_start,
    p_period_end,
    p_company_id,
    p_company_bank_account_id
  ) c
  where c.payment_request_id = any(v_locked_request_ids);

  select
    count(*) filter (where c.classification = 'ready_regular'),
    count(*) filter (where c.classification = 'ready_extraordinary'),
    count(*) filter (where c.classification = 'legacy_eligible'),
    count(*) filter (where c.classification = 'rejected_by_direction'),
    count(*) filter (where c.classification = 'pending_finance_close'),
    count(*) filter (where c.classification = 'pending_director'),
    count(*) filter (where c.classification = 'direction_reapproval_required'),
    count(*) filter (where c.classification = 'invalid_data'),
    count(*) filter (where c.classification = 'already_executed')
  into
    v_regular_count,
    v_extraordinary_count,
    v_legacy_count,
    v_rejected_count,
    v_pending_close_count,
    v_pending_director_count,
    v_direction_reapproval_count,
    v_invalid_count,
    v_already_executed_count
  from jsonb_to_recordset(v_candidates) as c(
    classification text,
    payment_request_id uuid
  );

  v_payment_count := v_regular_count + v_extraordinary_count + v_legacy_count;
  select coalesce(jsonb_agg(jsonb_build_object(
    'payment_request_id', c.payment_request_id,
    'request_number', c.request_number,
    'reason', c.classification_reason,
    'missing_fields', c.missing_fields
  ) order by c.request_number), '[]'::jsonb)
  into v_invalid_requests
  from jsonb_to_recordset(v_candidates) as c(
    classification text,
    classification_reason text,
    payment_request_id uuid,
    request_number text,
    missing_fields text[]
  )
  where c.classification = 'invalid_data';

  if v_payment_count = 0 then
    return jsonb_build_object(
      'layout_id', null,
      'status', 'not_created',
      'payment_count', 0,
      'company_count', 0,
      'total_amount', 0,
      'ready_regular_count', v_regular_count,
      'extraordinary_count', v_extraordinary_count,
      'legacy_count', v_legacy_count,
      'rejected_count', v_rejected_count,
      'pending_close_count', v_pending_close_count,
      'pending_director_count', v_pending_director_count,
      'direction_reapproval_count', v_direction_reapproval_count,
      'invalid_count', v_invalid_count,
      'already_executed_count', v_already_executed_count,
      'invalid_requests', v_invalid_requests,
      'message', 'no_valid_payment_requests'
    );
  end if;

  v_layout_number := 'LAY-' || extract(year from p_period_start)::int || '-'
    || lpad(nextval('public.payment_layout_number_seq')::text, 4, '0');
  v_layout_name := coalesce(
    nullif(btrim(p_name), ''),
    'Layout BBVA - ' || p_period_start::text || ' a ' || p_period_end::text
  );

  insert into public.payment_layouts(
    layout_number,
    name,
    period_start,
    period_end,
    status,
    generated_by,
    generated_at
  ) values (
    v_layout_number,
    v_layout_name,
    p_period_start,
    p_period_end,
    'draft',
    v_actor,
    now()
  ) returning id into v_layout_id;

  insert into public.payment_layout_lines(
    layout_id,
    payment_request_id,
    company_id,
    proveedor_id,
    company_bank_account_id,
    source_account_number,
    company_name,
    destination_type,
    destination_value,
    beneficiary_name,
    amount,
    payment_reference,
    payment_concept,
    request_number,
    status
  )
  select
    v_layout_id,
    payment_request_id,
    company_id,
    proveedor_id,
    company_bank_account_id,
    source_account_number,
    company_name,
    destination_type,
    destination_value,
    beneficiary_name,
    amount,
    payment_reference,
    payment_concept,
    request_number,
    'included'
  from jsonb_to_recordset(v_candidates) as c(
    classification text,
    payment_request_id uuid,
    request_number text,
    company_id uuid,
    proveedor_id uuid,
    company_bank_account_id uuid,
    source_account_number text,
    company_name text,
    destination_type text,
    destination_value text,
    beneficiary_name text,
    amount numeric,
    payment_reference text,
    payment_concept text
  )
  where c.classification in ('ready_regular', 'ready_extraordinary', 'legacy_eligible')
  order by c.request_number, c.payment_request_id;

  get diagnostics v_payment_count = row_count;
  select count(distinct company_id), coalesce(sum(amount), 0)
    into v_company_count, v_total_amount
  from public.payment_layout_lines
  where layout_id = v_layout_id;

  update public.payment_layouts
  set company_count = v_company_count,
      payment_count = v_payment_count,
      total_amount = v_total_amount,
      updated_at = now()
  where id = v_layout_id;

  update public.payment_requests pr
  set status = 'finance_validation'::public.payment_request_status,
      scheduled_by = v_actor,
      scheduled_at = now(),
      updated_at = now()
  where pr.id in (
    select pll.payment_request_id
    from public.payment_layout_lines pll
    where pll.layout_id = v_layout_id
  );

  return jsonb_build_object(
    'layout_id', v_layout_id,
    'layout_number', v_layout_number,
    'status', 'draft',
    'payment_count', v_payment_count,
    'company_count', v_company_count,
    'total_amount', v_total_amount,
    'ready_regular_count', v_regular_count,
    'extraordinary_count', v_extraordinary_count,
    'legacy_count', v_legacy_count,
    'rejected_count', v_rejected_count,
    'pending_close_count', v_pending_close_count,
    'pending_director_count', v_pending_director_count,
    'direction_reapproval_count', v_direction_reapproval_count,
    'invalid_count', v_invalid_count,
    'already_executed_count', v_already_executed_count,
    'invalid_requests', v_invalid_requests,
    'message', 'layout_created_with_batch_controls'
  );
end
$$;


ALTER FUNCTION "public"."create_payment_layout"("p_period_start" "date", "p_period_end" "date", "p_generated_by" "uuid", "p_name" "text", "p_company_id" "uuid", "p_company_bank_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_request"("p_proveedor_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount_requested" numeric, "p_currency" "text" DEFAULT 'MXN'::"text", "p_exchange_rate" numeric DEFAULT 1, "p_description" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_requested_by" "uuid" DEFAULT NULL::"uuid", "p_is_extraordinary_adjustment" boolean DEFAULT false, "p_approver_id" "uuid" DEFAULT NULL::"uuid", "p_approver_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_current_profile_id uuid := public.current_profile_id();
  v_requester_id uuid;
  v_assignment public.approver_assignments%rowtype;
  v_has_pool boolean;
  v_budget_month date;
  v_currency text;
  v_exchange_rate numeric;
  v_budget_amount numeric;
  v_budget_result jsonb;
  v_budget_decision text;
  v_budget_block_reason text;
  v_available_before numeric;
  v_available_after numeric;
  v_shortfall numeric;
  v_request_number text;
  v_payment_request_id uuid;
  v_year integer;
  v_concept text;
begin
  if v_current_profile_id is null then
    raise exception 'not_authenticated';
  end if;

  v_requester_id := coalesce(p_requested_by, v_current_profile_id);
  if v_requester_id <> v_current_profile_id
     and not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'requested_by_must_match_current_profile';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = v_requester_id and coalesce(active, true)
  ) then
    raise exception 'requested_by_not_found_or_inactive';
  end if;

  if p_proveedor_id is null then
    raise exception 'proveedor_id es obligatorio';
  end if;
  if not exists (select 1 from public.proveedores where id = p_proveedor_id) then
    raise exception 'El proveedor indicado no existe en public.proveedores';
  end if;
  if p_company_id is null or not exists (
    select 1 from public.companies where id = p_company_id and coalesce(active, true)
  ) then
    raise exception 'La empresa indicada no existe';
  end if;
  if not public.has_active_company_membership(v_requester_id, p_company_id) then
    raise exception 'requester_company_membership_required';
  end if;
  if p_cost_center_id is null or not exists (
    select 1 from public.cost_centers where id = p_cost_center_id
  ) then
    raise exception 'El centro de costo indicado no existe';
  end if;
  if p_budget_category_id is null or not exists (
    select 1 from public.budget_categories where id = p_budget_category_id
  ) then
    raise exception 'La partida presupuestal indicada no existe';
  end if;
  if p_budget_month is null then
    raise exception 'budget_month es obligatorio';
  end if;
  if p_amount_requested is null or p_amount_requested <= 0 then
    raise exception 'amount_requested debe ser mayor a 0';
  end if;
  if p_approver_id is null then
    raise exception 'approver_id_required';
  end if;
  if p_approver_id = v_requester_id then
    raise exception 'requester_cannot_be_own_approver';
  end if;

  v_has_pool := public.payment_request_has_active_approver_pool(v_requester_id, p_company_id);
  if v_has_pool then
    if p_approver_assignment_id is null then
      raise exception 'approver_assignment_id_required';
    end if;

    select * into v_assignment
    from public.approver_assignments aa
    where aa.id = p_approver_assignment_id
      and aa.company_id = p_company_id
      and aa.requester_id = v_requester_id
      and aa.approver_id = p_approver_id
      and aa.active;
    if not found then
      raise exception 'approver_not_in_configured_pool';
    end if;
    if not public.is_payment_request_approver_for_company(p_approver_id, p_company_id) then
      raise exception 'configured_approver_no_longer_eligible';
    end if;
  else
    if p_approver_assignment_id is not null then
      raise exception 'approver_assignment_not_allowed_without_pool';
    end if;
    if not public.payment_request_rule_allows(
      p_approver_id, p_company_id, p_cost_center_id, p_amount_requested, 'approved'
    ) then
      raise exception 'approver_not_allowed_by_approval_rules';
    end if;
  end if;

  v_currency := upper(coalesce(nullif(trim(p_currency), ''), 'MXN'));
  v_exchange_rate := coalesce(p_exchange_rate, 1);
  if v_exchange_rate <= 0 then
    raise exception 'exchange_rate debe ser mayor a 0';
  end if;

  v_budget_month := date_trunc('month', p_budget_month)::date;
  v_budget_amount := round(p_amount_requested * v_exchange_rate, 2);
  v_year := extract(year from v_budget_month)::integer;
  v_concept := coalesce(nullif(trim(p_description), ''), 'Solicitud de pago');

  v_budget_result := public.verify_budget_availability(
    p_company_id,
    p_cost_center_id,
    p_budget_category_id,
    v_budget_month,
    v_budget_amount,
    coalesce(p_is_extraordinary_adjustment, false)
  );
  v_budget_decision := coalesce(v_budget_result ->> 'status', 'bloqueado');
  if v_budget_decision not in ('aprobable', 'bloqueado') then
    v_budget_decision := 'bloqueado';
  end if;
  v_budget_block_reason := v_budget_result ->> 'motivo';
  v_available_before := nullif(v_budget_result ->> 'disponible_actual', '')::numeric;
  v_available_after := nullif(v_budget_result ->> 'disponible_despues', '')::numeric;
  v_shortfall := nullif(v_budget_result ->> 'faltante', '')::numeric;
  v_request_number := public.generate_payment_request_number(v_year);

  insert into public.payment_requests (
    provider_id, proveedor_id, company_id, cost_center_id, budget_category_id,
    budget_month, request_type, requested_by, approver_id, approver_assignment_id,
    approver_selection_source,
    amount_requested, currency, exchange_rate, requires_invoice, invoice_received,
    status, concept, description, notes, submitted_at, request_number,
    budget_decision, budget_block_reason, budget_available_before,
    budget_available_after, budget_shortfall, budget_checked_at, budget_result,
    is_extraordinary_adjustment, created_at, updated_at
  ) values (
    null, p_proveedor_id, p_company_id, p_cost_center_id, p_budget_category_id,
    v_budget_month, 'provider_payment'::payment_request_type, v_requester_id,
    p_approver_id, p_approver_assignment_id,
    case when p_approver_assignment_id is null then 'approval_rules' else 'assigned' end,
    p_amount_requested, v_currency,
    v_exchange_rate, false, false, 'submitted'::payment_request_status,
    v_concept, p_description, p_notes, now(), v_request_number,
    v_budget_decision, v_budget_block_reason, v_available_before,
    v_available_after, v_shortfall, now(), v_budget_result,
    coalesce(p_is_extraordinary_adjustment, false), now(), now()
  ) returning id into v_payment_request_id;

  return jsonb_build_object(
    'payment_request_id', v_payment_request_id,
    'request_number', v_request_number,
    'status', 'submitted',
    'budget_decision', v_budget_decision,
    'budget_block_reason', v_budget_block_reason,
    'budget_result', v_budget_result,
    'approver_id', p_approver_id,
    'approver_assignment_id', p_approver_assignment_id,
    'approver_source', case when p_approver_assignment_id is null then 'approval_rules' else 'assigned' end
  );
end;
$$;


ALTER FUNCTION "public"."create_payment_request"("p_proveedor_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount_requested" numeric, "p_currency" "text", "p_exchange_rate" numeric, "p_description" "text", "p_notes" "text", "p_requested_by" "uuid", "p_is_extraordinary_adjustment" boolean, "p_approver_id" "uuid", "p_approver_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_request_with_extraordinary_intent"("p_proveedor_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount_requested" numeric, "p_currency" "text" DEFAULT 'MXN'::"text", "p_exchange_rate" numeric DEFAULT 1, "p_description" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_requested_by" "uuid" DEFAULT NULL::"uuid", "p_is_extraordinary_adjustment" boolean DEFAULT false, "p_approver_id" "uuid" DEFAULT NULL::"uuid", "p_approver_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_extraordinary_requested" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_result jsonb;
  v_request_id uuid;
begin
  v_result := public.create_payment_request(
    p_proveedor_id,
    p_company_id,
    p_cost_center_id,
    p_budget_category_id,
    p_budget_month,
    p_amount_requested,
    p_currency,
    p_exchange_rate,
    p_description,
    p_notes,
    p_requested_by,
    p_is_extraordinary_adjustment,
    p_approver_id,
    p_approver_assignment_id
  );
  v_request_id := (v_result->>'payment_request_id')::uuid;

  if coalesce(p_extraordinary_requested, false) then
    if not public.extraordinary_profile_has_explicit_faculty(
      v_actor,
      p_company_id
    ) then
      raise exception 'explicit_extraordinary_faculty_required';
    end if;

    update public.payment_requests
    set extraordinary_state = 'extraordinary_requested',
        extraordinary_requested_by = v_actor,
        extraordinary_requested_at = clock_timestamp(),
        extraordinary_intent_cancelled_by = null,
        extraordinary_intent_cancelled_at = null
    where id = v_request_id;

    insert into public.payment_request_extraordinary_events(
      authorization_id,
      payment_request_id,
      company_id,
      event_type,
      actor_profile_id,
      idempotency_key,
      metadata
    ) values (
      null,
      v_request_id,
      p_company_id,
      'intent_requested',
      v_actor,
      'intent-requested:' || v_request_id::text,
      jsonb_build_object(
        'creation_mark_is_intent_only', true,
        'layout_bypass_enabled', false
      )
    );
  end if;

  return v_result || jsonb_build_object(
    'extraordinary_state',
    case when coalesce(p_extraordinary_requested, false)
      then 'extraordinary_requested'
      else 'normal'
    end
  );
end
$$;


ALTER FUNCTION "public"."create_payment_request_with_extraordinary_intent"("p_proveedor_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount_requested" numeric, "p_currency" "text", "p_exchange_rate" numeric, "p_description" "text", "p_notes" "text", "p_requested_by" "uuid", "p_is_extraordinary_adjustment" boolean, "p_approver_id" "uuid", "p_approver_assignment_id" "uuid", "p_extraordinary_requested" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_provider_intake_internal"("p_token_hash" "text", "p_submission" "jsonb", "p_submission_fingerprint" "text", "p_idempotency_key_hash" "text", "p_client_ip_hash" "text" DEFAULT NULL::"text", "p_user_agent_hash" "text" DEFAULT NULL::"text", "p_captcha_provider" "text" DEFAULT 'turnstile'::"text", "p_fingerprint_window_seconds" integer DEFAULT 86400) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_link record;
  v_existing record;
  v_intake_id uuid;
  v_public_folio text;
  v_window_seconds integer;
  v_fingerprint_window_start timestamptz;
  v_day_start timestamptz;
  v_link_submission_count integer;
  v_ip_submission_count integer;
  v_raw_amount numeric;
  v_amount numeric(18, 2);
begin
  if p_token_hash is null or lower(btrim(p_token_hash)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_link_not_available';
  end if;
  if p_submission is null or jsonb_typeof(p_submission) <> 'object' then
    raise exception 'provider_intake_invalid_submission';
  end if;
  if p_submission_fingerprint is null
     or lower(btrim(p_submission_fingerprint)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_invalid_fingerprint';
  end if;
  if p_idempotency_key_hash is null
     or lower(btrim(p_idempotency_key_hash)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_invalid_idempotency_key';
  end if;
  if p_client_ip_hash is not null
     and lower(btrim(p_client_ip_hash)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_invalid_client_hash';
  end if;
  if p_user_agent_hash is not null
     and lower(btrim(p_user_agent_hash)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_invalid_agent_hash';
  end if;
  if nullif(btrim(coalesce(p_captcha_provider, '')), '') is null then
    raise exception 'provider_intake_captcha_required';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(p_submission) as supplied(key)
    where supplied.key <> all (array[
      'provider_name',
      'provider_rfc',
      'provider_email',
      'provider_phone',
      'concept',
      'description',
      'amount_requested',
      'currency',
      'requested_payment_date',
      'invoice_folio',
      'invoice_uuid',
      'invoice_date',
      'bank_name',
      'bank_account',
      'bank_clabe',
      'beneficiary_name'
    ]::text[])
  ) then
    raise exception 'provider_intake_unknown_field';
  end if;

  begin
    if coalesce(p_submission ->> 'amount_requested', '') !~ '^[0-9]+(\.[0-9]{1,2})?$' then
      raise exception 'provider_intake_invalid_amount';
    end if;
    v_raw_amount := (p_submission ->> 'amount_requested')::numeric;
    v_amount := v_raw_amount::numeric(18, 2);
  exception when others then
    raise exception 'provider_intake_invalid_amount';
  end;

  if nullif(btrim(p_submission ->> 'provider_name'), '') is null
     or nullif(btrim(p_submission ->> 'provider_email'), '') is null
     or nullif(btrim(p_submission ->> 'concept'), '') is null
     or v_amount is null
     or v_amount <= 0
     or length(btrim(p_submission ->> 'provider_name')) > 200
     or btrim(p_submission ->> 'provider_name') ~ '[[:cntrl:]]'
     or length(btrim(p_submission ->> 'provider_email')) > 254
     or lower(btrim(p_submission ->> 'provider_email')) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or length(btrim(p_submission ->> 'concept')) > 300
     or btrim(p_submission ->> 'concept') ~ '[[:cntrl:]]'
     or length(coalesce(p_submission ->> 'description', '')) > 4000
     or coalesce(p_submission ->> 'description', '') ~ '[[:cntrl:]]'
     or upper(coalesce(nullif(btrim(p_submission ->> 'currency'), ''), 'MXN')) !~ '^[A-Z]{3}$'
     or (
       nullif(btrim(p_submission ->> 'provider_rfc'), '') is not null
       and upper(replace(replace(btrim(p_submission ->> 'provider_rfc'), ' ', ''), '-', ''))
         !~ '^[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}$'
     )
     or (
       nullif(btrim(p_submission ->> 'bank_clabe'), '') is not null
       and replace(replace(btrim(p_submission ->> 'bank_clabe'), ' ', ''), '-', '') !~ '^[0-9]{18}$'
     )
     or (
       nullif(btrim(p_submission ->> 'bank_account'), '') is not null
       and replace(replace(btrim(p_submission ->> 'bank_account'), ' ', ''), '-', '') !~ '^[A-Za-z0-9]{4,34}$'
     )
     or (
       nullif(btrim(p_submission ->> 'invoice_uuid'), '') is not null
       and upper(btrim(p_submission ->> 'invoice_uuid'))
         !~ '^[0-9A-F]{8}-[0-9A-F]{4}-[1-5][0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12}$'
     ) then
    raise exception 'provider_intake_invalid_submission';
  end if;

  begin
    if nullif(btrim(p_submission ->> 'requested_payment_date'), '') is not null then
      perform (p_submission ->> 'requested_payment_date')::date;
    end if;
    if nullif(btrim(p_submission ->> 'invoice_date'), '') is not null then
      perform (p_submission ->> 'invoice_date')::date;
    end if;
  exception when others then
    raise exception 'provider_intake_invalid_submission';
  end;

  select
    il.id,
    il.company_id,
    il.max_submissions_per_day
    into v_link
  from public.intake_links il
  join public.companies c on c.id = il.company_id
  where il.token_hash = lower(btrim(p_token_hash))
    and il.status = 'active'
    and (il.expires_at is null or il.expires_at > now())
    and coalesce(c.active, true)
  for update of il;

  if not found then
    raise exception 'provider_intake_link_not_available';
  end if;

  select pi.id, pi.public_folio
    into v_existing
  from public.payment_intake pi
  where pi.intake_link_id = v_link.id
    and pi.idempotency_key = lower(btrim(p_idempotency_key_hash))
  limit 1;

  if found then
    return jsonb_build_object(
      'payment_intake_id', v_existing.id,
      'public_folio', v_existing.public_folio,
      'status', 'received',
      'duplicate', true
    );
  end if;

  v_window_seconds := greatest(60, least(coalesce(p_fingerprint_window_seconds, 86400), 86400));
  v_day_start := date_trunc('day', now() at time zone 'America/Mexico_City')
    at time zone 'America/Mexico_City';
  v_fingerprint_window_start := now() - make_interval(secs => v_window_seconds);

  select pi.id, pi.public_folio
    into v_existing
  from public.payment_intake pi
  where pi.intake_link_id = v_link.id
    and pi.submission_fingerprint = lower(btrim(p_submission_fingerprint))
    and pi.created_at >= v_fingerprint_window_start
  order by pi.created_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'payment_intake_id', v_existing.id,
      'public_folio', v_existing.public_folio,
      'status', 'received',
      'duplicate', true
    );
  end if;

  select count(*)::integer
    into v_link_submission_count
  from public.payment_intake pi
  where pi.intake_link_id = v_link.id
    and pi.created_at >= v_day_start;

  if v_link_submission_count >= v_link.max_submissions_per_day then
    raise exception 'provider_intake_rate_limited';
  end if;

  if p_client_ip_hash is not null then
    select count(*)::integer
      into v_ip_submission_count
    from public.payment_intake pi
    where pi.intake_link_id = v_link.id
      and pi.client_ip_hash = lower(btrim(p_client_ip_hash))
      and pi.created_at >= v_fingerprint_window_start;

    if v_ip_submission_count >= v_link.max_submissions_per_day then
      raise exception 'provider_intake_rate_limited';
    end if;
  end if;

  v_intake_id := gen_random_uuid();
  v_public_folio := public.next_payment_intake_public_folio();

  insert into public.payment_intake (
    id,
    public_folio,
    intake_link_id,
    company_id,
    status,
    provider_name,
    provider_rfc,
    provider_email,
    provider_phone,
    concept,
    description,
    amount_requested,
    currency,
    requested_payment_date,
    invoice_folio,
    invoice_uuid,
    invoice_date,
    bank_name,
    bank_account,
    bank_clabe,
    beneficiary_name,
    submission_fingerprint,
    idempotency_key,
    client_ip_hash,
    user_agent_hash,
    payload_version,
    captcha_provider,
    captcha_verified_at
  ) values (
    v_intake_id,
    v_public_folio,
    v_link.id,
    v_link.company_id,
    'received',
    btrim(p_submission ->> 'provider_name'),
    nullif(upper(replace(replace(btrim(p_submission ->> 'provider_rfc'), ' ', ''), '-', '')), ''),
    lower(btrim(p_submission ->> 'provider_email')),
    nullif(btrim(p_submission ->> 'provider_phone'), ''),
    btrim(p_submission ->> 'concept'),
    nullif(btrim(p_submission ->> 'description'), ''),
    v_amount,
    upper(coalesce(nullif(btrim(p_submission ->> 'currency'), ''), 'MXN')),
    nullif(p_submission ->> 'requested_payment_date', '')::date,
    nullif(btrim(p_submission ->> 'invoice_folio'), ''),
    nullif(upper(btrim(p_submission ->> 'invoice_uuid')), ''),
    nullif(p_submission ->> 'invoice_date', '')::date,
    nullif(btrim(p_submission ->> 'bank_name'), ''),
    nullif(replace(replace(btrim(p_submission ->> 'bank_account'), ' ', ''), '-', ''), ''),
    nullif(replace(replace(btrim(p_submission ->> 'bank_clabe'), ' ', ''), '-', ''), ''),
    nullif(btrim(p_submission ->> 'beneficiary_name'), ''),
    lower(btrim(p_submission_fingerprint)),
    lower(btrim(p_idempotency_key_hash)),
    nullif(lower(btrim(coalesce(p_client_ip_hash, ''))), ''),
    nullif(lower(btrim(coalesce(p_user_agent_hash, ''))), ''),
    1,
    lower(btrim(p_captcha_provider)),
    now()
  );

  insert into public.payment_intake_events (
    payment_intake_id,
    event_type,
    actor_type,
    from_status,
    to_status,
    metadata
  ) values (
    v_intake_id,
    'received',
    'public_provider',
    null,
    'received',
    jsonb_build_object('contract_version', 1)
  );

  return jsonb_build_object(
    'payment_intake_id', v_intake_id,
    'public_folio', v_public_folio,
    'status', 'received',
    'duplicate', false
  );
exception
  when unique_violation then
    select pi.id, pi.public_folio
      into v_existing
    from public.payment_intake pi
    where pi.intake_link_id = v_link.id
      and pi.idempotency_key = lower(btrim(p_idempotency_key_hash))
    limit 1;

    if found then
      return jsonb_build_object(
        'payment_intake_id', v_existing.id,
        'public_folio', v_existing.public_folio,
        'status', 'received',
        'duplicate', true
      );
    end if;
    raise;
end
$_$;


ALTER FUNCTION "public"."create_provider_intake_internal"("p_token_hash" "text", "p_submission" "jsonb", "p_submission_fingerprint" "text", "p_idempotency_key_hash" "text", "p_client_ip_hash" "text", "p_user_agent_hash" "text", "p_captcha_provider" "text", "p_fingerprint_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_provider_intake_internal"("p_token_hash" "text", "p_submission" "jsonb", "p_submission_fingerprint" "text", "p_idempotency_key_hash" "text", "p_client_ip_hash" "text", "p_user_agent_hash" "text", "p_captcha_provider" "text", "p_fingerprint_window_seconds" integer) IS 'Service-only transactional provider intake creation with link lock, rate limit, idempotency, folio, and received ledger event.';



CREATE OR REPLACE FUNCTION "public"."current_extraordinary_faculty_company_ids"() RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(faculty.company_id order by faculty.company_id), '{}')
  from public.extraordinary_profile_faculties faculty
  where faculty.profile_id = public.current_profile_id()
    and public.extraordinary_profile_has_explicit_faculty(
      faculty.profile_id,
      faculty.company_id
    );
$$;


ALTER FUNCTION "public"."current_extraordinary_faculty_company_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_profile_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select p.id
  from public.profiles p
  where p.auth_user_id = auth.uid()
    and coalesce(p.active, true) = true
  limit 1;
$$;


ALTER FUNCTION "public"."current_profile_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_user_has_role"("p_roles" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = public.current_profile_id()
      and lower(
        coalesce(
          to_jsonb(r)->>'name',
          to_jsonb(r)->>'nombre',
          to_jsonb(r)->>'role_name'
        )
      ) = any (
        select lower(x)
        from unnest(p_roles) as x
      )
  );
$$;


ALTER FUNCTION "public"."current_user_has_role"("p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_assert_access"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  if not public.current_user_has_role(array[
    'admin',
    'superadmin',
    'sysadmin',
    'system_admin',
    'finance',
    'finanzas',
    'treasury',
    'tesoreria',
    'administracion',
    'approver_2',
    'aprobador_2',
    'direccion',
    'director'
  ]) then
    raise exception 'not_allowed_to_view_dashboard';
  end if;
end;
$$;


ALTER FUNCTION "public"."dashboard_assert_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_budget_comparison"("p_period_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_start date := public.dashboard_period_start(p_period_key);
  v_end date := public.dashboard_period_end(p_period_key);
  v_result jsonb;
begin
  perform public.dashboard_assert_access();

  with grouped as (
    select
      pr.company_id,
      coalesce(c.legal_name, c.name, 'Sin empresa') as company,

      pr.cost_center_id,
      coalesce(cc.name, cc.code, 'Sin centro') as cost_center,

      pr.budget_category_id,
      coalesce(bc.name, bc.category, 'Sin partida') as budget_category,
      coalesce(bc.code, '') as category_code,

      0::numeric as budget_amount,

      coalesce(sum(pr.amount_requested) filter (
        where pr.status in ('approved','finance_validation','scheduled')
      ), 0) as committed_amount,

      coalesce(sum(pr.amount_requested) filter (
        where pr.status = 'paid'
      ), 0) as executed_amount
    from public.payment_requests pr
    left join public.companies c on c.id = pr.company_id
    left join public.cost_centers cc on cc.id = pr.cost_center_id
    left join public.budget_categories bc on bc.id = pr.budget_category_id
    where coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    group by
      pr.company_id,
      coalesce(c.legal_name, c.name, 'Sin empresa'),
      pr.cost_center_id,
      coalesce(cc.name, cc.code, 'Sin centro'),
      pr.budget_category_id,
      coalesce(bc.name, bc.category, 'Sin partida'),
      coalesce(bc.code, '')
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'company_id', company_id,
        'company', company,
        'cost_center_id', cost_center_id,
        'cost_center', cost_center,
        'budget_category_id', budget_category_id,
        'budget_category', budget_category,
        'category_code', category_code,
        'budget_amount', budget_amount,
        'committed_amount', committed_amount,
        'executed_amount', executed_amount,
        'available_amount', budget_amount - committed_amount - executed_amount,
        'variance_amount', budget_amount - executed_amount,
        'variance_pct',
          case
            when budget_amount > 0 then round(((budget_amount - executed_amount) / budget_amount) * 100, 2)
            else 0
          end
      )
      order by abs(budget_amount - executed_amount) desc, company, cost_center, category_code
    ),
    '[]'::jsonb
  )
  into v_result
  from grouped;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."dashboard_budget_comparison"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_closure_checklist"("p_period_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_start date;
  v_end date;

  v_pending_payment_requests integer := 0;
  v_approved_without_operation integer := 0;
  v_unconfirmed_layouts integer := 0;
  v_unpaid_approved_requests integer := 0;
  v_overdue_cash_funds integer := 0;
  v_cash_reconciliations_in_review integer := 0;
  v_open_incidents integer := 0;
  v_issued_unpaid_invoices integer := 0;
  v_overdue_maintenance_fees integer := 0;
  v_missing_budget_comments integer := 0;

  v_blocking_reasons jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_can_close boolean := true;
begin
  perform public.dashboard_assert_access();

  if p_period_key is null or trim(p_period_key) = '' then
    raise exception 'period_key_required';
  end if;

  v_start := public.dashboard_period_start(p_period_key);
  v_end := public.dashboard_period_end(p_period_key);

  select count(*)
  into v_pending_payment_requests
  from public.payment_requests pr
  where pr.status in ('submitted','changes_requested','finance_validation')
    and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end;

  select count(*)
  into v_approved_without_operation
  from public.payment_requests pr
  where pr.status = 'approved'
    and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    and not exists (
      select 1
      from public.payment_layout_lines pll
      join public.payment_layouts pl on pl.id = pll.layout_id
      where pll.payment_request_id = pr.id
        and pl.status <> 'cancelled'
    )
    and not exists (
      select 1
      from public.cash_funds cf
      where cf.payment_request_id = pr.id
        and cf.status <> 'cancelled'
    )
    and not exists (
      select 1
      from public.payment_receipts prc
      where prc.payment_request_id = pr.id
    );

  select count(*)
  into v_unconfirmed_layouts
  from public.payment_layouts pl
  where pl.status in ('generated','uploaded')
    and coalesce(pl.updated_at, pl.created_at)::date between v_start and v_end;

  select count(*)
  into v_unpaid_approved_requests
  from public.payment_requests pr
  where pr.status in ('approved','scheduled','finance_validation')
    and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end;

  select count(*)
  into v_overdue_cash_funds
  from public.cash_funds cf
  where cf.status in ('active','pending_receipt','blocked','receipt_review')
    and cf.due_date < current_date;

  select count(*)
  into v_cash_reconciliations_in_review
  from public.cash_reconciliations cr
  where cr.status = 'submitted';

  select count(*)
  into v_open_incidents
  from public.incident_charges ic
  where ic.status = 'open'
    and ic.incident_date between v_start and v_end;

  select count(*)
  into v_issued_unpaid_invoices
  from public.invoices inv
  where inv.status = 'issued'
    and inv.issue_date between v_start and v_end;

  select count(*)
  into v_overdue_maintenance_fees
  from public.maintenance_fee_charges mfc
  join public.billing_periods bp on bp.id = mfc.billing_period_id
  where mfc.status = 'overdue'
    and bp.cutoff_date <= v_end;

  v_missing_budget_comments := 0;
  v_warnings := v_warnings || jsonb_build_array(
    'budget_variance_comment_check_pending_model_confirmation'
  );

  if v_pending_payment_requests > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('pending_payment_requests');
  end if;

  if v_approved_without_operation > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('approved_without_operation');
  end if;

  if v_unconfirmed_layouts > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('unconfirmed_layouts');
  end if;

  if v_unpaid_approved_requests > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('unpaid_approved_requests');
  end if;

  if v_overdue_cash_funds > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('overdue_cash_funds');
  end if;

  if v_cash_reconciliations_in_review > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('cash_reconciliations_in_review');
  end if;

  if v_open_incidents > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('open_incidents');
  end if;

  if v_issued_unpaid_invoices > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('issued_unpaid_invoices');
  end if;

  if v_overdue_maintenance_fees > 0 then
    v_blocking_reasons := v_blocking_reasons || jsonb_build_array('overdue_maintenance_fees');
  end if;

  v_can_close := jsonb_array_length(v_blocking_reasons) = 0;

  return jsonb_build_object(
    'period_key', p_period_key,
    'can_close', v_can_close,
    'blocking_reasons', v_blocking_reasons,
    'warnings', v_warnings,
    'checks', jsonb_build_object(
      'pending_payment_requests', v_pending_payment_requests,
      'approved_without_operation', v_approved_without_operation,
      'unconfirmed_layouts', v_unconfirmed_layouts,
      'unpaid_approved_requests', v_unpaid_approved_requests,
      'overdue_cash_funds', v_overdue_cash_funds,
      'cash_reconciliations_in_review', v_cash_reconciliations_in_review,
      'open_incidents', v_open_incidents,
      'issued_unpaid_invoices', v_issued_unpaid_invoices,
      'overdue_maintenance_fees', v_overdue_maintenance_fees,
      'missing_budget_comments', v_missing_budget_comments
    )
  );
end;
$$;


ALTER FUNCTION "public"."dashboard_closure_checklist"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_export_payload"("p_period_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_period_key text := public.dashboard_period_key(p_period_key);
  v_year integer;
  v_month integer;

  v_kpis jsonb;
  v_budget jsonb;
  v_ytd jsonb;
  v_income jsonb;
  v_checklist jsonb;
  v_comments jsonb;
  v_top_variances jsonb;
begin
  perform public.dashboard_assert_access();

  if p_period_key is null or trim(p_period_key) = '' then
    raise exception 'period_key_required';
  end if;

  v_year := split_part(v_period_key, '-', 1)::integer;
  v_month := split_part(v_period_key, '-', 2)::integer;

  v_kpis := public.dashboard_kpis(v_period_key);
  v_budget := public.dashboard_budget_comparison(v_period_key);
  v_ytd := public.dashboard_ytd(v_year, v_month);
  v_income := public.dashboard_income_members(v_year, v_period_key);
  v_checklist := public.dashboard_closure_checklist(v_period_key);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'section', mcc.section,
        'comment', mcc.comment,
        'created_by', mcc.created_by,
        'created_at', mcc.created_at
      )
      order by mcc.section, mcc.created_at
    ),
    '[]'::jsonb
  )
  into v_comments
  from public.monthly_closure_comments mcc
  join public.monthly_closures mc on mc.id = mcc.monthly_closure_id
  where mc.period_key = v_period_key;

  select coalesce(
    jsonb_agg(item order by abs(coalesce((item->>'variance_amount')::numeric, 0)) desc),
    '[]'::jsonb
  )
  into v_top_variances
  from (
    select item
    from jsonb_array_elements(v_budget) as item
    order by abs(coalesce((item->>'variance_amount')::numeric, 0)) desc
    limit 10
  ) s;

  return jsonb_build_object(
    'metadata', jsonb_build_object(
      'generated_at', now(),
      'period_key', v_period_key,
      'year', v_year,
      'month', v_month
    ),
    'kpis', v_kpis,
    'budget_comparison', v_budget,
    'ytd', v_ytd,
    'income_members', v_income,
    'closure_checklist', v_checklist,
    'closure_comments', v_comments,
    'top_variances', v_top_variances
  );
end;
$$;


ALTER FUNCTION "public"."dashboard_export_payload"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_income_members"("p_year" integer DEFAULT NULL::integer, "p_period_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_year integer := coalesce(p_year, extract(year from current_date)::integer);
  v_start date;
  v_end date;
  v_result jsonb;
begin
  perform public.dashboard_assert_access();

  if p_period_key is not null then
    v_start := public.dashboard_period_start(p_period_key);
    v_end := public.dashboard_period_end(p_period_key);
  else
    v_start := make_date(v_year, 1, 1);
    v_end := make_date(v_year, 12, 31);
  end if;

  with base as (
    select
      m.id as member_id,
      m.full_name as member_name,
      m.lineage,
      bp.name as billing_period,
      bp.cutoff_date,
      mfc.expected_amount,
      mfc.paid_amount,
      mfc.pending_amount,
      mfc.status,
      mfc.invoice_id
    from public.maintenance_fee_charges mfc
    join public.members m on m.id = mfc.member_id
    join public.billing_periods bp on bp.id = mfc.billing_period_id
    where bp.cutoff_date between v_start and v_end
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'member_id', b.member_id,
        'member_name', b.member_name,
        'lineage', b.lineage,
        'billing_period', b.billing_period,
        'cutoff_date', b.cutoff_date,
        'expected_amount', coalesce(b.expected_amount, 0),
        'paid_amount', coalesce(b.paid_amount, 0),
        'pending_amount', coalesce(b.pending_amount, 0),
        'status', b.status,
        'open_incidents', coalesce((
          select count(*)
          from public.incident_charges ic
          where ic.member_id = b.member_id
            and ic.status in ('open','invoiced')
            and ic.incident_date between v_start and v_end
        ), 0),
        'paid_incidents', coalesce((
          select count(*)
          from public.incident_charges ic
          where ic.member_id = b.member_id
            and ic.status = 'paid'
            and ic.incident_date between v_start and v_end
        ), 0),
        'issued_invoices', coalesce((
          select count(*)
          from public.invoices inv
          where inv.member_id = b.member_id
            and inv.status = 'issued'
            and inv.issue_date between v_start and v_end
        ), 0),
        'paid_invoices', coalesce((
          select count(*)
          from public.invoices inv
          where inv.member_id = b.member_id
            and inv.status = 'paid'
            and coalesce(inv.payment_date, inv.issue_date) between v_start and v_end
        ), 0)
      )
      order by b.member_name, b.cutoff_date
    ),
    '[]'::jsonb
  )
  into v_result
  from base b;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."dashboard_income_members"("p_year" integer, "p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_kpis"("p_period_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_period_key text := public.dashboard_period_key(p_period_key);
  v_start date := public.dashboard_period_start(p_period_key);
  v_end date := public.dashboard_period_end(p_period_key);

  v_total_requested numeric := 0;
  v_total_approved numeric := 0;
  v_total_paid numeric := 0;
  v_total_pending_payment numeric := 0;
  v_pending_payment_requests integer := 0;
  v_approved_ready_to_operate integer := 0;
  v_active_layouts integer := 0;
  v_confirmed_layouts integer := 0;

  v_active_cash_funds integer := 0;
  v_pending_cash_reconciliation integer := 0;
  v_cash_in_review integer := 0;
  v_overdue_cash_funds integer := 0;
  v_cash_assigned_amount numeric := 0;
  v_cash_verified_amount numeric := 0;
  v_cash_pending_amount numeric := 0;

  v_active_members integer := 0;
  v_maintenance_expected numeric := 0;
  v_maintenance_collected numeric := 0;
  v_maintenance_pending numeric := 0;
  v_open_incidents integer := 0;
  v_paid_incidents integer := 0;
  v_issued_invoices integer := 0;
  v_paid_invoices integer := 0;
  v_pending_invoices integer := 0;

  v_closure_status text := 'not_created';
  v_closure_closed_at timestamptz := null;
  v_last_export_at timestamptz := null;
begin
  perform public.dashboard_assert_access();

  select
    coalesce(sum(pr.amount_requested) filter (
      where coalesce(pr.created_at, pr.updated_at)::date between v_start and v_end
    ), 0),

    coalesce(sum(pr.amount_requested) filter (
      where pr.status in ('approved','finance_validation','scheduled','paid')
        and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    ), 0),

    coalesce(sum(pr.amount_requested) filter (
      where pr.status = 'paid'
        and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    ), 0),

    coalesce(sum(pr.amount_requested) filter (
      where pr.status in ('approved','finance_validation','scheduled')
        and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    ), 0),

    count(*) filter (
      where pr.status in ('submitted','changes_requested','finance_validation')
        and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    ),

    count(*) filter (
      where pr.status = 'approved'
        and coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
        and not exists (
          select 1
          from public.payment_layout_lines pll
          join public.payment_layouts pl on pl.id = pll.layout_id
          where pll.payment_request_id = pr.id
            and pl.status <> 'cancelled'
        )
        and not exists (
          select 1
          from public.cash_funds cf
          where cf.payment_request_id = pr.id
            and cf.status <> 'cancelled'
        )
    )
  into
    v_total_requested,
    v_total_approved,
    v_total_paid,
    v_total_pending_payment,
    v_pending_payment_requests,
    v_approved_ready_to_operate
  from public.payment_requests pr;

  select
    count(*) filter (
      where status in ('draft','generated','uploaded')
        and coalesce(updated_at, created_at)::date between v_start and v_end
    ),
    count(*) filter (
      where status = 'confirmed'
        and coalesce(updated_at, created_at)::date between v_start and v_end
    )
  into
    v_active_layouts,
    v_confirmed_layouts
  from public.payment_layouts;

  select
    count(*) filter (where status in ('active','pending_receipt','blocked','receipt_review')),
    count(*) filter (where status in ('pending_receipt','blocked')),
    count(*) filter (where status = 'receipt_review'),
    count(*) filter (
      where status in ('active','pending_receipt','blocked','receipt_review')
        and due_date < current_date
    ),
    coalesce(sum(assigned_amount), 0),
    coalesce(sum(verified_amount), 0),
    coalesce(sum(pending_amount), 0)
  into
    v_active_cash_funds,
    v_pending_cash_reconciliation,
    v_cash_in_review,
    v_overdue_cash_funds,
    v_cash_assigned_amount,
    v_cash_verified_amount,
    v_cash_pending_amount
  from public.cash_funds
  where assignment_date between v_start and v_end
     or due_date between v_start and v_end
     or status in ('active','pending_receipt','blocked','receipt_review');

  select count(*)
  into v_active_members
  from public.members
  where active = true;

  select
    coalesce(sum(mfc.expected_amount), 0),
    coalesce(sum(mfc.paid_amount), 0),
    coalesce(sum(mfc.pending_amount), 0)
  into
    v_maintenance_expected,
    v_maintenance_collected,
    v_maintenance_pending
  from public.maintenance_fee_charges mfc
  join public.billing_periods bp on bp.id = mfc.billing_period_id
  where bp.cutoff_date between v_start and v_end;

  select
    count(*) filter (where status in ('open','invoiced')),
    count(*) filter (where status = 'paid')
  into
    v_open_incidents,
    v_paid_incidents
  from public.incident_charges
  where incident_date between v_start and v_end;

  select
    count(*) filter (where status = 'issued'),
    count(*) filter (where status = 'paid'),
    count(*) filter (where status = 'issued')
  into
    v_issued_invoices,
    v_paid_invoices,
    v_pending_invoices
  from public.invoices
  where issue_date between v_start and v_end
     or payment_date between v_start and v_end;

  select
    mc.status,
    mc.closed_at
  into
    v_closure_status,
    v_closure_closed_at
  from public.monthly_closures mc
  where mc.period_key = v_period_key;

  if v_closure_status is null then
    v_closure_status := 'not_created';
  end if;

  select max(mce.completed_at)
  into v_last_export_at
  from public.monthly_closure_exports mce
  join public.monthly_closures mc on mc.id = mce.monthly_closure_id
  where mc.period_key = v_period_key
    and mce.status = 'completed';

  return jsonb_build_object(
    'period_key', v_period_key,
    'egresos', jsonb_build_object(
      'total_requested', coalesce(v_total_requested, 0),
      'total_approved', coalesce(v_total_approved, 0),
      'total_paid', coalesce(v_total_paid, 0),
      'total_pending_payment', coalesce(v_total_pending_payment, 0),
      'pending_payment_requests', coalesce(v_pending_payment_requests, 0),
      'approved_ready_to_operate', coalesce(v_approved_ready_to_operate, 0),
      'active_layouts', coalesce(v_active_layouts, 0),
      'confirmed_layouts', coalesce(v_confirmed_layouts, 0)
    ),
    'efectivo', jsonb_build_object(
      'active_cash_funds', coalesce(v_active_cash_funds, 0),
      'pending_cash_reconciliation', coalesce(v_pending_cash_reconciliation, 0),
      'cash_in_review', coalesce(v_cash_in_review, 0),
      'overdue_cash_funds', coalesce(v_overdue_cash_funds, 0),
      'cash_assigned_amount', coalesce(v_cash_assigned_amount, 0),
      'cash_verified_amount', coalesce(v_cash_verified_amount, 0),
      'cash_pending_amount', coalesce(v_cash_pending_amount, 0)
    ),
    'ingresos', jsonb_build_object(
      'active_members', coalesce(v_active_members, 0),
      'maintenance_expected', coalesce(v_maintenance_expected, 0),
      'maintenance_collected', coalesce(v_maintenance_collected, 0),
      'maintenance_pending', coalesce(v_maintenance_pending, 0),
      'open_incidents', coalesce(v_open_incidents, 0),
      'paid_incidents', coalesce(v_paid_incidents, 0),
      'issued_invoices', coalesce(v_issued_invoices, 0),
      'paid_invoices', coalesce(v_paid_invoices, 0),
      'pending_invoices', coalesce(v_pending_invoices, 0)
    ),
    'balance', jsonb_build_object(
      'total_outflows', coalesce(v_total_paid, 0) + coalesce(v_cash_assigned_amount, 0),
      'total_inflows', coalesce(v_maintenance_collected, 0),
      'net_balance', coalesce(v_maintenance_collected, 0) - (coalesce(v_total_paid, 0) + coalesce(v_cash_assigned_amount, 0))
    ),
    'cierre', jsonb_build_object(
      'closure_status', v_closure_status,
      'closure_closed_at', v_closure_closed_at,
      'last_export_at', v_last_export_at
    ),
    'last_updated', now()
  );
end;
$$;


ALTER FUNCTION "public"."dashboard_kpis"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_period_end"("p_period_key" "text" DEFAULT NULL::"text") RETURNS "date"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select (
    public.dashboard_period_start(p_period_key)
    + interval '1 month'
    - interval '1 day'
  )::date;
$$;


ALTER FUNCTION "public"."dashboard_period_end"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_period_key"("p_period_key" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(nullif(trim(p_period_key), ''), to_char(current_date, 'YYYY-MM'));
$$;


ALTER FUNCTION "public"."dashboard_period_key"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_period_start"("p_period_key" "text" DEFAULT NULL::"text") RETURNS "date"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select to_date(public.dashboard_period_key(p_period_key) || '-01', 'YYYY-MM-DD');
$$;


ALTER FUNCTION "public"."dashboard_period_start"("p_period_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dashboard_ytd"("p_year" integer DEFAULT NULL::integer, "p_through_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_year integer := coalesce(p_year, extract(year from current_date)::integer);
  v_month integer := coalesce(p_through_month, extract(month from current_date)::integer);
  v_start date;
  v_end date;
  v_result jsonb;
begin
  perform public.dashboard_assert_access();

  if v_month < 1 or v_month > 12 then
    raise exception 'invalid_month';
  end if;

  v_start := make_date(v_year, 1, 1);
  v_end := (make_date(v_year, v_month, 1) + interval '1 month' - interval '1 day')::date;

  with grouped as (
    select
      coalesce(c.legal_name, c.name, 'Sin empresa') as company,
      coalesce(cc.name, cc.code, 'Sin centro') as cost_center,
      coalesce(bc.name, bc.category, 'Sin partida') as budget_category,

      0::numeric as ytd_budget,

      coalesce(sum(pr.amount_requested) filter (
        where pr.status in ('approved','finance_validation','scheduled')
      ), 0) as ytd_committed,

      coalesce(sum(pr.amount_requested) filter (
        where pr.status = 'paid'
      ), 0) as ytd_executed
    from public.payment_requests pr
    left join public.companies c on c.id = pr.company_id
    left join public.cost_centers cc on cc.id = pr.cost_center_id
    left join public.budget_categories bc on bc.id = pr.budget_category_id
    where coalesce(pr.updated_at, pr.created_at)::date between v_start and v_end
    group by
      coalesce(c.legal_name, c.name, 'Sin empresa'),
      coalesce(cc.name, cc.code, 'Sin centro'),
      coalesce(bc.name, bc.category, 'Sin partida')
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'company', company,
        'cost_center', cost_center,
        'budget_category', budget_category,
        'ytd_budget', ytd_budget,
        'ytd_committed', ytd_committed,
        'ytd_executed', ytd_executed,
        'ytd_available', ytd_budget - ytd_committed - ytd_executed,
        'ytd_variance_amount', ytd_budget - ytd_executed,
        'ytd_variance_pct',
          case
            when ytd_budget > 0 then round(((ytd_budget - ytd_executed) / ytd_budget) * 100, 2)
            else 0
          end
      )
      order by abs(ytd_budget - ytd_executed) desc, company, cost_center, budget_category
    ),
    '[]'::jsonb
  )
  into v_result
  from grouped;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."dashboard_ytd"("p_year" integer, "p_through_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_approval_batch_items"("p_batch_id" "uuid", "p_decisions" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_decision jsonb;
  v_item_id uuid;
  v_status text;
  v_reason text;
  v_updated integer := 0;
  v_pending integer;
  v_approved integer;
  v_rejected integer;
  v_final_status text;
begin
  v_actor := public.approval_batch_require_active_direction();

  select *
    into v_batch
  from public.approval_batches
  where id = p_batch_id
  for update;

  if not found then raise exception 'batch_not_found'; end if;
  if v_batch.director_id <> v_actor then
    raise exception 'batch_director_required';
  end if;
  if v_batch.status <> 'submitted' then
    raise exception 'batch_must_be_submitted';
  end if;
  if jsonb_typeof(p_decisions) <> 'array'
     or jsonb_array_length(p_decisions) = 0 then
    raise exception 'decisions_array_required';
  end if;

  if exists (
    select 1
    from (
      select nullif(value ->> 'item_id', '') as item_id
      from jsonb_array_elements(p_decisions)
    ) decisions
    group by decisions.item_id
    having decisions.item_id is null or count(*) > 1
  ) then
    raise exception 'duplicate_or_missing_item_decision';
  end if;

  for v_decision in
    select value from jsonb_array_elements(p_decisions)
  loop
    v_item_id := nullif(v_decision ->> 'item_id', '')::uuid;
    v_status := lower(btrim(coalesce(v_decision ->> 'status', '')));
    v_reason :=
      nullif(btrim(coalesce(v_decision ->> 'reject_reason', '')), '');

    if v_status not in ('approved', 'rejected') then
      raise exception 'invalid_item_decision';
    end if;
    if v_status = 'rejected' and v_reason is null then
      raise exception 'reject_reason_required';
    end if;

    update public.approval_batch_items
    set director_status = v_status,
        director_reject_reason = case
          when v_status = 'rejected' then v_reason
          else null
        end,
        rebatch_status = case
          when v_status = 'rejected' then 'blocked'
          else 'not_applicable'
        end,
        rebatch_released_by = null,
        rebatch_released_at = null,
        rebatch_release_note = null,
        decided_by = v_actor,
        decided_at = now()
    where id = v_item_id
      and batch_id = p_batch_id
      and removed_at is null
      and director_status = 'pending';

    if not found then
      raise exception 'pending_batch_item_not_found:%', v_item_id;
    end if;
    v_updated := v_updated + 1;
  end loop;

  select
    count(*) filter (where director_status = 'pending'),
    count(*) filter (where director_status = 'approved'),
    count(*) filter (where director_status = 'rejected')
    into v_pending, v_approved, v_rejected
  from public.approval_batch_items
  where batch_id = p_batch_id
    and removed_at is null;

  if v_pending = 0 then
    v_final_status := case
      when v_rejected > 0 then 'partially_approved'
      else 'approved'
    end;

    update public.approval_batches
    set status = v_final_status,
        decided_by = v_actor,
        decided_at = now()
    where id = p_batch_id;
  else
    v_final_status := 'submitted';
  end if;

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'status', v_final_status,
    'updated_items', v_updated,
    'pending_items', v_pending,
    'approved_items', v_approved,
    'rejected_items', v_rejected,
    'approval_model', 'single_direction'
  );
end
$$;


ALTER FUNCTION "public"."decide_approval_batch_items"("p_batch_id" "uuid", "p_decisions" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decide_approval_batch_items"("p_batch_id" "uuid", "p_decisions" "jsonb") IS 'Allows only the active Direction profile stored on the batch to decide items; future-pool membership is intentionally ignored.';



CREATE OR REPLACE FUNCTION "public"."decide_payment_request"("p_payment_request_id" "uuid", "p_actor_profile_id" "uuid", "p_action" "text", "p_comments" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_assignment public.approver_assignments%rowtype;
  v_current_profile_id uuid := public.current_profile_id();
  v_previous_status text;
  v_new_status text;
  v_role_id uuid;
  v_rule_id uuid;
  v_approval_level integer;
  v_is_exception boolean;
  v_clean_comments text;
  v_uses_assignment_snapshot boolean := false;
  v_legacy_assignment_override boolean := false;
begin
  if v_current_profile_id is null then
    raise exception 'not_authenticated';
  end if;
  if p_actor_profile_id is null or p_actor_profile_id <> v_current_profile_id then
    raise exception 'actor_profile_must_match_current_profile';
  end if;

  v_clean_comments := nullif(btrim(coalesce(p_comments, '')), '');
  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then
    raise exception 'payment_request_not_found';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = p_actor_profile_id and coalesce(p.active, true)
  ) then
    raise exception 'actor_profile_not_found';
  end if;

  if p_action not in (
    'approved', 'rejected', 'changes_requested', 'exception_approved',
    'exception_rejected', 'amount_change_requested', 'category_change_requested',
    'budget_adjustment_requested'
  ) then
    raise exception 'invalid_action';
  end if;

  v_is_exception := (
    v_request.budget_decision = 'bloqueado'
    or coalesce(v_request.is_extraordinary_adjustment, false)
  );
  if p_action in (
    'exception_approved', 'exception_rejected', 'amount_change_requested',
    'category_change_requested', 'budget_adjustment_requested'
  ) and v_clean_comments is null then
    raise exception 'comments_required_for_exception_action';
  end if;
  if p_action = 'changes_requested' and v_clean_comments is null then
    raise exception 'comments_required_for_changes_requested';
  end if;
  if not v_is_exception and p_action not in ('approved', 'rejected', 'changes_requested') then
    raise exception 'exception_action_not_allowed_for_approvable_request';
  end if;
  if v_is_exception and p_action = 'approved' then
    raise exception 'normal_approval_not_allowed_for_budget_exception';
  end if;
  if v_is_exception and p_action not in (
    'exception_approved', 'exception_rejected', 'amount_change_requested',
    'category_change_requested', 'budget_adjustment_requested'
  ) then
    raise exception 'invalid_exception_action';
  end if;

  if v_request.approver_id is not null
     and p_actor_profile_id <> v_request.approver_id then
    raise exception 'selected_approver_only';
  end if;

  -- Migration 018 did not store the assignment id. Preserve its override only
  -- when the same assignment already existed when the request was created.
  if v_request.approver_assignment_id is null
     and v_request.approver_selection_source is null
     and v_request.approver_id is not null then
    select * into v_assignment
    from public.approver_assignments aa
    where aa.company_id = v_request.company_id
      and aa.requester_id = v_request.requested_by
      and aa.approver_id = v_request.approver_id
      and aa.created_at <= v_request.created_at
    order by aa.created_at desc
    limit 1;
    v_legacy_assignment_override := found;
  end if;

  if v_request.approver_assignment_id is not null or v_legacy_assignment_override then
    if v_request.approver_assignment_id is not null then
      select * into v_assignment
      from public.approver_assignments aa
      where aa.id = v_request.approver_assignment_id;
    end if;
    if not found
       or v_assignment.company_id <> v_request.company_id
       or v_assignment.requester_id <> v_request.requested_by
       or v_assignment.approver_id <> v_request.approver_id then
      raise exception 'approver_assignment_snapshot_invalid';
    end if;

    select r.id into v_role_id
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = p_actor_profile_id
    order by
      case when lower(trim(r.name)) = any (public.payment_request_approver_role_names()) then 0 else 1 end,
      lower(trim(r.name))
    limit 1;
    v_rule_id := null;
    v_approval_level := 0;
    v_uses_assignment_snapshot := true;
  else
    if not exists (
      select 1 from public.user_roles ur where ur.profile_id = p_actor_profile_id
    ) then
      raise exception 'actor_has_no_role';
    end if;

    select ar.id, ar.role_id, ar.approval_level
    into v_rule_id, v_role_id, v_approval_level
    from public.approval_rules ar
    join public.user_roles ur
      on ur.role_id = ar.role_id and ur.profile_id = p_actor_profile_id
    join public.roles rule_role on rule_role.id = ar.role_id
    where ar.active
      and (
        v_request.approver_id is null
        or lower(trim(rule_role.name)) = any (public.payment_request_approver_role_names())
      )
      and (ar.company_id is null or ar.company_id = v_request.company_id)
      and (ar.cost_center_id is null or ar.cost_center_id = v_request.cost_center_id)
      and coalesce(v_request.amount_requested, 0) >= ar.amount_min
      and (ar.amount_max is null or coalesce(v_request.amount_requested, 0) <= ar.amount_max)
      and (
        (p_action = 'approved' and ar.can_approve)
        or (p_action = 'exception_approved' and ar.can_approve and ar.can_approve_exception)
        or (p_action in ('rejected', 'exception_rejected') and ar.can_reject)
        or (p_action in ('changes_requested', 'amount_change_requested', 'category_change_requested') and ar.can_request_changes)
        or (p_action = 'budget_adjustment_requested' and ar.can_request_budget_adjustment)
      )
    order by
      case when ar.company_id is not null then 0 else 1 end,
      case when ar.cost_center_id is not null then 0 else 1 end,
      ar.approval_level asc
    limit 1;

    if v_rule_id is null then
      if p_action = 'exception_approved' then
        raise exception 'selected_approver_cannot_approve_exception';
      elsif p_action = 'approved' then
        raise exception 'selected_approver_cannot_approve';
      elsif p_action in ('rejected', 'exception_rejected') then
        raise exception 'selected_approver_cannot_reject';
      elsif p_action in ('changes_requested', 'amount_change_requested', 'category_change_requested') then
        raise exception 'selected_approver_cannot_request_changes';
      elsif p_action = 'budget_adjustment_requested' then
        raise exception 'selected_approver_cannot_request_budget_adjustment';
      else
        raise exception 'approval_rule_not_found';
      end if;
    end if;
  end if;

  v_previous_status := v_request.status::text;
  v_new_status := case p_action
    when 'approved' then 'approved'
    when 'rejected' then 'rejected'
    when 'changes_requested' then 'changes_requested'
    when 'exception_approved' then 'approved'
    when 'exception_rejected' then 'rejected'
    when 'amount_change_requested' then 'changes_requested'
    when 'category_change_requested' then 'changes_requested'
    when 'budget_adjustment_requested' then 'changes_requested'
  end;

  insert into public.payment_request_approvals (
    payment_request_id, actor_profile_id, role_id, action, from_status,
    to_status, comments, approval_level, budget_decision_snapshot,
    budget_block_reason_snapshot, budget_result_snapshot
  ) values (
    p_payment_request_id, p_actor_profile_id, v_role_id, p_action,
    v_previous_status, v_new_status, v_clean_comments, v_approval_level,
    v_request.budget_decision, v_request.budget_block_reason, v_request.budget_result
  );

  update public.payment_requests
  set status = v_new_status::public.payment_request_status,
      exception_status = case
        when p_action = 'exception_approved' then 'approved'
        when p_action = 'exception_rejected' then 'rejected'
        when p_action in ('amount_change_requested','category_change_requested','budget_adjustment_requested') then 'changes_requested'
        else exception_status
      end,
      exception_action = case when v_is_exception then p_action else exception_action end,
      exception_reason = case when v_is_exception then v_clean_comments else exception_reason end,
      exception_approved_by = case when p_action = 'exception_approved' then p_actor_profile_id else exception_approved_by end,
      exception_approved_at = case when p_action = 'exception_approved' then now() else exception_approved_at end,
      requires_budget_adjustment = case when p_action = 'budget_adjustment_requested' then true else requires_budget_adjustment end,
      operational_comments = coalesce(v_clean_comments, operational_comments),
      updated_at = now()
  where id = p_payment_request_id;

  return jsonb_build_object(
    'payment_request_id', p_payment_request_id,
    'previous_status', v_previous_status,
    'new_status', v_new_status,
    'action', p_action,
    'actor_profile_id', p_actor_profile_id,
    'budget_decision', v_request.budget_decision,
    'is_exception', v_is_exception,
    'assignment_snapshot_override', v_uses_assignment_snapshot,
    'legacy_assignment_override', v_legacy_assignment_override,
    'message', 'decision_registered'
  );
end;
$$;


ALTER FUNCTION "public"."decide_payment_request"("p_payment_request_id" "uuid", "p_actor_profile_id" "uuid", "p_action" "text", "p_comments" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispute_extraordinary_authorization"("p_authorization_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  if v_reason is null or char_length(v_reason) < 20 then
    raise exception 'dispute_reason_too_short';
  end if;
  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'invalid_idempotency_key';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_authorization_id::text, 37037));
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id
  for update;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;
  if v_actor <> v_authorization.external_director_profile_id
     or not public.extraordinary_profile_is_company_director(
       v_actor,
       v_authorization.company_id
     ) then
    raise exception 'registered_external_director_required';
  end if;
  if v_authorization.status <> 'consumed_pending_ratification' then
    raise exception 'extraordinary_authorization_not_pending_ratification';
  end if;

  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set status = 'disputed',
      disputed_by = v_actor,
      disputed_at = v_now,
      dispute_reason = v_reason,
      updated_at = v_now
  where id = v_authorization.id
    and status = 'consumed_pending_ratification';

  perform public.extraordinary_append_event(
    v_authorization.id,
    'authorization_disputed',
    v_actor,
    'authorization-disputed:' || v_authorization.id::text || ':' || v_key,
    jsonb_build_object(
      'layout_id', v_authorization.consumed_layout_id,
      'layout_line_id', v_authorization.consumed_layout_line_id,
      'reason', v_reason
    )
  );
  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'status', 'disputed',
    'disputed_at', v_now
  );
end
$$;


ALTER FUNCTION "public"."dispute_extraordinary_authorization"("p_authorization_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_approval_batch_item_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.approval_batches%rowtype;
  v_request public.payment_requests%rowtype;
  v_company_name text;
  v_provider_name text;
  v_recipient record;
  v_has_recipient boolean := false;
begin
  if new.director_status <> 'rejected' or old.director_status = 'rejected' then return new; end if;
  select * into v_batch from public.approval_batches where id = new.batch_id;
  select * into v_request from public.payment_requests where id = new.payment_request_id;
  select coalesce(nullif(btrim(legal_name), ''), name) into v_company_name
  from public.companies where id = v_batch.company_id;
  select coalesce(nullif(btrim(alias), ''), nombre_completo) into v_provider_name
  from public.proveedores where id = v_request.proveedor_id;

  for v_recipient in
    with candidates as (
      select p.id, p.email, 'usuario_solicitante'::text as recipient_type,
             'solicitante'::text as recipient_role, 1 as priority_order
      from public.profiles p where p.id = v_request.requested_by
      union all
      select p.id, p.email, 'administrador_sistema', 'finanzas', 2
      from public.profiles p
      join public.user_roles ur on ur.profile_id = p.id
      join public.roles r on r.id = ur.role_id
      where coalesce(p.active, true)
        and lower(btrim(r.name)) = any (public.flux_finance_roles())
    )
    select distinct on (lower(btrim(email))) id, email, recipient_type, recipient_role
    from candidates
    where nullif(btrim(email), '') is not null
    order by lower(btrim(email)), priority_order, id
  loop
    v_has_recipient := true;
    perform public.insert_approval_batch_notification(
      'approval_batch.item_rejected', 'approval_batch_items', new.id,
      v_request.request_number, v_recipient.recipient_type,
      v_recipient.id, v_recipient.email, v_recipient.recipient_role,
      'Pago rechazado en corte: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object('batch_label', v_batch.label, 'company', v_company_name,
        'folio', v_request.request_number, 'provider', v_provider_name,
        'amount', v_request.amount_requested, 'currency', v_request.currency,
        'status', new.director_status, 'decision_comment', new.director_reject_reason,
        'decision_label', 'Motivo de rechazo', 'path', '/approval_batches.html'),
      'approval_batch.item_rejected:' || new.id::text || ':' || v_recipient.id::text,
      'high'
    );
  end loop;
  if not v_has_recipient then
    perform public.insert_approval_batch_notification(
      'approval_batch.item_rejected', 'approval_batch_items', new.id,
      v_request.request_number, 'administrador_sistema', null, null, 'finanzas',
      'Pago rechazado sin destinatario: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object('batch_label', v_batch.label, 'company', v_company_name,
        'folio', v_request.request_number, 'status', new.director_status,
        'decision_comment', new.director_reject_reason,
        'decision_label', 'Motivo de rechazo', 'path', '/approval_batches.html'),
      'approval_batch.item_rejected:' || new.id::text || ':missing_recipient',
      'high'
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enqueue_approval_batch_item_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_approval_batch_status_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_company_name text;
  v_director public.profiles%rowtype;
  v_recipient record;
  v_totals jsonb;
  v_count integer;
  v_event_type text;
  v_has_recipient boolean := false;
begin
  if old.status = new.status then return new; end if;
  select coalesce(nullif(btrim(legal_name), ''), name) into v_company_name
  from public.companies where id = new.company_id;
  select * into v_director from public.profiles where id = new.director_id;
  select count(*)
    into v_count
  from public.approval_batch_items abi
  where abi.batch_id = new.id and abi.removed_at is null;
  v_totals := public.approval_batch_totals_by_currency(new.id);

  if new.status = 'submitted' then
    perform public.insert_approval_batch_notification(
      'approval_batch.submitted', 'approval_batches', new.id, new.label,
      'administrador_sistema', v_director.id, v_director.email, 'direccion',
      'Corte semanal por autorizar: ' || new.label,
      jsonb_build_object('batch_label', new.label, 'company', v_company_name,
        'period_start', new.period_start, 'period_end', new.period_end,
        'item_count', v_count, 'totals_by_currency', v_totals, 'status', new.status,
        'path', '/approval_batches.html'),
      'approval_batch.submitted:' || new.id::text || ':' || new.director_id::text,
      'high'
    );
  elsif new.status in ('approved', 'partially_approved') then
    v_event_type := case when new.status = 'approved'
      then 'approval_batch.approved' else 'approval_batch.partially_approved' end;
    for v_recipient in
      select distinct on (lower(btrim(p.email))) p.id, p.email
      from public.profiles p
      join public.user_roles ur on ur.profile_id = p.id
      join public.roles r on r.id = ur.role_id
      where coalesce(p.active, true)
        and nullif(btrim(p.email), '') is not null
        and lower(btrim(r.name)) = any (public.flux_finance_roles())
      order by lower(btrim(p.email)), p.id
    loop
      v_has_recipient := true;
      perform public.insert_approval_batch_notification(
        v_event_type, 'approval_batches', new.id, new.label,
        'administrador_sistema', v_recipient.id, v_recipient.email, 'finanzas',
        case when new.status = 'approved' then 'Corte semanal aprobado: ' else 'Corte semanal con rechazos: ' end || new.label,
        jsonb_build_object('batch_label', new.label, 'company', v_company_name,
          'period_start', new.period_start, 'period_end', new.period_end,
          'item_count', v_count, 'totals_by_currency', v_totals, 'status', new.status,
          'path', '/approval_batches.html'),
        v_event_type || ':' || new.id::text || ':' || v_recipient.id::text,
        'high'
      );
    end loop;
    if not v_has_recipient then
      perform public.insert_approval_batch_notification(
        v_event_type, 'approval_batches', new.id, new.label,
        'administrador_sistema', null, null, 'finanzas',
        'Corte semanal sin destinatario de Finanzas: ' || new.label,
        jsonb_build_object('batch_label', new.label, 'company', v_company_name,
          'totals_by_currency', v_totals, 'status', new.status,
          'path', '/approval_batches.html'),
        v_event_type || ':' || new.id::text || ':missing_finance',
        'high'
      );
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enqueue_approval_batch_status_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_extraordinary_payment_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_company_name text;
  v_provider_name text;
  v_authorizer_name text;
  v_recipient record;
  v_has_recipient boolean := false;
begin
  if new.status <> 'active' then return new; end if;
  select * into v_request from public.payment_requests where id = new.payment_request_id;
  select coalesce(nullif(btrim(c.legal_name), ''), c.name)
    into v_company_name from public.companies c where c.id = v_request.company_id;
  select coalesce(nullif(btrim(p.alias), ''), p.nombre_completo)
    into v_provider_name from public.proveedores p where p.id = v_request.proveedor_id;
  select p.full_name into v_authorizer_name from public.profiles p where p.id = new.authorized_by;

  for v_recipient in
    with candidates as (
      select p.id, p.email, 'finanzas'::text as recipient_role, 1 as priority_order
      from public.profiles p
      join public.user_roles ur on ur.profile_id = p.id
      join public.roles r on r.id = ur.role_id
      where coalesce(p.active, true)
        and lower(btrim(r.name)) = any (public.flux_finance_roles())
      union all
      select p.id, p.email, 'direccion', 2
      from public.company_directors cd
      join public.profiles p on p.id = cd.director_profile_id
      where cd.company_id = v_request.company_id
        and cd.active
        and coalesce(p.active, true)
    )
    select distinct on (lower(btrim(email))) id, email, recipient_role
    from candidates
    where nullif(btrim(email), '') is not null
    order by lower(btrim(email)), priority_order, id
  loop
    v_has_recipient := true;
    perform public.insert_approval_batch_notification(
      'payment_request.extraordinary_authorized',
      'payment_request_extraordinary_authorizations',
      new.id,
      v_request.request_number,
      'administrador_sistema',
      v_recipient.id,
      v_recipient.email,
      v_recipient.recipient_role,
      'Pago extraordinario autorizado: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object(
        'folio', v_request.request_number,
        'provider', v_provider_name,
        'amount', v_request.amount_requested,
        'currency', v_request.currency,
        'company', v_company_name,
        'status', 'extraordinary_authorized',
        'extraordinary_category', new.category,
        'decision_comment', new.reason,
        'decision_label', 'Motivo extraordinario (' || new.category || ')',
        'authorized_by', v_authorizer_name,
        'authorized_at', new.authorized_at,
        'path', '/solicitudes.html?request_id=' || v_request.id::text
      ),
      'payment_request.extraordinary_authorized:' || new.id::text || ':' || v_recipient.id::text,
      'high'
    );
  end loop;

  if not v_has_recipient then
    perform public.insert_approval_batch_notification(
      'payment_request.extraordinary_authorized',
      'payment_request_extraordinary_authorizations',
      new.id,
      v_request.request_number,
      'administrador_sistema',
      null,
      null,
      'finanzas',
      'Pago extraordinario sin destinatario: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object(
        'folio', v_request.request_number,
        'company', v_company_name,
        'status', 'extraordinary_authorized',
        'decision_comment', new.reason,
        'decision_label', 'Motivo extraordinario',
        'path', '/solicitudes.html?request_id=' || v_request.id::text
      ),
      'payment_request.extraordinary_authorized:' || new.id::text || ':missing_recipient',
      'high'
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enqueue_extraordinary_payment_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification_event"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid" DEFAULT NULL::"uuid", "p_recipient_role" "text" DEFAULT NULL::"text", "p_subject" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_ids uuid[] := array[]::uuid[];
  v_inserted_id uuid;
  v_existing_id uuid;
  v_profile_id uuid;
  v_email text;
  v_status text;
  v_last_error text;
  v_missing_recipient boolean := false;
  v_missing_email boolean := false;
  v_deduplicated boolean := false;
  v_key text;
  v_admin record;
  v_admin_count integer := 0;
begin
  if not public.notification_current_user_has_role(array['admin', 'sysadmin']) then
    raise exception 'not_allowed_to_enqueue_notifications';
  end if;

  if nullif(trim(coalesce(p_event_type, '')), '') is null then
    raise exception 'event_type_required';
  end if;

  if p_recipient_type not in ('usuario_solicitante', 'administrador_sistema') then
    raise exception 'invalid_recipient_type';
  end if;

  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  if coalesce(p_payload, '{}'::jsonb) ?| array[
    'bank_account',
    'account',
    'account_number',
    'cuenta',
    'clabe',
    'raw_payload',
    'token',
    'secret',
    'password',
    'private_key'
  ] then
    raise exception 'payload_contains_sensitive_key';
  end if;

  if p_recipient_type = 'usuario_solicitante' then
    if p_recipient_profile_id is null then
      v_status := 'dead_letter';
      v_last_error := 'missing_recipient_profile_id';
      v_missing_recipient := true;
    else
      select p.id, nullif(trim(coalesce(p.email, '')), '')
      into v_profile_id, v_email
      from public.profiles p
      where p.id = p_recipient_profile_id;

      if v_profile_id is null then
        v_status := 'dead_letter';
        v_last_error := 'recipient_profile_not_found';
        v_missing_recipient := true;
      elsif v_email is null then
        v_status := 'dead_letter';
        v_last_error := 'recipient_email_missing';
        v_missing_email := true;
      else
        v_status := 'pending';
      end if;
    end if;

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      last_error,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      v_profile_id,
      v_email,
      p_recipient_role,
      'email',
      coalesce(nullif(trim(p_priority), ''), 'normal'),
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      p_idempotency_key,
      v_status,
      v_last_error,
      case when v_status = 'pending' then now() else null end
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id into v_existing_id
      from public.notification_events
      where idempotency_key = p_idempotency_key;
      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;

    return jsonb_build_object(
      'event_ids', to_jsonb(v_event_ids),
      'status', v_status,
      'deduplicated', v_deduplicated,
      'missing_recipient', v_missing_recipient,
      'missing_email', v_missing_email
    );
  end if;

  for v_admin in
    select distinct
      p.id as profile_id,
      nullif(trim(coalesce(p.email, '')), '') as email
    from public.profiles p
    join public.user_roles ur on ur.profile_id = p.id
    join public.roles r on r.id = ur.role_id
    where lower(trim(r.name)) in ('admin', 'sysadmin')
      and nullif(trim(coalesce(p.email, '')), '') is not null
  loop
    v_admin_count := v_admin_count + 1;
    v_key := p_idempotency_key || ':admin:' || v_admin.profile_id::text;

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      v_admin.profile_id,
      v_admin.email,
      coalesce(p_recipient_role, 'admin'),
      'email',
      coalesce(nullif(trim(p_priority), ''), 'normal'),
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      v_key,
      'pending',
      now()
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id into v_existing_id
      from public.notification_events
      where idempotency_key = v_key;
      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;
  end loop;

  if v_admin_count = 0 then
    v_missing_recipient := true;
    v_key := p_idempotency_key || ':admin:none';

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      last_error,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      coalesce(p_recipient_role, 'admin'),
      'email',
      coalesce(nullif(trim(p_priority), ''), 'normal'),
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      v_key,
      'dead_letter',
      'admin_recipient_missing',
      null
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id into v_existing_id
      from public.notification_events
      where idempotency_key = v_key;
      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;
  end if;

  return jsonb_build_object(
    'event_ids', to_jsonb(v_event_ids),
    'status', case when v_missing_recipient then 'dead_letter' else 'pending' end,
    'deduplicated', v_deduplicated,
    'missing_recipient', v_missing_recipient,
    'missing_email', false
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_notification_event"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid", "p_recipient_role" "text", "p_subject" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification_event_internal"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid" DEFAULT NULL::"uuid", "p_recipient_role" "text" DEFAULT NULL::"text", "p_subject" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_ids uuid[] := array[]::uuid[];
  v_inserted_id uuid;
  v_existing_id uuid;
  v_profile_id uuid;
  v_email text;
  v_status text;
  v_last_error text;
  v_missing_recipient boolean := false;
  v_missing_email boolean := false;
  v_deduplicated boolean := false;
  v_key text;
  v_admin record;
  v_admin_count integer := 0;
  v_priority text;
begin
  v_priority := case lower(trim(coalesce(p_priority, 'normal')))
    when 'low' then 'low'
    when 'baja' then 'low'
    when 'normal' then 'normal'
    when 'media' then 'normal'
    when 'medium' then 'normal'
    when 'high' then 'high'
    when 'alta' then 'high'
    when 'critical' then 'critical'
    when 'critica' then 'critical'
    else 'normal'
  end;

  if nullif(trim(coalesce(p_event_type, '')), '') is null then
    raise exception 'event_type_required';
  end if;

  if p_event_type not in (
    'payment_request.created',
    'payment_request.approved',
    'payment_request.rejected',
    'payment_request.changes_requested',
    'payment_request.exception_approved',
    'payment_request.exception_rejected'
  ) then
    raise exception 'invalid_phase2_event_type';
  end if;

  if p_source_table <> 'payment_requests' then
    raise exception 'invalid_phase2_source_table';
  end if;

  if p_source_id is null then
    raise exception 'source_id_required';
  end if;

  if not exists (
    select 1
    from public.payment_requests pr
    where pr.id = p_source_id
  ) then
    raise exception 'source_payment_request_not_found';
  end if;

  if p_recipient_type not in ('usuario_solicitante', 'administrador_sistema') then
    raise exception 'invalid_recipient_type';
  end if;

  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(coalesce(p_payload, '{}'::jsonb)) as k(key_name)
    where lower(k.key_name) = any (array[
      ('bank' || '_account'),
      ('acc' || 'ount'),
      ('account' || '_number'),
      ('cue' || 'nta'),
      ('cla' || 'be'),
      ('raw' || '_payload'),
      ('tok' || 'en'),
      ('se' || 'cret'),
      ('pass' || 'word'),
      ('private' || '_key'),
      ('api' || '_key')
    ])
  ) then
    raise exception 'payload_contains_sensitive_key';
  end if;

  if p_recipient_type = 'usuario_solicitante' then
    if p_recipient_profile_id is null then
      v_status := 'dead_letter';
      v_last_error := 'missing_recipient_profile_id';
      v_missing_recipient := true;
    else
      select p.id, nullif(trim(coalesce(p.email, '')), '')
      into v_profile_id, v_email
      from public.profiles p
      where p.id = p_recipient_profile_id;

      if v_profile_id is null then
        v_status := 'dead_letter';
        v_last_error := 'recipient_profile_not_found';
        v_missing_recipient := true;
      elsif v_email is null then
        v_status := 'dead_letter';
        v_last_error := 'recipient_email_missing';
        v_missing_email := true;
      else
        v_status := 'pending';
      end if;
    end if;

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      last_error,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      v_profile_id,
      v_email,
      p_recipient_role,
      'email',
      v_priority,
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      p_idempotency_key,
      v_status,
      v_last_error,
      case when v_status = 'pending' then now() else null end
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id
      into v_existing_id
      from public.notification_events
      where idempotency_key = p_idempotency_key;

      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;

    return jsonb_build_object(
      'event_ids', to_jsonb(v_event_ids),
      'status', v_status,
      'deduplicated', v_deduplicated,
      'missing_recipient', v_missing_recipient,
      'missing_email', v_missing_email
    );
  end if;

  for v_admin in
    select distinct
      p.id as profile_id,
      nullif(trim(coalesce(p.email, '')), '') as email
    from public.profiles p
    join public.user_roles ur on ur.profile_id = p.id
    join public.roles r on r.id = ur.role_id
    where lower(trim(r.name)) in ('admin', 'sysadmin')
      and nullif(trim(coalesce(p.email, '')), '') is not null
  loop
    v_admin_count := v_admin_count + 1;
    v_key := p_idempotency_key || ':admin:' || v_admin.profile_id::text;

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      v_admin.profile_id,
      v_admin.email,
      coalesce(p_recipient_role, 'admin'),
      'email',
      v_priority,
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      v_key,
      'pending',
      now()
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id
      into v_existing_id
      from public.notification_events
      where idempotency_key = v_key;

      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;
  end loop;

  if v_admin_count = 0 then
    v_missing_recipient := true;
    v_key := p_idempotency_key || ':admin:none';

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      last_error,
      next_attempt_at
    )
    values (
      p_event_type,
      p_source_table,
      p_source_id,
      p_source_folio,
      p_recipient_type,
      coalesce(p_recipient_role, 'admin'),
      'email',
      v_priority,
      p_subject,
      coalesce(p_payload, '{}'::jsonb),
      v_key,
      'dead_letter',
      'admin_recipient_missing',
      null
    )
    on conflict (idempotency_key) do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      select id
      into v_existing_id
      from public.notification_events
      where idempotency_key = v_key;

      v_event_ids := array_append(v_event_ids, v_existing_id);
      v_deduplicated := true;
    else
      v_event_ids := array_append(v_event_ids, v_inserted_id);
    end if;
  end if;

  return jsonb_build_object(
    'event_ids', to_jsonb(v_event_ids),
    'status', case when v_missing_recipient then 'dead_letter' else 'pending' end,
    'deduplicated', v_deduplicated,
    'missing_recipient', v_missing_recipient,
    'missing_email', false
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_notification_event_internal"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid", "p_recipient_role" "text", "p_subject" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_receipt_linked_notifications_internal"("p_link_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_link public.payment_request_receipt_links%rowtype;
  v_request public.payment_requests%rowtype;
  v_evidence public.payment_operation_evidence%rowtype;
  v_requester_profile public.profiles%rowtype;
  v_provider public.proveedores%rowtype;
  v_company_name text;
  v_intake_folio text;
  v_external_folio text;
  v_requester_email text;
  v_provider_email text;
  v_requester_state text;
  v_provider_state text;
  v_unique_recipient_count integer := 0;
  v_notification_resolution jsonb;
  v_notification_event_ids uuid[] := array[]::uuid[];
  v_notification_events_created integer := 0;
  v_base_payload jsonb;
  v_recipient record;
  v_event_id uuid;
  v_idempotency_key text;
begin
  if p_link_id is null then
    raise exception 'payment_receipt_notification_link_id_required';
  end if;

  select *
    into v_link
  from public.payment_request_receipt_links
  where id = p_link_id;
  if not found then
    raise exception 'payment_receipt_notification_link_not_found';
  end if;

  select *
    into v_request
  from public.payment_requests
  where id = v_link.payment_request_id;
  if not found then
    raise exception 'payment_receipt_notification_request_not_found';
  end if;

  select *
    into v_evidence
  from public.payment_operation_evidence
  where id = v_link.evidence_id;
  if not found then
    raise exception 'payment_receipt_notification_evidence_not_found';
  end if;

  if v_request.id <> v_link.payment_request_id
     or v_request.company_id <> v_link.company_id
     or v_evidence.id <> v_link.evidence_id
     or v_evidence.operation_id <> v_link.operation_id
     or v_evidence.company_id <> v_link.company_id
     or v_request.status::text <> 'paid'
     or v_evidence.status <> 'shareable'
     or v_evidence.page_count is distinct from 1
     or not v_evidence.single_operation_attested
     or v_evidence.storage_bucket <> 'payment-batch-documents'
     or v_evidence.mime_type <> 'application/pdf'
     or v_evidence.file_size_bytes is null
     or v_evidence.file_size_bytes not between 1 and 26214400
     or v_evidence.individual_sha256 is null
     or v_evidence.individual_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'payment_receipt_notification_contract_invalid';
  end if;

  if v_request.requested_by is not null then
    select *
      into v_requester_profile
    from public.profiles
    where id = v_request.requested_by
      and coalesce(active, true);
  end if;

  select *
    into v_provider
  from public.proveedores
  where id = v_request.proveedor_id;
  if not found then
    raise exception 'payment_receipt_notification_provider_not_found';
  end if;

  select c.name
    into v_company_name
  from public.companies c
  where c.id = v_link.company_id;

  select pi.public_folio
    into v_intake_folio
  from public.payment_intake pi
  where pi.created_payment_request_id = v_request.id
  limit 1;

  v_external_folio := coalesce(
    nullif(btrim(v_intake_folio), ''),
    nullif(btrim(v_request.request_number), '')
  );
  v_requester_email := lower(btrim(coalesce(v_requester_profile.email, '')));
  v_provider_email := lower(btrim(coalesce(v_provider.email, '')));
  v_requester_state := public.payment_receipt_notification_email_state(
    v_requester_profile.email
  );
  v_provider_state := public.payment_receipt_notification_email_state(
    v_provider.email
  );

  select count(distinct candidate.email_normalized)::integer
    into v_unique_recipient_count
  from (
    values
      (v_requester_email, v_requester_state),
      (v_provider_email, v_provider_state)
  ) as candidate(email_normalized, resolution)
  where candidate.resolution = 'eligible';

  v_notification_resolution := jsonb_build_object(
    'requester', v_requester_state,
    'provider', v_provider_state,
    'unique_recipient_count', v_unique_recipient_count
  );

  if v_external_folio is null then
    return jsonb_build_object(
      'notification_resolution', v_notification_resolution,
      'notification_event_ids', to_jsonb(v_notification_event_ids),
      'notification_events_created', 0,
      'notification_events_total', 0,
      'notification_block_reason', 'missing_external_folio'
    );
  end if;

  v_base_payload := jsonb_build_object(
    'contract_version', 'v1',
    'folio', v_external_folio,
    'provider', coalesce(
      nullif(btrim(v_provider.alias), ''),
      nullif(btrim(v_provider.nombre_completo), ''),
      'Proveedor'
    ),
    'company', coalesce(nullif(btrim(v_company_name), ''), 'Empresa'),
    'concept', coalesce(
      nullif(btrim(v_request.concept), ''),
      nullif(btrim(v_request.payment_concept), ''),
      'Solicitud de pago'
    ),
    'amount', v_request.amount_requested,
    'currency', v_request.currency,
    'payment_date', v_link.payment_date,
    'reference_hint', v_link.reference_hint,
    'status', 'paid',
    'recipient_roles', '[]'::jsonb
  );

  for v_recipient in
    with candidates as (
      select
        'requester'::text as recipient_role,
        v_requester_email as email_normalized,
        v_requester_state as resolution,
        v_request.requested_by as profile_id
      union all
      select
        'provider'::text,
        v_provider_email,
        v_provider_state,
        null::uuid
    )
    select
      candidate.email_normalized,
      array_agg(
        candidate.recipient_role
        order by case candidate.recipient_role when 'requester' then 1 else 2 end
      ) as recipient_roles,
      case
        when bool_or(candidate.recipient_role = 'requester')
          then 'usuario_solicitante'
        else 'proveedor'
      end as recipient_type,
      (
        array_agg(candidate.profile_id) filter (
          where candidate.recipient_role = 'requester'
        )
      )[1] as recipient_profile_id
    from candidates candidate
    where candidate.resolution = 'eligible'
    group by candidate.email_normalized
    order by min(
      case candidate.recipient_role when 'requester' then 1 else 2 end
    )
  loop
    v_idempotency_key := format(
      'notification:payment_receipt.linked:%s:%s:v1',
      v_link.id,
      md5(v_recipient.email_normalized)
    );

    insert into public.notification_events(
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      next_attempt_at
    ) values (
      'payment_receipt.linked',
      'payment_request_receipt_links',
      v_link.id,
      v_external_folio,
      v_recipient.recipient_type,
      v_recipient.recipient_profile_id,
      v_recipient.email_normalized,
      case
        when v_recipient.recipient_roles = array['requester', 'provider']::text[]
          then 'requester_provider'
        else v_recipient.recipient_roles[1]
      end,
      'email',
      'normal',
      case
        when 'requester' = any(v_recipient.recipient_roles)
          then format('Comprobante de pago disponible — %s', v_external_folio)
        else format('Comprobante de pago — %s', v_external_folio)
      end,
      jsonb_set(
        v_base_payload,
        '{recipient_roles}',
        to_jsonb(v_recipient.recipient_roles),
        true
      ),
      v_idempotency_key,
      'pending',
      clock_timestamp()
    )
    on conflict (idempotency_key) do nothing
    returning id into v_event_id;

    if v_event_id is null then
      select event.id
        into v_event_id
      from public.notification_events event
      where event.idempotency_key = v_idempotency_key;
    else
      v_notification_events_created := v_notification_events_created + 1;
    end if;

    if v_event_id is not null then
      v_notification_event_ids := array_append(
        v_notification_event_ids,
        v_event_id
      );
    end if;
    v_event_id := null;
  end loop;

  return jsonb_build_object(
    'notification_resolution', v_notification_resolution,
    'notification_event_ids', to_jsonb(v_notification_event_ids),
    'notification_events_created', v_notification_events_created,
    'notification_events_total', cardinality(v_notification_event_ids)
  );
end;
$_$;


ALTER FUNCTION "public"."enqueue_payment_receipt_linked_notifications_internal"("p_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_request_created_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile public.profiles%rowtype;
  v_role_name text;
  v_status text := 'pending';
  v_last_error text;
  v_payload jsonb;
begin
  if new.approver_id is null then
    v_status := 'dead_letter';
    v_last_error := 'missing_approver_profile_id';
  else
    select * into v_profile
    from public.profiles
    where id = new.approver_id and coalesce(active, true);

    if not found then
      v_status := 'dead_letter';
      v_last_error := 'approver_profile_not_found';
    elsif not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
      v_status := 'dead_letter';
      v_last_error := 'approver_not_eligible_for_company';
    elsif nullif(btrim(coalesce(v_profile.email, '')), '') is null then
      v_status := 'dead_letter';
      v_last_error := 'recipient_email_missing';
    end if;
  end if;

  select lower(trim(r.name)) into v_role_name
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  where ur.profile_id = new.approver_id
    and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
  order by lower(trim(r.name))
  limit 1;

  v_payload := public.notification_payment_request_payload_with_extra(
    new.id,
    jsonb_build_object(
      'approver', coalesce(nullif(btrim(v_profile.full_name), ''), v_profile.email),
      'approver_profile_id', new.approver_id
    )
  );

  insert into public.notification_events (
    event_type, source_table, source_id, source_folio, recipient_type,
    recipient_profile_id, recipient_email, recipient_role, channel, priority,
    subject, payload, idempotency_key, status, last_error, next_attempt_at
  ) values (
    'payment_request.created', 'payment_requests', new.id, new.request_number,
    'administrador_sistema',
    case when v_profile.id is not null then v_profile.id else null end,
    case when v_status = 'pending' then nullif(btrim(v_profile.email), '') else null end,
    v_role_name, 'email', 'normal',
    'Nueva solicitud de pago: ' || coalesce(new.request_number, new.id::text),
    v_payload,
    'payment_request.created:' || new.id::text || ':approver',
    v_status, v_last_error,
    case when v_status = 'pending' then now() else null end
  )
  on conflict (idempotency_key) do nothing;

  return new;
exception
  when others then
    insert into public.notification_events (
      event_type, source_table, source_id, source_folio, recipient_type,
      channel, priority, subject, payload, idempotency_key, status, last_error
    ) values (
      'payment_request.created', 'payment_requests', new.id, new.request_number,
      'administrador_sistema', 'email', 'normal',
      'Nueva solicitud de pago: ' || coalesce(new.request_number, new.id::text),
      jsonb_build_object('folio', new.request_number, 'path', '/solicitudes.html'),
      'payment_request.created:' || new.id::text || ':enqueue-error',
      'dead_letter', 'created_notification_enqueue_failed'
    )
    on conflict (idempotency_key) do nothing;
    return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_payment_request_created_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_request_decision_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_type text;
  v_request public.payment_requests%rowtype;
  v_subject text;
  v_idempotency_prefix text;
  v_decision_label text;
  v_payload jsonb;
  v_priority text;
  v_role_names text[] := array[]::text[];
begin
  select * into v_request
  from public.payment_requests
  where id = new.payment_request_id;
  if not found then
    return new;
  end if;

  v_event_type := case new.action
    when 'approved' then 'payment_request.approved'
    when 'rejected' then 'payment_request.rejected'
    when 'changes_requested' then 'payment_request.changes_requested'
    when 'amount_change_requested' then 'payment_request.changes_requested'
    when 'category_change_requested' then 'payment_request.changes_requested'
    when 'budget_adjustment_requested' then 'payment_request.changes_requested'
    when 'exception_approved' then 'payment_request.exception_approved'
    when 'exception_rejected' then 'payment_request.exception_rejected'
    else null
  end;
  if v_event_type is null then
    return new;
  end if;

  v_priority := case when v_event_type like 'payment_request.exception_%' then 'high' else 'normal' end;
  v_decision_label := public.notification_decision_label(v_event_type);
  v_payload := public.notification_payment_request_payload_with_extra(
    v_request.id,
    jsonb_build_object(
      'decision_action', new.action,
      'decision_comment', nullif(btrim(coalesce(new.comments, '')), ''),
      'decision_label', v_decision_label
    )
  );
  v_idempotency_prefix := v_event_type || ':' || new.payment_request_id::text || ':' || new.id::text;
  v_subject := case v_event_type
    when 'payment_request.approved' then 'Solicitud aprobada: '
    when 'payment_request.rejected' then 'Solicitud rechazada: '
    when 'payment_request.changes_requested' then 'Cambios solicitados: '
    when 'payment_request.exception_approved' then 'Excepcion presupuestal aprobada: '
    when 'payment_request.exception_rejected' then 'Excepcion presupuestal rechazada: '
    else 'Actualizacion de solicitud: '
  end || coalesce(v_request.request_number, new.payment_request_id::text);

  if v_event_type in ('payment_request.approved', 'payment_request.exception_approved') then
    v_role_names := array['finance', 'finanzas'];
  end if;

  with requester_candidate as (
    select
      10 as sort_rank,
      'usuario_solicitante'::text as recipient_type,
      p.id as recipient_profile_id,
      null::text as recipient_role,
      nullif(btrim(coalesce(p.email, '')), '') as recipient_email,
      case
        when v_request.requested_by is null then 'dead_letter'
        when p.id is null then 'dead_letter'
        when nullif(btrim(coalesce(p.email, '')), '') is null then 'dead_letter'
        else 'pending'
      end as status,
      case
        when v_request.requested_by is null then 'missing_recipient_profile_id'
        when p.id is null then 'recipient_profile_not_found'
        when nullif(btrim(coalesce(p.email, '')), '') is null then 'recipient_email_missing'
        else null::text
      end as last_error,
      v_payload as payload,
      v_idempotency_prefix || ':requester' as idempotency_key
    from (select 1) seed
    left join public.profiles p
      on p.id = v_request.requested_by and coalesce(p.active, true)
  ),
  role_candidates as (
    select distinct on (p.id)
      20 as sort_rank,
      'administrador_sistema'::text as recipient_type,
      p.id as recipient_profile_id,
      lower(trim(r.name)) as recipient_role,
      nullif(btrim(coalesce(p.email, '')), '') as recipient_email,
      case when nullif(btrim(coalesce(p.email, '')), '') is null then 'dead_letter' else 'pending' end as status,
      case when nullif(btrim(coalesce(p.email, '')), '') is null then 'recipient_email_missing' else null::text end as last_error,
      v_payload as payload,
      v_idempotency_prefix || ':role:' || p.id::text as idempotency_key
    from public.profile_company_memberships pcm
    join public.profiles p on p.id = pcm.profile_id
    join public.user_roles ur on ur.profile_id = p.id
    join public.roles r on r.id = ur.role_id
    where pcm.company_id = v_request.company_id
      and pcm.active
      and coalesce(p.active, true)
      and lower(trim(r.name)) = any (
        select lower(trim(role_name))
        from unnest(coalesce(v_role_names, array[]::text[])) as expected_roles(role_name)
      )
    order by p.id, lower(trim(r.name))
  ),
  role_missing_candidate as (
    select
      30 as sort_rank,
      'administrador_sistema'::text as recipient_type,
      null::uuid as recipient_profile_id,
      array_to_string(v_role_names, ',') as recipient_role,
      null::text as recipient_email,
      'dead_letter'::text as status,
      'role_recipient_missing'::text as last_error,
      v_payload as payload,
      v_idempotency_prefix || ':role:none' as idempotency_key
    where array_length(v_role_names, 1) is not null
      and not exists (select 1 from role_candidates)
  ),
  candidates as (
    select * from requester_candidate
    union all select * from role_candidates
    union all select * from role_missing_candidate
  ),
  ranked_candidates as (
    select candidates.*,
      row_number() over (
        partition by v_event_type, v_request.id, 'email',
          coalesce(
            nullif(lower(trim(candidates.recipient_email)), ''),
            case when candidates.recipient_profile_id is not null then 'profile:' || candidates.recipient_profile_id::text end,
            candidates.recipient_type || ':' || coalesce(candidates.recipient_role, '')
          )
        order by
          case when nullif(candidates.payload->>'decision_comment', '') is not null then 0 else 1 end,
          case when candidates.idempotency_key like '%:requester' then 0 else 1 end,
          candidates.sort_rank,
          candidates.idempotency_key
      ) as recipient_rank
    from candidates
  )
  insert into public.notification_events (
    event_type, source_table, source_id, source_folio, recipient_type,
    recipient_profile_id, recipient_email, recipient_role, channel, priority,
    subject, payload, idempotency_key, status, last_error, next_attempt_at
  )
  select v_event_type, 'payment_requests', v_request.id, v_request.request_number,
    recipient_type, recipient_profile_id,
    case when status = 'pending' then recipient_email else null end,
    recipient_role, 'email', v_priority, v_subject, payload, idempotency_key,
    status, last_error, case when status = 'pending' then now() else null end
  from ranked_candidates
  where recipient_rank = 1
  on conflict (idempotency_key) do nothing;

  return new;
exception
  when others then
    insert into public.notification_events (
      event_type, source_table, source_id, source_folio, recipient_type,
      channel, priority, subject, payload, idempotency_key, status, last_error
    ) values (
      coalesce(v_event_type, 'payment_request.notification_failed'),
      'payment_requests', new.payment_request_id, v_request.request_number,
      'administrador_sistema', 'email', coalesce(v_priority, 'normal'),
      coalesce(v_subject, 'Actualizacion de solicitud'),
      jsonb_build_object('folio', v_request.request_number, 'path', '/solicitudes.html'),
      'payment_request.notification_failed:' || new.payment_request_id::text || ':' || new.id::text,
      'dead_letter', 'decision_notification_enqueue_failed'
    )
    on conflict (idempotency_key) do nothing;
    return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_payment_request_decision_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_request_notification_for_profile"("p_payment_request_id" "uuid", "p_event_type" "text", "p_recipient_profile_id" "uuid", "p_subject" "text", "p_idempotency_key" "text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_status text := 'pending';
  v_last_error text;
  v_priority text;
begin
  select *
    into v_request
  from public.payment_requests
  where id = p_payment_request_id;

  if not found then
    return;
  end if;

  v_priority := case lower(trim(coalesce(p_priority, 'normal')))
    when 'low' then 'low'
    when 'normal' then 'normal'
    when 'high' then 'high'
    when 'critical' then 'critical'
    else 'normal'
  end;

  if p_recipient_profile_id is null then
    v_status := 'dead_letter';
    v_last_error := 'missing_recipient_profile_id';
  else
    select *
      into v_profile
    from public.profiles
    where id = p_recipient_profile_id
      and coalesce(active, true);

    if not found then
      v_status := 'dead_letter';
      v_last_error := 'recipient_profile_not_found';
    elsif nullif(trim(coalesce(v_profile.email, '')), '') is null then
      v_status := 'dead_letter';
      v_last_error := 'recipient_email_missing';
    end if;
  end if;

  insert into public.notification_events (
    event_type,
    source_table,
    source_id,
    source_folio,
    recipient_type,
    recipient_profile_id,
    recipient_email,
    channel,
    priority,
    subject,
    payload,
    idempotency_key,
    status,
    last_error,
    next_attempt_at
  )
  values (
    p_event_type,
    'payment_requests',
    v_request.id,
    v_request.request_number,
    'usuario_solicitante',
    case when v_status = 'pending' then v_profile.id else null end,
    case when v_status = 'pending' then nullif(trim(coalesce(v_profile.email, '')), '') else null end,
    'email',
    v_priority,
    p_subject,
    public.notification_payment_request_payload(v_request.id),
    p_idempotency_key,
    v_status,
    v_last_error,
    case when v_status = 'pending' then now() else null end
  )
  on conflict (idempotency_key) do nothing;
end;
$$;


ALTER FUNCTION "public"."enqueue_payment_request_notification_for_profile"("p_payment_request_id" "uuid", "p_event_type" "text", "p_recipient_profile_id" "uuid", "p_subject" "text", "p_idempotency_key" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_request_notification_for_profile"("p_payment_request_id" "uuid", "p_event_type" "text", "p_recipient_profile_id" "uuid", "p_subject" "text", "p_idempotency_key" "text", "p_priority" "text", "p_payload_extra" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_status text := 'pending';
  v_last_error text;
  v_priority text;
begin
  select *
    into v_request
  from public.payment_requests
  where id = p_payment_request_id;

  if not found then
    return;
  end if;

  v_priority := case lower(trim(coalesce(p_priority, 'normal')))
    when 'low' then 'low'
    when 'normal' then 'normal'
    when 'high' then 'high'
    when 'critical' then 'critical'
    else 'normal'
  end;

  if p_recipient_profile_id is null then
    v_status := 'dead_letter';
    v_last_error := 'missing_recipient_profile_id';
  else
    select *
      into v_profile
    from public.profiles
    where id = p_recipient_profile_id
      and coalesce(active, true);

    if not found then
      v_status := 'dead_letter';
      v_last_error := 'recipient_profile_not_found';
    elsif nullif(trim(coalesce(v_profile.email, '')), '') is null then
      v_status := 'dead_letter';
      v_last_error := 'recipient_email_missing';
    end if;
  end if;

  insert into public.notification_events (
    event_type,
    source_table,
    source_id,
    source_folio,
    recipient_type,
    recipient_profile_id,
    recipient_email,
    channel,
    priority,
    subject,
    payload,
    idempotency_key,
    status,
    last_error,
    next_attempt_at
  )
  values (
    p_event_type,
    'payment_requests',
    v_request.id,
    v_request.request_number,
    'usuario_solicitante',
    case when v_status = 'pending' then v_profile.id else null end,
    case when v_status = 'pending' then nullif(trim(coalesce(v_profile.email, '')), '') else null end,
    'email',
    v_priority,
    p_subject,
    public.notification_payment_request_payload_with_extra(v_request.id, p_payload_extra),
    p_idempotency_key,
    v_status,
    v_last_error,
    case when v_status = 'pending' then now() else null end
  )
  on conflict (idempotency_key) do nothing;
end;
$$;


ALTER FUNCTION "public"."enqueue_payment_request_notification_for_profile"("p_payment_request_id" "uuid", "p_event_type" "text", "p_recipient_profile_id" "uuid", "p_subject" "text", "p_idempotency_key" "text", "p_priority" "text", "p_payload_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_payment_request_notification_for_roles"("p_payment_request_id" "uuid", "p_event_type" "text", "p_role_names" "text"[], "p_subject" "text", "p_idempotency_prefix" "text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_recipient record;
  v_inserted_count integer := 0;
  v_priority text;
begin
  select *
    into v_request
  from public.payment_requests
  where id = p_payment_request_id;

  if not found then
    return;
  end if;

  v_priority := case lower(trim(coalesce(p_priority, 'normal')))
    when 'low' then 'low'
    when 'normal' then 'normal'
    when 'high' then 'high'
    when 'critical' then 'critical'
    else 'normal'
  end;

  for v_recipient in
    select distinct on (p.id)
      p.id as profile_id,
      nullif(trim(coalesce(p.email, '')), '') as email,
      lower(trim(r.name)) as role_name
    from public.profiles p
    join public.user_roles ur on ur.profile_id = p.id
    join public.roles r on r.id = ur.role_id
    where coalesce(p.active, true)
      and nullif(trim(coalesce(p.email, '')), '') is not null
      and lower(trim(r.name)) = any (
        select lower(trim(role_name))
        from unnest(coalesce(p_role_names, array[]::text[])) as expected_roles(role_name)
      )
    order by p.id, lower(trim(r.name))
  loop
    v_inserted_count := v_inserted_count + 1;

    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_profile_id,
      recipient_email,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      next_attempt_at
    )
    values (
      p_event_type,
      'payment_requests',
      v_request.id,
      v_request.request_number,
      'administrador_sistema',
      v_recipient.profile_id,
      v_recipient.email,
      v_recipient.role_name,
      'email',
      v_priority,
      p_subject,
      public.notification_payment_request_payload(v_request.id),
      p_idempotency_prefix || ':role:' || v_recipient.profile_id::text,
      'pending',
      now()
    )
    on conflict (idempotency_key) do nothing;
  end loop;

  if v_inserted_count = 0 then
    insert into public.notification_events (
      event_type,
      source_table,
      source_id,
      source_folio,
      recipient_type,
      recipient_role,
      channel,
      priority,
      subject,
      payload,
      idempotency_key,
      status,
      last_error
    )
    values (
      p_event_type,
      'payment_requests',
      v_request.id,
      v_request.request_number,
      'administrador_sistema',
      array_to_string(p_role_names, ','),
      'email',
      v_priority,
      p_subject,
      public.notification_payment_request_payload(v_request.id),
      p_idempotency_prefix || ':role:none',
      'dead_letter',
      'role_recipient_missing'
    )
    on conflict (idempotency_key) do nothing;
  end if;
end;
$$;


