CREATE OR REPLACE FUNCTION "public"."enqueue_rebatched_item_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_source_batch public.approval_batches%rowtype;
  v_target record;
  v_company_name text;
  v_recipient record;
  v_has_recipient boolean := false;
begin
  if old.rebatch_status <> 'blocked' or new.rebatch_status <> 'released' then
    return new;
  end if;

  select * into v_request
  from public.payment_requests
  where id = new.payment_request_id;
  select * into v_source_batch
  from public.approval_batches
  where id = new.batch_id;
  select coalesce(nullif(btrim(c.legal_name), ''), c.name)
    into v_company_name
  from public.companies c
  where c.id = v_request.company_id;

  select
    abi.id as item_id,
    ab.id as batch_id,
    ab.label as batch_label,
    abi.review_sequence,
    abi.resubmitted_by,
    abi.resubmitted_at,
    abi.resubmission_note
  into v_target
  from public.approval_batch_items abi
  join public.approval_batches ab on ab.id = abi.batch_id
  where abi.previous_item_id = new.id
    and abi.payment_request_id = new.payment_request_id
    and abi.removed_at is null
    and abi.director_status = 'pending'
    and ab.status = 'draft'
  order by abi.review_sequence desc, abi.created_at desc, abi.id desc
  limit 1;

  for v_recipient in
    with candidates as (
      select p.id, p.email, 'usuario_solicitante'::text as recipient_type,
             'solicitante'::text as recipient_role, 1 as priority_order
      from public.profiles p
      where p.id = v_request.requested_by
      union all
      select p.id, p.email, 'administrador_sistema', 'finanzas', 2
      from public.profiles p
      join public.user_roles ur on ur.profile_id = p.id
      join public.roles r on r.id = ur.role_id
      where coalesce(p.active, true)
        and lower(btrim(r.name)) = any (public.flux_finance_roles())
    )
    select distinct on (lower(btrim(email))) id, email, recipient_type, recipient_role
    from candidates
    where nullif(btrim(email), '') is not null
    order by lower(btrim(email)), priority_order, id
  loop
    v_has_recipient := true;
    perform public.insert_approval_batch_notification(
      'approval_batch.item_rebatched',
      'approval_batch_items',
      new.id,
      v_request.request_number,
      v_recipient.recipient_type,
      v_recipient.id,
      v_recipient.email,
      v_recipient.recipient_role,
      'Solicitud habilitada para nueva revision: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object(
        'company', v_company_name,
        'folio', v_request.request_number,
        'status', case when v_target.item_id is null then 'available_for_rebatch' else 'rebatched_pending' end,
        'previous_batch_id', v_source_batch.id,
        'previous_batch_label', v_source_batch.label,
        'previous_item_id', new.id,
        'previous_reject_reason', new.director_reject_reason,
        'correction_note', new.rebatch_release_note,
        'new_batch_id', v_target.batch_id,
        'new_batch_label', v_target.batch_label,
        'new_item_id', v_target.item_id,
        'review_sequence', coalesce(v_target.review_sequence, new.review_sequence + 1),
        'resubmitted_by', coalesce(v_target.resubmitted_by, new.rebatch_released_by),
        'resubmitted_at', coalesce(v_target.resubmitted_at, new.rebatch_released_at),
        'decision_comment', new.rebatch_release_note,
        'decision_label', 'Correccion documentada',
        'path', '/approval_batches.html'
      ),
      'approval_batch.item_rebatched:' || new.id::text || ':' || coalesce(v_target.item_id::text, 'available') || ':' || v_recipient.id::text,
      'normal'
    );
  end loop;

  if not v_has_recipient then
    perform public.insert_approval_batch_notification(
      'approval_batch.item_rebatched',
      'approval_batch_items',
      new.id,
      v_request.request_number,
      'administrador_sistema',
      null,
      null,
      'finanzas',
      'Reingreso sin destinatario: ' || coalesce(v_request.request_number, new.id::text),
      jsonb_build_object(
        'company', v_company_name,
        'folio', v_request.request_number,
        'status', case when v_target.item_id is null then 'available_for_rebatch' else 'rebatched_pending' end,
        'previous_batch_id', v_source_batch.id,
        'previous_batch_label', v_source_batch.label,
        'previous_item_id', new.id,
        'previous_reject_reason', new.director_reject_reason,
        'correction_note', new.rebatch_release_note,
        'new_batch_id', v_target.batch_id,
        'new_batch_label', v_target.batch_label,
        'new_item_id', v_target.item_id,
        'review_sequence', coalesce(v_target.review_sequence, new.review_sequence + 1),
        'resubmitted_by', coalesce(v_target.resubmitted_by, new.rebatch_released_by),
        'resubmitted_at', coalesce(v_target.resubmitted_at, new.rebatch_released_at),
        'decision_comment', new.rebatch_release_note,
        'decision_label', 'Correccion documentada',
        'path', '/approval_batches.html'
      ),
      'approval_batch.item_rebatched:' || new.id::text || ':' || coalesce(v_target.item_id::text, 'available') || ':missing_recipient',
      'normal'
    );
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enqueue_rebatched_item_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_payment_reservation"("p_reservation_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_initial public.payment_allocation_reservations%rowtype;
  v_reservation public.payment_allocation_reservations%rowtype;
  v_plan public.payment_allocation_plans%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_decided_at timestamptz;
begin
  select * into v_initial
  from public.payment_allocation_reservations
  where id = p_reservation_id;
  if not found then raise exception 'payment_reservation_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_initial.company_id);
  v_payload := jsonb_build_object(
    'operation', 'expire',
    'reservation_id', p_reservation_id
  );
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_initial.company_id, 'payment_allocation.expire',
    p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;

  -- All reservation terminal transitions use plan -> operation -> reservation.
  select * into v_plan
  from public.payment_allocation_plans
  where id = v_initial.plan_id
  for update;
  if not found then raise exception 'payment_allocation_plan_not_found'; end if;
  select * into v_operation
  from public.bank_payment_operations
  where id = v_initial.operation_id
  for update;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  select * into v_reservation
  from public.payment_allocation_reservations
  where id = p_reservation_id
  for update;
  if v_reservation.plan_id <> v_plan.id
     or v_reservation.operation_id <> v_operation.id
     or v_reservation.company_id <> v_plan.company_id then
    raise exception 'payment_reservation_scope_mismatch';
  end if;
  if v_reservation.status <> 'active' then
    raise exception 'payment_reservation_not_active';
  end if;
  v_decided_at := clock_timestamp();
  if v_reservation.expires_at > v_decided_at then
    raise exception 'payment_reservation_not_expired';
  end if;

  update public.payment_allocation_reservations
  set status = 'expired', closed_by = v_actor, closed_at = v_decided_at,
      close_reason = 'Expiration materialized against authoritative database clock'
  where id = v_reservation.id;
  update public.payment_allocation_plans
  set status = 'draft'
  where id = v_plan.id and status = 'reserved';
  update public.bank_payment_operations
  set status = 'available'
  where id = v_operation.id and status = 'reserved';
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_allocation.expired',
    'payment_allocation_reservation',
    v_reservation.id,
    v_reservation.company_id,
    v_actor,
    jsonb_build_object(
      'expired_at', v_reservation.expires_at,
      'operation_id', v_reservation.operation_id,
      'plan_id', v_reservation.plan_id,
      'reservation_id', v_reservation.id
    ),
    v_reservation.operation_id,
    null,
    'payment_allocation.expired:' || v_reservation.id::text
  );
  v_result := jsonb_build_object(
    'event_id', v_event_id,
    'plan_id', v_reservation.plan_id,
    'reservation_id', v_reservation.id,
    'status', 'expired'
  );
  return public.payment_reconciliation_store_command(
    v_reservation.company_id, 'payment_allocation.expire',
    p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."expire_payment_reservation"("p_reservation_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extraordinary_append_event"("p_authorization_id" "uuid", "p_event_type" "text", "p_actor_profile_id" "uuid", "p_idempotency_key" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_event_id uuid;
begin
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;

  insert into public.payment_request_extraordinary_events(
    authorization_id,
    payment_request_id,
    company_id,
    event_type,
    actor_profile_id,
    idempotency_key,
    metadata
  ) values (
    v_authorization.id,
    v_authorization.payment_request_id,
    v_authorization.company_id,
    p_event_type,
    p_actor_profile_id,
    p_idempotency_key,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_event_id;
  return v_event_id;
end
$$;


ALTER FUNCTION "public"."extraordinary_append_event"("p_authorization_id" "uuid", "p_event_type" "text", "p_actor_profile_id" "uuid", "p_idempotency_key" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extraordinary_authorization_can_consume_layout_line"("p_authorization_id" "uuid", "p_layout_line_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    join public.payment_requests request
      on request.id = extraordinary_auth.payment_request_id
     and request.company_id = extraordinary_auth.company_id
    join public.extraordinary_payment_policies policy
      on policy.company_id = extraordinary_auth.company_id
    join public.payment_layout_lines line
      on line.id = p_layout_line_id
     and line.payment_request_id = request.id
     and line.company_id = extraordinary_auth.company_id
    join public.payment_layouts layout
      on layout.id = line.layout_id
    where extraordinary_auth.id = p_authorization_id
      and extraordinary_auth.status = 'active'
      and extraordinary_auth.idempotency_key is not null
      and policy.enabled
      and (
        not policy.evidence_required
        or (
          extraordinary_auth.evidence_verified_at is not null
          and extraordinary_auth.evidence_match_attested_at is not null
        )
      )
      and extraordinary_auth.valid_until > clock_timestamp()
      and extraordinary_auth.external_authorized_at >=
        request.approval_material_updated_at
      and request.currency = 'MXN'
      and (
        policy.max_amount_mxn is null
        or request.amount_requested <= policy.max_amount_mxn
      )
      and extraordinary_auth.category = any(policy.allowed_categories)
      and request.status::text in (
        'submitted', 'pending_approval', 'approved'
      )
      and line.status = 'included'
      and layout.status <> 'cancelled'
      and coalesce(
        public.approval_batch_budget_validation(request.id)->>'status',
        'bloqueado'
      ) = 'aprobable'
      and cardinality(
        public.payment_request_layout_missing_fields(request)
      ) = 0
      and not exists (
        select 1
        from public.payment_layout_lines other_line
        where other_line.payment_request_id = request.id
          and other_line.id <> line.id
      )
      and not exists (
        select 1
        from public.cash_funds cash_fund
        where cash_fund.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payment_receipts receipt
        where receipt.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payment_request_receipt_links receipt_link
        where receipt_link.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payable_snapshots snapshot
        join public.payment_allocation_items item
          on item.snapshot_id = snapshot.id
        where snapshot.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payable_snapshots snapshot
        join public.payment_allocation_movements movement
          on movement.snapshot_id = snapshot.id
        where snapshot.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payable_snapshots snapshot
        join public.payment_allocation_items item
          on item.snapshot_id = snapshot.id
        join public.payment_allocation_reservations reservation
          on reservation.plan_id = item.plan_id
        where snapshot.payment_request_id = request.id
      )
      and not exists (
        select 1
        from public.payment_request_extraordinary_authorizations other_auth
        where other_auth.payment_request_id = request.id
          and other_auth.id <> extraordinary_auth.id
          and other_auth.idempotency_key is not null
          and other_auth.status in (
            'draft', 'active', 'consumed_pending_ratification'
          )
      )
      and not exists (
        select 1
        from public.approval_batch_items batch_item
        join public.approval_batches batch
          on batch.id = batch_item.batch_id
        where batch_item.payment_request_id = request.id
          and (
            (
              batch_item.removed_at is null
              and batch_item.director_status = 'rejected'
            )
            or batch.status in ('draft', 'submitted')
          )
      )
  );
$$;


ALTER FUNCTION "public"."extraordinary_authorization_can_consume_layout_line"("p_authorization_id" "uuid", "p_layout_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extraordinary_authorization_is_ready"("p_authorization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    join public.payment_requests request
      on request.id = extraordinary_auth.payment_request_id
    join public.extraordinary_payment_policies policy
      on policy.company_id = extraordinary_auth.company_id
    where extraordinary_auth.id = p_authorization_id
      and extraordinary_auth.status = 'active'
      and request.extraordinary_state = 'extraordinary_active'
      and policy.enabled
      and (
        not policy.evidence_required
        or (
          extraordinary_auth.evidence_verified_at is not null
          and extraordinary_auth.evidence_match_attested_at is not null
        )
      )
      and extraordinary_auth.authorization_medium is not null
      and extraordinary_auth.authorization_reference is not null
      and extraordinary_auth.director_absence_confirmed
      and extraordinary_auth.cannot_wait_confirmed
      and extraordinary_auth.valid_until > clock_timestamp()
      and extraordinary_auth.external_authorized_at >=
        request.approval_material_updated_at
      and request.currency = 'MXN'
      and (
        policy.max_amount_mxn is null
        or request.amount_requested <= policy.max_amount_mxn
      )
      and extraordinary_auth.category = any(policy.allowed_categories)
      and request.status::text in (
        'submitted', 'pending_approval', 'approved'
      )
      and coalesce(
        public.approval_batch_budget_validation(request.id)->>'status',
        'bloqueado'
      ) = 'aprobable'
      and cardinality(
        public.payment_request_layout_missing_fields(request)
      ) = 0
      and not public.approval_batch_request_has_any_execution_record(request.id)
      and not exists (
        select 1
        from public.payment_request_receipt_links receipt_link
        where receipt_link.payment_request_id = request.id
      )
  );
$$;


ALTER FUNCTION "public"."extraordinary_authorization_is_ready"("p_authorization_id" "uuid") OWNER TO "postgres";


