CREATE OR REPLACE FUNCTION "public"."extraordinary_validate_layout_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
begin
  if exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    where extraordinary_auth.payment_request_id = new.payment_request_id
      and extraordinary_auth.idempotency_key is not null
      and extraordinary_auth.status in (
        'consumed_pending_ratification',
        'ratified',
        'disputed',
        'expired',
        'revoked'
      )
  ) then
    raise exception
      'extraordinary_authorization_already_consumed_or_closed';
  end if;

  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where payment_request_id = new.payment_request_id
    and status = 'active'
    and idempotency_key is not null
  order by authorized_at desc
  limit 1
  for update;

  if not found then
    if exists (
      select 1
      from public.payment_request_extraordinary_authorizations
      where payment_request_id = new.payment_request_id
        and idempotency_key is not null
    ) then
      raise exception 'secure_extraordinary_authorization_changed';
    end if;
    return new;
  end if;

  if v_authorization.company_id <> new.company_id then
    raise exception 'secure_extraordinary_company_mismatch';
  end if;

  if not exists (
    select 1
    from public.payment_requests request
    where request.id = new.payment_request_id
      and request.company_id = new.company_id
  ) then
    raise exception 'secure_extraordinary_request_mismatch';
  end if;

  if not exists (
    select 1
    from public.payment_layouts layout
    where layout.id = new.layout_id
      and layout.status <> 'cancelled'
  ) then
    raise exception 'secure_extraordinary_layout_not_available';
  end if;

  if new.status <> 'included' then
    raise exception 'secure_extraordinary_layout_line_not_includable';
  end if;

  if not public.extraordinary_authorization_is_ready(
    v_authorization.id
  ) then
    raise exception 'secure_extraordinary_authorization_not_ready';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."extraordinary_validate_layout_line"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_extraordinary_authorization"("p_authorization_id" "uuid", "p_evidence_type" "text", "p_evidence_sha256" "text", "p_evidence_mime_type" "text", "p_evidence_size_bytes" bigint, "p_finance_attests_evidence_matches_request" boolean, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage', 'pg_temp'
    AS $_$
declare
  v_actor uuid;
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_request public.payment_requests%rowtype;
  v_policy public.extraordinary_payment_policies%rowtype;
  v_object storage.objects%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_mime text := lower(btrim(coalesce(p_evidence_mime_type, '')));
  v_hash text := lower(btrim(coalesce(p_evidence_sha256, '')));
  v_type text := lower(btrim(coalesce(p_evidence_type, '')));
  v_now timestamptz := clock_timestamp();
begin
  if p_authorization_id is null then raise exception 'authorization_id_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_authorization_id::text, 37037));

  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id
  for update;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;

  v_actor := public.extraordinary_require_finance_for_company(
    v_authorization.company_id
  );
  if v_actor <> v_authorization.authorized_by
     and not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'draft_owner_or_sysadmin_required';
  end if;
  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'invalid_idempotency_key';
  end if;
  if v_authorization.status = 'active' then
    return jsonb_build_object(
      'authorization_id', v_authorization.id,
      'status', 'active',
      'valid_until', v_authorization.valid_until,
      'ratification_due_at', v_authorization.ratification_due_at,
      'idempotent_replay', true
    );
  end if;
  if v_authorization.status <> 'draft' then
    raise exception 'extraordinary_authorization_not_draft';
  end if;

  select * into v_request
  from public.payment_requests
  where id = v_authorization.payment_request_id
  for update;
  select * into v_policy
  from public.extraordinary_payment_policies
  where company_id = v_authorization.company_id
  for share;

  if not found or not v_policy.enabled then
    raise exception 'extraordinary_policy_disabled';
  end if;
  if v_now >= v_authorization.valid_until
     or v_authorization.external_authorized_at <
       v_request.approval_material_updated_at then
    raise exception 'extraordinary_authorization_expired_or_stale';
  end if;
  if not public.extraordinary_profile_is_company_director(
    v_authorization.external_director_profile_id,
    v_authorization.company_id
  ) then
    raise exception 'external_director_not_active_for_company';
  end if;
  if v_request.currency <> 'MXN'
     or v_request.amount_requested > v_policy.max_amount_mxn
     or v_authorization.category <> all(v_policy.allowed_categories) then
    raise exception 'extraordinary_policy_no_longer_matches';
  end if;
  if public.approval_batch_request_has_any_execution_record(v_request.id)
     or exists (
       select 1
       from public.payment_request_receipt_links receipt_link
       where receipt_link.payment_request_id = v_request.id
     ) then
    raise exception 'payment_request_already_executed';
  end if;
  if coalesce(
    public.approval_batch_budget_validation(v_request.id)->>'status',
    'bloqueado'
  ) <> 'aprobable' then
    raise exception 'budget_revalidation_required';
  end if;
  if not coalesce(p_finance_attests_evidence_matches_request, false) then
    raise exception 'evidence_request_match_attestation_required';
  end if;
  if v_type not in (
    'whatsapp_export', 'email', 'signed_document', 'other'
  ) then
    raise exception 'invalid_evidence_type';
  end if;
  if v_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_evidence_sha256';
  end if;
  if v_mime not in (
    'application/pdf', 'image/jpeg', 'image/png', 'image/webp'
  ) or p_evidence_size_bytes not between 1 and 5242880 then
    raise exception 'invalid_evidence_file';
  end if;

  select * into v_object
  from storage.objects object
  where object.bucket_id = v_authorization.evidence_storage_bucket
    and object.name = v_authorization.evidence_storage_path;
  if not found then raise exception 'extraordinary_evidence_object_not_found'; end if;
  if lower(coalesce(v_object.metadata->>'mimetype', '')) <> v_mime
     or nullif(v_object.metadata->>'size', '') is null
     or (v_object.metadata->>'size')::bigint <> p_evidence_size_bytes
     or coalesce(
       to_jsonb(v_object)->'user_metadata'->>'sha256',
       v_object.metadata->'metadata'->>'sha256',
       v_object.metadata->>'sha256',
       ''
     ) <> v_hash then
    raise exception 'extraordinary_evidence_object_metadata_mismatch';
  end if;

  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set status = 'active',
      evidence_type = v_type,
      evidence_sha256 = v_hash,
      evidence_mime_type = v_mime,
      evidence_size_bytes = p_evidence_size_bytes,
      evidence_verified_at = v_now,
      evidence_match_attested_by = v_actor,
      evidence_match_attested_at = v_now,
      updated_at = v_now
  where id = v_authorization.id
    and status = 'draft';
  if not found then raise exception 'extraordinary_authorization_changed'; end if;

  perform public.extraordinary_append_event(
    v_authorization.id,
    'evidence_finalized',
    v_actor,
    'evidence-finalized:' || v_authorization.id::text || ':' || v_key,
    jsonb_build_object(
      'evidence_type', v_type,
      'evidence_sha256', v_hash,
      'mime_type', v_mime,
      'size_bytes', p_evidence_size_bytes,
      'request_match_attested', true
    )
  );
  perform public.extraordinary_append_event(
    v_authorization.id,
    'authorization_activated',
    v_actor,
    'authorization-activated:' || v_authorization.id::text || ':' || v_key,
    jsonb_build_object(
      'valid_until', v_authorization.valid_until,
      'ratification_due_at', v_authorization.ratification_due_at
    )
  );

  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'status', 'active',
    'valid_until', v_authorization.valid_until,
    'ratification_due_at', v_authorization.ratification_due_at,
    'idempotent_replay', false
  );
end
$_$;


ALTER FUNCTION "public"."finalize_extraordinary_authorization"("p_authorization_id" "uuid", "p_evidence_type" "text", "p_evidence_sha256" "text", "p_evidence_mime_type" "text", "p_evidence_size_bytes" bigint, "p_finance_attests_evidence_matches_request" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_extraordinary_authorization"("p_authorization_id" "uuid", "p_evidence_type" "text", "p_evidence_sha256" "text", "p_evidence_mime_type" "text", "p_evidence_size_bytes" bigint, "p_finance_attests_evidence_matches_request" boolean, "p_idempotency_key" "text") IS 'Validates policy, actor, Director, object metadata and financial attestation before activation.';



CREATE OR REPLACE FUNCTION "public"."finalize_payment_ingestion_upload"("p_batch_id" "uuid", "p_page_count" integer, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.payment_ingestion_batches%rowtype;
  v_document public.payment_documents%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_storage_metadata jsonb;
  v_result jsonb;
begin
  select * into v_batch from public.payment_ingestion_batches where id = p_batch_id for update;
  if not found then raise exception 'payment_batch_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_batch.company_id);
  v_payload := jsonb_build_object('batch_id', p_batch_id, 'page_count', p_page_count);
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_batch.company_id, 'payment_batch.finalize_upload', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if p_page_count is null or p_page_count not between 1 and 500 then
    raise exception 'invalid_page_count';
  end if;
  select * into v_document from public.payment_documents where batch_id = p_batch_id;
  select object.metadata into v_storage_metadata
  from storage.objects object
  where object.bucket_id = v_document.storage_bucket and object.name = v_document.storage_path;
  if not found then
    raise exception 'payment_batch_upload_not_found';
  end if;
  if coalesce(v_storage_metadata->>'mimetype', '') <> 'application/pdf'
     or coalesce((v_storage_metadata->>'size')::bigint, 0) <> v_document.file_size_bytes then
    raise exception 'payment_batch_upload_metadata_mismatch';
  end if;
  if v_batch.status not in ('awaiting_upload', 'extracting') then
    raise exception 'payment_batch_not_uploadable';
  end if;
  if v_batch.status = 'extracting' then
    if v_document.uploaded_at is null
       or v_document.uploaded_by is null
       or v_document.page_count is distinct from p_page_count then
      raise exception 'payment_batch_finalize_conflict';
    end if;
    v_result := jsonb_build_object(
      'batch_id', p_batch_id,
      'page_count', v_document.page_count,
      'status', 'extracting'
    );
    return public.payment_reconciliation_store_command(
      v_batch.company_id, 'payment_batch.finalize_upload',
      p_idempotency_key, v_hash, v_actor, v_result
    );
  end if;
  update public.payment_documents
  set page_count = p_page_count, uploaded_by = v_actor,
      uploaded_at = clock_timestamp()
  where id = v_document.id;
  update public.payment_ingestion_batches
  set status = 'extracting', page_count = p_page_count, error_code = null
  where id = p_batch_id;
  v_result := jsonb_build_object('batch_id', p_batch_id, 'status', 'extracting', 'page_count', p_page_count);
  return public.payment_reconciliation_store_command(
    v_batch.company_id, 'payment_batch.finalize_upload', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."finalize_payment_ingestion_upload"("p_batch_id" "uuid", "p_page_count" integer, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_payment_operation_evidence"("p_evidence_id" "uuid", "p_derived_sha256" "text", "p_file_size_bytes" bigint, "p_page_count" integer, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_evidence public.payment_operation_evidence%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_uploaded_at timestamptz;
  v_result jsonb;
begin
  select * into v_evidence
  from public.payment_operation_evidence
  where id = p_evidence_id
  for update;
  if not found then raise exception 'payment_evidence_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_evidence.company_id);
  v_payload := jsonb_build_object(
    'derived_sha256', p_derived_sha256,
    'evidence_id', p_evidence_id,
    'file_size_bytes', p_file_size_bytes,
    'page_count', p_page_count
  );
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_evidence.company_id,
    'payment_evidence.finalize',
    p_idempotency_key,
    v_payload_hash,
    v_actor
  );
  if v_replay is not null then return v_replay; end if;

  if p_derived_sha256 !~ '^[0-9a-f]{64}$'
     or p_file_size_bytes not between 1 and 26214400
     or p_page_count <> 1 then
    raise exception 'individual_receipt_must_have_one_page';
  end if;
  if v_evidence.status <> 'pending_upload' then
    raise exception 'payment_evidence_not_pending_upload';
  end if;
  if not exists (
    select 1 from storage.objects object
    where object.bucket_id = v_evidence.storage_bucket
      and object.name = v_evidence.storage_path
  ) then
    raise exception 'payment_evidence_object_not_found';
  end if;

  v_uploaded_at := clock_timestamp();
  update public.payment_operation_evidence
  set status = 'pending_review',
      individual_sha256 = p_derived_sha256,
      file_size_bytes = p_file_size_bytes,
      page_count = 1,
      uploaded_by = v_actor,
      uploaded_at = v_uploaded_at
  where id = v_evidence.id;

  v_result := jsonb_build_object(
    'evidence_id', v_evidence.id,
    'operation_id', v_evidence.operation_id,
    'status', 'pending_review',
    'storage_bucket', v_evidence.storage_bucket,
    'storage_path', v_evidence.storage_path
  );
  return public.payment_reconciliation_store_command(
    v_evidence.company_id,
    'payment_evidence.finalize',
    p_idempotency_key,
    v_payload_hash,
    v_actor,
    v_result
  );
end
$_$;


ALTER FUNCTION "public"."finalize_payment_operation_evidence"("p_evidence_id" "uuid", "p_derived_sha256" "text", "p_file_size_bytes" bigint, "p_page_count" integer, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_payment_allocation_candidates"("p_operation_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_operation public.bank_payment_operations%rowtype;
begin
  select * into v_operation from public.bank_payment_operations where id = p_operation_id;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_operation.company_id);
  if p_limit is null or p_limit not between 1 and 100 then raise exception 'invalid_limit'; end if;
  return coalesce((
    with latest_snapshots as (
      select distinct on (snapshot.payment_request_id) snapshot.*
      from public.payable_snapshots snapshot
      where snapshot.company_id = v_operation.company_id
      order by snapshot.payment_request_id, snapshot.version desc
    ), candidates as (
      select snapshot.id as snapshot_id, request.id as payment_request_id,
        request.request_number, request.concept, request.proveedor_id,
        coalesce(proveedor.alias, proveedor.nombre_completo, 'Proveedor') as proveedor_name,
        snapshot.amount_minor, snapshot.currency,
        snapshot.amount_minor - public.payable_snapshot_confirmed_minor(snapshot.id) as confirmed_balance_minor,
        snapshot.amount_minor - public.payable_snapshot_confirmed_minor(snapshot.id)
          - public.payable_snapshot_reserved_minor(snapshot.id) as available_minor,
        (
          case when snapshot.amount_minor - public.payable_snapshot_confirmed_minor(snapshot.id) = v_operation.amount_minor then 50 else 0 end
          + case when v_operation.destination_account_hash is not null and (
              v_operation.destination_account_hash = public.payment_reconciliation_account_hash(proveedor.clabe)
              or v_operation.destination_account_hash = public.payment_reconciliation_account_hash(proveedor.cuenta_bancaria)
            ) then 35 else 0 end
          + case when v_operation.beneficiary_name is not null and (
              lower(v_operation.beneficiary_name) like '%' || lower(coalesce(nullif(proveedor.alias, ''), '---')) || '%'
              or lower(v_operation.beneficiary_name) like '%' || lower(coalesce(nullif(proveedor.nombre_completo, ''), '---')) || '%'
            ) then 15 else 0 end
        )::integer as match_score
      from latest_snapshots snapshot
      join public.payment_requests request on request.id = snapshot.payment_request_id
      left join public.proveedores proveedor on proveedor.id = request.proveedor_id
      where snapshot.currency = v_operation.currency
        and public.payment_reconciliation_snapshot_is_payable(snapshot.id)
        and snapshot.amount_minor - public.payable_snapshot_confirmed_minor(snapshot.id)
          - public.payable_snapshot_reserved_minor(snapshot.id) > 0
    )
    select jsonb_agg(to_jsonb(candidate) order by candidate.match_score desc, candidate.request_number nulls last, candidate.payment_request_id)
    from (select * from candidates order by match_score desc, payment_request_id limit p_limit) candidate
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."find_payment_allocation_candidates"("p_operation_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_payment_receipt_candidates"("p_operation_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_operation public.bank_payment_operations%rowtype;
  v_items jsonb;
begin
  select * into v_operation
  from public.bank_payment_operations
  where id = p_operation_id;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_operation.company_id);
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception 'invalid_limit';
  end if;
  if exists (
    select 1 from public.payment_request_receipt_links
    where operation_id = v_operation.id
  ) then
    raise exception 'bank_receipt_already_linked';
  end if;
  if not exists (
    select 1 from public.payment_operation_evidence
    where operation_id = v_operation.id
      and status = 'shareable'
      and page_count = 1
      and single_operation_attested
  ) then
    raise exception 'shareable_single_page_evidence_required';
  end if;

  with latest_snapshots as (
    select distinct on (snapshot.payment_request_id) snapshot.*
    from public.payable_snapshots snapshot
    where snapshot.company_id = v_operation.company_id
    order by snapshot.payment_request_id, snapshot.version desc
  ), exact_candidates as (
    select
      snapshot.id as snapshot_id,
      request.id as payment_request_id,
      request.request_number,
      request.concept,
      request.status::text as request_status,
      coalesce(proveedor.alias, proveedor.nombre_completo, 'Proveedor') as proveedor_name,
      snapshot.amount_minor,
      snapshot.currency,
      v_operation.beneficiary_name as receipt_beneficiary,
      v_operation.payment_reason as receipt_reference,
      (
        v_operation.destination_account_hash is not null
        and (
          v_operation.destination_account_hash =
            public.payment_reconciliation_account_hash(proveedor.clabe)
          or v_operation.destination_account_hash =
            public.payment_reconciliation_account_hash(proveedor.cuenta_bancaria)
        )
      ) as account_match,
      (
        nullif(public.payment_receipt_normalize_match_text(v_operation.beneficiary_name), '') is not null
        and (
          (
            nullif(public.payment_receipt_normalize_match_text(proveedor.alias), '') is not null
            and public.payment_receipt_normalize_match_text(v_operation.beneficiary_name)
              like '%' || public.payment_receipt_normalize_match_text(proveedor.alias) || '%'
          )
          or (
            nullif(public.payment_receipt_normalize_match_text(proveedor.nombre_completo), '') is not null
            and public.payment_receipt_normalize_match_text(v_operation.beneficiary_name)
              like '%' || public.payment_receipt_normalize_match_text(proveedor.nombre_completo) || '%'
          )
        )
      ) as name_match
    from latest_snapshots snapshot
    join public.payment_requests request on request.id = snapshot.payment_request_id
    join public.proveedores proveedor on proveedor.id = request.proveedor_id
    where request.company_id = v_operation.company_id
      and request.status::text in ('approved', 'finance_validation', 'paid')
      and snapshot.amount_minor = v_operation.amount_minor
      and snapshot.currency = v_operation.currency
      and public.payment_reconciliation_snapshot_is_receipt_matchable(snapshot.id)
      and not exists (
        select 1 from public.payment_request_receipt_links link
        where link.payment_request_id = request.id
      )
      and (
        request.status::text = 'paid'
        or not exists (
          select 1 from public.payment_receipts legacy
          where legacy.payment_request_id = request.id
        )
      )
  )
  select coalesce(jsonb_agg(to_jsonb(candidate)
    order by candidate.account_match desc, candidate.name_match desc,
      candidate.request_number, candidate.payment_request_id), '[]'::jsonb)
    into v_items
  from (
    select *
    from exact_candidates
    where account_match or name_match
    order by account_match desc, name_match desc, payment_request_id
    limit p_limit
  ) candidate;

  return jsonb_build_object(
    'items', v_items,
    'outcome', case jsonb_array_length(v_items)
      when 0 then 'none'
      when 1 then 'exact'
      else 'multiple'
    end,
    'read_only', true
  );
end
$$;


ALTER FUNCTION "public"."find_payment_receipt_candidates"("p_operation_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_provider_intake_candidates"("p_payment_intake_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_intake public.payment_intake%rowtype;
  v_search text;
  v_limit integer;
  v_result jsonb;
begin
  if p_payment_intake_id is null then
    raise exception 'provider_intake_id_required';
  end if;

  perform public.provider_intake_actor_context();

  select *
    into v_intake
  from public.payment_intake
  where id = p_payment_intake_id;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  v_search := public.normalize_provider_match_text(p_search);
  if v_search is not null and length(v_search) < 2 then
    raise exception 'provider_intake_search_too_short';
  end if;
  v_limit := least(greatest(coalesce(p_limit, 12), 1), 25);

  with
  intake_values as (
    select
      public.normalize_provider_match_text(v_intake.provider_name) as provider_name,
      nullif(upper(regexp_replace(coalesce(v_intake.provider_rfc, ''), '[[:space:]-]+', '', 'g')), '') as rfc,
      public.normalize_provider_match_text(v_intake.bank_name) as bank_name,
      public.normalize_provider_match_digits(v_intake.bank_account) as bank_account,
      public.normalize_provider_match_digits(v_intake.bank_clabe) as bank_clabe,
      lower(nullif(btrim(coalesce(v_intake.provider_email, '')), '')) as email,
      public.normalize_provider_match_digits(v_intake.provider_phone) as phone
  ),
  provider_values as (
    select
      p.*,
      public.normalize_provider_match_text(p.nombre_completo) as legal_name,
      public.normalize_provider_match_text(p.alias) as alias_name,
      nullif(upper(regexp_replace(coalesce(p.rfc, ''), '[[:space:]-]+', '', 'g')), '') as normalized_rfc,
      public.normalize_provider_match_text(p.banco) as normalized_bank,
      public.normalize_provider_match_digits(p.cuenta_bancaria) as normalized_account,
      public.normalize_provider_match_digits(p.clabe) as normalized_clabe,
      lower(nullif(btrim(coalesce(p.email, '')), '')) as normalized_email,
      public.normalize_provider_match_digits(p.telefono) as normalized_phone
    from public.proveedores p
  ),
  signals as (
    select
      pv.*,
      iv.provider_name as intake_provider_name,
      iv.rfc as intake_rfc,
      iv.bank_name as intake_bank_name,
      iv.bank_account as intake_bank_account,
      iv.bank_clabe as intake_bank_clabe,
      iv.email as intake_email,
      iv.phone as intake_phone,
      (iv.rfc is not null and pv.normalized_rfc = iv.rfc) as rfc_exact,
      (iv.bank_clabe is not null and pv.normalized_clabe = iv.bank_clabe) as clabe_exact,
      (
        iv.bank_account is not null
        and pv.normalized_account = iv.bank_account
        and (
          iv.bank_name is null
          or pv.normalized_bank is null
          or pv.normalized_bank = iv.bank_name
        )
      ) as account_exact,
      (
        iv.provider_name is not null
        and pv.legal_name = iv.provider_name
      ) as legal_exact,
      (
        iv.provider_name is not null
        and length(iv.provider_name) >= 4
        and pv.legal_name is not null
        and (
          pv.legal_name like iv.provider_name || '%'
          or iv.provider_name like pv.legal_name || '%'
        )
      ) as legal_prefix,
      (
        iv.provider_name is not null
        and pv.alias_name = iv.provider_name
      ) as alias_exact,
      (
        iv.provider_name is not null
        and length(iv.provider_name) >= 4
        and pv.alias_name is not null
        and (
          pv.alias_name like iv.provider_name || '%'
          or iv.provider_name like pv.alias_name || '%'
        )
      ) as alias_prefix,
      (
        iv.email is not null
        and pv.normalized_email = iv.email
      ) as email_exact,
      (
        iv.phone is not null
        and length(iv.phone) >= 7
        and pv.normalized_phone = iv.phone
      ) as phone_exact,
      (
        v_search is not null
        and (
          pv.legal_name like v_search || '%'
          or pv.alias_name like v_search || '%'
          or pv.normalized_rfc like replace(v_search, ' ', '') || '%'
        )
      ) as manual_search_match
    from provider_values pv
    cross join intake_values iv
  ),
  scored as (
    select
      s.*,
      least(
        100,
        (case when rfc_exact then 70 else 0 end)
        + (case when clabe_exact then 45 else 0 end)
        + (case when account_exact then 30 else 0 end)
        + (case when legal_exact then 25 when legal_prefix then 12 else 0 end)
        + (case when alias_exact then 15 when alias_prefix then 8 else 0 end)
        + (case when email_exact then 5 else 0 end)
        + (case when phone_exact then 5 else 0 end)
      )::integer as score
    from signals s
    where
      rfc_exact or clabe_exact or account_exact or legal_exact or legal_prefix
      or alias_exact or alias_prefix or email_exact or phone_exact or manual_search_match
  ),
  eligible_candidates as (
    select *
    from scored
    where coalesce(activo, true)
       or rfc_exact
       or clabe_exact
       or account_exact
    order by coalesce(activo, true) desc, score desc, alias, id
    limit v_limit
  )
  select jsonb_build_object(
    'payment_intake_id', v_intake.id,
    'status', v_intake.status,
    'updated_at', v_intake.updated_at,
    'eligible', (
      v_intake.status = 'in_review'
      and v_intake.created_payment_request_id is null
    ),
    'current_match', (
      select case when p.id is null then null else jsonb_build_object(
        'proveedor_id', p.id,
        'alias', p.alias,
        'legal_name', coalesce(p.nombre_completo, p.beneficiary_name),
        'rfc', p.rfc,
        'payment_method', p.metodo_pago::text,
        'bank', p.banco,
        'account_masked', public.provider_intake_mask_value(p.cuenta_bancaria),
        'clabe_masked', public.provider_intake_mask_value(p.clabe),
        'active', coalesce(p.activo, true)
      ) end
      from (select 1) seed
      left join public.proveedores p on p.id = v_intake.matched_proveedor_id
    ),
    'duplicate_rfc_count', (
      select count(*)
      from public.proveedores p
      cross join intake_values iv
      where iv.rfc is not null
        and nullif(upper(regexp_replace(coalesce(p.rfc, ''), '[[:space:]-]+', '', 'g')), '') = iv.rfc
    ),
    'candidates', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'proveedor_id', c.id,
          'alias', c.alias,
          'legal_name', coalesce(c.nombre_completo, c.beneficiary_name),
          'rfc', c.rfc,
          'payment_method', c.metodo_pago::text,
          'bank', c.banco,
          'account_masked', public.provider_intake_mask_value(c.cuenta_bancaria),
          'clabe_masked', public.provider_intake_mask_value(c.clabe),
          'active', coalesce(c.activo, true),
          'selectable', coalesce(c.activo, true),
          'score', c.score,
          'confidence', case
            when c.score >= 70 then 'high'
            when c.score >= 40 then 'medium'
            else 'low'
          end,
          'reasons', to_jsonb(array_remove(array[
            case when c.rfc_exact then 'RFC exacto' end,
            case when c.clabe_exact then 'CLABE exacta' end,
            case when c.account_exact then 'Cuenta bancaria exacta' end,
            case when c.legal_exact then 'Razón social exacta'
                 when c.legal_prefix then 'Prefijo de razón social' end,
            case when c.alias_exact then 'Alias exacto'
                 when c.alias_prefix then 'Prefijo de alias' end,
            case when c.email_exact then 'Correo coincide' end,
            case when c.phone_exact then 'Teléfono coincide' end,
            case when c.manual_search_match
                      and not (
                        c.rfc_exact or c.clabe_exact or c.account_exact or c.legal_exact
                        or c.legal_prefix or c.alias_exact or c.alias_prefix
                        or c.email_exact or c.phone_exact
                      )
                 then 'Coincide con la búsqueda manual' end
          ]::text[], null)),
          'differences', to_jsonb(array_remove(array[
            case when c.intake_provider_name is not null and c.legal_name is not null
                       and c.intake_provider_name <> c.legal_name
                 then 'Razón social distinta' end,
            case when c.intake_rfc is not null and c.normalized_rfc is not null
                       and c.intake_rfc <> c.normalized_rfc
                 then 'RFC distinto' end,
            case when c.intake_bank_name is not null and c.normalized_bank is not null
                       and c.intake_bank_name <> c.normalized_bank
                 then 'Banco distinto' end,
            case when c.intake_email is not null and c.normalized_email is not null
                       and c.intake_email <> c.normalized_email
                 then 'Correo distinto' end,
            case when c.intake_phone is not null and c.normalized_phone is not null
                       and c.intake_phone <> c.normalized_phone
                 then 'Teléfono distinto' end
          ]::text[], null))
        )
        order by coalesce(c.activo, true) desc, c.score desc, c.alias, c.id
      )
      from eligible_candidates c
    ), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'event_id', pie.id,
          'action_kind', pie.metadata ->> 'action_kind',
          'previous_provider', previous_provider.alias,
          'new_provider', new_provider.alias,
          'match_confidence', pie.metadata ->> 'match_confidence',
          'reason_code', pie.metadata ->> 'reason_code',
          'reason', pie.notes,
          'actor_type', pie.actor_type,
          'created_at', pie.created_at
        )
        order by pie.created_at desc, pie.id desc
      )
      from public.payment_intake_events pie
      left join public.proveedores previous_provider
        on previous_provider.id = nullif(pie.metadata ->> 'previous_proveedor_id', '')::uuid
      left join public.proveedores new_provider
        on new_provider.id = nullif(pie.metadata ->> 'new_proveedor_id', '')::uuid
      where pie.payment_intake_id = v_intake.id
        and pie.event_type = 'provider_matched'
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end
$$;


