CREATE OR REPLACE FUNCTION "public"."get_approval_batch_detail"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
begin
  v_actor := public.approval_batch_require_actor();
  select * into v_batch
  from public.approval_batches
  where id = p_batch_id;
  if not found then raise exception 'batch_not_found'; end if;
  if v_batch.director_id <> v_actor
     and not public.current_user_has_role(public.flux_finance_roles()) then
    raise exception 'batch_access_denied';
  end if;

  return jsonb_build_object(
    'batch', (
      select jsonb_build_object(
        'id', ab.id,
        'company_id', ab.company_id,
        'company_name', coalesce(nullif(btrim(c.legal_name), ''), c.name),
        'label', ab.label,
        'period_start', ab.period_start,
        'period_end', ab.period_end,
        'status', ab.status,
        'director_id', ab.director_id,
        'director_name', dp.full_name,
        'director_email', dp.email,
        'created_by', ab.created_by,
        'submitted_at', ab.submitted_at,
        'decided_at', ab.decided_at,
        'closed_at', ab.closed_at,
        'notes', ab.notes,
        'approval_model', 'single_direction',
        'can_finance_manage', public.current_user_has_role(public.flux_finance_roles()),
        'can_director_decide', ab.director_id = v_actor
      )
      from public.approval_batches ab
      join public.companies c on c.id = ab.company_id
      join public.profiles dp on dp.id = ab.director_id
      where ab.id = p_batch_id
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', abi.id,
        'payment_request_id', pr.id,
        'request_number', pr.request_number,
        'provider_name', coalesce(nullif(btrim(p.alias), ''), p.nombre_completo),
        'company_name', coalesce(nullif(btrim(c.legal_name), ''), c.name),
        'cost_center', coalesce(nullif(btrim(cc.code), '') || ' - ', '') || cc.name,
        'budget_category', coalesce(nullif(btrim(bc.code), '') || ' - ', '') || bc.name,
        'payment_method', coalesce(
          nullif(pr.payment_method, ''),
          case when pr.request_type::text in ('cash', 'check') then pr.request_type::text else 'transfer' end
        ),
        'currency', pr.currency,
        'amount', pr.amount_requested,
        'request_status', pr.status,
        'director_status', abi.director_status,
        'reject_reason', abi.director_reject_reason,
        'rebatch_status', abi.rebatch_status,
        'rebatch_released_at', abi.rebatch_released_at,
        'rebatch_release_note', abi.rebatch_release_note,
        'requester_name', requester.full_name,
        'finance_reviewed_at', abi.finance_reviewed_at,
        'prepared_at', abi.finance_reviewed_at,
        'decided_at', abi.decided_at,
        'decided_by_name', decider.full_name,
        'previous_item_id', abi.previous_item_id,
        'review_sequence', abi.review_sequence,
        'resubmitted_at', abi.resubmitted_at,
        'resubmitted_by', abi.resubmitted_by,
        'resubmitted_by_name', resubmitter.full_name,
        'resubmission_note', abi.resubmission_note,
        'previous_batch_id', previous_batch.id,
        'previous_batch_label', previous_batch.label,
        'previous_reject_reason', previous_item.director_reject_reason,
        'previous_rejected_at', previous_item.decided_at,
        'previous_decided_by_name', previous_decider.full_name,
        'previous_correction_note', previous_item.rebatch_release_note,
        'budget_status', budget.result ->> 'status',
        'budget_reason', budget.result ->> 'motivo',
        'budget_available', nullif(budget.result ->> 'disponible_actual', '')::numeric,
        'review_history', coalesce((
          select jsonb_agg(jsonb_build_object(
            'item_id', history.id,
            'batch_id', history_batch.id,
            'batch_label', history_batch.label,
            'batch_status', history_batch.status,
            'review_sequence', history.review_sequence,
            'director_status', history.director_status,
            'reject_reason', history.director_reject_reason,
            'decided_at', history.decided_at,
            'decided_by', history.decided_by,
            'decided_by_name', history_decider.full_name,
            'rebatch_status', history.rebatch_status,
            'correction_note', history.rebatch_release_note,
            'resubmitted_at', history.resubmitted_at,
            'resubmission_note', history.resubmission_note
          ) order by history.review_sequence, history.created_at, history.id)
          from public.approval_batch_items history
          join public.approval_batches history_batch on history_batch.id = history.batch_id
          left join public.profiles history_decider on history_decider.id = history.decided_by
          where history.payment_request_id = abi.payment_request_id
            and history.removed_at is null
            and history.review_sequence <= abi.review_sequence
        ), '[]'::jsonb)
      ) order by pr.request_number, abi.created_at, abi.id)
      from public.approval_batch_items abi
      join public.payment_requests pr on pr.id = abi.payment_request_id
      join public.companies c on c.id = pr.company_id
      left join public.proveedores p on p.id = pr.proveedor_id
      left join public.cost_centers cc on cc.id = pr.cost_center_id
      left join public.budget_categories bc on bc.id = pr.budget_category_id
      left join public.profiles requester on requester.id = pr.requested_by
      left join public.profiles decider on decider.id = abi.decided_by
      left join public.profiles resubmitter on resubmitter.id = abi.resubmitted_by
      left join public.approval_batch_items previous_item on previous_item.id = abi.previous_item_id
      left join public.approval_batches previous_batch on previous_batch.id = previous_item.batch_id
      left join public.profiles previous_decider on previous_decider.id = previous_item.decided_by
      cross join lateral (
        select public.approval_batch_budget_validation(pr.id) as result
      ) budget
      where abi.batch_id = p_batch_id
        and abi.removed_at is null
    ), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "public"."get_approval_batch_detail"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_extraordinary_authorization_evidence_access"("p_authorization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;

  if not (
    public.extraordinary_profile_has_explicit_faculty(
      v_actor,
      v_authorization.company_id
    )
    or v_actor = v_authorization.external_director_profile_id
  ) then
    raise exception 'extraordinary_evidence_access_denied';
  end if;
  if v_authorization.evidence_verified_at is null then
    raise exception 'extraordinary_evidence_not_finalized';
  end if;

  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'storage_bucket', v_authorization.evidence_storage_bucket,
    'storage_path', v_authorization.evidence_storage_path,
    'url_ttl_seconds', 120,
    'mime_type', v_authorization.evidence_mime_type,
    'size_bytes', v_authorization.evidence_size_bytes
  );
end
$$;


ALTER FUNCTION "public"."get_extraordinary_authorization_evidence_access"("p_authorization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_batch_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_is_finance boolean;
  v_is_sysadmin boolean;
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  v_is_finance := public.current_user_has_role(public.flux_finance_roles());
  v_is_sysadmin := public.current_user_has_role(public.flux_sysadmin_roles());
  return jsonb_build_object(
    'actor_profile_id', v_actor,
    'can_access', v_is_finance,
    'capabilities', jsonb_build_object(
      'can_ingest', v_is_finance,
      'can_review', v_is_finance,
      'can_match', v_is_finance,
      'can_link', v_is_finance,
      'can_propose', false,
      'can_reserve', false,
      'can_confirm', false,
      'can_reverse', false
    ),
    'companies', coalesce((
      select jsonb_agg(jsonb_build_object('id', company.id, 'name', company.name)
        order by company.name)
      from public.companies company
      where coalesce(company.active, true)
        and v_is_finance
        and (
          v_is_sysadmin
          or public.has_active_company_membership(v_actor, company.id)
        )
    ), '[]'::jsonb),
    'upload_policy', jsonb_build_object(
      'allowed_mime_types', jsonb_build_array('application/pdf'),
      'max_file_bytes', 26214400,
      'max_pages', 500
    ),
    'matching_model', 'one_receipt_to_one_approved_request',
    'amount_source', 'accepted_bank_extraction'
  );
end
$$;


ALTER FUNCTION "public"."get_payment_batch_context"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_payment_batch_context"() IS 'Finance-scoped module context. Confirmation and reversal remain false until a separate cutover implementation.';



CREATE OR REPLACE FUNCTION "public"."get_payment_batch_receipt_summary"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.payment_ingestion_batches%rowtype;
  v_total integer;
  v_linked integer;
begin
  select * into v_batch
  from public.payment_ingestion_batches
  where id = p_batch_id;
  if not found then raise exception 'payment_batch_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_batch.company_id);

  select
    count(operation.id)::integer,
    count(link.id)::integer
    into v_total, v_linked
  from public.bank_payment_operations operation
  join public.payment_document_extractions extraction
    on extraction.id = operation.extraction_id
  left join public.payment_request_receipt_links link
    on link.operation_id = operation.id
  where extraction.batch_id = v_batch.id;

  return jsonb_build_object(
    'batch_id', v_batch.id,
    'accepted_receipts', v_total,
    'linked_receipts', v_linked,
    'derived_link_status', case
      when v_total > 0 and v_linked = v_total then 'completed'
      when v_linked > 0 then 'partially_completed'
      else 'pending'
    end
  );
end
$$;


ALTER FUNCTION "public"."get_payment_batch_receipt_summary"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_ingestion_batch_detail"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch public.payment_ingestion_batches%rowtype;
begin
  select * into v_batch from public.payment_ingestion_batches where id = p_batch_id;
  if not found then raise exception 'payment_batch_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_batch.company_id);
  return jsonb_build_object(
    'batch', (select to_jsonb(data) from (
      select batch.id, batch.company_id, company.name as company_name, batch.status,
        batch.original_file_name, batch.page_count, batch.extraction_count,
        batch.operation_count, batch.error_code, batch.created_at, batch.updated_at
      from public.payment_ingestion_batches batch
      join public.companies company on company.id = batch.company_id
      where batch.id = p_batch_id
    ) data),
    'document', (select to_jsonb(data) from (
      select document.id, document.storage_bucket, document.storage_path,
        document.mime_type, document.file_size_bytes, document.page_count,
        document.uploaded_by, document.uploaded_at
      from public.payment_documents document where document.batch_id = p_batch_id
    ) data),
    'extractions', coalesce((
      select jsonb_agg(to_jsonb(data) order by data.page_number)
      from (
        select extraction.id, extraction.page_number, extraction.status,
          extraction.parser_version, extraction.parser_confidence, extraction.bank_name,
          extraction.bank_status, extraction.bank_unique_folio, extraction.application_date,
          extraction.amount_minor, extraction.currency, extraction.source_account_last4,
          extraction.destination_account_last4, extraction.beneficiary_name,
          extraction.payment_reason, extraction.rejection_reason, extraction.updated_at
        from public.payment_document_extractions extraction
        where extraction.batch_id = p_batch_id
      ) data
    ), '[]'::jsonb),
    'operations', coalesce((
      select jsonb_agg(to_jsonb(data) order by data.page_number)
      from (
        select coalesce(operation.id, extraction.id) as id,
          operation.id as bank_operation_id, extraction.id as extraction_id,
          extraction.page_number, extraction.status as extraction_status,
          coalesce(operation.status, extraction.status) as status,
          extraction.bank_name, extraction.bank_status, extraction.bank_unique_folio,
          extraction.application_date, extraction.amount_minor, extraction.currency,
          extraction.source_account_last4, extraction.destination_account_last4,
          extraction.beneficiary_name, extraction.payment_reason, extraction.rejection_reason,
          array_remove(array[
            case when upper(btrim(extraction.bank_name)) <> 'BBVA'
              then 'bank_not_identified' end,
            case when lower(coalesce(extraction.bank_status, '')) <> 'operado'
              then 'bank_status_not_operated' end,
            case when extraction.application_date is null
              then 'operation_date_missing' end,
            case when extraction.amount_minor is null
              then 'amount_missing_or_invalid' end,
            case when extraction.currency is null
              then 'currency_missing_or_invalid' end,
            case when nullif(btrim(extraction.bank_unique_folio), '') is null
              then 'bank_unique_folio_missing' end,
            case when extraction.source_account_hash is null
              then 'strong_bank_identity_missing' end,
            case when nullif(btrim(extraction.beneficiary_name), '') is null
              then 'beneficiary_missing' end
          ]::text[], null) as review_issues,
          extraction.updated_at as extraction_updated_at,
          coalesce(operation.created_at, extraction.created_at) as created_at,
          case when operation.id is null then extraction.amount_minor
            else operation.amount_minor - public.payment_operation_confirmed_minor(operation.id) end as financial_remainder_minor,
          case when operation.id is null then extraction.amount_minor
            else operation.amount_minor - public.payment_operation_confirmed_minor(operation.id)
              - public.payment_operation_reserved_minor(operation.id) end as available_minor,
          'unreconciled'::text as reconciliation_status,
          jsonb_build_array(
            'Página ' || extraction.page_number::text,
            'Cuenta destino ••••' || coalesce(extraction.destination_account_last4, '—'),
            'Estado bancario ' || coalesce(extraction.bank_status, 'no identificado')
          ) as evidence_excerpt,
          (
            select to_jsonb(plan_data)
            from (
              select plan.id, plan.status, plan.total_amount_minor, plan.currency,
                plan.cancel_reason,
                coalesce((
                  select jsonb_agg(jsonb_build_object(
                    'amount_minor', item.amount_minor,
                    'currency', item.currency,
                    'id', item.id,
                    'note', item.note,
                    'payment_request_id', snapshot.payment_request_id,
                    'position', item.position,
                    'proveedor_name', coalesce(
                      proveedor.alias, proveedor.nombre_completo, 'Proveedor'
                    ),
                    'request_number', request.request_number,
                    'snapshot_id', item.snapshot_id
                  ) order by item.position)
                  from public.payment_allocation_items item
                  join public.payable_snapshots snapshot on snapshot.id = item.snapshot_id
                  join public.payment_requests request on request.id = snapshot.payment_request_id
                  left join public.proveedores proveedor on proveedor.id = request.proveedor_id
                  where item.plan_id = plan.id
                ), '[]'::jsonb) as items,
                reservation.id as reservation_id,
                case
                  when reservation.status = 'active' and reservation.expires_at <= now()
                    then 'expired'
                  else reservation.status
                end as reservation_status,
                coalesce(
                  reservation.status = 'active' and reservation.expires_at <= now(),
                  false
                ) as reservation_expired,
                reservation.expires_at, reservation.close_reason, reservation.closed_at
              from public.payment_allocation_plans plan
              left join lateral (
                select candidate.*
                from public.payment_allocation_reservations candidate
                where candidate.plan_id = plan.id
                order by candidate.created_at desc, candidate.id desc
                limit 1
              ) reservation on true
              where plan.operation_id = operation.id
              order by plan.created_at desc
              limit 1
            ) plan_data
          ) as plan
        from public.payment_document_extractions extraction
        left join public.bank_payment_operations operation on operation.extraction_id = extraction.id
        where extraction.batch_id = p_batch_id
      ) data
    ), '[]'::jsonb),
    'plans', coalesce((
      select jsonb_agg(to_jsonb(data) order by data.created_at desc)
      from (
        select plan.id, plan.operation_id, plan.status, plan.total_amount_minor,
          plan.currency, plan.proposed_by, plan.proposed_at, plan.cancel_reason,
          plan.created_at,
          coalesce((
            select jsonb_agg(jsonb_build_object(
              'amount_minor', item.amount_minor,
              'currency', item.currency,
              'id', item.id,
              'note', item.note,
              'payment_request_id', snapshot.payment_request_id,
              'position', item.position,
              'proveedor_name', coalesce(
                proveedor.alias, proveedor.nombre_completo, 'Proveedor'
              ),
              'request_number', request.request_number,
              'snapshot_id', item.snapshot_id
            ) order by item.position)
            from public.payment_allocation_items item
            join public.payable_snapshots snapshot on snapshot.id = item.snapshot_id
            join public.payment_requests request on request.id = snapshot.payment_request_id
            left join public.proveedores proveedor on proveedor.id = request.proveedor_id
            where item.plan_id = plan.id
          ), '[]'::jsonb) as items,
          reservation.id as reservation_id,
          case
            when reservation.status = 'active' and reservation.expires_at <= now()
              then 'expired'
            else reservation.status
          end as reservation_status,
          coalesce(
            reservation.status = 'active' and reservation.expires_at <= now(),
            false
          ) as reservation_expired,
          reservation.expires_at, reservation.close_reason, reservation.closed_at
        from public.payment_allocation_plans plan
        left join lateral (
          select candidate.*
          from public.payment_allocation_reservations candidate
          where candidate.plan_id = plan.id
          order by candidate.created_at desc, candidate.id desc
          limit 1
        ) reservation on true
        where exists (
          select 1 from public.bank_payment_operations operation
          join public.payment_document_extractions extraction on extraction.id = operation.extraction_id
          where operation.id = plan.operation_id and extraction.batch_id = p_batch_id
        )
      ) data
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(to_jsonb(data) order by data.created_at desc)
      from (
        select event.id, event.event_type, event.aggregate_type, event.aggregate_id,
          event.actor_profile_id, profile.full_name as actor_name,
          event.occurred_at as created_at
        from public.financial_outbox_events event
        left join public.profiles profile on profile.id = event.actor_profile_id
        where event.company_id = v_batch.company_id
          and (
            event.correlation_id = p_batch_id
            or event.correlation_id in (
              select operation.id
              from public.bank_payment_operations operation
              join public.payment_document_extractions extraction on extraction.id = operation.extraction_id
              where extraction.batch_id = p_batch_id
            )
            or event.aggregate_id in (
              select operation.id
              from public.bank_payment_operations operation
              join public.payment_document_extractions extraction on extraction.id = operation.extraction_id
              where extraction.batch_id = p_batch_id
            )
          )
        order by event.occurred_at desc
      ) data
    ), '[]'::jsonb)
  );
end
$$;


