CREATE OR REPLACE FUNCTION "public"."get_payment_receipt_link_preview"("p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_operation public.bank_payment_operations%rowtype;
  v_evidence public.payment_operation_evidence%rowtype;
  v_link record;
begin
  select operation.* into v_operation
  from public.bank_payment_operations operation
  where operation.id = p_operation_id
     or operation.extraction_id = p_operation_id
  order by case when operation.id = p_operation_id then 0 else 1 end
  limit 1;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_operation.company_id);

  select * into v_evidence
  from public.payment_operation_evidence
  where operation_id = v_operation.id
  order by version desc
  limit 1;

  select link.*, request.request_number into v_link
  from public.payment_request_receipt_links link
  join public.payment_requests request on request.id = link.payment_request_id
  where link.operation_id = v_operation.id;

  return jsonb_build_object(
    'operation_id', v_operation.id,
    'amount_minor', v_operation.amount_minor,
    'currency', v_operation.currency,
    'payment_date', v_operation.application_date,
    'reference_hint', right(v_operation.bank_unique_folio, 6),
    'evidence', case when v_evidence.id is null then null else jsonb_build_object(
      'id', v_evidence.id,
      'status', v_evidence.status,
      'version', v_evidence.version,
      'storage_bucket', v_evidence.storage_bucket,
      'storage_path', v_evidence.storage_path,
      'individual_sha256', v_evidence.individual_sha256,
      'file_size_bytes', v_evidence.file_size_bytes,
      'page_count', v_evidence.page_count,
      'single_operation_attested', v_evidence.single_operation_attested
    ) end,
    'link', case when v_link.id is null then null else jsonb_build_object(
      'id', v_link.id,
      'payment_request_id', v_link.payment_request_id,
      'request_number', v_link.request_number,
      'evidence_id', v_link.evidence_id,
      'amount_minor', v_link.amount_minor,
      'currency', v_link.currency,
      'payment_date', v_link.payment_date,
      'reference_hint', v_link.reference_hint,
      'linked_at', v_link.linked_at
    ) end,
    'can_search',
      v_link.id is null
      and v_evidence.status = 'shareable'
      and v_evidence.page_count = 1,
    'external_provider_access', false,
    'external_provider_block_reason', 'provider_identity_link_not_implemented'
  );
end
$$;


ALTER FUNCTION "public"."get_payment_receipt_link_preview"("p_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_receipt_notification_attachment"("p_notification_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_event public.notification_events%rowtype;
  v_link public.payment_request_receipt_links%rowtype;
  v_request public.payment_requests%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_evidence public.payment_operation_evidence%rowtype;
  v_provider public.proveedores%rowtype;
  v_safe_folio text;
  v_safe_provider text;
  v_filename text;
begin
  if p_notification_event_id is null then
    raise exception 'notification_event_required';
  end if;

  select *
    into v_event
  from public.notification_events
  where id = p_notification_event_id;
  if not found then
    raise exception 'notification_event_not_found';
  end if;
  if v_event.event_type <> 'payment_receipt.linked'
     or v_event.source_table <> 'payment_request_receipt_links'
     or v_event.source_id is null then
    raise exception 'notification_event_source_invalid';
  end if;

  select *
    into v_link
  from public.payment_request_receipt_links
  where id = v_event.source_id;
  if not found then
    raise exception 'payment_receipt_link_not_found';
  end if;

  select *
    into v_request
  from public.payment_requests
  where id = v_link.payment_request_id;
  if not found then
    raise exception 'payment_request_not_found';
  end if;

  select *
    into v_operation
  from public.bank_payment_operations
  where id = v_link.operation_id;
  if not found then
    raise exception 'bank_payment_operation_not_found';
  end if;

  select *
    into v_evidence
  from public.payment_operation_evidence
  where id = v_link.evidence_id;
  if not found then
    raise exception 'payment_evidence_not_found';
  end if;

  select *
    into v_provider
  from public.proveedores
  where id = v_request.proveedor_id;
  if not found then
    raise exception 'payment_request_provider_not_found';
  end if;

  if v_event.source_id <> v_link.id
     or v_request.id <> v_link.payment_request_id
     or v_operation.id <> v_link.operation_id
     or v_evidence.id <> v_link.evidence_id
     or v_evidence.operation_id <> v_operation.id
     or v_request.company_id <> v_link.company_id
     or v_operation.company_id <> v_link.company_id
     or v_evidence.company_id <> v_link.company_id
     or v_evidence.status <> 'shareable'
     or v_evidence.page_count is distinct from 1
     or not v_evidence.single_operation_attested
     or v_evidence.storage_bucket <> 'payment-batch-documents'
     or v_evidence.storage_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/evidence/[0-9a-f-]{36}\.pdf$'
     or v_evidence.mime_type <> 'application/pdf'
     or v_evidence.file_size_bytes is null
     or v_evidence.file_size_bytes not between 1 and 26214400
     or v_evidence.individual_sha256 is null
     or v_evidence.individual_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'payment_receipt_attachment_contract_invalid';
  end if;

  v_safe_folio := regexp_replace(
    coalesce(nullif(btrim(v_event.source_folio), ''), 'sin-folio'),
    '[^a-zA-Z0-9._-]',
    '-',
    'g'
  );
  v_safe_provider := regexp_replace(
    coalesce(
      nullif(btrim(v_provider.alias), ''),
      nullif(btrim(v_provider.nombre_completo), ''),
      'proveedor'
    ),
    '[^a-zA-Z0-9._-]',
    '-',
    'g'
  );
  v_filename := left(
    format('Comprobante_%s_%s.pdf', v_safe_folio, v_safe_provider),
    120
  );

  return jsonb_build_object(
    'bucket', v_evidence.storage_bucket,
    'path', v_evidence.storage_path,
    'mime_type', v_evidence.mime_type,
    'size_bytes', v_evidence.file_size_bytes,
    'sha256', v_evidence.individual_sha256,
    'filename', v_filename
  );
end;
$_$;


ALTER FUNCTION "public"."get_payment_receipt_notification_attachment"("p_notification_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_payment_receipt_notification_attachment"("p_notification_event_id" "uuid") IS 'Service-only resolver for the private, single-page PDF attached to payment_receipt.linked notifications.';



CREATE OR REPLACE FUNCTION "public"."get_payment_request_approver_details"("p_payment_request_id" "uuid") RETURNS TABLE("profile_id" "uuid", "display_name" "text", "email" "text", "is_fixed" boolean, "source" "text", "eligible_roles" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_id uuid := public.current_profile_id();
  v_request public.payment_requests%rowtype;
begin
  if v_actor_id is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id;
  if not found then
    raise exception 'payment_request_not_found';
  end if;

  if not (
    v_request.requested_by = v_actor_id
    or v_request.approver_id = v_actor_id
    or public.current_user_has_role(public.flux_sysadmin_roles())
    or (
      public.current_user_has_role(public.flux_approver_roles())
      and public.has_active_company_membership(v_actor_id, v_request.company_id)
    )
  ) then
    raise exception 'payment_request_not_visible';
  end if;

  return query
  select
    p.id,
    coalesce(nullif(btrim(p.full_name), ''), p.email),
    p.email,
    v_request.approver_assignment_id is not null,
    coalesce(v_request.approver_selection_source, 'historical'),
    coalesce(array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))) filter (
      where lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    ), array[]::text[])
  from (select 1) seed
  left join public.profiles p on p.id = v_request.approver_id
  left join public.user_roles ur on ur.profile_id = p.id
  left join public.roles r on r.id = ur.role_id
  group by p.id, p.full_name, p.email;
end;
$$;


ALTER FUNCTION "public"."get_payment_request_approver_details"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_request_execution_context"("p_payment_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_actor uuid := public.current_profile_id();
  v_policy public.extraordinary_payment_policies%rowtype;
  v_policy_found boolean := false;
  v_directors jsonb := '[]'::jsonb;
  v_authorization record;
  v_has_authorization boolean := false;
  v_has_open_authorization boolean := false;
  v_is_finance boolean := false;
  v_has_faculty boolean := false;
  v_request_state text := 'normal';
  v_can_begin boolean := false;
  v_block_reason text;
begin
  v_base := public.get_payment_request_execution_context_pre_037(
    p_payment_request_id
  );
  v_is_finance := coalesce((v_base->>'is_finance')::boolean, false);

  select request.extraordinary_state,
         public.extraordinary_profile_has_explicit_faculty(v_actor, request.company_id)
  into v_request_state, v_has_faculty
  from public.payment_requests request
  where request.id = p_payment_request_id;

  select policy.*
  into v_policy
  from public.extraordinary_payment_policies policy
  join public.payment_requests request
    on request.company_id = policy.company_id
  where request.id = p_payment_request_id;
  v_policy_found := found;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'profile_id', director.director_profile_id,
      'name', profile.full_name
    )
    order by profile.full_name, director.director_profile_id
  ), '[]'::jsonb)
  into v_directors
  from public.payment_requests request
  join public.company_directors director
    on director.company_id = request.company_id
   and director.active
  join public.profiles profile
    on profile.id = director.director_profile_id
   and profile.active
  where request.id = p_payment_request_id
    and public.extraordinary_profile_is_company_director(
      director.director_profile_id,
      request.company_id
    );

  select
    extraordinary_auth.*,
    author.full_name as authorized_by_name,
    external_director.full_name as external_director_name
  into v_authorization
  from public.payment_request_extraordinary_authorizations extraordinary_auth
  left join public.profiles author
    on author.id = extraordinary_auth.authorized_by
  left join public.profiles external_director
    on external_director.id = extraordinary_auth.external_director_profile_id
  where extraordinary_auth.payment_request_id = p_payment_request_id
  order by extraordinary_auth.authorized_at desc, extraordinary_auth.id desc
  limit 1;
  v_has_authorization := found;

  select exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    where extraordinary_auth.payment_request_id = p_payment_request_id
      and extraordinary_auth.status in (
        'draft', 'active', 'consumed_pending_ratification'
      )
  )
  into v_has_open_authorization;

  v_can_begin :=
    v_has_faculty
    and v_request_state = 'extraordinary_requested'
    and v_policy_found
    and v_policy.enabled
    and jsonb_array_length(v_directors) > 0
    and not v_has_open_authorization;

  v_block_reason := case
    when not v_has_faculty then 'explicit_extraordinary_faculty_required'
    when v_request_state <> 'extraordinary_requested'
      then 'extraordinary_intent_required_before_draft'
    when v_has_open_authorization then 'extraordinary_authorization_already_open'
    when not v_policy_found or not v_policy.enabled
      then 'extraordinary_policy_disabled'
    when jsonb_array_length(v_directors) = 0
      then 'external_director_not_active_for_company'
    when not coalesce((v_base->>'budget_validation_current')::boolean, false)
      then 'budget_revalidation_required'
    else null
  end;

  return v_base || jsonb_build_object(
    'can_authorize_extraordinary', v_can_begin,
    'is_extraordinary_faculty', v_has_faculty,
    'extraordinary_state', v_request_state,
    'authorization_block_reason', v_block_reason,
    'extraordinary_policy', case
      when not v_policy_found then null
      else jsonb_build_object(
        'enabled', v_policy.enabled,
        'max_amount_mxn', v_policy.max_amount_mxn,
        'allowed_categories', v_policy.allowed_categories,
        'authorization_valid_hours', v_policy.authorization_valid_hours,
        'ratification_due_hours', v_policy.ratification_due_hours,
        'evidence_required', v_policy.evidence_required
      )
    end,
    'eligible_external_directors', v_directors,
    'extraordinary', case
      when not v_has_authorization then null
      else jsonb_build_object(
        'id', v_authorization.id,
        'secure_contract',
          v_authorization.external_director_profile_id is not null,
        'status', v_authorization.status,
        'category', v_authorization.category,
        'reason', v_authorization.reason,
        'authorized_by', v_authorization.authorized_by,
        'authorized_by_name', v_authorization.authorized_by_name,
        'authorized_at', v_authorization.authorized_at,
        'external_director_profile_id',
          v_authorization.external_director_profile_id,
        'external_director_name', v_authorization.external_director_name,
        'external_authorized_at', v_authorization.external_authorized_at,
        'authorization_medium', v_authorization.authorization_medium,
        'authorization_reference', v_authorization.authorization_reference,
        'director_absence_confirmed', v_authorization.director_absence_confirmed,
        'cannot_wait_confirmed', v_authorization.cannot_wait_confirmed,
        'valid_until', v_authorization.valid_until,
        'ratification_due_at', v_authorization.ratification_due_at,
        'evidence_type', v_authorization.evidence_type,
        'evidence_sha256', v_authorization.evidence_sha256,
        'evidence_mime_type', v_authorization.evidence_mime_type,
        'evidence_size_bytes', v_authorization.evidence_size_bytes,
        'evidence_finalized',
          v_authorization.evidence_verified_at is not null,
        'storage_bucket', case
          when v_authorization.status = 'draft'
            and (
              v_authorization.authorized_by = v_actor
            )
          then v_authorization.evidence_storage_bucket
          else null
        end,
        'storage_path', case
          when v_authorization.status = 'draft'
            and (
              v_authorization.authorized_by = v_actor
            )
          then v_authorization.evidence_storage_path
          else null
        end,
        'can_resume', v_authorization.status = 'draft'
          and (
            v_authorization.authorized_by = v_actor
          ),
        'authorization_current',
          v_authorization.status = 'active'
          and public.extraordinary_authorization_is_ready(v_authorization.id),
        'ready_for_layout',
          public.extraordinary_authorization_is_ready(v_authorization.id),
        'can_revoke',
          v_has_faculty
          and v_authorization.status in ('draft', 'active')
          and not coalesce((v_base->>'executed')::boolean, false),
        'consumed_at', v_authorization.consumed_at,
        'consumed_layout_id', v_authorization.consumed_layout_id,
        'ratification_cut_count', v_authorization.ratification_cut_count,
        'ratification_overdue_at', v_authorization.ratification_overdue_at,
        'ratified_at', v_authorization.ratified_at,
        'disputed_at', v_authorization.disputed_at,
        'dispute_reason', v_authorization.dispute_reason,
        'legacy_classification_reason',
          v_authorization.legacy_classification_reason
      )
    end
  );
end
$$;


ALTER FUNCTION "public"."get_payment_request_execution_context"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_request_execution_context_pre_037"("p_payment_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_actor uuid := public.current_profile_id();
  v_policy public.extraordinary_payment_policies%rowtype;
  v_policy_found boolean := false;
  v_directors jsonb := '[]'::jsonb;
  v_authorization record;
  v_has_authorization boolean := false;
  v_has_open_authorization boolean := false;
  v_is_finance boolean := false;
  v_can_begin boolean := false;
  v_block_reason text;
begin
  v_base := public.get_payment_request_execution_context_pre_037(
    p_payment_request_id
  );
  v_is_finance := coalesce((v_base->>'is_finance')::boolean, false);

  select policy.*
  into v_policy
  from public.extraordinary_payment_policies policy
  join public.payment_requests request
    on request.company_id = policy.company_id
  where request.id = p_payment_request_id;
  v_policy_found := found;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'profile_id', director.director_profile_id,
      'name', profile.full_name
    )
    order by profile.full_name, director.director_profile_id
  ), '[]'::jsonb)
  into v_directors
  from public.payment_requests request
  join public.company_directors director
    on director.company_id = request.company_id
   and director.active
  join public.profiles profile
    on profile.id = director.director_profile_id
   and profile.active
  where request.id = p_payment_request_id
    and public.extraordinary_profile_is_company_director(
      director.director_profile_id,
      request.company_id
    );

  select
    extraordinary_auth.*,
    author.full_name as authorized_by_name,
    external_director.full_name as external_director_name
  into v_authorization
  from public.payment_request_extraordinary_authorizations extraordinary_auth
  left join public.profiles author
    on author.id = extraordinary_auth.authorized_by
  left join public.profiles external_director
    on external_director.id = extraordinary_auth.external_director_profile_id
  where extraordinary_auth.payment_request_id = p_payment_request_id
  order by extraordinary_auth.authorized_at desc, extraordinary_auth.id desc
  limit 1;
  v_has_authorization := found;

  select exists (
    select 1
    from public.payment_request_extraordinary_authorizations extraordinary_auth
    where extraordinary_auth.payment_request_id = p_payment_request_id
      and extraordinary_auth.status in (
        'draft', 'active', 'consumed_pending_ratification'
      )
  )
  into v_has_open_authorization;

  v_can_begin :=
    v_is_finance
    and coalesce((v_base->>'can_authorize_extraordinary')::boolean, false)
    and v_policy_found
    and v_policy.enabled
    and jsonb_array_length(v_directors) > 0
    and not v_has_open_authorization;

  v_block_reason := case
    when not v_is_finance then 'finance_role_required'
    when v_has_open_authorization then 'extraordinary_authorization_already_open'
    when not coalesce((v_base->>'can_authorize_extraordinary')::boolean, false)
      then v_base->>'authorization_block_reason'
    when not v_policy_found or not v_policy.enabled
      then 'extraordinary_policy_disabled'
    when jsonb_array_length(v_directors) = 0
      then 'external_director_not_active_for_company'
    else null
  end;

  return v_base || jsonb_build_object(
    'can_authorize_extraordinary', v_can_begin,
    'authorization_block_reason', v_block_reason,
    'extraordinary_policy', case
      when not v_policy_found then null
      else jsonb_build_object(
        'enabled', v_policy.enabled,
        'max_amount_mxn', v_policy.max_amount_mxn,
        'allowed_categories', v_policy.allowed_categories,
        'authorization_valid_hours', v_policy.authorization_valid_hours,
        'ratification_due_hours', v_policy.ratification_due_hours,
        'evidence_required', v_policy.evidence_required
      )
    end,
    'eligible_external_directors', v_directors,
    'extraordinary', case
      when not v_has_authorization then null
      else jsonb_build_object(
        'id', v_authorization.id,
        'secure_contract',
          v_authorization.external_director_profile_id is not null,
        'status', v_authorization.status,
        'category', v_authorization.category,
        'reason', v_authorization.reason,
        'authorized_by', v_authorization.authorized_by,
        'authorized_by_name', v_authorization.authorized_by_name,
        'authorized_at', v_authorization.authorized_at,
        'external_director_profile_id',
          v_authorization.external_director_profile_id,
        'external_director_name', v_authorization.external_director_name,
        'external_authorized_at', v_authorization.external_authorized_at,
        'valid_until', v_authorization.valid_until,
        'ratification_due_at', v_authorization.ratification_due_at,
        'evidence_type', v_authorization.evidence_type,
        'evidence_sha256', v_authorization.evidence_sha256,
        'evidence_mime_type', v_authorization.evidence_mime_type,
        'evidence_size_bytes', v_authorization.evidence_size_bytes,
        'evidence_finalized',
          v_authorization.evidence_verified_at is not null,
        'storage_bucket', case
          when v_authorization.status = 'draft'
            and (
              v_authorization.authorized_by = v_actor
              or public.current_user_has_role(public.flux_sysadmin_roles())
            )
          then v_authorization.evidence_storage_bucket
          else null
        end,
        'storage_path', case
          when v_authorization.status = 'draft'
            and (
              v_authorization.authorized_by = v_actor
              or public.current_user_has_role(public.flux_sysadmin_roles())
            )
          then v_authorization.evidence_storage_path
          else null
        end,
        'can_resume', v_authorization.status = 'draft'
          and (
            v_authorization.authorized_by = v_actor
            or public.current_user_has_role(public.flux_sysadmin_roles())
          ),
        'authorization_current',
          v_authorization.status = 'active'
          and public.extraordinary_authorization_is_ready(v_authorization.id),
        'ready_for_layout',
          public.extraordinary_authorization_is_ready(v_authorization.id),
        'can_revoke',
          v_is_finance
          and v_authorization.status in ('draft', 'active')
          and not coalesce((v_base->>'executed')::boolean, false),
        'consumed_at', v_authorization.consumed_at,
        'consumed_layout_id', v_authorization.consumed_layout_id,
        'ratified_at', v_authorization.ratified_at,
        'disputed_at', v_authorization.disputed_at,
        'dispute_reason', v_authorization.dispute_reason,
        'legacy_classification_reason',
          v_authorization.legacy_classification_reason
      )
    end
  );
end
$$;


ALTER FUNCTION "public"."get_payment_request_execution_context_pre_037"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_request_execution_readiness"("p_payment_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_latest record;
  v_extra record;
  v_request_status text;
  v_payment_method text;
  v_enforced boolean := false;
  v_has_execution boolean := false;
  v_has_cash_fund boolean := false;
  v_has_batch_item boolean := false;
  v_has_open_batch boolean := false;
  v_has_direction_rejection boolean := false;
  v_direction_current boolean := false;
  v_extraordinary_current boolean := false;
  v_is_finance boolean := false;
  v_can_execute boolean := false;
  v_can_create_cash_fund boolean := false;
  v_authorization_source text;
  v_block_reason text;
  v_cash_fund_block_reason text;
begin
  if p_payment_request_id is null then
    raise exception 'payment_request_required';
  end if;

  select *
    into v_request
  from public.payment_requests
  where id = p_payment_request_id;

  if not found then
    raise exception 'payment_request_not_found';
  end if;

  v_request_status := v_request.status::text;
  v_payment_method := lower(
    coalesce(
      nullif(btrim(v_request.payment_method), ''),
      nullif(btrim(v_request.request_type::text), '')
    )
  );
  v_payment_method := case v_payment_method
    when 'efectivo' then 'cash'
    when 'cheque' then 'check'
    else v_payment_method
  end;

  v_is_finance := public.current_user_has_role(public.flux_finance_roles());
  v_has_execution := public.approval_batch_request_has_any_execution_record(v_request.id);
  v_has_cash_fund := exists (
    select 1
    from public.cash_funds cf
    where cf.payment_request_id = v_request.id
  );

  select coalesce(
    settings.regular_payments_require_closed_batch
      and settings.enforcement_started_at is not null
      and v_request.created_at >= settings.enforcement_started_at,
    false
  )
    into v_enforced
  from public.approval_batch_company_settings settings
  where settings.company_id = v_request.company_id;
  v_enforced := coalesce(v_enforced, false);

  select
    abi.id as item_id,
    abi.director_status,
    abi.decided_at,
    abi.review_sequence,
    abi.rebatch_status,
    ab.id as batch_id,
    ab.status as batch_status,
    ab.closed_at
    into v_latest
  from public.approval_batch_items abi
  join public.approval_batches ab on ab.id = abi.batch_id
  where abi.payment_request_id = v_request.id
    and abi.removed_at is null
  order by abi.review_sequence desc, abi.created_at desc, abi.id desc
  limit 1;
  v_has_batch_item := found;

  select prea.id, prea.authorized_at
    into v_extra
  from public.payment_request_extraordinary_authorizations prea
  where prea.payment_request_id = v_request.id
    and prea.status = 'active'
  order by prea.authorized_at desc, prea.id desc
  limit 1;

  v_extraordinary_current := coalesce(
    v_extra.id is not null
      and v_extra.authorized_at >= v_request.approval_material_updated_at,
    false
  );
  v_direction_current := public.approval_batch_request_has_current_direction_approval(v_request.id);
  v_has_open_batch := exists (
    select 1
    from public.approval_batch_items abi
    join public.approval_batches ab on ab.id = abi.batch_id
    where abi.payment_request_id = v_request.id
      and abi.removed_at is null
      and ab.status in ('draft', 'submitted')
  );
  v_has_direction_rejection := exists (
    select 1
    from public.approval_batch_items abi
    where abi.payment_request_id = v_request.id
      and abi.removed_at is null
      and abi.director_status = 'rejected'
  );

  if v_has_execution then
    v_block_reason := 'payment_request_already_executed';
  elsif v_request_status not in ('submitted', 'pending_approval', 'approved') then
    v_block_reason := 'request_status_not_executable';
  elsif v_extra.id is not null then
    if not v_extraordinary_current then
      v_block_reason := 'extraordinary_not_current';
    elsif v_has_direction_rejection then
      v_block_reason := 'direction_rejected';
    elsif v_has_open_batch then
      v_block_reason := 'batch_not_closed';
    else
      v_authorization_source := 'extraordinary';
    end if;
  elsif v_has_batch_item then
    if v_latest.director_status = 'rejected' then
      v_block_reason := 'direction_rejected';
    elsif v_latest.director_status = 'pending'
       or v_latest.batch_status = 'submitted' then
      v_block_reason := 'direction_pending';
    elsif v_latest.director_status = 'approved'
       and (
         v_latest.decided_at is null
         or v_latest.decided_at < v_request.approval_material_updated_at
       ) then
      v_block_reason := 'material_change_requires_reapproval';
    elsif v_latest.director_status = 'approved'
       and v_latest.batch_status <> 'closed' then
      v_block_reason := 'batch_not_closed';
    elsif v_latest.director_status = 'approved'
       and (
         v_latest.closed_at is null
         or v_latest.closed_at < v_latest.decided_at
       ) then
      v_block_reason := 'batch_not_closed';
    elsif v_latest.director_status = 'approved'
       and not v_direction_current then
      v_block_reason := 'material_change_requires_reapproval';
    elsif v_latest.director_status = 'approved'
       and v_latest.batch_status = 'closed'
       and v_direction_current then
      v_authorization_source := 'closed_batch';
    else
      v_block_reason := 'execution_not_authorized';
    end if;
  elsif not v_enforced and v_request_status = 'approved' then
    v_authorization_source := 'legacy_approved';
  elsif v_enforced then
    v_block_reason := 'direction_pending';
  else
    v_block_reason := 'execution_not_authorized';
  end if;

  v_can_execute := v_block_reason is null and v_authorization_source is not null;
  v_cash_fund_block_reason := case
    when not v_is_finance then 'finance_role_required'
    when v_payment_method not in ('cash', 'check') then 'payment_request_must_be_cash_or_check'
    when v_has_cash_fund then 'cash_fund_already_exists'
    when v_can_execute then null
    when v_block_reason = 'direction_pending' then 'cash_fund_direction_pending'
    when v_block_reason = 'direction_rejected' then 'cash_fund_direction_rejected'
    when v_block_reason = 'batch_not_closed' then 'cash_fund_batch_not_closed'
    when v_block_reason = 'material_change_requires_reapproval'
      then 'cash_fund_material_change_requires_reapproval'
    when v_block_reason = 'extraordinary_not_current'
      then 'cash_fund_extraordinary_not_current'
    else 'cash_fund_execution_not_authorized'
  end;
  v_can_create_cash_fund := v_cash_fund_block_reason is null;

  return jsonb_build_object(
    'payment_request_id', v_request.id,
    'request_status', v_request_status,
    'payment_method', v_payment_method,
    'can_execute', v_can_execute,
    'can_create_cash_fund', v_can_create_cash_fund,
    'authorization_source', v_authorization_source,
    'block_reason', v_block_reason,
    'cash_fund_block_reason', v_cash_fund_block_reason,
    'finance_actor', v_is_finance,
    'direction_approval_current', v_direction_current,
    'batch_closed', coalesce(v_latest.batch_status = 'closed' and v_latest.closed_at is not null, false),
    'extraordinary_current', v_extraordinary_current,
    'execution_exists', v_has_execution,
    'cash_fund_exists', v_has_cash_fund,
    'enforcement_required', v_enforced,
    'latest_batch_id', v_latest.batch_id,
    'latest_batch_status', v_latest.batch_status,
    'latest_item_id', v_latest.item_id,
    'latest_director_status', v_latest.director_status,
    'direction_decided_at', v_latest.decided_at,
    'batch_closed_at', v_latest.closed_at
  );
end
$$;


ALTER FUNCTION "public"."get_payment_request_execution_readiness"("p_payment_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_payment_request_execution_readiness"("p_payment_request_id" "uuid") IS 'Internal canonical readiness for closed-batch, current-extraordinary and legacy-approved execution paths; returns no banking data.';



CREATE OR REPLACE FUNCTION "public"."get_payment_request_receipt_summary"("p_payment_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.payment_requests%rowtype;
  v_snapshot public.payable_snapshots%rowtype;
  v_link record;
begin
  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id;
  if not found then raise exception 'payment_request_not_found'; end if;
  perform public.payment_reconciliation_require_finance(v_request.company_id);

  select * into v_snapshot
  from public.payable_snapshots
  where payment_request_id = v_request.id
  order by version desc
  limit 1;

  select
    link.*,
    request.request_number,
    evidence.status as evidence_status,
    evidence.page_count
    into v_link
  from public.payment_request_receipt_links link
  join public.payment_requests request on request.id = link.payment_request_id
  join public.payment_operation_evidence evidence on evidence.id = link.evidence_id
  where link.payment_request_id = v_request.id;

  return jsonb_build_object(
    'payment_request_id', v_request.id,
    'request_number', v_request.request_number,
    'request_status', v_request.status::text,
    'authorized_minor', v_snapshot.amount_minor,
    'currency', coalesce(v_snapshot.currency, v_request.currency),
    'link', case when v_link.id is null then null else jsonb_build_object(
      'id', v_link.id,
      'request_number', v_link.request_number,
      'amount_minor', v_link.amount_minor,
      'currency', v_link.currency,
      'payment_date', v_link.payment_date,
      'reference_hint', v_link.reference_hint,
      'evidence_id', v_link.evidence_id,
      'evidence_status', v_link.evidence_status,
      'page_count', v_link.page_count,
      'linked_at', v_link.linked_at
    ) end,
    'external_provider_access', false,
    'external_provider_block_reason', 'provider_identity_link_not_implemented'
  );
end
$$;


ALTER FUNCTION "public"."get_payment_request_receipt_summary"("p_payment_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_provider_intake_detail"("p_payment_intake_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_intake public.payment_intake%rowtype;
  v_company_name text;
  v_result jsonb;
begin
  if p_payment_intake_id is null then
    raise exception 'provider_intake_id_required';
  end if;

  perform public.provider_intake_actor_context();

  select pi.*
    into v_intake
  from public.payment_intake pi
  join public.companies c on c.id = pi.company_id
  where pi.id = p_payment_intake_id;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  v_company_name := (
    select c.name
    from public.companies c
    where c.id = v_intake.company_id
  );

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  select jsonb_build_object(
    'intake', jsonb_build_object(
      'id', v_intake.id,
      'public_folio', v_intake.public_folio,
      'company_id', v_intake.company_id,
      'company_name', v_company_name,
      'status', v_intake.status,
      'provider_name', v_intake.provider_name,
      'provider_rfc', v_intake.provider_rfc,
      'provider_email', v_intake.provider_email,
      'provider_phone', v_intake.provider_phone,
      'concept', v_intake.concept,
      'description', v_intake.description,
      'amount_requested', v_intake.amount_requested,
      'currency', v_intake.currency,
      'requested_payment_date', v_intake.requested_payment_date,
      'invoice_folio', v_intake.invoice_folio,
      'invoice_uuid', v_intake.invoice_uuid,
      'invoice_date', v_intake.invoice_date,
      'bank_name', v_intake.bank_name,
      'bank_account_masked', public.provider_intake_mask_value(v_intake.bank_account),
      'bank_clabe_masked', public.provider_intake_mask_value(v_intake.bank_clabe),
      'beneficiary_name', v_intake.beneficiary_name,
      'created_at', v_intake.created_at,
      'updated_at', v_intake.updated_at
    ),
    'files', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', pif.id,
          'payment_intake_id', pif.payment_intake_id,
          'original_filename', pif.original_filename,
          'mime_type', pif.mime_type,
          'size_bytes', pif.size_bytes,
          'file_kind', pif.file_kind,
          'quarantine_status', pif.quarantine_status,
          'created_at', pif.created_at
        )
        order by pif.created_at, pif.id
      )
      from public.payment_intake_files pif
      where pif.payment_intake_id = v_intake.id
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', pie.id,
          'event_type', pie.event_type,
          'actor_type', pie.actor_type,
          'actor_name', coalesce(p.full_name, 'Sistema'),
          'from_status', pie.from_status,
          'to_status', pie.to_status,
          'notes', pie.notes,
          'created_at', pie.created_at
        )
        order by pie.created_at desc, pie.id desc
      )
      from public.payment_intake_events pie
      left join public.profiles p on p.id = pie.actor_profile_id
      where pie.payment_intake_id = v_intake.id
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end
$$;


ALTER FUNCTION "public"."get_provider_intake_detail"("p_payment_intake_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_provider_intake_detail"("p_payment_intake_id" "uuid") IS 'Authorized provider-intake detail with masked bank values, private file metadata without storage paths, and sanitized audit history.';



CREATE OR REPLACE FUNCTION "public"."get_provider_intake_match_comparison"("p_payment_intake_id" "uuid", "p_proveedor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_intake public.payment_intake%rowtype;
  v_provider public.proveedores%rowtype;
begin
  if p_payment_intake_id is null or p_proveedor_id is null then
    raise exception 'provider_intake_comparison_fields_required';
  end if;

  perform public.provider_intake_actor_context();

  select *
    into v_intake
  from public.payment_intake
  where id = p_payment_intake_id;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  select *
    into v_provider
  from public.proveedores
  where id = p_proveedor_id;

  if not found then
    raise exception 'provider_intake_provider_not_found';
  end if;

  return jsonb_build_object(
    'payment_intake_id', v_intake.id,
    'status', v_intake.status,
    'updated_at', v_intake.updated_at,
    'eligible', (
      v_intake.status = 'in_review'
      and v_intake.created_payment_request_id is null
      and coalesce(v_provider.activo, true)
    ),
    'proveedor_id', v_provider.id,
    'provider_alias', v_provider.alias,
    'provider_active', coalesce(v_provider.activo, true),
    'rows', jsonb_build_array(
      jsonb_build_object(
        'field', 'Razón social',
        'declared', v_intake.provider_name,
        'master', coalesce(v_provider.nombre_completo, v_provider.beneficiary_name, v_provider.alias),
        'result', case
          when nullif(btrim(v_intake.provider_name), '') is null
            or nullif(btrim(coalesce(v_provider.nombre_completo, v_provider.beneficiary_name, v_provider.alias)), '') is null
            then 'not_reported'
          when public.normalize_provider_match_text(v_intake.provider_name)
            = public.normalize_provider_match_text(coalesce(v_provider.nombre_completo, v_provider.beneficiary_name, v_provider.alias))
            then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'RFC',
        'declared', v_intake.provider_rfc,
        'master', v_provider.rfc,
        'result', case
          when v_intake.provider_rfc is null or v_provider.rfc is null then 'not_reported'
          when upper(regexp_replace(v_intake.provider_rfc, '[[:space:]-]+', '', 'g'))
            = upper(regexp_replace(v_provider.rfc, '[[:space:]-]+', '', 'g')) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'Banco',
        'declared', v_intake.bank_name,
        'master', v_provider.banco,
        'result', case
          when v_intake.bank_name is null or v_provider.banco is null then 'not_reported'
          when public.normalize_provider_match_text(v_intake.bank_name)
            = public.normalize_provider_match_text(v_provider.banco) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'Cuenta',
        'declared', public.provider_intake_mask_value(v_intake.bank_account),
        'master', public.provider_intake_mask_value(v_provider.cuenta_bancaria),
        'result', case
          when v_intake.bank_account is null or v_provider.cuenta_bancaria is null then 'not_reported'
          when public.normalize_provider_match_digits(v_intake.bank_account)
            = public.normalize_provider_match_digits(v_provider.cuenta_bancaria) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'CLABE',
        'declared', public.provider_intake_mask_value(v_intake.bank_clabe),
        'master', public.provider_intake_mask_value(v_provider.clabe),
        'result', case
          when v_intake.bank_clabe is null or v_provider.clabe is null then 'not_reported'
          when public.normalize_provider_match_digits(v_intake.bank_clabe)
            = public.normalize_provider_match_digits(v_provider.clabe) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'Beneficiario',
        'declared', v_intake.beneficiary_name,
        'master', v_provider.beneficiary_name,
        'result', case
          when v_intake.beneficiary_name is null or v_provider.beneficiary_name is null then 'not_reported'
          when public.normalize_provider_match_text(v_intake.beneficiary_name)
            = public.normalize_provider_match_text(v_provider.beneficiary_name) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'Correo',
        'declared', v_intake.provider_email,
        'master', v_provider.email,
        'result', case
          when v_intake.provider_email is null or v_provider.email is null then 'not_reported'
          when lower(btrim(v_intake.provider_email)) = lower(btrim(v_provider.email)) then 'match'
          else 'different'
        end
      ),
      jsonb_build_object(
        'field', 'Teléfono',
        'declared', v_intake.provider_phone,
        'master', v_provider.telefono,
        'result', case
          when v_intake.provider_phone is null or v_provider.telefono is null then 'not_reported'
          when public.normalize_provider_match_digits(v_intake.provider_phone)
            = public.normalize_provider_match_digits(v_provider.telefono) then 'match'
          else 'different'
        end
      )
    )
  );
end
$$;


ALTER FUNCTION "public"."get_provider_intake_match_comparison"("p_payment_intake_id" "uuid", "p_proveedor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_provider_intake_match_comparison"("p_payment_intake_id" "uuid", "p_proveedor_id" "uuid") IS 'Authorized field-by-field comparison between immutable intake declarations and a canonical provider, with bank identifiers masked.';



CREATE OR REPLACE FUNCTION "public"."guard_payment_request_execution_data_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if row(
    old.provider_bank_account_id,
    old.company_bank_account_id,
    old.due_date,
    old.scheduled_payment_date,
    old.payment_reference,
    old.payment_concept
  ) is not distinct from row(
    new.provider_bank_account_id,
    new.company_bank_account_id,
    new.due_date,
    new.scheduled_payment_date,
    new.payment_reference,
    new.payment_concept
  ) then
    return new;
  end if;

  perform public.approval_batch_require_finance();

  if current_setting('flux.payment_execution_rpc', true)
       is distinct from new.id::text then
    raise exception 'payment_execution_rpc_required';
  end if;

  if new.company_bank_account_id is not null and not exists (
    select 1
    from public.company_bank_accounts company_account
    where company_account.id = new.company_bank_account_id
      and company_account.company_id = new.company_id
      and coalesce(company_account.active, false)
      and nullif(btrim(company_account.account_number), '') is not null
  ) then
    raise exception 'company_bank_account_not_found_inactive_or_company_mismatch';
  end if;

  if new.provider_bank_account_id is not null and not exists (
    select 1
    from public.provider_bank_accounts provider_account
    where provider_account.id = new.provider_bank_account_id
      and (
        (
          new.provider_id is not null
          and provider_account.provider_id = new.provider_id
        )
        or (
          new.proveedor_id is not null
          and exists (
            select 1
            from public.proveedor_provider_links provider_link
            where provider_link.provider_id = provider_account.provider_id
              and provider_link.proveedor_id = new.proveedor_id
          )
        )
      )
  ) then
    raise exception 'provider_bank_account_provider_mismatch';
  end if;

  if new.payment_reference is not null
     and nullif(btrim(new.payment_reference), '') is not null
     and btrim(new.payment_reference) !~ '^[0-9]+$' then
    raise exception 'payment_reference_must_be_numeric';
  end if;

  if new.payment_reference is not null
     and char_length(btrim(new.payment_reference)) > 5 then
    raise exception 'payment_reference_too_long';
  end if;

  if new.payment_concept is not null
     and char_length(btrim(new.payment_concept)) > 120 then
    raise exception 'payment_concept_too_long';
  end if;

  if new.payment_concept is not null
     and new.payment_concept ~ '[[:cntrl:]]' then
    raise exception 'payment_concept_invalid_characters';
  end if;

  return new;
end
$_$;


ALTER FUNCTION "public"."guard_payment_request_execution_data_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_provider_payment_execution_data_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_missing text[];
begin
  if nullif(btrim(coalesce(new.destination_type, '')), '') is null
     and nullif(btrim(coalesce(new.clabe, '')), '') is null
     and nullif(btrim(coalesce(new.cuenta_bancaria, '')), '') is null
     and nullif(btrim(coalesce(new.convenio_number, '')), '') is null
     and nullif(btrim(coalesce(new.beneficiary_name, '')), '') is null
     and nullif(btrim(coalesce(new.banco, '')), '') is null then
    return new;
  end if;

  perform public.approval_batch_require_finance();

  if current_setting('flux.provider_payment_execution_rpc', true)
       is distinct from new.id::text then
    raise exception 'provider_payment_execution_rpc_required';
  end if;

  v_missing := public.provider_payment_execution_missing_fields(new);
  if v_missing && array[
    'beneficiary_name_invalid',
    'banco_invalid',
    'destination_type_invalid',
    'clabe_invalid',
    'cuenta_bancaria_invalid',
    'convenio_number_invalid'
  ]::text[] then
    raise exception 'provider_payment_execution_data_invalid';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."guard_provider_payment_execution_data_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_active_company_membership"("p_profile_id" "uuid", "p_company_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profile_company_memberships pcm
    join public.profiles p on p.id = pcm.profile_id
    join public.companies c on c.id = pcm.company_id
    where pcm.profile_id = p_profile_id
      and pcm.company_id = p_company_id
      and pcm.active
      and coalesce(p.active, true)
      and coalesce(c.active, true)
  );
$$;


ALTER FUNCTION "public"."has_active_company_membership"("p_profile_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_approval_batch_notification"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid", "p_recipient_email" "text", "p_recipient_role" "text", "p_subject" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_email text := nullif(lower(btrim(coalesce(p_recipient_email, ''))), '');
begin
  insert into public.notification_events(
    event_type, source_table, source_id, source_folio,
    recipient_type, recipient_profile_id, recipient_email, recipient_role,
    channel, priority, subject, payload, idempotency_key,
    status, next_attempt_at, last_error
  ) values (
    p_event_type, p_source_table, p_source_id, p_source_folio,
    p_recipient_type, p_recipient_profile_id, v_email, p_recipient_role,
    'email', p_priority, p_subject, coalesce(p_payload, '{}'::jsonb), p_idempotency_key,
    case when v_email is null then 'dead_letter' else 'pending' end,
    case when v_email is null then null else now() end,
    case when v_email is null then 'missing_recipient_email' else null end
  ) on conflict (idempotency_key) do nothing;
end
$$;


ALTER FUNCTION "public"."insert_approval_batch_notification"("p_event_type" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_folio" "text", "p_recipient_type" "text", "p_recipient_profile_id" "uuid", "p_recipient_email" "text", "p_recipient_role" "text", "p_subject" "text", "p_payload" "jsonb", "p_idempotency_key" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_payment_request_approver_for_company"("p_profile_id" "uuid", "p_company_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.has_active_company_membership(p_profile_id, p_company_id)
    and exists (
      select 1
      from public.user_roles ur
      join public.roles r on r.id = ur.role_id
      where ur.profile_id = p_profile_id
        and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    );
$$;


ALTER FUNCTION "public"."is_payment_request_approver_for_company"("p_profile_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_payment_receipt_to_request"("p_operation_id" "uuid", "p_payment_request_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_initial public.bank_payment_operations%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_request public.payment_requests%rowtype;
  v_snapshot public.payable_snapshots%rowtype;
  v_evidence public.payment_operation_evidence%rowtype;
  v_legacy_receipt public.payment_receipts%rowtype;
  v_provider record;
  v_actor uuid;
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_provider_match boolean;
  v_link_id uuid;
  v_event_id uuid;
  v_linked_at timestamptz;
  v_result jsonb;
  v_notification jsonb;
  v_updated integer;
  v_layout_line_count integer := 0;
  v_total_layout_lines integer := 0;
  v_legacy_receipt_count integer := 0;
  v_layout_line public.payment_layout_lines%rowtype;
  v_layout public.payment_layouts%rowtype;
  v_layout_final_status text;
begin
  select * into v_initial
  from public.bank_payment_operations
  where id = p_operation_id;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_initial.company_id);
  v_payload := jsonb_build_object(
    'operation_id', p_operation_id,
    'payment_request_id', p_payment_request_id
  );
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_initial.company_id,
    'payment_receipt.link',
    p_idempotency_key,
    v_payload_hash,
    v_actor
  );
  if v_replay is not null then return v_replay; end if;

  select * into v_operation
  from public.bank_payment_operations
  where id = p_operation_id
  for update;
  if v_operation.company_id <> v_initial.company_id then
    raise exception 'bank_payment_operation_company_changed';
  end if;
  if v_operation.status = 'cancelled' then
    raise exception 'bank_payment_operation_not_linkable';
  end if;
  if exists (
    select 1 from public.payment_request_receipt_links
    where operation_id = v_operation.id
  ) then
    raise exception 'bank_receipt_already_linked';
  end if;
  if not exists (
    select 1 from public.payment_document_extractions extraction
    where extraction.id = v_operation.extraction_id
      and extraction.status = 'accepted'
  ) then
    raise exception 'accepted_payment_extraction_required';
  end if;

  select * into v_request
  from public.payment_requests
  where id = p_payment_request_id
  for update;
  if not found then raise exception 'payment_request_not_found'; end if;
  if v_request.company_id <> v_operation.company_id then
    raise exception 'payment_request_company_mismatch';
  end if;
  if v_request.status::text not in ('approved', 'finance_validation', 'paid') then
    raise exception 'payment_request_must_be_approved_in_layout_or_paid_by_layout';
  end if;
  if exists (
    select 1 from public.payment_request_receipt_links
    where payment_request_id = v_request.id
  ) then
    raise exception 'payment_request_already_has_receipt';
  end if;
  if v_request.status::text <> 'paid' and exists (
    select 1 from public.payment_receipts legacy
    where legacy.payment_request_id = v_request.id
  ) then
    raise exception 'payment_request_already_has_receipt';
  end if;

  if v_request.status::text = 'finance_validation' then
    select count(*) into v_layout_line_count
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'included'
      and layout.status in ('generated', 'uploaded');

    if v_layout_line_count <> 1 then
      raise exception 'payment_request_live_layout_line_required';
    end if;

    select line.* into v_layout_line
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'included'
      and layout.status in ('generated', 'uploaded')
    for update of line;

    select * into v_layout
    from public.payment_layouts
    where id = v_layout_line.layout_id
    for update;

    if v_layout.status not in ('generated', 'uploaded')
       or v_layout_line.status <> 'included' then
      raise exception 'payment_request_live_layout_line_changed';
    end if;
  elsif v_request.status::text = 'paid' then
    if v_request.paid_by is null or v_request.paid_at is null then
      raise exception 'paid_layout_request_audit_incomplete';
    end if;

    select count(*) into v_total_layout_lines
    from public.payment_layout_lines line
    where line.payment_request_id = v_request.id;

    select count(*) into v_layout_line_count
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'paid'
      and layout.status = 'confirmed';

    if v_total_layout_lines <> 1 or v_layout_line_count <> 1 then
      raise exception 'paid_request_confirmed_layout_line_required';
    end if;

    select line.* into v_layout_line
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'paid'
      and layout.status = 'confirmed'
    for update of line;

    select * into v_layout
    from public.payment_layouts
    where id = v_layout_line.layout_id
    for update;

    if v_layout.status <> 'confirmed' or v_layout_line.status <> 'paid' then
      raise exception 'paid_request_confirmed_layout_changed';
    end if;

    select count(*) into v_legacy_receipt_count
    from public.payment_receipts legacy
    where legacy.payment_request_id = v_request.id;

    if v_legacy_receipt_count <> 1 then
      raise exception 'paid_request_single_layout_receipt_required';
    end if;

    select * into v_legacy_receipt
    from public.payment_receipts legacy
    where legacy.payment_request_id = v_request.id
      and legacy.layout_id = v_layout.id
      and legacy.registered_by is not distinct from v_request.paid_by
      and legacy.created_at is not distinct from v_request.paid_at
    for update;

    if not found then
      raise exception 'paid_request_layout_receipt_provenance_mismatch';
    end if;
  end if;

  select * into v_snapshot
  from public.payable_snapshots
  where payment_request_id = v_request.id
  order by version desc
  limit 1
  for update;
  if not found or not public.payment_reconciliation_snapshot_is_receipt_matchable(v_snapshot.id) then
    raise exception 'payment_request_not_payable';
  end if;
  if v_snapshot.amount_minor <> v_operation.amount_minor then
    raise exception 'receipt_request_amount_mismatch';
  end if;
  if v_snapshot.currency <> v_operation.currency then
    raise exception 'receipt_request_currency_mismatch';
  end if;
  if v_layout_line.id is not null
     and public.payment_amount_to_minor(v_layout_line.amount, v_snapshot.currency) <>
       v_snapshot.amount_minor then
    raise exception 'layout_line_snapshot_amount_mismatch';
  end if;
  if v_legacy_receipt.id is not null
     and public.payment_amount_to_minor(v_legacy_receipt.amount, v_snapshot.currency) <>
       v_snapshot.amount_minor then
    raise exception 'layout_receipt_snapshot_amount_mismatch';
  end if;

  select
    proveedor.alias,
    proveedor.nombre_completo,
    proveedor.clabe,
    proveedor.cuenta_bancaria
    into v_provider
  from public.proveedores proveedor
  where proveedor.id = v_request.proveedor_id;
  if not found then raise exception 'payment_request_provider_not_found'; end if;

  v_provider_match := (
    v_operation.destination_account_hash is not null
    and (
      v_operation.destination_account_hash =
        public.payment_reconciliation_account_hash(v_provider.clabe)
      or v_operation.destination_account_hash =
        public.payment_reconciliation_account_hash(v_provider.cuenta_bancaria)
    )
  ) or (
    nullif(public.payment_receipt_normalize_match_text(v_operation.beneficiary_name), '') is not null
    and (
      (
        nullif(public.payment_receipt_normalize_match_text(v_provider.alias), '') is not null
        and public.payment_receipt_normalize_match_text(v_operation.beneficiary_name)
          like '%' || public.payment_receipt_normalize_match_text(v_provider.alias) || '%'
      )
      or (
        nullif(public.payment_receipt_normalize_match_text(v_provider.nombre_completo), '') is not null
        and public.payment_receipt_normalize_match_text(v_operation.beneficiary_name)
          like '%' || public.payment_receipt_normalize_match_text(v_provider.nombre_completo) || '%'
      )
    )
  );
  if not v_provider_match then
    raise exception 'receipt_request_provider_mismatch';
  end if;

  select * into v_evidence
  from public.payment_operation_evidence
  where operation_id = v_operation.id
    and status = 'shareable'
    and page_count = 1
    and single_operation_attested
  for update;
  if not found then
    raise exception 'shareable_single_page_evidence_required';
  end if;

  v_linked_at := clock_timestamp();
  begin
    insert into public.payment_request_receipt_links(
      company_id, operation_id, payment_request_id, snapshot_id, evidence_id,
      amount_minor, currency, payment_date, reference_hint, linked_by, linked_at
    ) values (
      v_operation.company_id, v_operation.id, v_request.id, v_snapshot.id,
      v_evidence.id, v_operation.amount_minor, v_operation.currency,
      v_operation.application_date, right(v_operation.bank_unique_folio, 6),
      v_actor, v_linked_at
    ) returning id into v_link_id;
  exception when unique_violation then
    raise exception 'receipt_or_request_already_linked';
  end;

  -- Do not rewrite the original paid audit trail when Layout already confirmed it.
  if v_request.status::text <> 'paid' then
    update public.payment_requests
    set status = 'paid'::public.payment_request_status,
        paid_by = v_actor,
        paid_at = v_linked_at,
        updated_at = v_linked_at
    where id = v_request.id
      and status::text = v_request.status::text;
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'payment_request_changed_during_link';
    end if;
  end if;

  if v_request.status::text = 'finance_validation' then
    update public.payment_layout_lines
    set status = 'paid',
        updated_at = v_linked_at
    where id = v_layout_line.id
      and status = 'included';
    get diagnostics v_updated = row_count;
    if v_updated <> 1 then
      raise exception 'payment_layout_line_changed_during_link';
    end if;

    update public.payment_layouts layout
    set status = case
          when not exists (
            select 1
            from public.payment_layout_lines pending
            where pending.layout_id = layout.id
              and pending.status = 'included'
          ) then 'confirmed'
          else layout.status
        end,
        updated_at = v_linked_at
    where layout.id = v_layout.id
      and layout.status in ('generated', 'uploaded')
    returning layout.status into v_layout_final_status;

    if v_layout_final_status is null then
      raise exception 'payment_layout_changed_during_link';
    end if;
  elsif v_request.status::text = 'paid' then
    v_layout_final_status := 'confirmed';
  end if;

  v_notification :=
    public.enqueue_payment_receipt_linked_notifications_internal(v_link_id);

  v_event_id := public.append_financial_outbox_event_internal(
    'payment_receipt.linked',
    'payment_request_receipt_link',
    v_link_id,
    v_operation.company_id,
    v_actor,
    jsonb_build_object(
      'amount_minor', v_operation.amount_minor,
      'currency', v_operation.currency,
      'evidence_id', v_evidence.id,
      'operation_id', v_operation.id,
      'payment_request_id', v_request.id
    )
    || case when v_layout_line.id is not null then jsonb_build_object(
      'layout_id', v_layout.id,
      'layout_line_id', v_layout_line.id,
      'layout_status', v_layout_final_status
    ) else '{}'::jsonb end
    || jsonb_build_object(
      'notification_resolution', v_notification -> 'notification_resolution'
    ),
    v_operation.id,
    null,
    'receipt-linked:' || v_payload_hash
  );

  v_result := jsonb_build_object(
    'amount_minor', v_operation.amount_minor,
    'currency', v_operation.currency,
    'evidence_id', v_evidence.id,
    'event_id', v_event_id,
    'link_id', v_link_id,
    'operation_id', v_operation.id,
    'payment_date', v_operation.application_date,
    'payment_request_id', v_request.id,
    'reference_hint', right(v_operation.bank_unique_folio, 6),
    'request_number', v_request.request_number,
    'request_status', 'paid',
    'layout_id', v_layout.id,
    'layout_line_id', v_layout_line.id,
    'layout_status', v_layout_final_status
  );
  return public.payment_reconciliation_store_command(
    v_operation.company_id,
    'payment_receipt.link',
    p_idempotency_key,
    v_payload_hash,
    v_actor,
    v_result
  );
end
$$;


ALTER FUNCTION "public"."link_payment_receipt_to_request"("p_operation_id" "uuid", "p_payment_request_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_approval_batch_director_candidates"("p_company_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.approval_batch_require_finance();

  if p_company_id is not null and not exists (
    select 1
    from public.companies company
    where company.id = p_company_id
      and coalesce(company.active, false)
  ) then
    raise exception 'company_not_found_or_inactive';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'profile_id', candidate.profile_id,
        'name', candidate.full_name,
        'email', candidate.email,
        'roles', candidate.roles,
        'profile_active', true,
        'membership_active', true,
        'assignment_id', candidate.assignment_id,
        'assigned_active', candidate.assigned_active
      )
      order by
        candidate.assigned_active desc,
        candidate.full_name,
        candidate.email
    )
    from (
      select
        profile.id as profile_id,
        profile.full_name,
        profile.email,
        array_agg(
          distinct lower(btrim(role.name))
          order by lower(btrim(role.name))
        ) as roles,
        (
          select director_assignment.id
          from public.company_directors director_assignment
          where director_assignment.company_id = p_company_id
            and director_assignment.director_profile_id = profile.id
          order by
            director_assignment.active desc,
            director_assignment.created_at desc,
            director_assignment.id desc
          limit 1
        ) as assignment_id,
        exists (
          select 1
          from public.company_directors director_assignment
          where director_assignment.company_id = p_company_id
            and director_assignment.director_profile_id = profile.id
            and director_assignment.active
        ) as assigned_active
      from public.profiles profile
      join public.user_roles user_role on user_role.profile_id = profile.id
      join public.roles role on role.id = user_role.role_id
      where profile.active
        and lower(btrim(role.name)) =
          any(public.approval_batch_direction_roles())
        and exists (
          select 1
          from public.profile_company_memberships membership
          join public.companies member_company
            on member_company.id = membership.company_id
          where membership.profile_id = profile.id
            and membership.active
            and coalesce(member_company.active, false)
            and (
              p_company_id is null
              or membership.company_id = p_company_id
            )
        )
      group by profile.id, profile.full_name, profile.email
    ) candidate
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."list_approval_batch_director_candidates"("p_company_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_approval_batch_director_candidates"("p_company_id" "uuid") IS 'Returns active Direction profiles with active company membership and reports whether each one is already in the future-batch pool.';



CREATE OR REPLACE FUNCTION "public"."list_approver_assignments"() RETURNS TABLE("id" "uuid", "company_id" "uuid", "company_name" "text", "requester_id" "uuid", "requester_name" "text", "requester_email" "text", "approver_id" "uuid", "approver_name" "text", "approver_email" "text", "approver_roles" "text"[], "active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;

  return query
  select
    aa.id,
    c.id,
    coalesce(nullif(btrim(c.legal_name), ''), c.name),
    requester.id,
    requester.full_name,
    requester.email,
    approver.id,
    approver.full_name,
    approver.email,
    coalesce(array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))) filter (
      where lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    ), array[]::text[]),
    aa.active,
    aa.created_at,
    aa.updated_at
  from public.approver_assignments aa
  join public.companies c on c.id = aa.company_id
  join public.profiles requester on requester.id = aa.requester_id
  join public.profiles approver on approver.id = aa.approver_id
  left join public.user_roles ur on ur.profile_id = approver.id
  left join public.roles r on r.id = ur.role_id
  group by aa.id, c.id, c.legal_name, c.name, requester.id, approver.id
  order by coalesce(nullif(btrim(c.legal_name), ''), c.name),
           coalesce(nullif(btrim(requester.full_name), ''), requester.email),
           aa.active desc,
           coalesce(nullif(btrim(approver.full_name), ''), approver.email);
end;
$$;


ALTER FUNCTION "public"."list_approver_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_batch_eligible_requests"("p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.approval_batch_require_finance();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', pr.id,
      'request_number', pr.request_number,
      'company_id', pr.company_id,
      'company_name', coalesce(nullif(btrim(c.legal_name), ''), c.name),
      'provider_name', coalesce(nullif(btrim(p.alias), ''), p.nombre_completo),
      'cost_center', coalesce(nullif(btrim(cc.code), '') || ' - ', '') || cc.name,
      'budget_category', coalesce(nullif(btrim(bc.code), '') || ' - ', '') || bc.name,
      'payment_method', coalesce(
        nullif(pr.payment_method, ''),
        case when pr.request_type::text in ('cash', 'check') then pr.request_type::text else 'transfer' end
      ),
      'currency', pr.currency,
      'amount', pr.amount_requested,
      'status', pr.status,
      'requested_by', pr.requested_by,
      'requester_name', requester.full_name,
      'created_at', pr.created_at,
      'eligible', coalesce((eligibility.result ->> 'eligible')::boolean, false),
      'classification', eligibility.result ->> 'classification',
      'classification_reason', eligibility.result ->> 'reason',
      'origin', eligibility.result ->> 'origin',
      'review_sequence', coalesce((eligibility.result ->> 'review_sequence')::integer, 1),
      'budget_status', eligibility.result ->> 'budget_status',
      'budget_reason', eligibility.result ->> 'budget_reason',
      'budget_available', nullif(eligibility.result ->> 'budget_available', '')::numeric,
      'budget_after', nullif(eligibility.result ->> 'budget_after', '')::numeric,
      'budget_shortfall', nullif(eligibility.result ->> 'budget_shortfall', '')::numeric,
      'missing_fields', coalesce(eligibility.result -> 'missing_fields', '[]'::jsonb),
      'previous_item_id', nullif(eligibility.result ->> 'previous_item_id', '')::uuid,
      'previous_batch_id', nullif(eligibility.result ->> 'previous_batch_id', '')::uuid,
      'previous_batch_label', eligibility.result ->> 'previous_batch_label',
      'previous_reject_reason', eligibility.result ->> 'previous_reject_reason',
      'previous_correction_note', eligibility.result ->> 'previous_correction_note',
      'previous_decided_at', nullif(eligibility.result ->> 'previous_decided_at', '')::timestamptz
    ) order by
      coalesce((eligibility.result ->> 'eligible')::boolean, false) desc,
      pr.created_at,
      pr.id)
    from public.payment_requests pr
    join public.companies c on c.id = pr.company_id
    left join public.proveedores p on p.id = pr.proveedor_id
    left join public.cost_centers cc on cc.id = pr.cost_center_id
    left join public.budget_categories bc on bc.id = pr.budget_category_id
    left join public.profiles requester on requester.id = pr.requested_by
    cross join lateral (
      select public.approval_batch_request_eligibility(pr.id, null) as result
    ) eligibility
    where pr.company_id = p_company_id
      and pr.status::text in ('submitted', 'pending_approval', 'approved', 'rejected', 'changes_requested')
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."list_batch_eligible_requests"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_company_approver_candidates"("p_company_id" "uuid", "p_requester_id" "uuid") RETURNS TABLE("profile_id" "uuid", "display_name" "text", "email" "text", "eligible_roles" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;

  return query
  select
    p.id,
    coalesce(nullif(btrim(p.full_name), ''), p.email),
    p.email,
    array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name)))
  from public.profile_company_memberships pcm
  join public.profiles p on p.id = pcm.profile_id
  join public.user_roles ur on ur.profile_id = p.id
  join public.roles r on r.id = ur.role_id
  where pcm.company_id = p_company_id
    and pcm.active
    and coalesce(p.active, true)
    and p.id <> p_requester_id
    and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    and not exists (
      select 1
      from public.approver_assignments aa
      where aa.company_id = p_company_id
        and aa.requester_id = p_requester_id
        and aa.approver_id = p.id
        and aa.active
    )
  group by p.id, p.full_name, p.email
  order by coalesce(nullif(btrim(p.full_name), ''), p.email);
end;
$$;


ALTER FUNCTION "public"."list_company_approver_candidates"("p_company_id" "uuid", "p_requester_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_company_directors"("p_company_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.approval_batch_require_finance();

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', director_assignment.id,
        'company_id', director_assignment.company_id,
        'company_name', coalesce(
          nullif(btrim(company.legal_name), ''),
          company.name
        ),
        'director_profile_id', director_assignment.director_profile_id,
        'director_name', director_profile.full_name,
        'director_email', director_profile.email,
        'director_profile_active', coalesce(director_profile.active, false),
        'director_role_valid', exists (
          select 1
          from public.user_roles user_role
          join public.roles role on role.id = user_role.role_id
          where user_role.profile_id = director_assignment.director_profile_id
            and lower(btrim(role.name)) =
              any(public.approval_batch_direction_roles())
        ),
        'director_membership_active', exists (
          select 1
          from public.profile_company_memberships membership
          where membership.profile_id = director_assignment.director_profile_id
            and membership.company_id = director_assignment.company_id
            and membership.active
        ),
        'active', director_assignment.active
      )
      order by
        coalesce(nullif(btrim(company.legal_name), ''), company.name),
        director_assignment.active desc,
        director_profile.full_name,
        director_assignment.created_at,
        director_assignment.id
    )
    from public.company_directors director_assignment
    join public.companies company
      on company.id = director_assignment.company_id
    join public.profiles director_profile
      on director_profile.id = director_assignment.director_profile_id
    where p_company_id is null
       or director_assignment.company_id = p_company_id
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."list_company_directors"("p_company_id" "uuid") OWNER TO "postgres";


