CREATE OR REPLACE FUNCTION "public"."list_payment_ingestion_batches"("p_company_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_is_sysadmin boolean;
begin
  if v_actor is null or not public.current_user_has_role(public.flux_finance_roles()) then
    raise exception 'finance_role_required';
  end if;
  if p_limit is null or p_limit not between 1 and 200 then raise exception 'invalid_limit'; end if;
  if p_status is not null and p_status not in ('awaiting_upload', 'extracting', 'review_required', 'ready', 'failed', 'cancelled') then
    raise exception 'invalid_batch_status';
  end if;
  v_is_sysadmin := public.current_user_has_role(public.flux_sysadmin_roles());
  if p_company_id is not null then perform public.payment_reconciliation_require_finance(p_company_id); end if;
  return coalesce((
    select jsonb_agg(to_jsonb(row_data) order by row_data.created_at desc)
    from (
      select batch.id, batch.company_id, company.name as company_name, batch.status,
        batch.original_file_name, batch.page_count, batch.extraction_count,
        batch.operation_count, batch.created_at, batch.updated_at
      from public.payment_ingestion_batches batch
      join public.companies company on company.id = batch.company_id
      where (p_company_id is null or batch.company_id = p_company_id)
        and (p_status is null or batch.status = p_status)
        and (v_is_sysadmin or public.has_active_company_membership(v_actor, batch.company_id))
      order by batch.created_at desc
      limit p_limit
    ) row_data
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."list_payment_ingestion_batches"("p_company_id" "uuid", "p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_payment_request_approver_options"("p_company_id" "uuid", "p_cost_center_id" "uuid", "p_amount" numeric) RETURNS TABLE("profile_id" "uuid", "display_name" "text", "email" "text", "eligible_roles" "text"[], "source" "text", "assignment_id" "uuid", "option_label" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_requester_id uuid := public.current_profile_id();
  v_has_pool boolean;
begin
  if v_requester_id is null then
    raise exception 'not_authenticated';
  end if;
  if not public.has_active_company_membership(v_requester_id, p_company_id)
     and not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'company_scope_required';
  end if;

  v_has_pool := public.payment_request_has_active_approver_pool(v_requester_id, p_company_id);

  if v_has_pool then
    return query
    select
      p.id,
      coalesce(nullif(btrim(p.full_name), ''), p.email),
      p.email,
      array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))),
      'assigned'::text,
      aa.id,
      coalesce(nullif(btrim(p.full_name), ''), p.email)
        || ' - '
        || array_to_string(array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))), ', ')
    from public.approver_assignments aa
    join public.profiles p on p.id = aa.approver_id
    join public.profile_company_memberships pcm
      on pcm.profile_id = p.id and pcm.company_id = aa.company_id and pcm.active
    join public.user_roles ur on ur.profile_id = p.id
    join public.roles r on r.id = ur.role_id
    where aa.requester_id = v_requester_id
      and aa.company_id = p_company_id
      and aa.active
      and coalesce(p.active, true)
      and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    group by aa.id, p.id, p.full_name, p.email
    order by coalesce(nullif(btrim(p.full_name), ''), p.email);
    return;
  end if;

  if p_cost_center_id is null or p_amount is null or p_amount <= 0 then
    return;
  end if;

  return query
  select
    p.id,
    coalesce(nullif(btrim(p.full_name), ''), p.email),
    p.email,
    array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))),
    'approval_rules'::text,
    null::uuid,
    coalesce(nullif(btrim(p.full_name), ''), p.email)
      || ' - '
      || array_to_string(array_agg(distinct lower(trim(r.name)) order by lower(trim(r.name))), ', ')
  from public.profile_company_memberships pcm
  join public.profiles p on p.id = pcm.profile_id
  join public.user_roles ur on ur.profile_id = p.id
  join public.roles r on r.id = ur.role_id
  where pcm.company_id = p_company_id
    and pcm.active
    and coalesce(p.active, true)
    and p.id <> v_requester_id
    and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    and public.payment_request_rule_allows(
      p.id, p_company_id, p_cost_center_id, p_amount, 'approved'
    )
  group by p.id, p.full_name, p.email
  order by coalesce(nullif(btrim(p.full_name), ''), p.email);
end;
$$;


ALTER FUNCTION "public"."list_payment_request_approver_options"("p_company_id" "uuid", "p_cost_center_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_profile_company_memberships"() RETURNS TABLE("id" "uuid", "profile_id" "uuid", "profile_name" "text", "profile_email" "text", "company_id" "uuid", "company_name" "text", "active" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;

  return query
  select pcm.id, p.id, p.full_name, p.email, c.id,
         coalesce(nullif(btrim(c.legal_name), ''), c.name), pcm.active, pcm.created_at
  from public.profile_company_memberships pcm
  join public.profiles p on p.id = pcm.profile_id
  join public.companies c on c.id = pcm.company_id
  order by coalesce(nullif(btrim(p.full_name), ''), p.email),
           coalesce(nullif(btrim(c.legal_name), ''), c.name);
end;
$$;


ALTER FUNCTION "public"."list_profile_company_memberships"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_provider_intakes"("p_company_id" "uuid" DEFAULT NULL::"uuid", "p_statuses" "text"[] DEFAULT ARRAY['received'::"text", 'in_review'::"text"], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_has_files" boolean DEFAULT NULL::boolean, "p_folio" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT NULL::"text", "p_sort_direction" "text" DEFAULT 'desc'::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor jsonb;
  v_profile_id uuid;
  v_global_access boolean;
  v_statuses text[];
  v_page integer;
  v_page_size integer;
  v_offset integer;
  v_sort_direction text;
  v_result jsonb;
begin
  v_actor := public.provider_intake_actor_context();
  v_profile_id := (v_actor ->> 'profile_id')::uuid;
  v_global_access := coalesce((v_actor ->> 'global_access')::boolean, false);
  v_page := greatest(coalesce(p_page, 1), 1);
  v_page_size := greatest(1, least(coalesce(p_page_size, 25), 100));
  v_offset := (v_page - 1) * v_page_size;
  v_sort_direction := lower(btrim(coalesce(p_sort_direction, 'desc')));

  if v_sort_direction not in ('asc', 'desc') then
    raise exception 'provider_intake_invalid_sort';
  end if;
  if p_date_from is not null and p_date_to is not null and p_date_from > p_date_to then
    raise exception 'provider_intake_invalid_date_range';
  end if;

  v_statuses := coalesce(p_statuses, array[]::text[]);
  if exists (
    select 1
    from unnest(v_statuses) status_value
    where status_value not in (
      'received', 'in_review', 'needs_correction',
      'rejected', 'converted', 'cancelled'
    )
  ) then
    raise exception 'provider_intake_invalid_status';
  end if;

  if p_company_id is not null then
    perform public.provider_intake_assert_company_access(p_company_id);
  end if;

  with accessible_companies as (
    select c.id, c.name
    from public.companies c
    where coalesce(c.active, true)
      and (
        v_global_access
        or public.has_active_company_membership(v_profile_id, c.id)
      )
  ),
  visible as (
    select
      pi.id,
      pi.public_folio,
      pi.company_id,
      c.name as company_name,
      pi.status,
      pi.provider_name,
      pi.concept,
      pi.amount_requested,
      pi.currency,
      pi.created_at,
      pi.updated_at,
      (
        select count(*)::integer
        from public.payment_intake_files pif
        where pif.payment_intake_id = pi.id
      ) as file_count
    from public.payment_intake pi
    join accessible_companies c on c.id = pi.company_id
    where (p_company_id is null or pi.company_id = p_company_id)
      and (p_date_from is null or pi.created_at >= p_date_from::timestamptz)
      and (p_date_to is null or pi.created_at < (p_date_to + 1)::timestamptz)
      and (
        nullif(btrim(coalesce(p_folio, '')), '') is null
        or pi.public_folio ilike ('%' || btrim(p_folio) || '%')
      )
      and (
        nullif(btrim(coalesce(p_provider, '')), '') is null
        or pi.provider_name ilike ('%' || btrim(p_provider) || '%')
      )
      and (
        p_has_files is null
        or p_has_files = exists (
          select 1
          from public.payment_intake_files pif
          where pif.payment_intake_id = pi.id
        )
      )
  ),
  filtered as (
    select *
    from visible
    where cardinality(v_statuses) = 0 or status = any (v_statuses)
  ),
  page_rows as (
    select
      id,
      public_folio,
      company_id,
      company_name,
      status,
      provider_name,
      concept,
      amount_requested,
      currency,
      created_at,
      updated_at,
      file_count
    from filtered
    order by
      case when v_sort_direction = 'asc' then created_at end asc,
      case when v_sort_direction = 'desc' then created_at end desc,
      id
    limit v_page_size
    offset v_offset
  )
  select jsonb_build_object(
    'items',
      coalesce((select jsonb_agg(to_jsonb(page_rows)) from page_rows), '[]'::jsonb),
    'page', v_page,
    'page_size', v_page_size,
    'total', (select count(*) from filtered),
    'summary', jsonb_build_object(
      'total', (select count(*) from visible),
      'received', (select count(*) from visible where status = 'received'),
      'in_review', (select count(*) from visible where status = 'in_review'),
      'needs_correction', (select count(*) from visible where status = 'needs_correction'),
      'rejected', (select count(*) from visible where status = 'rejected'),
      'converted', (select count(*) from visible where status = 'converted'),
      'cancelled', (select count(*) from visible where status = 'cancelled')
    ),
    'companies',
      coalesce((
        select jsonb_agg(company_row order by company_row ->> 'name')
        from (
          select jsonb_build_object(
            'id', id,
            'name', name
          ) as company_row
          from accessible_companies
        ) available_companies
      ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end
$$;


