CREATE OR REPLACE FUNCTION "public"."mark_notification_failed"("p_event_id" "uuid", "p_error_message" "text", "p_worker_id" "text" DEFAULT NULL::"text", "p_n8n_execution_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.notification_events%rowtype;
  v_attempt_number integer;
  v_new_status text;
  v_next_attempt_at timestamptz;
begin
  if not public.notification_current_user_has_role(array['admin', 'sysadmin']) then
    raise exception 'not_allowed_to_mark_notifications';
  end if;

  select *
  into v_event
  from public.notification_events
  where id = p_event_id
  for update;

  if not found then
    raise exception 'notification_event_not_found';
  end if;

  if v_event.status <> 'processing' then
    raise exception 'notification_event_not_failable:%', v_event.status;
  end if;

  v_attempt_number := v_event.attempt_count + 1;

  if v_attempt_number >= v_event.max_attempts then
    v_new_status := 'dead_letter';
    v_next_attempt_at := null;
  else
    v_new_status := 'failed';
    v_next_attempt_at := now() + (interval '5 minutes' * greatest(v_attempt_number, 1));
  end if;

  insert into public.notification_delivery_attempts (
    notification_event_id,
    attempt_number,
    status,
    error_message,
    n8n_execution_id,
    worker_id
  )
  values (
    p_event_id,
    v_attempt_number,
    v_new_status,
    left(coalesce(p_error_message, 'notification_failed'), 1000),
    p_n8n_execution_id,
    coalesce(p_worker_id, v_event.locked_by)
  );

  update public.notification_events
  set
    status = v_new_status,
    attempt_count = v_attempt_number,
    last_error = left(coalesce(p_error_message, 'notification_failed'), 1000),
    last_attempt_at = now(),
    next_attempt_at = v_next_attempt_at,
    locked_at = null,
    locked_by = null
  where id = p_event_id;

  return jsonb_build_object(
    'event_id', p_event_id,
    'status', v_new_status,
    'attempt_number', v_attempt_number,
    'will_retry', v_new_status = 'failed'
  );
end;
$$;


ALTER FUNCTION "public"."mark_notification_failed"("p_event_id" "uuid", "p_error_message" "text", "p_worker_id" "text", "p_n8n_execution_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_notification_failed_for_dispatcher"("p_event_id" "uuid", "p_error_message" "text", "p_worker_id" "text", "p_resend_email_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.notification_events%rowtype;
  v_attempt_number integer;
  v_new_status text;
  v_next_attempt_at timestamptz;
  v_worker_id text := left(coalesce(nullif(trim(p_worker_id), ''), 'edge-notification-dispatcher'), 120);
  v_error_message text := left(coalesce(nullif(trim(p_error_message), ''), 'notification_dispatch_failed'), 1000);
  v_resend_email_id text := left(nullif(trim(coalesce(p_resend_email_id, '')), ''), 255);
begin
  select *
    into v_event
  from public.notification_events
  where id = p_event_id
  for update;

  if not found then
    raise exception 'notification_event_not_found';
  end if;

  if v_event.status <> 'processing' then
    raise exception 'notification_event_not_failable:%', v_event.status;
  end if;

  if nullif(trim(coalesce(v_event.locked_by, '')), '') is not null
     and v_event.locked_by <> v_worker_id then
    raise exception 'notification_event_locked_by_different_worker';
  end if;

  v_attempt_number := v_event.attempt_count + 1;

  if v_attempt_number >= v_event.max_attempts then
    v_new_status := 'dead_letter';
    v_next_attempt_at := null;
  else
    v_new_status := 'failed';
    v_next_attempt_at := now() + (interval '5 minutes' * greatest(v_attempt_number, 1));
  end if;

  insert into public.notification_delivery_attempts (
    notification_event_id,
    attempt_number,
    status,
    provider_message_id,
    error_message,
    worker_id
  )
  values (
    p_event_id,
    v_attempt_number,
    v_new_status,
    v_resend_email_id,
    v_error_message,
    v_worker_id
  );

  update public.notification_events
     set status = v_new_status,
         attempt_count = v_attempt_number,
         last_error = v_error_message,
         last_attempt_at = now(),
         next_attempt_at = v_next_attempt_at,
         locked_at = null,
         locked_by = null,
         updated_at = now()
   where id = p_event_id;

  return jsonb_build_object(
    'event_id', p_event_id,
    'status', v_new_status,
    'attempt_number', v_attempt_number,
    'will_retry', v_new_status = 'failed',
    'resend_email_id', v_resend_email_id
  );
end;
$$;


ALTER FUNCTION "public"."mark_notification_failed_for_dispatcher"("p_event_id" "uuid", "p_error_message" "text", "p_worker_id" "text", "p_resend_email_id" "text") OWNER TO "postgres";


