CREATE OR REPLACE FUNCTION "public"."mark_payment_layout_uploaded"("p_layout_id" "uuid", "p_actor_profile_id" "uuid", "p_comments" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_layout public.payment_layouts%rowtype;
  v_previous_status text;
begin
  select *
  into v_layout
  from public.payment_layouts
  where id = p_layout_id
  for update;

  if not found then
    raise exception 'layout_not_found';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_actor_profile_id
      and coalesce(active, true) = true
  ) then
    raise exception 'profile_not_found';
  end if;

  v_previous_status := v_layout.status;

  if v_layout.status = 'draft' then
    raise exception 'layout_must_be_generated_first';
  end if;

  if v_layout.status = 'uploaded' then
    return jsonb_build_object(
      'layout_id', p_layout_id,
      'previous_status', v_previous_status,
      'new_status', 'uploaded',
      'message', 'layout_already_uploaded'
    );
  end if;

  if v_layout.status = 'confirmed' then
    raise exception 'layout_already_confirmed';
  end if;

  if v_layout.status = 'cancelled' then
    raise exception 'layout_cancelled';
  end if;

  if v_layout.status <> 'generated' then
    raise exception 'invalid_layout_status_for_upload';
  end if;

  update public.payment_layouts
  set
    status = 'uploaded',
    updated_at = now()
  where id = p_layout_id;

  return jsonb_build_object(
    'layout_id', p_layout_id,
    'previous_status', v_previous_status,
    'new_status', 'uploaded',
    'message', 'layout_marked_as_uploaded'
  );
end;
$$;


ALTER FUNCTION "public"."mark_payment_layout_uploaded"("p_layout_id" "uuid", "p_actor_profile_id" "uuid", "p_comments" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_payment_request_material_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
      begin
        if tg_op = 'INSERT' then
          new.approval_material_updated_at := clock_timestamp();
          return new;
        end if;

        if row(
          old.company_id,
          old.requested_by,
          old.proveedor_id,
          old.provider_id,
          old.cost_center_id,
          old.budget_category_id,
          old.budget_month,
          old.amount_requested,
          old.currency,
          old.exchange_rate,
          old.request_type,
          old.payment_method,
          old.is_extraordinary_adjustment
        ) is distinct from row(
          new.company_id,
          new.requested_by,
          new.proveedor_id,
          new.provider_id,
          new.cost_center_id,
          new.budget_category_id,
          new.budget_month,
          new.amount_requested,
          new.currency,
          new.exchange_rate,
          new.request_type,
          new.payment_method,
          new.is_extraordinary_adjustment
        ) then
          new.approval_material_updated_at := clock_timestamp();
        else
          new.approval_material_updated_at :=
            old.approval_material_updated_at;
        end if;

        return new;
      end
      $$;


ALTER FUNCTION "public"."mark_payment_request_material_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_payment_request_material_change"() IS 'Advances approval materiality for economic/request identity changes while preserving Direction approval for Layout execution data, including payment concept.';



CREATE OR REPLACE FUNCTION "public"."mark_provider_intake_upload_issue_internal"("p_payment_intake_id" "uuid", "p_issue_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_previous_status text;
  v_issue_code text;
begin
  v_issue_code := lower(btrim(coalesce(p_issue_code, '')));
  if v_issue_code not in (
    'storage_upload_failed',
    'storage_cleanup_failed',
    'file_metadata_failed',
    'storage_unavailable'
  ) then
    raise exception 'provider_intake_invalid_issue_code';
  end if;

  select pi.status
    into v_previous_status
  from public.payment_intake pi
  where pi.id = p_payment_intake_id
  for update;

  if not found or v_previous_status not in ('received', 'needs_correction') then
    raise exception 'provider_intake_invalid_issue_state';
  end if;

  if v_previous_status <> 'needs_correction' then
    update public.payment_intake
       set status = 'needs_correction',
           updated_at = now()
     where id = p_payment_intake_id;
  end if;

  if not exists (
    select 1
    from public.payment_intake_events pie
    where pie.payment_intake_id = p_payment_intake_id
      and pie.event_type = 'status_changed'
      and pie.metadata ->> 'issue_code' = v_issue_code
  ) then
    insert into public.payment_intake_events (
      payment_intake_id,
      event_type,
      actor_type,
      from_status,
      to_status,
      metadata
    ) values (
      p_payment_intake_id,
      'status_changed',
      'system',
      v_previous_status,
      'needs_correction',
      jsonb_build_object('issue_code', v_issue_code)
    );
  end if;

  return jsonb_build_object(
    'payment_intake_id', p_payment_intake_id,
    'status', 'needs_correction'
  );
end
$$;


ALTER FUNCTION "public"."mark_provider_intake_upload_issue_internal"("p_payment_intake_id" "uuid", "p_issue_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_provider_intake_upload_issue_internal"("p_payment_intake_id" "uuid", "p_issue_code" "text") IS 'Service-only transition to needs_correction after a sanitized upload or metadata issue.';



CREATE OR REPLACE FUNCTION "public"."mark_provider_payment_material_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_changed_fields text[];
  v_completed_fields text[];
  v_missing_before text[];
  v_missing_after text[];
  v_now timestamptz := clock_timestamp();
begin
  v_changed_fields := array_remove(array[
    case when old.destination_type is distinct from new.destination_type then 'destination_type' end,
    case when old.clabe is distinct from new.clabe then 'clabe' end,
    case when old.cuenta_bancaria is distinct from new.cuenta_bancaria then 'cuenta_bancaria' end,
    case when old.convenio_number is distinct from new.convenio_number then 'convenio_number' end,
    case when old.beneficiary_name is distinct from new.beneficiary_name then 'beneficiary_name' end,
    case when old.banco is distinct from new.banco then 'banco' end
  ]::text[], null);

  if cardinality(v_changed_fields) = 0 then
    return new;
  end if;

  v_actor := public.approval_batch_require_finance();

  if current_setting('flux.provider_payment_execution_rpc', true)
       is distinct from new.id::text then
    raise exception 'provider_payment_execution_rpc_required';
  end if;

  v_missing_before := public.provider_payment_execution_missing_fields(old);
  v_missing_after := public.provider_payment_execution_missing_fields(new);

  if 'destination_type_invalid' = any(v_missing_after)
     or 'clabe_invalid' = any(v_missing_after)
     or 'cuenta_bancaria_invalid' = any(v_missing_after)
     or 'convenio_number_invalid' = any(v_missing_after)
     or 'beneficiary_name_invalid' = any(v_missing_after)
     or 'banco_invalid' = any(v_missing_after) then
    raise exception 'provider_payment_execution_data_invalid';
  end if;

  select coalesce(
    array_agg(completed_field.field_name order by completed_field.field_name),
    array[]::text[]
  )
    into v_completed_fields
  from unnest(v_missing_before) as completed_field(field_name)
  where not (completed_field.field_name = any(v_missing_after));

  insert into public.activity_log(
    entity_type,
    entity_id,
    action,
    old_values,
    new_values,
    performed_by,
    performed_at,
    notes
  ) values (
    'proveedor',
    new.id,
    'payment_execution_data_updated',
    jsonb_build_object(
      'layout_data_complete', cardinality(v_missing_before) = 0,
      'missing_fields', to_jsonb(v_missing_before)
    ),
    jsonb_build_object(
      'changed_fields', to_jsonb(v_changed_fields),
      'completed_fields', to_jsonb(v_completed_fields),
      'layout_data_complete', cardinality(v_missing_after) = 0,
      'missing_fields', to_jsonb(v_missing_after)
    ),
    v_actor,
    v_now,
    'Provider payment-execution audit; banking values intentionally omitted.'
  );

  return new;
end
$$;


ALTER FUNCTION "public"."mark_provider_payment_material_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_provider_payment_material_change"() IS 'Validates and audits provider execution data without advancing payment-request approval materiality.';



CREATE OR REPLACE FUNCTION "public"."materialize_closed_batch_payable_snapshots"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_item record;
begin
  if new.status <> 'closed' or old.status = 'closed' then
    return new;
  end if;
  if new.closed_by is null or new.closed_at is null then
    raise exception 'closed_batch_actor_required';
  end if;
  for v_item in
    select item.id, item.payment_request_id, item.decided_by, item.decided_at
    from public.approval_batch_items item
    where item.batch_id = new.id
      and item.removed_at is null
      and item.director_status = 'approved'
      and item.finance_release_status = 'released'
    order by item.payment_request_id, item.id
  loop
    perform public.create_payable_snapshot_internal(
      v_item.payment_request_id,
      'approval_batch_item',
      v_item.id,
      'closed',
      v_item.decided_by,
      v_item.decided_at,
      new.closed_by,
      'Authorized by closed approval batch ' || new.id::text
    );
  end loop;
  return new;
end
$$;


ALTER FUNCTION "public"."materialize_closed_batch_payable_snapshots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_extraordinary_payable_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status <> 'active' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.status = 'active' then
    return new;
  end if;
  perform public.create_payable_snapshot_internal(
    new.payment_request_id,
    'extraordinary_authorization',
    new.id,
    'active',
    new.authorized_by,
    new.authorized_at,
    new.authorized_by,
    new.category || ': ' || new.reason
  );
  return new;
end
$$;


