CREATE OR REPLACE FUNCTION "public"."normalize_payment_intake_foundation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.provider_name := regexp_replace(btrim(new.provider_name), '[[:space:]]+', ' ', 'g');
  new.provider_rfc := nullif(
    upper(regexp_replace(btrim(coalesce(new.provider_rfc, '')), '[[:space:]-]+', '', 'g')),
    ''
  );
  new.provider_email := lower(btrim(new.provider_email));
  new.provider_phone := nullif(regexp_replace(btrim(coalesce(new.provider_phone, '')), '[[:space:]]+', ' ', 'g'), '');
  new.concept := regexp_replace(btrim(new.concept), '[[:space:]]+', ' ', 'g');
  new.description := nullif(btrim(coalesce(new.description, '')), '');
  new.currency := upper(btrim(new.currency));
  new.invoice_folio := nullif(btrim(coalesce(new.invoice_folio, '')), '');
  new.invoice_uuid := nullif(upper(btrim(coalesce(new.invoice_uuid, ''))), '');
  new.bank_name := nullif(regexp_replace(btrim(coalesce(new.bank_name, '')), '[[:space:]]+', ' ', 'g'), '');
  new.bank_account := nullif(regexp_replace(btrim(coalesce(new.bank_account, '')), '[[:space:]-]+', '', 'g'), '');
  new.bank_clabe := nullif(regexp_replace(btrim(coalesce(new.bank_clabe, '')), '[[:space:]-]+', '', 'g'), '');
  new.beneficiary_name := nullif(regexp_replace(btrim(coalesce(new.beneficiary_name, '')), '[[:space:]]+', ' ', 'g'), '');
  new.submission_fingerprint := lower(btrim(new.submission_fingerprint));
  new.idempotency_key := nullif(btrim(coalesce(new.idempotency_key, '')), '');
  new.client_ip_hash := nullif(lower(btrim(coalesce(new.client_ip_hash, ''))), '');
  new.user_agent_hash := nullif(lower(btrim(coalesce(new.user_agent_hash, ''))), '');
  new.captcha_provider := nullif(lower(btrim(coalesce(new.captcha_provider, ''))), '');
  new.rejection_reason := nullif(btrim(coalesce(new.rejection_reason, '')), '');
  return new;
end
$$;


ALTER FUNCTION "public"."normalize_payment_intake_foundation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_proveedores_canonical"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_alias_base text;
  v_alias_candidate text;
  v_alias_suffix text;
  v_persona_tipo text;
begin
  new.id := coalesce(new.id, gen_random_uuid());

  new.rfc := nullif(upper(btrim(coalesce(new.rfc, ''))), '');
  if new.rfc is not null
     and new.rfc !~ '^[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}$' then
    raise exception 'rfc_invalido: use un RFC mexicano de 12 o 13 caracteres sin espacios ni guiones';
  end if;

  if nullif(btrim(coalesce(new.clabe, '')), '') is null then
    new.clabe := null;
  else
    if new.clabe !~ '^[0-9[:space:]-]+$' then
      raise exception 'clabe_invalida: solo se permiten digitos, espacios y guiones';
    end if;
    new.clabe := regexp_replace(new.clabe, '[[:space:]-]', '', 'g');
    if char_length(new.clabe) <> 18 then
      raise exception 'clabe_invalida: se requieren exactamente 18 digitos';
    end if;
  end if;

  new.banco := nullif(regexp_replace(btrim(coalesce(new.banco, '')), '[[:space:]]+', ' ', 'g'), '');
  new.cuenta_bancaria := nullif(
    regexp_replace(btrim(coalesce(new.cuenta_bancaria, '')), '[[:space:]]+', ' ', 'g'),
    ''
  );

  v_persona_tipo := lower(
    regexp_replace(btrim(coalesce(new.persona_tipo, '')), '[[:space:]]+', ' ', 'g')
  );
  new.persona_tipo := case
    when v_persona_tipo = '' then null
    when v_persona_tipo in ('fisica', 'física', 'persona fisica', 'persona física', 'pf') then 'fisica'
    when v_persona_tipo in ('moral', 'persona moral', 'pm') then 'moral'
    else null
  end;
  if v_persona_tipo <> '' and new.persona_tipo is null then
    raise exception 'persona_tipo_invalido: use fisica, moral o NULL';
  end if;

  if nullif(btrim(coalesce(new.alias, '')), '') is null then
    v_alias_base := coalesce(
      nullif(regexp_replace(btrim(coalesce(new.nombre_completo, '')), '[[:space:]]+', ' ', 'g'), ''),
      nullif(regexp_replace(btrim(coalesce(new.beneficiary_name, '')), '[[:space:]]+', ' ', 'g'), ''),
      'PROVEEDOR'
    );
    v_alias_candidate := left(v_alias_base, 120);

    if exists (
      select 1
      from public.proveedores p
      where lower(regexp_replace(btrim(p.alias), '[[:space:]]+', ' ', 'g')) =
            lower(regexp_replace(btrim(v_alias_candidate), '[[:space:]]+', ' ', 'g'))
        and p.id is distinct from new.id
    ) then
      v_alias_suffix := '-' || left(replace(new.id::text, '-', ''), 8);
      v_alias_candidate := left(v_alias_base, 120 - char_length(v_alias_suffix)) || v_alias_suffix;
    end if;

    new.alias := v_alias_candidate;
  else
    new.alias := regexp_replace(btrim(new.alias), '[[:space:]]+', ' ', 'g');
    if exists (
      select 1
      from public.proveedores p
      where lower(regexp_replace(btrim(p.alias), '[[:space:]]+', ' ', 'g')) =
            lower(regexp_replace(btrim(new.alias), '[[:space:]]+', ' ', 'g'))
        and p.id is distinct from new.id
    ) then
      raise exception 'alias_duplicado: el alias % ya pertenece a otro proveedor', new.alias
        using errcode = '23505';
    end if;
  end if;

  return new;
end
$_$;


ALTER FUNCTION "public"."normalize_proveedores_canonical"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_proveedores_canonical"() IS 'Normaliza RFC, CLABE, banco, cuenta, alias faltante y persona_tipo antes de escribir public.proveedores.';



