      from unnest(p_field_codes) code
      where code <> all (array[
        'provider_name',
        'provider_rfc',
        'provider_email',
        'provider_phone',
        'concept',
        'description',
        'amount_requested',
        'currency',
        'requested_payment_date',
        'invoice_folio',
        'invoice_uuid',
        'invoice_date',
        'invoice_pdf',
        'invoice_xml',
        'bank_document',
        'beneficiary_name'
      ]::text[])
    )
    and cardinality(p_field_codes) = (
      select count(distinct code)::integer
      from unnest(p_field_codes) code
    )
$$;


