CREATE OR REPLACE FUNCTION "public"."payment_reconciliation_snapshot_is_payable"("p_snapshot_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_snapshot public.payable_snapshots%rowtype;
  v_readiness jsonb;
  v_authorization_source text;
begin
  select * into v_snapshot from public.payable_snapshots where id = p_snapshot_id;
  if not found then return false; end if;
  v_readiness := public.get_payment_request_execution_readiness(v_snapshot.payment_request_id);
  if not coalesce((v_readiness->>'can_execute')::boolean, false) then return false; end if;
  v_authorization_source := v_readiness->>'authorization_source';
  return case v_snapshot.source_type
    when 'approval_batch_item' then v_authorization_source = 'closed_batch'
    when 'extraordinary_authorization' then v_authorization_source = 'extraordinary'
    when 'legacy_backfill' then v_authorization_source = 'legacy_approved'
    else false
  end;
end
$$;


ALTER FUNCTION "public"."payment_reconciliation_snapshot_is_payable"("p_snapshot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_reconciliation_snapshot_is_receipt_matchable"("p_snapshot_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_snapshot public.payable_snapshots%rowtype;
  v_request public.payment_requests%rowtype;
  v_currency text;
  v_amount_minor bigint;
  v_matching_layout_lines integer := 0;
  v_total_layout_lines integer := 0;
  v_matching_legacy_receipts integer := 0;
  v_total_legacy_receipts integer := 0;
  v_paid_layout_id uuid;
  v_source_current boolean := false;
begin
  select * into v_snapshot
  from public.payable_snapshots
  where id = p_snapshot_id;
  if not found then return false; end if;

  select * into v_request
  from public.payment_requests
  where id = v_snapshot.payment_request_id;
  if not found then return false; end if;

  -- Preserve the original contract for requests not yet materialized in a layout.
  if v_request.status::text = 'approved' then
    return public.payment_reconciliation_snapshot_is_payable(v_snapshot.id);
  end if;

  if v_request.status::text not in ('finance_validation', 'paid') then
    return false;
  end if;

  if v_snapshot.company_id <> v_request.company_id
     or v_snapshot.source_approval_material_updated_at is distinct from
       v_request.approval_material_updated_at
     or v_snapshot.authorized_at < v_request.approval_material_updated_at then
    return false;
  end if;

  v_currency := public.payment_reconciliation_normalize_currency(v_request.currency);
  v_amount_minor := public.payment_amount_to_minor(v_request.amount_requested, v_currency);
  if v_snapshot.currency is distinct from v_currency
     or v_snapshot.amount_minor is distinct from v_amount_minor then
    return false;
  end if;

  if v_request.status::text = 'finance_validation' then
    select count(*) into v_matching_layout_lines
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'included'
      and layout.status in ('generated', 'uploaded')
      and public.payment_amount_to_minor(line.amount, v_currency) = v_snapshot.amount_minor;

    if v_matching_layout_lines <> 1 then
      return false;
    end if;
  else
    -- A paid request is eligible only when payment came from exactly one
    -- confirmed layout line and has not yet received a bank evidence link.
    if v_request.paid_by is null or v_request.paid_at is null then
      return false;
    end if;

    select count(*) into v_total_layout_lines
    from public.payment_layout_lines line
    where line.payment_request_id = v_request.id;

    select count(*) into v_matching_layout_lines
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'paid'
      and layout.status = 'confirmed'
      and public.payment_amount_to_minor(line.amount, v_currency) = v_snapshot.amount_minor;

    if v_total_layout_lines <> 1 or v_matching_layout_lines <> 1 then
      return false;
    end if;

    select line.layout_id into v_paid_layout_id
    from public.payment_layout_lines line
    join public.payment_layouts layout on layout.id = line.layout_id
    where line.payment_request_id = v_request.id
      and line.company_id = v_request.company_id
      and line.proveedor_id = v_request.proveedor_id
      and line.status = 'paid'
      and layout.status = 'confirmed'
      and public.payment_amount_to_minor(line.amount, v_currency) = v_snapshot.amount_minor;

    select count(*) into v_total_legacy_receipts
    from public.payment_receipts legacy
    where legacy.payment_request_id = v_request.id;

    select count(*) into v_matching_legacy_receipts
    from public.payment_receipts legacy
    where legacy.payment_request_id = v_request.id
      and legacy.layout_id = v_paid_layout_id
      and public.payment_amount_to_minor(legacy.amount, v_currency) = v_snapshot.amount_minor
      and legacy.registered_by is not distinct from v_request.paid_by
      and legacy.created_at is not distinct from v_request.paid_at;

    if v_total_legacy_receipts <> 1 or v_matching_legacy_receipts <> 1 then
      return false;
    end if;

    if exists (
      select 1
      from public.payment_request_receipt_links link
      where link.payment_request_id = v_request.id
    ) then
      return false;
    end if;
  end if;

  if v_snapshot.source_type = 'approval_batch_item' then
    select exists (
      select 1
      from public.approval_batch_items item
      join public.approval_batches batch on batch.id = item.batch_id
      where item.id = v_snapshot.source_id
        and item.payment_request_id = v_request.id
        and item.removed_at is null
        and item.director_status = 'approved'
        and item.finance_release_status = 'released'
        and item.decided_by = v_snapshot.authorized_by
        and item.decided_at is not distinct from v_snapshot.authorized_at
        and batch.status = 'closed'
        and batch.closed_at is not null
        and v_snapshot.source_status = 'closed'
        and public.approval_batch_request_has_current_direction_approval(v_request.id)
    ) into v_source_current;
  elsif v_snapshot.source_type = 'extraordinary_authorization' then
    select exists (
      select 1
      from public.payment_request_extraordinary_authorizations extra_auth
      where extra_auth.id = v_snapshot.source_id
        and extra_auth.payment_request_id = v_request.id
        and extra_auth.status = 'active'
        and extra_auth.authorized_by = v_snapshot.authorized_by
        and extra_auth.authorized_at is not distinct from v_snapshot.authorized_at
        and v_snapshot.source_status = 'active'
    ) into v_source_current;
  else
    v_source_current := false;
  end if;

  return coalesce(v_source_current, false);
end
$$;


ALTER FUNCTION "public"."payment_reconciliation_snapshot_is_receipt_matchable"("p_snapshot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_reconciliation_storage_path_allowed"("p_storage_path" "text", "p_for_upload" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.payment_documents document
    join public.payment_ingestion_batches batch on batch.id = document.batch_id
    where document.storage_bucket = 'payment-batch-documents'
      and document.storage_path = p_storage_path
      and batch.company_id = document.company_id
      and public.current_profile_id() is not null
      and public.current_user_has_role(public.flux_finance_roles())
      and (
        public.current_user_has_role(public.flux_sysadmin_roles())
        or public.has_active_company_membership(
          public.current_profile_id(),
          document.company_id
        )
      )
      and (
        not p_for_upload
        or (
          batch.status = 'awaiting_upload'
          and document.uploaded_at is null
        )
      )
  );
$$;


