SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."payment_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_id" "uuid",
    "provider_bank_account_id" "uuid",
    "celebration_event_id" "uuid",
    "production_event_id" "uuid",
    "cost_center_id" "uuid",
    "request_type" "public"."payment_request_type" DEFAULT 'provider_payment'::"public"."payment_request_type" NOT NULL,
    "requested_by" "uuid",
    "approved_by" "uuid",
    "validated_by" "uuid",
    "paid_by" "uuid",
    "amount_requested" numeric(14,2) NOT NULL,
    "currency" "text" DEFAULT 'MXN'::"text" NOT NULL,
    "exchange_rate" numeric(14,6),
    "requires_invoice" boolean DEFAULT false NOT NULL,
    "invoice_received" boolean DEFAULT false NOT NULL,
    "company_bank_account_id" "uuid",
    "status" "public"."payment_request_status" DEFAULT 'draft'::"public"."payment_request_status" NOT NULL,
    "due_date" "date",
    "scheduled_payment_date" "date",
    "paid_at" timestamp with time zone,
    "concept" "text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "company_id" "uuid",
    "proveedor_id" "uuid",
    "budget_category_id" "uuid",
    "budget_month" "date",
    "budget_decision" "text" DEFAULT 'not_checked'::"text" NOT NULL,
    "budget_block_reason" "text",
    "budget_available_before" numeric(14,2),
    "budget_available_after" numeric(14,2),
    "budget_shortfall" numeric(14,2),
    "budget_checked_at" timestamp with time zone,
    "is_extraordinary_adjustment" boolean DEFAULT false NOT NULL,
    "request_number" "text",
    "description" "text",
    "submitted_at" timestamp with time zone,
    "budget_result" "jsonb",
    "exception_status" "text",
    "exception_action" "text",
    "exception_reason" "text",
    "exception_approved_by" "uuid",
    "exception_approved_at" timestamp with time zone,
    "requires_budget_adjustment" boolean DEFAULT false NOT NULL,
    "operational_comments" "text",
    "payment_reference" "text",
    "payment_concept" "text",
    "scheduled_by" "uuid",
    "scheduled_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "invoice_storage_path" "text",
    "payment_method" "text",
    "approver_id" "uuid",
    "approver_assignment_id" "uuid",
    "approver_selection_source" "text",
    "approval_material_updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "extraordinary_state" "text" DEFAULT 'normal'::"text" NOT NULL,
    "extraordinary_requested_by" "uuid",
    "extraordinary_requested_at" timestamp with time zone,
    "extraordinary_intent_cancelled_by" "uuid",
    "extraordinary_intent_cancelled_at" timestamp with time zone,
    CONSTRAINT "payment_requests_amount_requested_check" CHECK (("amount_requested" > (0)::numeric)),
    CONSTRAINT "payment_requests_approver_selection_source_check" CHECK ((("approver_selection_source" IS NULL) OR ("approver_selection_source" = ANY (ARRAY['assigned'::"text", 'approval_rules'::"text"])))),
    CONSTRAINT "payment_requests_budget_decision_chk" CHECK (("budget_decision" = ANY (ARRAY['not_checked'::"text", 'aprobable'::"text", 'bloqueado'::"text"]))),
    CONSTRAINT "payment_requests_budget_month_first_day_chk" CHECK ((("budget_month" IS NULL) OR (("date_trunc"('month'::"text", ("budget_month")::timestamp with time zone))::"date" = "budget_month"))),
    CONSTRAINT "payment_requests_check" CHECK ((("celebration_event_id" IS NOT NULL) OR ("production_event_id" IS NOT NULL) OR ("cost_center_id" IS NOT NULL))),
    CONSTRAINT "payment_requests_exception_status_check" CHECK ((("exception_status" IS NULL) OR ("exception_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'changes_requested'::"text"])))),
    CONSTRAINT "payment_requests_extraordinary_state_check" CHECK (("extraordinary_state" = ANY (ARRAY['normal'::"text", 'extraordinary_requested'::"text", 'extraordinary_draft'::"text", 'extraordinary_active'::"text", 'consumed_pending_ratification'::"text", 'ratified'::"text", 'disputed'::"text", 'revoked'::"text", 'expired'::"text", 'materially_invalidated'::"text"]))),
    CONSTRAINT "payment_requests_payment_method_check" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['transfer'::"text", 'cash'::"text", 'check'::"text", 'other'::"text"]))))
);


ALTER TABLE "public"."payment_requests" OWNER TO "postgres";


COMMENT ON COLUMN "public"."payment_requests"."payment_method" IS 'Fase 2: metodo operativo de pago separado del tipo de solicitud. Valores: transfer, cash, check, other.';



COMMENT ON COLUMN "public"."payment_requests"."approval_material_updated_at" IS 'Ultimo cambio material que exige aprobaciones posteriores de Finanzas y Direccion.';



CREATE OR REPLACE FUNCTION "public"."payment_request_layout_missing_fields"("p_request" "public"."payment_requests") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_company public.companies%rowtype;
  v_company_found boolean := false;
  v_company_account public.company_bank_accounts%rowtype;
  v_company_account_found boolean := false;
  v_provider public.proveedores%rowtype;
  v_provider_found boolean := false;
  v_source_normalized text;
  v_payment_concept text := coalesce(
    nullif(btrim(p_request.payment_concept), ''),
    nullif(btrim(p_request.concept), ''),
    nullif(btrim(p_request.description), '')
  );
  v_missing text[];
begin
  if p_request.company_id is not null then
    select *
      into v_company
    from public.companies company
    where company.id = p_request.company_id;
    v_company_found := found;
  end if;

  if p_request.company_bank_account_id is not null then
    select *
      into v_company_account
    from public.company_bank_accounts company_account
    where company_account.id = p_request.company_bank_account_id;
    v_company_account_found := found;
  end if;

  if p_request.proveedor_id is not null then
    select *
      into v_provider
    from public.proveedores provider
    where provider.id = p_request.proveedor_id;
    v_provider_found := found;
  end if;

  v_source_normalized := regexp_replace(
    coalesce(v_company_account.account_number, ''),
    '[[:space:]-]',
    '',
    'g'
  );

  v_missing := array_remove(array[
    case when p_request.scheduled_payment_date is null then 'scheduled_payment_date' end,
    case when p_request.company_id is null then 'company_id' end,
    case when p_request.company_id is not null and not v_company_found then 'company_not_found' end,
    case
      when v_company_found and not coalesce(v_company.active, false)
        then 'company_inactive'
    end,
    case
      when v_company_found
        and coalesce(
          nullif(btrim(v_company.legal_name), ''),
          nullif(btrim(v_company.name), '')
        ) is null
        then 'company_name'
    end,
    case when p_request.company_bank_account_id is null then 'company_bank_account_id' end,
    case
      when p_request.company_bank_account_id is not null
        and not v_company_account_found
        then 'company_bank_account_id_not_found'
    end,
    case
      when v_company_account_found
        and v_company_account.company_id is distinct from p_request.company_id
        then 'company_bank_account_company_mismatch'
    end,
    case
      when v_company_account_found
        and not coalesce(v_company_account.active, false)
        then 'company_bank_account_inactive'
    end,
    case
      when v_company_account_found
        and nullif(btrim(v_company_account.account_number), '') is null
        then 'source_account_number'
    end,
    case
      when v_company_account_found
        and nullif(btrim(v_company_account.account_number), '') is not null
        and v_source_normalized !~ '^[0-9]{1,18}$'
        then 'source_account_number_invalid'
    end,
    case when p_request.proveedor_id is null then 'proveedor_id' end,
    case
      when p_request.proveedor_id is not null and not v_provider_found
        then 'proveedor_not_found'
    end,
    case
      when v_provider_found and not coalesce(v_provider.activo, false)
        then 'proveedor_inactive'
    end,
    case
      when nullif(btrim(p_request.payment_reference), '') is null
        then 'payment_reference'
    end,
    case
      when nullif(btrim(p_request.payment_reference), '') is not null
        and btrim(p_request.payment_reference) !~ '^[0-9]{1,5}$'
        then 'payment_reference_invalid'
    end,
    case
      when v_payment_concept is null
        then 'payment_concept'
    end,
    case
      when v_payment_concept is not null
        and (
          char_length(v_payment_concept) > 120
          or v_payment_concept ~ '[[:cntrl:]]'
        )
        then 'payment_concept_invalid'
    end,
    case
      when coalesce(nullif(upper(btrim(p_request.currency)), ''), 'MXN') <> 'MXN'
        then 'unsupported_layout_currency'
    end,
    case when coalesce(p_request.amount_requested, 0) <= 0 then 'invalid_amount' end
  ]::text[], null);

  if v_provider_found then
    v_missing := v_missing
      || public.provider_payment_execution_missing_fields(v_provider);
  end if;

  select coalesce(
    array_agg(distinct missing_field.field_name order by missing_field.field_name),
    array[]::text[]
  )
    into v_missing
  from unnest(v_missing) as missing_field(field_name);

  return v_missing;
end
$_$;


ALTER FUNCTION "public"."payment_request_layout_missing_fields"("p_request" "public"."payment_requests") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_request_rule_allows"("p_profile_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_amount" numeric, "p_action" "text" DEFAULT 'approved'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.is_payment_request_approver_for_company(p_profile_id, p_company_id)
    and exists (
      select 1
      from public.approval_rules ar
      join public.user_roles ur
        on ur.role_id = ar.role_id
       and ur.profile_id = p_profile_id
      join public.roles rule_role on rule_role.id = ar.role_id
      where ar.active
        and lower(trim(rule_role.name)) = any (public.payment_request_approver_role_names())
        and (ar.company_id is null or ar.company_id = p_company_id)
        and (ar.cost_center_id is null or ar.cost_center_id = p_cost_center_id)
        and coalesce(p_amount, 0) >= ar.amount_min
        and (ar.amount_max is null or coalesce(p_amount, 0) <= ar.amount_max)
        and case p_action
          when 'approved' then ar.can_approve
          when 'exception_approved' then ar.can_approve and ar.can_approve_exception
          when 'rejected' then ar.can_reject
          when 'exception_rejected' then ar.can_reject
          when 'changes_requested' then ar.can_request_changes
          when 'amount_change_requested' then ar.can_request_changes
          when 'category_change_requested' then ar.can_request_changes
          when 'budget_adjustment_requested' then ar.can_request_budget_adjustment
          else false
        end
    );
$$;


ALTER FUNCTION "public"."payment_request_rule_allows"("p_profile_id" "uuid", "p_company_id" "uuid", "p_cost_center_id" "uuid", "p_amount" numeric, "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_payment_operation_evidence"("p_operation_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_operation public.bank_payment_operations%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_source record;
  v_existing public.payment_operation_evidence%rowtype;
  v_evidence_id uuid := gen_random_uuid();
  v_version integer;
  v_storage_path text;
  v_result jsonb;
begin
  select * into v_operation
  from public.bank_payment_operations
  where id = p_operation_id
  for update;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_operation.company_id);
  v_payload := jsonb_build_object('operation_id', v_operation.id);
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_operation.company_id,
    'payment_evidence.prepare',
    p_idempotency_key,
    v_payload_hash,
    v_actor
  );
  if v_replay is not null then return v_replay; end if;

  if exists (
    select 1 from public.payment_request_receipt_links
    where operation_id = v_operation.id
  ) then
    raise exception 'bank_receipt_already_linked';
  end if;

  select * into v_existing
  from public.payment_operation_evidence
  where operation_id = v_operation.id
    and status in ('pending_upload', 'pending_review', 'shareable')
  order by version desc
  limit 1
  for update;

  if v_existing.id is not null then
    v_result := jsonb_build_object(
      'evidence_id', v_existing.id,
      'operation_id', v_existing.operation_id,
      'status', v_existing.status,
      'storage_bucket', v_existing.storage_bucket,
      'storage_path', v_existing.storage_path,
      'version', v_existing.version
    );
    return public.payment_reconciliation_store_command(
      v_operation.company_id,
      'payment_evidence.prepare',
      p_idempotency_key,
      v_payload_hash,
      v_actor,
      v_result
    );
  end if;

  select
    document.id as document_id,
    extraction.batch_id,
    extraction.page_number,
    document.sha256
    into v_source
  from public.payment_document_extractions extraction
  join public.payment_documents document on document.id = extraction.document_id
  where extraction.id = v_operation.extraction_id
    and extraction.status = 'accepted';
  if not found then raise exception 'accepted_payment_extraction_required'; end if;

  select coalesce(max(version), 0) + 1 into v_version
  from public.payment_operation_evidence
  where operation_id = v_operation.id;

  v_storage_path := v_operation.company_id::text || '/' || v_source.batch_id::text
    || '/evidence/' || v_evidence_id::text || '.pdf';

  insert into public.payment_operation_evidence(
    id, company_id, batch_id, operation_id, source_document_id,
    source_page_number, version, storage_path, source_document_sha256,
    created_by
  ) values (
    v_evidence_id, v_operation.company_id, v_source.batch_id, v_operation.id,
    v_source.document_id, v_source.page_number, v_version, v_storage_path,
    v_source.sha256, v_actor
  );

  v_result := jsonb_build_object(
    'evidence_id', v_evidence_id,
    'operation_id', v_operation.id,
    'status', 'pending_upload',
    'storage_bucket', 'payment-batch-documents',
    'storage_path', v_storage_path,
    'version', v_version
  );
  return public.payment_reconciliation_store_command(
    v_operation.company_id,
    'payment_evidence.prepare',
    p_idempotency_key,
    v_payload_hash,
    v_actor,
    v_result
  );
end
$$;


ALTER FUNCTION "public"."prepare_payment_operation_evidence"("p_operation_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_approval_batch_close"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_ready jsonb;
  v_blocked jsonb;
  v_ready_count integer;
  v_blocked_count integer;
  v_pending_count integer;
begin
  v_actor := public.approval_batch_require_finance();
  select * into v_batch
  from public.approval_batches
  where id = p_batch_id;
  if not found then raise exception 'batch_not_found'; end if;

  with evaluated as (
    select
      item.id as item_id,
      item.payment_request_id,
      request.request_number,
      request.amount_requested as amount,
      request.currency,
      item.director_status,
      public.approval_batch_item_release_block_reason(item.id) as reason
    from public.approval_batch_items item
    join public.payment_requests request
      on request.id = item.payment_request_id
    where item.batch_id = p_batch_id
      and item.removed_at is null
  )
  select
    coalesce(jsonb_agg(to_jsonb(evaluated) - 'reason'
      order by request_number, item_id)
      filter (
        where director_status = 'approved' and reason is null
      ), '[]'::jsonb),
    coalesce(jsonb_agg(to_jsonb(evaluated)
      order by request_number, item_id)
      filter (
        where director_status <> 'approved' or reason is not null
      ), '[]'::jsonb),
    count(*) filter (
      where director_status = 'approved' and reason is null
    )::integer,
    count(*) filter (
      where director_status <> 'approved' or reason is not null
    )::integer,
    count(*) filter (where director_status = 'pending')::integer
  into
    v_ready,
    v_blocked,
    v_ready_count,
    v_blocked_count,
    v_pending_count
  from evaluated;

  return jsonb_build_object(
    'batch_id', v_batch.id,
    'batch_status', v_batch.status,
    'can_close',
      v_batch.status in ('approved', 'partially_approved')
      and v_pending_count = 0
      and v_ready_count > 0,
    'ready_count', v_ready_count,
    'blocked_count', v_blocked_count,
    'pending_count', v_pending_count,
    'ready_items', v_ready,
    'blocked_items', v_blocked
  );
end
$$;


ALTER FUNCTION "public"."preview_approval_batch_close"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_payment_layout_eligibility"("p_period_start" "date", "p_period_end" "date", "p_company_id" "uuid" DEFAULT NULL::"uuid", "p_company_bank_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_ready jsonb;
  v_blocked jsonb;
  v_invalid jsonb;
  v_totals jsonb;
begin
  v_result := public.preview_payment_layout_eligibility_pre_037(
    p_period_start,
    p_period_end,
    p_company_id,
    p_company_bank_account_id
  );

  select coalesce(jsonb_agg(item), '[]'::jsonb)
  into v_ready
  from jsonb_array_elements(
    coalesce(v_result->'ready_extraordinary', '[]'::jsonb)
  ) item
  where public.extraordinary_authorization_is_ready(
    (item->>'extraordinary_authorization_id')::uuid
  );

  select coalesce(jsonb_agg(
    jsonb_set(
      jsonb_set(item, '{classification}', '"invalid_data"'::jsonb),
      '{classification_reason}',
      '"extraordinary_not_ready_secure_contract"'::jsonb
    )
  ), '[]'::jsonb)
  into v_blocked
  from jsonb_array_elements(
    coalesce(v_result->'ready_extraordinary', '[]'::jsonb)
  ) item
  where not public.extraordinary_authorization_is_ready(
    (item->>'extraordinary_authorization_id')::uuid
  );

  v_invalid := coalesce(v_result->'invalid_data', '[]'::jsonb) || v_blocked;

  with retained as (
    select total
    from jsonb_array_elements(
      coalesce(v_result->'totals_by_currency', '[]'::jsonb)
    ) total
    where total->>'classification' <> 'ready_extraordinary'
  ), secure_totals as (
    select jsonb_build_object(
      'classification', 'ready_extraordinary',
      'currency', item->>'currency',
      'payment_count', count(*),
      'amount', sum((item->>'amount')::numeric)
    ) total
    from jsonb_array_elements(v_ready) item
    group by item->>'currency'
  )
  select coalesce(jsonb_agg(total), '[]'::jsonb)
  into v_totals
  from (
    select total from retained
    union all
    select total from secure_totals
  ) totals;

  return jsonb_set(
    jsonb_set(
      jsonb_set(v_result, '{ready_extraordinary}', v_ready),
      '{invalid_data}',
      v_invalid
    ),
    '{totals_by_currency}',
    v_totals
  );
end
$$;


ALTER FUNCTION "public"."preview_payment_layout_eligibility"("p_period_start" "date", "p_period_end" "date", "p_company_id" "uuid", "p_company_bank_account_id" "uuid") OWNER TO "postgres";


