CREATE OR REPLACE FUNCTION "public"."propose_payment_allocations"("p_operation_id" "uuid", "p_allocations" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_operation public.bank_payment_operations%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_allocation jsonb;
  v_snapshot public.payable_snapshots%rowtype;
  v_snapshot_id uuid;
  v_amount_minor bigint;
  v_total bigint := 0;
  v_position integer := 0;
  v_plan_id uuid;
  v_event_id uuid;
  v_result jsonb;
begin
  select * into v_operation from public.bank_payment_operations where id = p_operation_id for update;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_operation.company_id);
  v_payload := jsonb_build_object('allocations', p_allocations, 'operation_id', p_operation_id);
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_operation.company_id, 'payment_allocation.propose', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_operation.status <> 'available' then raise exception 'bank_payment_operation_not_available'; end if;
  if jsonb_typeof(p_allocations) <> 'array' or jsonb_array_length(p_allocations) not between 1 and 100 then
    raise exception 'invalid_allocations';
  end if;
  if exists (
    select 1 from public.payment_allocation_plans plan
    where plan.operation_id = p_operation_id and plan.status in ('draft', 'reserved')
  ) then raise exception 'open_allocation_plan_exists'; end if;

  -- Serialize against snapshot materialization, then lock snapshots deterministically.
  perform 1
  from public.payment_requests request
  where request.id in (
    select distinct snapshot.payment_request_id
    from jsonb_array_elements(p_allocations) allocation
    join public.payable_snapshots snapshot
      on snapshot.id = (allocation.value->>'snapshot_id')::uuid
  )
  order by request.id
  for update;
  perform 1
  from public.payable_snapshots snapshot
  where snapshot.id in (
    select distinct (value->>'snapshot_id')::uuid from jsonb_array_elements(p_allocations)
  )
  order by snapshot.id
  for update;

  insert into public.payment_allocation_plans(
    company_id, operation_id, total_amount_minor, currency, proposed_by
  ) values (
    v_operation.company_id, v_operation.id, 1, v_operation.currency, v_actor
  ) returning id into v_plan_id;

  for v_allocation in select value from jsonb_array_elements(p_allocations)
  loop
    v_position := v_position + 1;
    v_snapshot_id := (v_allocation->>'snapshot_id')::uuid;
    v_amount_minor := (v_allocation->>'amount_minor')::bigint;
    if v_amount_minor is null or v_amount_minor <= 0 then raise exception 'allocation_amount_must_be_positive'; end if;
    select * into v_snapshot from public.payable_snapshots where id = v_snapshot_id;
    if not found or v_snapshot.company_id <> v_operation.company_id then raise exception 'payable_snapshot_not_found'; end if;
    if v_snapshot.currency <> v_operation.currency then raise exception 'allocation_currency_mismatch'; end if;
    if exists (
      select 1 from public.payable_snapshots newer
      where newer.payment_request_id = v_snapshot.payment_request_id and newer.version > v_snapshot.version
    ) then raise exception 'payable_snapshot_not_latest'; end if;
    if not public.payment_reconciliation_snapshot_is_payable(v_snapshot.id) then
      raise exception 'payable_snapshot_not_currently_payable';
    end if;
    if v_amount_minor > v_snapshot.amount_minor
      - public.payable_snapshot_confirmed_minor(v_snapshot.id)
      - public.payable_snapshot_reserved_minor(v_snapshot.id) then
      raise exception 'payable_snapshot_capacity_exceeded';
    end if;
    insert into public.payment_allocation_items(
      plan_id, operation_id, snapshot_id, amount_minor, currency, position, note
    ) values (
      v_plan_id, v_operation.id, v_snapshot.id, v_amount_minor, v_operation.currency,
      v_position, public.payment_reconciliation_redact_free_text(
        v_allocation->>'note', 300
      )
    );
    if v_total > 9007199254740991 - v_amount_minor then
      raise exception 'allocation_total_out_of_range';
    end if;
    v_total := v_total + v_amount_minor;
  end loop;
  if v_total > v_operation.amount_minor
      - public.payment_operation_confirmed_minor(v_operation.id)
      - public.payment_operation_reserved_minor(v_operation.id) then
    raise exception 'bank_payment_operation_capacity_exceeded';
  end if;
  update public.payment_allocation_plans set total_amount_minor = v_total where id = v_plan_id;
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_allocation.proposed', 'payment_allocation_plan', v_plan_id,
    v_operation.company_id, v_actor,
    jsonb_build_object(
      'allocation_count', v_position,
      'currency', v_operation.currency,
      'operation_id', v_operation.id,
      'plan_id', v_plan_id,
      'total_amount_minor', v_total
    ), v_operation.id, null
  );
  v_result := jsonb_build_object(
    'allocation_count', v_position, 'event_id', v_event_id,
    'plan_id', v_plan_id, 'status', 'draft', 'total_amount_minor', v_total
  );
  return public.payment_reconciliation_store_command(
    v_operation.company_id, 'payment_allocation.propose', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."propose_payment_allocations"("p_operation_id" "uuid", "p_allocations" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_assigned_company_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile_id uuid := old.profile_id;
  v_company_id uuid := old.company_id;
  v_deactivating boolean;
begin
  v_deactivating := tg_op = 'DELETE';
  if tg_op = 'UPDATE' then
    v_deactivating := (old.active and not new.active)
      or new.profile_id is distinct from old.profile_id
      or new.company_id is distinct from old.company_id;
  end if;

  if v_deactivating and exists (
    select 1
    from public.approver_assignments aa
    where aa.company_id = v_company_id
      and aa.active
      and (aa.requester_id = v_profile_id or aa.approver_id = v_profile_id)
  ) then
    raise exception 'membership_used_by_active_approver_pool';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."protect_assigned_company_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_external_notification_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_source record;
  v_expected_source_event_type text;
  v_payload_field_codes text[];
begin
  if tg_op = 'UPDATE' and new.audience is distinct from old.audience then
    raise exception 'notification_audience_immutable';
  end if;

  if tg_op = 'INSERT' and new.audience = 'external' then
    if new.max_attempts is distinct from 3
       or new.attempt_count is distinct from 0
       or new.locked_at is not null
       or new.locked_by is not null
       or new.processed_at is not null
       or new.last_attempt_at is not null
       or new.status not in ('pending', 'no_recipient')
       or exists (
         select 1
         from public.notification_delivery_attempts attempt
         where attempt.notification_event_id = new.id
       ) then
      raise exception 'external_notification_initial_attempt_state_invalid';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.audience = 'external' then
    if old.status = 'no_recipient' then
      raise exception 'no_recipient_terminal';
    end if;

    if new.event_type is distinct from old.event_type
       or new.source_table is distinct from old.source_table
       or new.source_id is distinct from old.source_id
       or new.source_folio is distinct from old.source_folio
       or new.recipient_type is distinct from old.recipient_type
       or new.recipient_profile_id is distinct from old.recipient_profile_id
       or new.recipient_email is distinct from old.recipient_email
       or new.recipient_role is distinct from old.recipient_role
       or new.channel is distinct from old.channel
       or new.subject is distinct from old.subject
       or new.payload is distinct from old.payload
       or new.idempotency_key is distinct from old.idempotency_key
       or new.event_version is distinct from old.event_version
       or new.max_attempts is distinct from old.max_attempts
       or new.rollout_id is distinct from old.rollout_id
       or new.external_subject_type is distinct from old.external_subject_type
       or new.external_subject_id is distinct from old.external_subject_id
       or new.terminal_reason is distinct from old.terminal_reason
       or new.created_at is distinct from old.created_at then
      raise exception 'external_notification_identity_immutable';
    end if;
  end if;

  if new.audience <> 'external' then
    return new;
  end if;

  select
    pie.event_type,
    pie.external_message,
    pie.external_field_codes,
    pie.external_contract_version,
    pie.created_at,
    pi.id as payment_intake_id,
    pi.public_folio,
    pi.provider_email,
    pi.expected_file_count,
    pi.submission_completed_at
    into v_source
  from public.payment_intake_events pie
  join public.payment_intake pi on pi.id = pie.payment_intake_id
  where pie.id = new.source_id;

  if not found or v_source.payment_intake_id is distinct from new.external_subject_id then
    raise exception 'external_notification_source_mismatch';
  end if;

  v_expected_source_event_type := case new.event_type
    when 'provider_intake.received' then 'submission_completed'
    when 'provider_intake.correction_requested' then 'correction_requested'
    when 'provider_intake.rejected' then 'rejected'
    else null
  end;

  if v_source.event_type is distinct from v_expected_source_event_type then
    raise exception 'external_notification_source_event_invalid';
  end if;

  if new.source_folio is distinct from v_source.public_folio
     or new.payload ->> 'public_folio' is distinct from v_source.public_folio
     or new.payload ->> 'occurred_on' is distinct from
       to_char(v_source.created_at at time zone 'America/Mexico_City', 'YYYY-MM-DD') then
    raise exception 'external_notification_public_reference_invalid';
  end if;

  if new.status <> 'no_recipient'
     and new.recipient_email is distinct from lower(btrim(v_source.provider_email)) then
    raise exception 'external_notification_recipient_mismatch';
  end if;

  if new.event_type = 'provider_intake.received' then
    if v_source.submission_completed_at is null
       or v_source.expected_file_count is null
       or v_source.external_message is not null
       or v_source.external_field_codes is not null
       or v_source.external_contract_version is not null then
      raise exception 'external_received_requires_submission_completed';
    end if;
  elsif new.event_type = 'provider_intake.correction_requested' then
    select array_agg(value order by value)
      into v_payload_field_codes
    from jsonb_array_elements_text(new.payload -> 'field_codes') value;

    if v_source.external_contract_version is distinct from 1
       or new.payload ->> 'external_message' is distinct from v_source.external_message
       or v_payload_field_codes is distinct from (
         select array_agg(code order by code)
         from unnest(v_source.external_field_codes) code
       ) then
      raise exception 'external_correction_contract_mismatch';
    end if;
  elsif new.event_type = 'provider_intake.rejected' then
    if v_source.external_contract_version is distinct from 1
       or new.payload ->> 'external_message' is distinct from v_source.external_message
       or cardinality(coalesce(v_source.external_field_codes, array[]::text[])) <> 0 then
      raise exception 'external_rejection_contract_mismatch';
    end if;
  end if;

  if new.status = 'no_recipient'
     and exists (
       select 1
       from public.notification_delivery_attempts attempt
       where attempt.notification_event_id = new.id
     ) then
    raise exception 'no_recipient_attempts_forbidden';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."protect_external_notification_contract"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_notification_delivery_attempt_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_event record;
begin
  select audience, status, idempotency_key
    into v_event
  from public.notification_events
  where id = new.notification_event_id;

  if not found then
    raise exception 'notification_event_not_found';
  end if;

  if v_event.status = 'no_recipient' then
    raise exception 'no_recipient_attempts_forbidden';
  end if;

  if v_event.audience = 'external'
     and new.provider_idempotency_key is distinct from v_event.idempotency_key then
    raise exception 'external_attempt_idempotency_mismatch';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."protect_notification_delivery_attempt_contract"() OWNER TO "postgres";


