CREATE OR REPLACE FUNCTION "public"."protect_payment_intake_submission_completed"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_intake public.payment_intake%rowtype;
  v_actual_file_count integer;
begin
  if new.event_type <> 'submission_completed' then
    return new;
  end if;

  select *
    into v_intake
  from public.payment_intake
  where id = new.payment_intake_id;

  if not found
     or v_intake.status <> 'received'
     or v_intake.expected_file_count is null
     or v_intake.submission_completed_at is null
     or v_intake.submission_completed_at > new.created_at
     or new.actor_type <> 'system'
     or new.actor_profile_id is not null
     or new.from_status is distinct from 'received'
     or new.to_status is distinct from 'received'
     or new.notes is not null
     or new.external_message is not null
     or new.external_field_codes is not null
     or new.external_contract_version is not null
     or new.metadata is distinct from jsonb_build_object(
       'contract_version', 1,
       'expected_file_count', v_intake.expected_file_count
     ) then
    raise exception 'submission_completed_contract_invalid';
  end if;

  select count(*)::integer
    into v_actual_file_count
  from public.payment_intake_files
  where payment_intake_id = new.payment_intake_id;

  if v_actual_file_count <> v_intake.expected_file_count then
    raise exception 'submission_completed_file_count_mismatch';
  end if;

  if exists (
    select 1
    from public.payment_intake_events previous_event
    where previous_event.payment_intake_id = new.payment_intake_id
      and previous_event.metadata ->> 'issue_code' in (
        'storage_upload_failed',
        'storage_cleanup_failed',
        'file_metadata_failed',
        'storage_unavailable'
      )
  ) then
    raise exception 'submission_completed_upload_issue_present';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."protect_payment_intake_submission_completed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provider_intake_action_fingerprint"("p_contract_version" integer, "p_action_kind" "text", "p_payment_intake_id" "uuid", "p_actor_profile_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_to_status" "text", "p_notes" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        jsonb_build_object(
          'actor_profile_id', p_actor_profile_id::text,
          'contract_version', p_contract_version,
          'expected_status', p_expected_status,
          'expected_updated_at', case
            when p_expected_updated_at is null then null
            else pg_catalog.to_char(
              p_expected_updated_at at time zone 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            )
          end,
          'notes', p_notes,
          'operation', p_action_kind,
          'payment_intake_id', p_payment_intake_id::text,
          'to_status', p_to_status
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "public"."provider_intake_action_fingerprint"("p_contract_version" integer, "p_action_kind" "text", "p_payment_intake_id" "uuid", "p_actor_profile_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_to_status" "text", "p_notes" "text") OWNER TO "postgres";


