COMMENT ON COLUMN "public"."proveedores"."csf_url" IS 'URL temporal de Airtable. Migrar archivos a Supabase Storage y actualizar.';



COMMENT ON COLUMN "public"."proveedores"."persona_tipo" IS 'Tipo de persona fiscal: fisica, moral o NULL cuando no se ha clasificado.';



CREATE OR REPLACE FUNCTION "public"."provider_payment_execution_missing_fields"("p_provider" "public"."proveedores") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_destination_type text := lower(nullif(btrim(p_provider.destination_type), ''));
  v_clabe_normalized text := regexp_replace(
    coalesce(p_provider.clabe, ''),
    '[[:space:]-]',
    '',
    'g'
  );
  v_account_normalized text := regexp_replace(
    coalesce(p_provider.cuenta_bancaria, ''),
    '[[:space:]-]',
    '',
    'g'
  );
  v_beneficiary text := coalesce(
    nullif(btrim(p_provider.beneficiary_name), ''),
    nullif(btrim(p_provider.nombre_completo), ''),
    nullif(btrim(p_provider.alias), '')
  );
begin
  return array_remove(array[
    case
      when v_beneficiary is null then 'beneficiary_name'
    end,
    case
      when v_beneficiary is not null
        and (
          char_length(v_beneficiary) > 180
          or v_beneficiary ~ '[[:cntrl:]]'
        )
        then 'beneficiary_name_invalid'
    end,
    case when nullif(btrim(p_provider.banco), '') is null then 'banco' end,
    case
      when nullif(btrim(p_provider.banco), '') is not null
        and (
          char_length(btrim(p_provider.banco)) > 100
          or p_provider.banco ~ '[[:cntrl:]]'
        )
        then 'banco_invalid'
    end,
    case when v_destination_type is null then 'destination_type' end,
    case
      when v_destination_type is not null
        and v_destination_type not in ('clabe', 'cuenta', 'convenio')
        then 'destination_type_invalid'
    end,
    case
      when v_destination_type = 'clabe'
        and nullif(btrim(p_provider.clabe), '') is null
        then 'clabe'
    end,
    case
      when v_destination_type = 'clabe'
        and nullif(btrim(p_provider.clabe), '') is not null
        and v_clabe_normalized !~ '^[0-9]{18}$'
        then 'clabe_invalid'
    end,
    case
      when v_destination_type = 'cuenta'
        and nullif(btrim(p_provider.cuenta_bancaria), '') is null
        then 'cuenta_bancaria'
    end,
    case
      when v_destination_type = 'cuenta'
        and nullif(btrim(p_provider.cuenta_bancaria), '') is not null
        and v_account_normalized !~ '^[0-9]{1,18}$'
        then 'cuenta_bancaria_invalid'
    end,
    case
      when v_destination_type = 'convenio'
        and nullif(btrim(p_provider.convenio_number), '') is null
        then 'convenio_number'
    end,
    case
      when v_destination_type = 'convenio'
        and nullif(btrim(p_provider.convenio_number), '') is not null
        and (
          char_length(btrim(p_provider.convenio_number)) > 30
          or p_provider.convenio_number ~ '[[:cntrl:]]'
        )
        then 'convenio_number_invalid'
    end
  ]::text[], null);
end
$_$;


ALTER FUNCTION "public"."provider_payment_execution_missing_fields"("p_provider" "public"."proveedores") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ratify_extraordinary_authorization"("p_authorization_id" "uuid", "p_note" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_request public.payment_requests%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_authorization_id::text, 37037));
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where id = p_authorization_id
  for update;
  if not found then raise exception 'extraordinary_authorization_not_found'; end if;
  if v_authorization.status = 'ratified'
     and v_authorization.ratified_by = v_actor then
    return jsonb_build_object(
      'authorization_id', v_authorization.id,
      'status', 'ratified',
      'ratified_at', v_authorization.ratified_at,
      'idempotent_replay', true
    );
  end if;
  if v_actor <> v_authorization.external_director_profile_id
     or not public.extraordinary_profile_is_company_director(
       v_actor,
       v_authorization.company_id
     ) then
    raise exception 'registered_external_director_required';
  end if;
  if v_authorization.status <> 'consumed_pending_ratification' then
    raise exception 'extraordinary_authorization_not_pending_ratification';
  end if;
  select * into v_request
  from public.payment_requests
  where id = v_authorization.payment_request_id;
  if v_authorization.external_authorized_at <
     v_request.approval_material_updated_at then
    raise exception 'extraordinary_authorization_materially_stale';
  end if;
  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'invalid_idempotency_key';
  end if;

  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set status = 'ratified',
      ratified_by = v_actor,
      ratified_at = v_now,
      ratification_note = nullif(btrim(coalesce(p_note, '')), ''),
      updated_at = v_now
  where id = v_authorization.id
    and status = 'consumed_pending_ratification';

  perform public.extraordinary_append_event(
    v_authorization.id,
    'authorization_ratified',
    v_actor,
    'authorization-ratified:' || v_authorization.id::text || ':' || v_key,
    jsonb_build_object(
      'layout_id', v_authorization.consumed_layout_id,
      'layout_line_id', v_authorization.consumed_layout_line_id
    )
  );
  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'status', 'ratified',
    'ratified_at', v_now,
    'idempotent_replay', false
  );
end
$$;


ALTER FUNCTION "public"."ratify_extraordinary_authorization"("p_authorization_id" "uuid", "p_note" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stale_external_notification_events"("p_limit" integer DEFAULT 1, "p_lease_minutes" integer DEFAULT 10, "p_worker_id" "text" DEFAULT 'external-notification-recovery'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 1), 1), 1);
  v_lease_minutes integer := least(greatest(coalesce(p_lease_minutes, 10), 10), 60);
  v_worker_id text := left(
    coalesce(nullif(btrim(p_worker_id), ''), 'external-notification-recovery'),
    120
  );
  v_recovered integer;
begin
  with candidate as (
    select e.id
    from public.notification_events e
    join public.notification_external_rollouts r on r.id = e.rollout_id
    where e.audience = 'external'
      and e.status = 'processing'
      and e.event_type in (
        'provider_intake.received',
        'provider_intake.correction_requested',
        'provider_intake.rejected'
      )
      and e.locked_at is not null
      and e.locked_at <= now() - make_interval(mins => v_lease_minutes)
      and e.attempt_count < e.max_attempts
      and e.max_attempts = 3
      and r.mode in ('test_only', 'pilot')
      and r.cutoff_at is not null
      and e.created_at >= r.cutoff_at
      and e.event_type = any (r.enabled_event_types)
      and public.notification_external_event_mode_allowed(e.event_type, r.mode)
      and not exists (
        select 1
        from public.notification_delivery_attempts attempt
        where attempt.notification_event_id = e.id
          and (
            attempt.provider_request_started_at is not null
            or attempt.provider_request_completed_at is not null
            or attempt.provider_message_id is not null
            or attempt.status = 'sent'
          )
      )
    order by e.locked_at, e.id
    for update of e skip locked
    limit v_limit
  ),
  recovered as (
    update public.notification_events e
       set status = 'pending',
           locked_at = null,
           locked_by = null,
           next_attempt_at = now(),
           last_error = 'external_processing_lease_expired',
           updated_at = now()
      from candidate c
     where e.id = c.id
     returning e.id
  )
  select count(*)::integer into v_recovered
  from recovered;

  perform v_worker_id;

  return v_recovered;
end
$$;


ALTER FUNCTION "public"."recover_stale_external_notification_events"("p_limit" integer, "p_lease_minutes" integer, "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_maintenance_fee_payment"("p_charge_id" "uuid", "p_amount" numeric, "p_payment_date" "date", "p_bank_reference" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT 'transfer'::"text", "p_registered_by" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_charge public.maintenance_fee_charges%rowtype;
  v_payment_id uuid;
  v_total_paid numeric;
  v_new_status text;
begin
  if p_charge_id is null then
    raise exception 'charge_required';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'invalid_payment_amount';
  end if;

  if p_payment_date is null then
    raise exception 'payment_date_required';
  end if;

  if p_payment_method is not null
     and p_payment_method not in ('transfer', 'cash', 'check', 'card', 'other') then
    raise exception 'invalid_payment_method';
  end if;

  select *
  into v_charge
  from public.maintenance_fee_charges
  where id = p_charge_id
  for update;

  if not found then
    raise exception 'charge_not_found';
  end if;

  if v_charge.status = 'cancelled' then
    raise exception 'charge_cancelled';
  end if;

  insert into public.maintenance_fee_payments (
    charge_id,
    member_id,
    billing_period_id,
    amount_paid,
    payment_date,
    bank_reference,
    payment_method,
    invoice_id,
    registered_by,
    notes
  )
  values (
    v_charge.id,
    v_charge.member_id,
    v_charge.billing_period_id,
    p_amount,
    p_payment_date,
    p_bank_reference,
    coalesce(p_payment_method, 'transfer'),
    v_charge.invoice_id,
    p_registered_by,
    p_notes
  )
  returning id into v_payment_id;

  select coalesce(sum(amount_paid), 0)
  into v_total_paid
  from public.maintenance_fee_payments
  where charge_id = v_charge.id;

  v_new_status :=
    case
      when v_total_paid >= v_charge.expected_amount then 'paid'
      when v_total_paid > 0 then 'partial'
      else 'pending'
    end;

  update public.maintenance_fee_charges
  set
    paid_amount = v_total_paid,
    status = v_new_status,
    updated_at = now()
  where id = v_charge.id;

  return jsonb_build_object(
    'message', 'maintenance_fee_payment_registered',
    'payment_id', v_payment_id,
    'charge_id', v_charge.id,
    'member_id', v_charge.member_id,
    'billing_period_id', v_charge.billing_period_id,
    'total_paid', v_total_paid,
    'expected_amount', v_charge.expected_amount,
    'pending_amount', v_charge.expected_amount - v_total_paid,
    'status', v_new_status
  );
end;
$$;


ALTER FUNCTION "public"."register_maintenance_fee_payment"("p_charge_id" "uuid", "p_amount" numeric, "p_payment_date" "date", "p_bank_reference" "text", "p_payment_method" "text", "p_registered_by" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_payment_document_extraction"("p_extraction_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_extraction public.payment_document_extractions%rowtype;
  v_actor uuid;
  v_reason text := public.payment_reconciliation_redact_free_text(p_reason, 500);
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_result jsonb;
begin
  select * into v_extraction
  from public.payment_document_extractions where id = p_extraction_id for update;
  if not found then raise exception 'payment_extraction_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_extraction.company_id);
  v_payload := jsonb_build_object(
    'expected_updated_at', p_expected_updated_at,
    'extraction_id', p_extraction_id,
    'operation', 'reject',
    'reason', v_reason
  );
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_extraction.company_id, 'payment_extraction.reject', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_reason is null or char_length(v_reason) < 10 then raise exception 'rejection_reason_too_short'; end if;
  if v_extraction.updated_at is distinct from p_expected_updated_at then raise exception 'stale_payment_extraction'; end if;
  if v_extraction.status not in ('review_required', 'blocked') then raise exception 'payment_extraction_not_reviewable'; end if;
  perform 1
  from public.payment_ingestion_batches batch
  where batch.id = v_extraction.batch_id
    and batch.company_id = v_extraction.company_id
  for update;
  if not found then raise exception 'payment_batch_scope_mismatch'; end if;
  update public.payment_document_extractions
  set status = 'rejected', reviewed_by = v_actor,
      reviewed_at = clock_timestamp(), rejection_reason = v_reason
  where id = v_extraction.id;
  update public.payment_ingestion_batches batch
  set status = case when not exists (
    select 1 from public.payment_document_extractions pending
    where pending.batch_id = batch.id and pending.status in ('review_required', 'blocked')
  ) then 'ready' else 'review_required' end
  where batch.id = v_extraction.batch_id;
  v_result := jsonb_build_object('extraction_id', v_extraction.id, 'status', 'rejected');
  return public.payment_reconciliation_store_command(
    v_extraction.company_id, 'payment_extraction.reject', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."reject_payment_document_extraction"("p_extraction_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_payment_layout_line"("p_line_id" "uuid", "p_reason" "text", "p_actor_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_line public.payment_layout_lines%rowtype;
  v_request_number text;
  v_clean_reason text;
begin
  v_clean_reason := nullif(btrim(coalesce(p_reason, '')), '');

  if v_clean_reason is null then
    raise exception 'rejection_reason_required';
  end if;

  select *
  into v_line
  from public.payment_layout_lines
  where id = p_line_id
  for update;

  if not found then
    raise exception 'layout_line_not_found';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_actor_profile_id
      and coalesce(active, true) = true
  ) then
    raise exception 'profile_not_found';
  end if;

  if v_line.status = 'paid' then
    raise exception 'line_already_paid';
  end if;

  if v_line.status = 'bank_rejected' then
    raise exception 'line_already_rejected';
  end if;

  update public.payment_layout_lines
  set
    status = 'bank_rejected',
    bank_rejection_reason = v_clean_reason,
    updated_at = now()
  where id = p_line_id;

  update public.payment_requests pr
  set
    status = 'approved'::public.payment_request_status,
    operational_comments = concat_ws(
      E'\n',
      nullif(pr.operational_comments, ''),
      'Rechazo bancario: ' || v_clean_reason
    ),
    updated_at = now()
  where pr.id = v_line.payment_request_id
  returning pr.request_number into v_request_number;

  return jsonb_build_object(
    'line_id', p_line_id,
    'payment_request_id', v_line.payment_request_id,
    'request_number', v_request_number,
    'new_line_status', 'bank_rejected',
    'new_request_status', 'approved',
    'message', 'layout_line_rejected'
  );
end;
$$;


ALTER FUNCTION "public"."reject_payment_layout_line"("p_line_id" "uuid", "p_reason" "text", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_and_rebatch_rejected_request"("p_rejected_item_id" "uuid", "p_correction_note" "text", "p_target_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_note text := nullif(btrim(coalesce(p_correction_note, '')), '');
  v_item public.approval_batch_items%rowtype;
  v_source_batch public.approval_batches%rowtype;
  v_target_batch public.approval_batches%rowtype;
  v_request public.payment_requests%rowtype;
  v_payment_request_id uuid;
  v_new_item_id uuid;
  v_review_sequence integer;
  v_budget jsonb;
  v_payment_method text;
begin
  v_actor := public.approval_batch_require_finance();
  if v_note is null or char_length(v_note) < 10 then
    raise exception 'rebatch_correction_note_too_short';
  end if;

  select payment_request_id into v_payment_request_id
  from public.approval_batch_items
  where id = p_rejected_item_id;
  if not found then raise exception 'rejected_batch_item_not_found'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_payment_request_id::text, 21021));

  select * into v_item
  from public.approval_batch_items
  where id = p_rejected_item_id
    and payment_request_id = v_payment_request_id
  for update;
  if not found then raise exception 'rejected_batch_item_not_found'; end if;

  select * into v_source_batch
  from public.approval_batches
  where id = v_item.batch_id
  for update;
  if not found then raise exception 'source_batch_not_found'; end if;

  select * into v_request
  from public.payment_requests
  where id = v_item.payment_request_id
  for update;
  if not found then raise exception 'payment_request_not_found'; end if;

  if v_item.removed_at is not null
     or v_item.director_status <> 'rejected'
     or v_item.rebatch_status <> 'blocked' then
    raise exception 'rejected_batch_item_not_blocked';
  end if;
  if v_source_batch.status not in ('partially_approved', 'closed') then
    raise exception 'source_batch_not_decided';
  end if;
  if public.approval_batch_request_has_any_execution_record(v_request.id) then
    raise exception 'payment_request_already_executed';
  end if;
  if public.approval_batch_request_has_active_extraordinary(v_request.id) then
    raise exception 'extraordinary_request_cannot_be_rebatched';
  end if;
  if public.approval_batch_request_open_elsewhere(v_request.id, p_target_batch_id) then
    raise exception 'payment_request_in_another_open_batch';
  end if;
  if v_request.status::text not in ('submitted', 'pending_approval', 'approved') then
    raise exception 'request_status_not_batch_eligible';
  end if;

  v_payment_method := coalesce(
    nullif(v_request.payment_method, ''),
    case when v_request.request_type::text in ('cash', 'check') then v_request.request_type::text else 'transfer' end
  );
  if v_request.company_id is null
     or v_request.requested_by is null
     or (v_request.proveedor_id is null and v_payment_method = 'transfer')
     or v_request.cost_center_id is null
     or v_request.budget_category_id is null
     or v_request.budget_month is null
     or coalesce(v_request.amount_requested, 0) <= 0
     or nullif(btrim(v_request.currency), '') is null then
    raise exception 'minimum_direction_data_missing';
  end if;

  v_budget := public.approval_batch_budget_validation(v_request.id);
  if coalesce(v_budget ->> 'status', 'bloqueado') <> 'aprobable' then
    raise exception 'budget_revalidation_required:%', coalesce(v_budget ->> 'motivo', 'unknown');
  end if;

  select coalesce(max(abi.review_sequence), 0) + 1
    into v_review_sequence
  from public.approval_batch_items abi
  where abi.payment_request_id = v_request.id
    and abi.removed_at is null;

  if p_target_batch_id is not null then
    select * into v_target_batch
    from public.approval_batches
    where id = p_target_batch_id
    for update;
    if not found then raise exception 'target_batch_not_found'; end if;
    if v_target_batch.status <> 'draft' then raise exception 'target_batch_must_be_draft'; end if;
    if v_target_batch.company_id <> v_request.company_id then
      raise exception 'target_batch_company_mismatch';
    end if;
    if exists (
      select 1
      from public.approval_batch_items abi
      where abi.batch_id = p_target_batch_id
        and abi.payment_request_id = v_request.id
        and abi.removed_at is null
    ) then
      raise exception 'payment_request_already_in_target_batch';
    end if;

    insert into public.approval_batch_items(
      batch_id,
      payment_request_id,
      finance_reviewed_by,
      finance_reviewed_at,
      previous_item_id,
      review_sequence,
      resubmitted_at,
      resubmitted_by,
      resubmission_note
    ) values (
      p_target_batch_id,
      v_request.id,
      v_actor,
      now(),
      v_item.id,
      v_review_sequence,
      now(),
      v_actor,
      v_note
    )
    returning id into v_new_item_id;
  end if;

  update public.approval_batch_items
  set rebatch_status = 'released',
      rebatch_released_by = v_actor,
      rebatch_released_at = now(),
      rebatch_release_note = v_note
  where id = v_item.id;

  return jsonb_build_object(
    'rejected_item_id', v_item.id,
    'payment_request_id', v_request.id,
    'rebatch_status', 'released',
    'target_batch_id', p_target_batch_id,
    'new_item_id', v_new_item_id,
    'review_sequence', v_review_sequence,
    'correction_note', v_note,
    'status', case when v_new_item_id is null then 'resubmission_available' else 'rebatched_pending' end
  );
end
$$;


ALTER FUNCTION "public"."release_and_rebatch_rejected_request"("p_rejected_item_id" "uuid", "p_correction_note" "text", "p_target_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_payment_reservation"("p_reservation_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_initial public.payment_allocation_reservations%rowtype;
  v_reservation public.payment_allocation_reservations%rowtype;
  v_plan public.payment_allocation_plans%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_actor uuid;
  v_reason text := public.payment_reconciliation_redact_free_text(p_reason, 500);
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_decided_at timestamptz;
begin
  select * into v_initial
  from public.payment_allocation_reservations where id = p_reservation_id;
  if not found then raise exception 'payment_reservation_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_initial.company_id);
  v_payload := jsonb_build_object('reason', v_reason, 'reservation_id', p_reservation_id);
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_initial.company_id, 'payment_allocation.release', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_reason is null or char_length(v_reason) < 10 then raise exception 'release_reason_too_short'; end if;

  -- Match expiration/cancellation ordering: plan -> operation -> reservation.
  select * into v_plan
  from public.payment_allocation_plans
  where id = v_initial.plan_id
  for update;
  if not found then raise exception 'payment_allocation_plan_not_found'; end if;
  select * into v_operation
  from public.bank_payment_operations
  where id = v_initial.operation_id
  for update;
  if not found then raise exception 'bank_payment_operation_not_found'; end if;
  select * into v_reservation
  from public.payment_allocation_reservations
  where id = p_reservation_id
  for update;
  if v_reservation.plan_id <> v_plan.id
     or v_reservation.operation_id <> v_operation.id
     or v_reservation.company_id <> v_plan.company_id then
    raise exception 'payment_reservation_scope_mismatch';
  end if;
  if v_reservation.status <> 'active' then raise exception 'payment_reservation_not_active'; end if;
  v_decided_at := clock_timestamp();
  if v_reservation.expires_at <= v_decided_at then
    raise exception 'payment_reservation_expired_use_expire';
  end if;
  update public.payment_allocation_reservations
  set status = 'released', closed_by = v_actor, closed_at = v_decided_at, close_reason = v_reason
  where id = v_reservation.id;
  update public.payment_allocation_plans set status = 'draft'
  where id = v_reservation.plan_id and status = 'reserved';
  update public.bank_payment_operations set status = 'available'
  where id = v_reservation.operation_id and status = 'reserved';
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_allocation.released', 'payment_allocation_reservation', v_reservation.id,
    v_reservation.company_id, v_actor,
    jsonb_build_object('operation_id', v_reservation.operation_id, 'plan_id', v_reservation.plan_id, 'reservation_id', v_reservation.id),
    v_reservation.operation_id, null
  );
  v_result := jsonb_build_object('event_id', v_event_id, 'reservation_id', v_reservation.id, 'status', 'released');
  return public.payment_reconciliation_store_command(
    v_reservation.company_id, 'payment_allocation.release', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."release_payment_reservation"("p_reservation_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_rejected_batch_item_for_rebatch"("p_item_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_request_id uuid;
begin
  v_actor := public.approval_batch_require_finance();
  if v_note is null then raise exception 'rebatch_release_note_required'; end if;

  update public.approval_batch_items abi
    set rebatch_status = 'released',
        rebatch_released_by = v_actor,
        rebatch_released_at = now(),
        rebatch_release_note = v_note
  from public.approval_batches ab
  where abi.id = p_item_id
    and ab.id = abi.batch_id
    and abi.removed_at is null
    and abi.director_status = 'rejected'
    and abi.rebatch_status = 'blocked'
    and ab.status in ('partially_approved', 'closed')
  returning abi.payment_request_id into v_request_id;

  if v_request_id is null then
    if exists (select 1 from public.approval_batch_items where id = p_item_id and rebatch_status = 'released') then
      raise exception 'batch_item_already_released';
    end if;
    raise exception 'rejected_decided_batch_item_not_found';
  end if;
  return jsonb_build_object(
    'item_id', p_item_id,
    'payment_request_id', v_request_id,
    'rebatch_status', 'released'
  );
end
$$;


ALTER FUNCTION "public"."release_rejected_batch_item_for_rebatch"("p_item_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_approver_assignment"("p_assignment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;

  update public.approver_assignments
  set active = false, updated_at = now()
  where id = p_assignment_id
    and active;
  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$$;


ALTER FUNCTION "public"."remove_approver_assignment"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_company_director_for_future_batches"("p_company_id" "uuid", "p_director_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_assignment_id uuid;
  v_active_count integer;
  v_now timestamptz := clock_timestamp();
begin
  if p_company_id is null or p_director_profile_id is null then
    raise exception 'company_and_director_required';
  end if;

  v_actor := public.approval_batch_require_finance();
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 21034));

  perform 1
  from public.companies company
  where company.id = p_company_id
  for update;

  if not found then
    raise exception 'company_not_found';
  end if;

  perform 1
  from public.company_directors director_assignment
  where director_assignment.company_id = p_company_id
  order by director_assignment.id
  for update;

  select director_assignment.id
    into v_assignment_id
  from public.company_directors director_assignment
  where director_assignment.company_id = p_company_id
    and director_assignment.director_profile_id = p_director_profile_id
    and director_assignment.active
  order by director_assignment.created_at desc, director_assignment.id desc
  limit 1;

  if v_assignment_id is null then
    select director_assignment.id
      into v_assignment_id
    from public.company_directors director_assignment
    where director_assignment.company_id = p_company_id
      and director_assignment.director_profile_id = p_director_profile_id
    order by director_assignment.created_at desc, director_assignment.id desc
    limit 1;

    return jsonb_build_object(
      'company_id', p_company_id,
      'director_assignment_id', v_assignment_id,
      'director_profile_id', p_director_profile_id,
      'active', false,
      'changed', false,
      'reason', 'already_inactive_or_not_assigned',
      'changed_at', null
    );
  end if;

  select count(*)
    into v_active_count
  from public.company_directors director_assignment
  where director_assignment.company_id = p_company_id
    and director_assignment.active;

  if v_active_count <= 1 then
    raise exception 'last_active_company_director_required';
  end if;

  update public.company_directors director_assignment
  set active = false,
      updated_at = v_now
  where director_assignment.id = v_assignment_id
    and director_assignment.active;

  insert into public.activity_log(
    entity_type,
    entity_id,
    action,
    old_values,
    new_values,
    performed_by,
    performed_at,
    notes
  ) values (
    'company',
    p_company_id,
    'future_batch_director_removed',
    jsonb_build_object(
      'director_profile_id', p_director_profile_id,
      'active', true
    ),
    jsonb_build_object(
      'director_profile_id', p_director_profile_id,
      'active', false
    ),
    v_actor,
    v_now,
    'Future-batch pool changed; existing and historical batch Director snapshots are unchanged.'
  );

  return jsonb_build_object(
    'company_id', p_company_id,
    'director_assignment_id', v_assignment_id,
    'director_profile_id', p_director_profile_id,
    'active', false,
    'changed', true,
    'changed_at', v_now
  );
end
$$;


ALTER FUNCTION "public"."remove_company_director_for_future_batches"("p_company_id" "uuid", "p_director_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_company_director_for_future_batches"("p_company_id" "uuid", "p_director_profile_id" "uuid") IS 'Removes one Director from the future-batch pool while preserving at least one active Director and every existing batch snapshot.';



CREATE OR REPLACE FUNCTION "public"."remove_request_from_approval_batch"("p_batch_id" "uuid", "p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_status text;
begin
  v_actor := public.approval_batch_require_finance();
  select status into v_status from public.approval_batches where id = p_batch_id for update;
  if v_status is null then raise exception 'batch_not_found'; end if;
  if v_status <> 'draft' then raise exception 'batch_must_be_draft'; end if;

  update public.approval_batch_items
    set removed_by = v_actor, removed_at = now()
  where id = p_item_id and batch_id = p_batch_id
    and removed_at is null and director_status = 'pending';
  if not found then raise exception 'active_batch_item_not_found'; end if;
  return jsonb_build_object('item_id', p_item_id, 'removed', true);
end
$$;


ALTER FUNCTION "public"."remove_request_from_approval_batch"("p_batch_id" "uuid", "p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_payment_allocations"("p_plan_id" "uuid", "p_expires_at" timestamp with time zone, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_plan public.payment_allocation_plans%rowtype;
  v_operation public.bank_payment_operations%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_item record;
  v_reservation_id uuid;
  v_event_id uuid;
  v_result jsonb;
  v_reserved_at timestamptz;
begin
  select * into v_plan from public.payment_allocation_plans where id = p_plan_id for update;
  if not found then raise exception 'payment_allocation_plan_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_plan.company_id);
  v_payload := jsonb_build_object('expires_at', p_expires_at, 'plan_id', p_plan_id);
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_plan.company_id, 'payment_allocation.reserve', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if v_plan.status <> 'draft' then raise exception 'payment_allocation_plan_not_draft'; end if;
  if p_expires_at is null then raise exception 'invalid_reservation_expiry'; end if;
  select * into v_operation from public.bank_payment_operations where id = v_plan.operation_id for update;
  if v_operation.status <> 'available' then raise exception 'bank_payment_operation_not_available'; end if;

  -- Snapshot creation locks the same requests, closing the reapproval/reservation race.
  perform 1
  from public.payment_requests request
  where request.id in (
    select snapshot.payment_request_id
    from public.payment_allocation_items item
    join public.payable_snapshots snapshot on snapshot.id = item.snapshot_id
    where item.plan_id = p_plan_id
  )
  order by request.id
  for update;

  perform 1 from public.payable_snapshots snapshot
  where snapshot.id in (
    select item.snapshot_id from public.payment_allocation_items item where item.plan_id = p_plan_id
  ) order by snapshot.id for update;

  if v_plan.total_amount_minor > v_operation.amount_minor
      - public.payment_operation_confirmed_minor(v_operation.id)
      - public.payment_operation_reserved_minor(v_operation.id) then
    raise exception 'bank_payment_operation_capacity_exceeded';
  end if;
  for v_item in
    select item.snapshot_id, item.amount_minor
    from public.payment_allocation_items item
    where item.plan_id = p_plan_id
    order by item.snapshot_id
  loop
    if exists (
      select 1
      from public.payable_snapshots newer
      join public.payable_snapshots current_snapshot
        on current_snapshot.id = v_item.snapshot_id
      where newer.payment_request_id = current_snapshot.payment_request_id
        and newer.version > current_snapshot.version
    ) then
      raise exception 'payable_snapshot_not_latest';
    end if;
    if not public.payment_reconciliation_snapshot_is_payable(v_item.snapshot_id) then
      raise exception 'payable_snapshot_not_currently_payable';
    end if;
    if v_item.amount_minor > (
      select snapshot.amount_minor
        - public.payable_snapshot_confirmed_minor(snapshot.id)
        - public.payable_snapshot_reserved_minor(snapshot.id)
      from public.payable_snapshots snapshot where snapshot.id = v_item.snapshot_id
    ) then raise exception 'payable_snapshot_capacity_exceeded'; end if;
  end loop;

  -- Evaluate the lease against a fresh database clock after every contended
  -- lock. A transaction-start timestamp could create an already-expired lease.
  v_reserved_at := clock_timestamp();
  if p_expires_at <= v_reserved_at
     or p_expires_at > v_reserved_at + interval '24 hours' then
    raise exception 'invalid_reservation_expiry';
  end if;

  insert into public.payment_allocation_reservations(
    company_id, plan_id, operation_id, amount_minor, currency,
    expires_at, created_by, created_at
  ) values (
    v_plan.company_id, v_plan.id, v_plan.operation_id, v_plan.total_amount_minor,
    v_plan.currency, p_expires_at, v_actor, v_reserved_at
  ) returning id into v_reservation_id;
  update public.payment_allocation_plans set status = 'reserved' where id = v_plan.id;
  update public.bank_payment_operations set status = 'reserved' where id = v_operation.id;
  v_event_id := public.append_financial_outbox_event_internal(
    'payment_allocation.reserved', 'payment_allocation_reservation', v_reservation_id,
    v_plan.company_id, v_actor,
    jsonb_build_object(
      'amount_minor', v_plan.total_amount_minor, 'currency', v_plan.currency,
      'expires_at', p_expires_at, 'operation_id', v_plan.operation_id,
      'plan_id', v_plan.id, 'reservation_id', v_reservation_id
    ), v_plan.operation_id, null
  );
  v_result := jsonb_build_object(
    'event_id', v_event_id, 'expires_at', p_expires_at,
    'plan_id', v_plan.id, 'reservation_id', v_reservation_id, 'status', 'active'
  );
  return public.payment_reconciliation_store_command(
    v_plan.company_id, 'payment_allocation.reserve', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$$;


ALTER FUNCTION "public"."reserve_payment_allocations"("p_plan_id" "uuid", "p_expires_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_invoice_receiver"("p_incident_charge_id" "uuid" DEFAULT NULL::"uuid", "p_charge_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_charge public.maintenance_fee_charges%rowtype;
  v_incident public.incident_charges%rowtype;
  v_member public.members%rowtype;
begin
  if p_charge_id is null and p_incident_charge_id is null then
    raise exception 'invoice_reference_required';
  end if;

  if p_charge_id is not null and p_incident_charge_id is not null then
    raise exception 'invoice_reference_must_be_unique';
  end if;

  if p_charge_id is not null then
    select *
    into v_charge
    from public.maintenance_fee_charges
    where id = p_charge_id;

    if not found then
      raise exception 'charge_not_found';
    end if;

    select *
    into v_member
    from public.members
    where id = v_charge.member_id;

    if not found then
      raise exception 'receiver_not_found';
    end if;

    return jsonb_build_object(
      'receiver_type', 'member',
      'name', v_member.full_name,
      'rfc', v_member.rfc,
      'member_id', v_member.id,
      'external_name', null,
      'reference_type', 'maintenance_fee',
      'reference_id', v_charge.id
    );
  end if;

  select *
  into v_incident
  from public.incident_charges
  where id = p_incident_charge_id;

  if not found then
    raise exception 'incident_charge_not_found';
  end if;

  if v_incident.member_id is not null then
    select *
    into v_member
    from public.members
    where id = v_incident.member_id;

    if not found then
      raise exception 'receiver_not_found';
    end if;

    return jsonb_build_object(
      'receiver_type', 'member',
      'name', v_member.full_name,
      'rfc', v_member.rfc,
      'member_id', v_member.id,
      'external_name', null,
      'reference_type', 'incident',
      'reference_id', v_incident.id
    );
  end if;

  if nullif(trim(coalesce(v_incident.external_name, '')), '') is null then
    raise exception 'receiver_not_found';
  end if;

  return jsonb_build_object(
    'receiver_type', 'external',
    'name', v_incident.external_name,
    'rfc', v_incident.external_rfc,
    'member_id', null,
    'external_name', v_incident.external_name,
    'reference_type', 'incident',
    'reference_id', v_incident.id
  );
end;
$$;


ALTER FUNCTION "public"."resolve_invoice_receiver"("p_incident_charge_id" "uuid", "p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_provider_intake_link_internal"("p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_result jsonb;
begin
  if p_token_hash is null or lower(btrim(p_token_hash)) !~ '^[0-9a-f]{64}$' then
    raise exception 'provider_intake_link_not_available';
  end if;

  select jsonb_build_object(
    'intake_link_id', il.id,
    'company_id', il.company_id,
    'company_display_name', coalesce(nullif(btrim(c.legal_name), ''), c.name),
    'max_file_mb', il.max_file_mb,
    'max_submissions_per_day', il.max_submissions_per_day,
    'allowed_file_types', to_jsonb(il.allowed_file_types)
  )
    into v_result
  from public.intake_links il
  join public.companies c on c.id = il.company_id
  where il.token_hash = lower(btrim(p_token_hash))
    and il.status = 'active'
    and (il.expires_at is null or il.expires_at > now())
    and coalesce(c.active, true)
  limit 1;

  if v_result is null then
    raise exception 'provider_intake_link_not_available';
  end if;

  return v_result;
end
$_$;


ALTER FUNCTION "public"."resolve_provider_intake_link_internal"("p_token_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_provider_intake_link_internal"("p_token_hash" "text") IS 'Service-only resolution of an active provider-intake token hash. Never expose its internal IDs directly.';



CREATE OR REPLACE FUNCTION "public"."review_cash_reconciliation"("p_reconciliation_id" "uuid", "p_reviewer_profile_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reconciliation public.cash_reconciliations%rowtype;
  v_fund public.cash_funds%rowtype;
  v_action text;
  v_accounted_amount numeric := 0;
  v_new_fund_status text;
  v_can_review boolean := false;
begin
  if p_reconciliation_id is null then
    raise exception 'reconciliation_required';
  end if;

  if p_reviewer_profile_id is null then
    raise exception 'reviewer_profile_required';
  end if;

  v_action := lower(nullif(btrim(coalesce(p_action, '')), ''));

  if v_action not in ('approved', 'rejected', 'correction_requested') then
    raise exception 'invalid_review_action';
  end if;

  if v_action in ('rejected', 'correction_requested')
     and nullif(btrim(coalesce(p_comment, '')), '') is null
  then
    raise exception 'review_comment_required';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_reviewer_profile_id
      and coalesce(active, true) = true
  ) then
    raise exception 'reviewer_profile_not_found';
  end if;

  -- Validación por profile_id recibido.
  -- Esto permite probar desde SQL Editor, donde auth.uid() suele ser NULL.
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = p_reviewer_profile_id
      and lower(trim(r.name)) in (
        'admin',
        'finance',
        'finanzas',
        'approver_2',
        'aprobador_2'
      )
  )
  into v_can_review;

  if not v_can_review then
    raise exception 'not_allowed_to_review_reconciliation';
  end if;

  select *
  into v_reconciliation
  from public.cash_reconciliations
  where id = p_reconciliation_id
  for update;

  if not found then
    raise exception 'reconciliation_not_found';
  end if;

  if v_reconciliation.status <> 'submitted' then
    raise exception 'only_submitted_reconciliations_can_be_reviewed';
  end if;

  select *
  into v_fund
  from public.cash_funds
  where id = v_reconciliation.cash_fund_id
  for update;

  if not found then
    raise exception 'cash_fund_not_found';
  end if;

  update public.cash_reconciliations
  set
    status = v_action,
    reviewer_profile_id = p_reviewer_profile_id,
    reviewer_comment = p_comment,
    reviewed_at = now()
  where id = p_reconciliation_id;

  if v_action = 'approved' then
    v_accounted_amount := v_reconciliation.total_tickets + v_reconciliation.returned_amount;

    v_new_fund_status := case
      when v_accounted_amount >= v_fund.assigned_amount then 'closed'
      else 'pending_receipt'
    end;

    update public.cash_funds
    set
      verified_amount = least(v_accounted_amount, assigned_amount),
      status = v_new_fund_status
    where id = v_fund.id;

    update public.payment_requests
    set
      operational_comments = concat_ws(
        E'\n',
        nullif(operational_comments, ''),
        'Comprobación de efectivo aprobada. Fondo: ' || v_fund.id::text
      ),
      updated_at = now()
    where id = v_fund.payment_request_id;

    return jsonb_build_object(
      'message', 'cash_reconciliation_approved',
      'reconciliation_id', p_reconciliation_id,
      'cash_fund_id', v_fund.id,
      'fund_status', v_new_fund_status,
      'accounted_amount', v_accounted_amount,
      'pending_amount', greatest(v_fund.assigned_amount - v_accounted_amount, 0)
    );
  end if;

  if v_action in ('rejected', 'correction_requested') then
    update public.cash_funds
    set status = 'pending_receipt'
    where id = v_fund.id;

    update public.payment_requests
    set
      operational_comments = concat_ws(
        E'\n',
        nullif(operational_comments, ''),
        'Comprobación de efectivo requiere atención: ' || coalesce(p_comment, '')
      ),
      updated_at = now()
    where id = v_fund.payment_request_id;

    return jsonb_build_object(
      'message', case
        when v_action = 'rejected' then 'cash_reconciliation_rejected'
        else 'cash_reconciliation_correction_requested'
      end,
      'reconciliation_id', p_reconciliation_id,
      'cash_fund_id', v_fund.id,
      'fund_status', 'pending_receipt',
      'comment', p_comment
    );
  end if;

  raise exception 'unexpected_review_action';
end;
$$;


ALTER FUNCTION "public"."review_cash_reconciliation"("p_reconciliation_id" "uuid", "p_reviewer_profile_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_payment_operation_evidence"("p_evidence_id" "uuid", "p_shareable" boolean, "p_single_operation_attested" boolean, "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_evidence public.payment_operation_evidence%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_payload_hash text;
  v_replay jsonb;
  v_status text;
  v_reviewed_at timestamptz;
  v_event_id uuid;
  v_result jsonb;
begin
  select * into v_evidence
  from public.payment_operation_evidence
  where id = p_evidence_id
  for update;
  if not found then raise exception 'payment_evidence_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_evidence.company_id);
  v_payload := jsonb_build_object(
    'evidence_id', p_evidence_id,
    'reason', nullif(btrim(p_reason), ''),
    'shareable', p_shareable,
    'single_operation_attested', p_single_operation_attested
  );
  v_payload_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_evidence.company_id,
    'payment_evidence.review',
    p_idempotency_key,
    v_payload_hash,
    v_actor
  );
  if v_replay is not null then return v_replay; end if;

  if v_evidence.status <> 'pending_review' then
    raise exception 'payment_evidence_not_pending_review';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 10 and 500 then
    raise exception 'payment_evidence_review_reason_required';
  end if;
  if p_shareable and not p_single_operation_attested then
    raise exception 'single_operation_attestation_required';
  end if;
  if v_evidence.page_count <> 1 then
    raise exception 'individual_receipt_must_have_one_page';
  end if;

  v_status := case when p_shareable then 'shareable' else 'not_shareable' end;
  v_reviewed_at := clock_timestamp();
  update public.payment_operation_evidence
  set status = v_status,
      single_operation_attested = p_single_operation_attested,
      reviewed_by = v_actor,
      reviewed_at = v_reviewed_at,
      review_reason = btrim(p_reason)
  where id = v_evidence.id;

  v_event_id := public.append_financial_outbox_event_internal(
    'payment_evidence.reviewed',
    'payment_operation_evidence',
    v_evidence.id,
    v_evidence.company_id,
    v_actor,
    jsonb_build_object(
      'evidence_id', v_evidence.id,
      'operation_id', v_evidence.operation_id,
      'page_count', 1,
      'status', v_status
    ),
    v_evidence.operation_id,
    null,
    'evidence-reviewed:' || v_payload_hash
  );

  v_result := jsonb_build_object(
    'event_id', v_event_id,
    'evidence_id', v_evidence.id,
    'operation_id', v_evidence.operation_id,
    'status', v_status
  );
  return public.payment_reconciliation_store_command(
    v_evidence.company_id,
    'payment_evidence.review',
    p_idempotency_key,
    v_payload_hash,
    v_actor,
    v_result
  );
end
$$;


ALTER FUNCTION "public"."review_payment_operation_evidence"("p_evidence_id" "uuid", "p_shareable" boolean, "p_single_operation_attested" boolean, "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_payment_request_extraordinary"("p_payment_request_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_authorization public.payment_request_extraordinary_authorizations%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_reason is null or char_length(v_reason) < 20 then
    raise exception 'revocation_reason_too_short';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended(p_payment_request_id::text, 37037)
  );
  select * into v_authorization
  from public.payment_request_extraordinary_authorizations
  where payment_request_id = p_payment_request_id
    and status in ('draft', 'active')
  order by authorized_at desc, id desc
  limit 1
  for update;
  if not found then
    raise exception 'active_extraordinary_authorization_not_found';
  end if;
  perform public.extraordinary_require_finance_for_company(
    v_authorization.company_id
  );
  if v_authorization.status not in ('draft', 'active') then
    raise exception 'extraordinary_authorization_not_revocable';
  end if;
  perform set_config('app.extraordinary_internal', 'on', true);
  update public.payment_request_extraordinary_authorizations
  set status = 'revoked',
      revoked_by = v_actor,
      revoked_at = v_now,
      revoke_reason = v_reason,
      updated_at = v_now
  where id = v_authorization.id;
  perform public.extraordinary_append_event(
    v_authorization.id,
    'authorization_revoked',
    v_actor,
    'authorization-revoked:' || v_authorization.id::text,
    jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object(
    'authorization_id', v_authorization.id,
    'status', 'revoked',
    'revoked_at', v_now
  );
end
$$;


ALTER FUNCTION "public"."revoke_payment_request_extraordinary"("p_payment_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rotate_payment_matching_policy"("p_currency" "text", "p_minor_unit_scale" smallint, "p_tolerance_minor" bigint, "p_effective_at" timestamp with time zone, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_currency text := public.payment_reconciliation_normalize_currency(p_currency);
  v_effective_at timestamptz;
  v_current public.payment_matching_policy_versions%rowtype;
  v_existing public.payment_matching_policy_versions%rowtype;
  v_new public.payment_matching_policy_versions%rowtype;
begin
  if v_actor is null then raise exception 'not_authenticated'; end if;
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'sysadmin_role_required';
  end if;
  if p_minor_unit_scale is null or p_minor_unit_scale not between 0 and 6
     or p_tolerance_minor is null
     or p_tolerance_minor not between 0 and 9007199254740991 then
    raise exception 'invalid_payment_matching_policy';
  end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 200 then
    raise exception 'invalid_idempotency_key';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('payment_matching_policy:' || v_currency, 32032));
  select * into v_existing
  from public.payment_matching_policy_versions policy
  where policy.currency = v_currency
    and policy.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.currency <> v_currency
       or v_existing.minor_unit_scale <> p_minor_unit_scale
       or v_existing.tolerance_minor <> p_tolerance_minor
       or v_existing.created_by is distinct from v_actor
       or (p_effective_at is not null and v_existing.valid_from <> p_effective_at) then
      raise exception 'idempotency_key_conflict';
    end if;
    return jsonb_build_object(
      'currency', v_existing.currency,
      'policy_id', v_existing.id,
      'valid_from', v_existing.valid_from,
      'version', v_existing.version
    );
  end if;

  v_effective_at := coalesce(p_effective_at, clock_timestamp());
  if v_effective_at < clock_timestamp() - interval '1 minute'
     or v_effective_at > clock_timestamp() + interval '1 year' then
    raise exception 'invalid_policy_effective_at';
  end if;
  select * into v_current
  from public.payment_matching_policy_versions policy
  where policy.currency = v_currency and policy.valid_to is null
  for update;
  if not found then raise exception 'active_currency_policy_not_found'; end if;
  if p_minor_unit_scale <> v_current.minor_unit_scale then
    raise exception 'currency_minor_unit_scale_is_immutable';
  end if;
  if v_effective_at <= v_current.valid_from then
    raise exception 'policy_effective_at_must_advance';
  end if;

  update public.payment_matching_policy_versions
  set valid_to = v_effective_at, retired_by = v_actor
  where id = v_current.id;
  insert into public.payment_matching_policy_versions(
    currency, version, minor_unit_scale, tolerance_minor, valid_from,
    created_by, idempotency_key
  ) values (
    v_currency, v_current.version + 1, p_minor_unit_scale,
    p_tolerance_minor, v_effective_at, v_actor, p_idempotency_key
  ) returning * into v_new;
  return jsonb_build_object(
    'currency', v_new.currency,
    'policy_id', v_new.id,
    'valid_from', v_new.valid_from,
    'version', v_new.version
  );
end
$$;


ALTER FUNCTION "public"."rotate_payment_matching_policy"("p_currency" "text", "p_minor_unit_scale" smallint, "p_tolerance_minor" bigint, "p_effective_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_provider_catalog_with_payment_execution_data"("p_proveedor_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_before public.proveedores%rowtype;
  v_after public.proveedores%rowtype;
  v_provider_id uuid;
  v_is_create boolean := p_proveedor_id is null;
  v_execution_changed boolean := false;
  v_execution_supplied boolean := false;
  v_execution_fields text[];
  v_missing_after text[];
  v_unsupported_keys text[];
  v_now timestamptz := clock_timestamp();
begin
  if p_payload is null or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception 'provider_payload_object_required';
  end if;

  select coalesce(
    array_agg(payload_key.key_name order by payload_key.key_name),
    array[]::text[]
  )
    into v_unsupported_keys
  from jsonb_object_keys(p_payload) as payload_key(key_name)
  where not (
    payload_key.key_name = any(array[
      'alias',
      'nombre_completo',
      'metodo_pago',
      'tipo_cuenta',
      'destination_type',
      'beneficiary_name',
      'banco',
      'clabe',
      'cuenta_bancaria',
      'convenio_number',
      'rfc',
      'persona_tipo',
      'email',
      'telefono',
      'tipo_proveedor',
      'notas',
      'es_personal_eventual',
      'activo',
      'updated_at'
    ]::text[])
  );

  if cardinality(v_unsupported_keys) > 0 then
    raise exception 'provider_payload_contains_unsupported_fields'
      using detail = array_to_string(v_unsupported_keys, ', ');
  end if;

  v_actor := public.approval_batch_require_actor();
  if not exists (
    select 1
    from public.profiles profile
    where profile.id = v_actor
      and coalesce(profile.active, false)
  ) then
    raise exception 'profile_inactive';
  end if;

  if v_is_create then
    if not public.current_user_has_role(public.flux_member_roles()) then
      raise exception 'provider_create_role_required';
    end if;

    v_provider_id := gen_random_uuid();
    perform pg_advisory_xact_lock(
      hashtextextended(v_provider_id::text, 21036)
    );
    v_after := jsonb_populate_record(
      null::public.proveedores,
      p_payload - 'updated_at'
    );
    v_after.id := v_provider_id;
    v_after.activo := coalesce(v_after.activo, true);
    v_after.es_personal_eventual :=
      coalesce(v_after.es_personal_eventual, false);
  else
    if not public.current_user_has_role(public.flux_approver_roles()) then
      raise exception 'provider_update_role_required';
    end if;

    perform pg_advisory_xact_lock(
      hashtextextended(p_proveedor_id::text, 21036)
    );

    select *
      into v_before
    from public.proveedores provider
    where provider.id = p_proveedor_id
    for update;

    if not found then
      raise exception 'proveedor_not_found';
    end if;

    v_provider_id := v_before.id;
    v_after := jsonb_populate_record(
      v_before,
      p_payload - 'updated_at'
    );
  end if;

  v_after.destination_type :=
    lower(nullif(btrim(coalesce(v_after.destination_type, '')), ''));
  v_after.clabe := nullif(
    regexp_replace(
      coalesce(v_after.clabe, ''),
      '[[:space:]-]',
      '',
      'g'
    ),
    ''
  );
  v_after.cuenta_bancaria := nullif(
    regexp_replace(
      coalesce(v_after.cuenta_bancaria, ''),
      '[[:space:]-]',
      '',
      'g'
    ),
    ''
  );
  v_after.convenio_number :=
    nullif(btrim(coalesce(v_after.convenio_number, '')), '');
  v_after.beneficiary_name :=
    nullif(btrim(coalesce(v_after.beneficiary_name, '')), '');
  v_after.banco := nullif(
    regexp_replace(
      btrim(coalesce(v_after.banco, '')),
      '[[:space:]]+',
      ' ',
      'g'
    ),
    ''
  );

  if nullif(btrim(coalesce(v_after.alias, '')), '') is null
     or nullif(btrim(coalesce(v_after.nombre_completo, '')), '') is null
     or nullif(
       btrim(coalesce(v_after.metodo_pago::text, '')),
       ''
     ) is null then
    raise exception 'provider_core_fields_required';
  end if;

  v_execution_supplied :=
    v_after.destination_type is not null
    or v_after.clabe is not null
    or v_after.cuenta_bancaria is not null
    or v_after.convenio_number is not null
    or v_after.beneficiary_name is not null
    or v_after.banco is not null;

  v_execution_changed := v_is_create and v_execution_supplied;
  if not v_is_create then
    v_execution_changed := row(
      v_before.destination_type,
      v_before.clabe,
      v_before.cuenta_bancaria,
      v_before.convenio_number,
      v_before.beneficiary_name,
      v_before.banco
    ) is distinct from row(
      v_after.destination_type,
      v_after.clabe,
      v_after.cuenta_bancaria,
      v_after.convenio_number,
      v_after.beneficiary_name,
      v_after.banco
    );
  end if;

  if v_execution_changed then
    if not coalesce(v_after.activo, false) then
      raise exception 'proveedor_not_found_or_inactive';
    end if;
    perform public.approval_batch_require_finance();
    perform set_config(
      'flux.provider_payment_execution_rpc',
      v_provider_id::text,
      true
    );
  end if;

  v_missing_after :=
    public.provider_payment_execution_missing_fields(v_after);
  if v_missing_after && array[
    'beneficiary_name_invalid',
    'banco_invalid',
    'destination_type_invalid',
    'clabe_invalid',
    'cuenta_bancaria_invalid',
    'convenio_number_invalid'
  ]::text[] then
    raise exception 'provider_payment_execution_data_invalid';
  end if;

  if v_is_create then
    insert into public.proveedores(
      id,
      alias,
      nombre_completo,
      metodo_pago,
      tipo_cuenta,
      destination_type,
      beneficiary_name,
      banco,
      clabe,
      cuenta_bancaria,
      convenio_number,
      rfc,
      persona_tipo,
      email,
      telefono,
      tipo_proveedor,
      notas,
      es_personal_eventual,
      activo,
      updated_at
    ) values (
      v_after.id,
      v_after.alias,
      v_after.nombre_completo,
      v_after.metodo_pago,
      v_after.tipo_cuenta,
      v_after.destination_type,
      v_after.beneficiary_name,
      v_after.banco,
      v_after.clabe,
      v_after.cuenta_bancaria,
      v_after.convenio_number,
      v_after.rfc,
      v_after.persona_tipo,
      v_after.email,
      v_after.telefono,
      v_after.tipo_proveedor,
      v_after.notas,
      v_after.es_personal_eventual,
      v_after.activo,
      v_now
    )
    returning * into v_after;

    if v_execution_changed then
      v_execution_fields := array_remove(array[
        case
          when v_after.destination_type is not null
            then 'destination_type'
        end,
        case when v_after.clabe is not null then 'clabe' end,
        case
          when v_after.cuenta_bancaria is not null
            then 'cuenta_bancaria'
        end,
        case
          when v_after.convenio_number is not null
            then 'convenio_number'
        end,
        case
          when v_after.beneficiary_name is not null
            then 'beneficiary_name'
        end,
        case when v_after.banco is not null then 'banco' end
      ]::text[], null);

      v_missing_after :=
        public.provider_payment_execution_missing_fields(v_after);

      insert into public.activity_log(
        entity_type,
        entity_id,
        action,
        old_values,
        new_values,
        performed_by,
        performed_at,
        notes
      ) values (
        'proveedor',
        v_after.id,
        'payment_execution_data_created',
        jsonb_build_object(
          'layout_data_complete', false,
          'missing_fields', '[]'::jsonb
        ),
        jsonb_build_object(
          'changed_fields', to_jsonb(v_execution_fields),
          'completed_fields', to_jsonb(v_execution_fields),
          'layout_data_complete', cardinality(v_missing_after) = 0,
          'missing_fields', to_jsonb(v_missing_after)
        ),
        v_actor,
        v_now,
        'Provider created through the authorized catalog RPC; banking values intentionally omitted.'
      );
    end if;
  else
    update public.proveedores provider
    set alias = v_after.alias,
        nombre_completo = v_after.nombre_completo,
        metodo_pago = v_after.metodo_pago,
        tipo_cuenta = v_after.tipo_cuenta,
        destination_type = v_after.destination_type,
        beneficiary_name = v_after.beneficiary_name,
        banco = v_after.banco,
        clabe = v_after.clabe,
        cuenta_bancaria = v_after.cuenta_bancaria,
        convenio_number = v_after.convenio_number,
        rfc = v_after.rfc,
        persona_tipo = v_after.persona_tipo,
        email = v_after.email,
        telefono = v_after.telefono,
        tipo_proveedor = v_after.tipo_proveedor,
        notas = v_after.notas,
        es_personal_eventual = v_after.es_personal_eventual,
        activo = v_after.activo,
        updated_at = v_now
    where provider.id = v_provider_id
    returning * into v_after;
  end if;

  return jsonb_build_object('id', v_after.id);
end
$$;


ALTER FUNCTION "public"."save_provider_catalog_with_payment_execution_data"("p_proveedor_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_provider_catalog_with_payment_execution_data"("p_proveedor_id" "uuid", "p_payload" "jsonb") IS 'Atomic provider catalog save with a strict payload allowlist; banking changes require Finance and the RPC-only marker.';



CREATE OR REPLACE FUNCTION "public"."set_approval_batch_company_enforcement"("p_company_id" "uuid", "p_enabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_existing public.approval_batch_company_settings%rowtype;
  v_row public.approval_batch_company_settings%rowtype;
  v_previous_enabled boolean;
begin
  v_actor := public.approval_batch_require_finance();
  if p_company_id is null or p_enabled is null then
    raise exception 'company_and_enabled_required';
  end if;
  if not exists (
    select 1 from public.companies c
    where c.id = p_company_id and coalesce(c.active, true)
  ) then
    raise exception 'company_not_found_or_inactive';
  end if;
  if p_enabled and not exists (
    select 1
    from public.company_directors cd
    join public.profiles p on p.id = cd.director_profile_id
    where cd.company_id = p_company_id
      and cd.active
      and coalesce(p.active, true)
      and exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.profile_id = cd.director_profile_id
          and lower(btrim(r.name)) = any (public.approval_batch_direction_roles())
      )
  ) then
    raise exception 'company_director_required';
  end if;

  select * into v_existing
  from public.approval_batch_company_settings
  where company_id = p_company_id
  for update;
  v_previous_enabled := case
    when found then v_existing.regular_payments_require_closed_batch
    else null
  end;

  if found
     and v_existing.enforcement_started_at is not null
     and not p_enabled then
    raise exception 'batch_enforcement_cannot_be_disabled_in_mvp';
  end if;

  if not found then
    insert into public.approval_batch_company_settings(
      company_id,
      regular_payments_require_closed_batch,
      enforcement_started_at,
      enabled_by,
      enabled_at,
      updated_by
    ) values (
      p_company_id,
      p_enabled,
      case when p_enabled then now() else null end,
      case when p_enabled then v_actor else null end,
      case when p_enabled then now() else null end,
      v_actor
    )
    returning * into v_row;
  else
    update public.approval_batch_company_settings
    set regular_payments_require_closed_batch = p_enabled,
        enforcement_started_at = case
          when p_enabled and v_existing.enforcement_started_at is null then now()
          else v_existing.enforcement_started_at
        end,
        enabled_by = case
          when p_enabled and v_existing.enforcement_started_at is null then v_actor
          else v_existing.enabled_by
        end,
        enabled_at = case
          when p_enabled and v_existing.enforcement_started_at is null then now()
          else v_existing.enabled_at
        end,
        updated_by = v_actor,
        updated_at = now()
    where company_id = p_company_id
    returning * into v_row;
  end if;

  if v_previous_enabled is distinct from p_enabled then
    insert into public.approval_batch_company_setting_events(
      company_id,
      previous_enabled,
      new_enabled,
      changed_by
    ) values (
      p_company_id,
      v_previous_enabled,
      p_enabled,
      v_actor
    );
  end if;

  return jsonb_build_object(
    'company_id', v_row.company_id,
    'regular_payments_require_closed_batch', v_row.regular_payments_require_closed_batch,
    'enforcement_started_at', v_row.enforcement_started_at,
    'updated_at', v_row.updated_at
  );
end
$$;


ALTER FUNCTION "public"."set_approval_batch_company_enforcement"("p_company_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";


