CREATE OR REPLACE FUNCTION "public"."set_company_batch_configuration"("p_company_id" "uuid", "p_director_profile_id" "uuid", "p_director_active" boolean, "p_enable_enforcement" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_director_id uuid;
  v_existing public.approval_batch_company_settings%rowtype;
  v_setting public.approval_batch_company_settings%rowtype;
  v_previous_enabled boolean;
  v_now timestamptz := clock_timestamp();
begin
  v_actor := public.approval_batch_require_finance();
  if p_company_id is null
     or p_director_profile_id is null
     or p_director_active is null
     or p_enable_enforcement is null then
    raise exception 'company_batch_configuration_required';
  end if;

  perform 1
  from public.companies c
  where c.id = p_company_id
    and coalesce(c.active, true)
  for update;
  if not found then raise exception 'company_not_found_or_inactive'; end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_director_profile_id
      and coalesce(p.active, true)
  ) then
    raise exception 'director_profile_not_found_or_inactive';
  end if;
  if p_director_active and not exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = p_director_profile_id
      and lower(btrim(r.name)) = any (public.approval_batch_direction_roles())
  ) then
    raise exception 'director_role_required';
  end if;
  if p_enable_enforcement and not p_director_active then
    raise exception 'company_director_required';
  end if;

  select cd.id into v_director_id
  from public.company_directors cd
  where cd.company_id = p_company_id
    and cd.director_profile_id = p_director_profile_id
  order by cd.created_at desc
  limit 1
  for update;

  if v_director_id is null then
    insert into public.company_directors(
      company_id,
      director_profile_id,
      active,
      created_by
    ) values (
      p_company_id,
      p_director_profile_id,
      p_director_active,
      v_actor
    )
    returning id into v_director_id;
  else
    update public.company_directors
    set active = p_director_active,
        updated_at = v_now
    where id = v_director_id;
  end if;

  select * into v_existing
  from public.approval_batch_company_settings
  where company_id = p_company_id
  for update;
  v_previous_enabled := case
    when found then v_existing.regular_payments_require_closed_batch
    else null
  end;

  if found
     and v_existing.enforcement_started_at is not null
     and not p_enable_enforcement then
    raise exception 'batch_enforcement_cannot_be_disabled_in_mvp';
  end if;

  if not found then
    insert into public.approval_batch_company_settings(
      company_id,
      regular_payments_require_closed_batch,
      enforcement_started_at,
      enabled_by,
      enabled_at,
      updated_by,
      updated_at
    ) values (
      p_company_id,
      p_enable_enforcement,
      case when p_enable_enforcement then v_now else null end,
      case when p_enable_enforcement then v_actor else null end,
      case when p_enable_enforcement then v_now else null end,
      v_actor,
      v_now
    )
    returning * into v_setting;
  else
    update public.approval_batch_company_settings
    set regular_payments_require_closed_batch = p_enable_enforcement,
        enforcement_started_at = case
          when p_enable_enforcement and v_existing.enforcement_started_at is null then v_now
          else v_existing.enforcement_started_at
        end,
        enabled_by = case
          when p_enable_enforcement and v_existing.enforcement_started_at is null then v_actor
          else v_existing.enabled_by
        end,
        enabled_at = case
          when p_enable_enforcement and v_existing.enforcement_started_at is null then v_now
          else v_existing.enabled_at
        end,
        updated_by = v_actor,
        updated_at = v_now
    where company_id = p_company_id
    returning * into v_setting;
  end if;

  insert into public.approval_batch_company_setting_events(
    company_id,
    event_type,
    previous_enabled,
    new_enabled,
    director_profile_id,
    director_active,
    changed_by,
    changed_at
  ) values (
    p_company_id,
    'company_batch_configuration',
    v_previous_enabled,
    p_enable_enforcement,
    p_director_profile_id,
    p_director_active,
    v_actor,
    v_now
  );

  return jsonb_build_object(
    'company_id', p_company_id,
    'director_id', v_director_id,
    'director_profile_id', p_director_profile_id,
    'director_active', p_director_active,
    'regular_payments_require_closed_batch', v_setting.regular_payments_require_closed_batch,
    'enforcement_started_at', v_setting.enforcement_started_at,
    'enabled_by', v_setting.enabled_by,
    'enabled_at', v_setting.enabled_at,
    'updated_at', v_setting.updated_at
  );
end
$$;


ALTER FUNCTION "public"."set_company_batch_configuration"("p_company_id" "uuid", "p_director_profile_id" "uuid", "p_director_active" boolean, "p_enable_enforcement" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_company_director"("p_company_id" "uuid", "p_director_profile_id" "uuid", "p_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_id uuid;
begin
  v_actor := public.approval_batch_require_finance();
  if not exists (select 1 from public.companies where id = p_company_id and coalesce(active, true)) then
    raise exception 'company_not_found_or_inactive';
  end if;
  if not exists (select 1 from public.profiles where id = p_director_profile_id and coalesce(active, true)) then
    raise exception 'director_profile_not_found_or_inactive';
  end if;
  if coalesce(p_active, true) and not exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.profile_id = p_director_profile_id
      and lower(btrim(r.name)) = any (public.approval_batch_direction_roles())
  ) then
    raise exception 'director_role_required';
  end if;

  select id into v_id
  from public.company_directors
  where company_id = p_company_id
    and director_profile_id = p_director_profile_id
  order by created_at desc
  limit 1
  for update;

  if v_id is null then
    insert into public.company_directors(company_id, director_profile_id, active, created_by)
    values (p_company_id, p_director_profile_id, coalesce(p_active, true), v_actor)
    returning id into v_id;
  else
    update public.company_directors
      set active = coalesce(p_active, true), updated_at = now()
    where id = v_id;
  end if;

  return jsonb_build_object('id', v_id, 'active', coalesce(p_active, true));
end
$$;


ALTER FUNCTION "public"."set_company_director"("p_company_id" "uuid", "p_director_profile_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_extraordinary_payment_policy"("p_company_id" "uuid", "p_enabled" boolean, "p_max_amount_mxn" numeric, "p_allowed_categories" "text"[], "p_authorization_valid_hours" integer, "p_ratification_due_hours" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_policy public.extraordinary_payment_policies%rowtype;
begin
  if v_actor is null
     or not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'sysadmin_role_required';
  end if;
  if not exists (
    select 1 from public.profiles where id = v_actor and active
  ) then
    raise exception 'active_profile_required';
  end if;

  insert into public.extraordinary_payment_policies(
    company_id,
    enabled,
    max_amount_mxn,
    allowed_categories,
    authorization_valid_hours,
    ratification_due_hours,
    evidence_required,
    created_by,
    updated_by
  ) values (
    p_company_id,
    coalesce(p_enabled, false),
    p_max_amount_mxn,
    array(
      select distinct lower(btrim(category))
      from unnest(p_allowed_categories) category
      order by 1
    ),
    p_authorization_valid_hours,
    p_ratification_due_hours,
    false,
    v_actor,
    v_actor
  )
  on conflict (company_id) do update
  set enabled = excluded.enabled,
      max_amount_mxn = excluded.max_amount_mxn,
      allowed_categories = excluded.allowed_categories,
      authorization_valid_hours = excluded.authorization_valid_hours,
      ratification_due_hours = excluded.ratification_due_hours,
      evidence_required = false,
      updated_by = v_actor,
      updated_at = clock_timestamp()
  returning * into v_policy;

  return jsonb_build_object(
    'company_id', v_policy.company_id,
    'enabled', v_policy.enabled,
    'max_amount_mxn', v_policy.max_amount_mxn,
    'allowed_categories', v_policy.allowed_categories,
    'authorization_valid_hours', v_policy.authorization_valid_hours,
    'ratification_due_hours', v_policy.ratification_due_hours,
    'evidence_required', false
  );
end
$$;


ALTER FUNCTION "public"."set_extraordinary_payment_policy"("p_company_id" "uuid", "p_enabled" boolean, "p_max_amount_mxn" numeric, "p_allowed_categories" "text"[], "p_authorization_valid_hours" integer, "p_ratification_due_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_extraordinary_profile_faculty"("p_profile_id" "uuid", "p_company_id" "uuid", "p_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := public.current_profile_id();
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_enabled boolean := coalesce(p_enabled, false);
begin
  if v_actor is null
     or not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'sysadmin_role_required';
  end if;
  if v_reason is null or char_length(v_reason) not between 10 and 500 then
    raise exception 'extraordinary_faculty_reason_required';
  end if;
  if not exists (
    select 1
    from public.profiles profile
    where profile.id = p_profile_id and coalesce(profile.active, true)
  ) then
    raise exception 'active_profile_required';
  end if;
  if not exists (
    select 1
    from public.profile_company_memberships membership
    where membership.profile_id = p_profile_id
      and membership.company_id = p_company_id
      and membership.active
  ) then
    raise exception 'active_company_membership_required';
  end if;

  insert into public.extraordinary_profile_faculties(
    profile_id, company_id, enabled, granted_by, granted_at,
    revoked_by, revoked_at, reason, updated_at
  ) values (
    p_profile_id, p_company_id, v_enabled, v_actor, clock_timestamp(),
    case when v_enabled then null else v_actor end,
    case when v_enabled then null else clock_timestamp() end,
    v_reason, clock_timestamp()
  )
  on conflict (profile_id, company_id) do update
  set enabled = excluded.enabled,
      granted_by = case
        when excluded.enabled then v_actor
        else extraordinary_profile_faculties.granted_by
      end,
      granted_at = case
        when excluded.enabled then clock_timestamp()
        else extraordinary_profile_faculties.granted_at
      end,
      revoked_by = case when excluded.enabled then null else v_actor end,
      revoked_at = case
        when excluded.enabled then null else clock_timestamp()
      end,
      reason = excluded.reason,
      updated_at = clock_timestamp();

  insert into public.extraordinary_profile_faculty_events(
    profile_id, company_id, enabled, actor_profile_id, reason
  ) values (
    p_profile_id, p_company_id, v_enabled, v_actor, v_reason
  );

  return jsonb_build_object(
    'profile_id', p_profile_id,
    'company_id', p_company_id,
    'enabled', v_enabled
  );
end
$$;


ALTER FUNCTION "public"."set_extraordinary_profile_faculty"("p_profile_id" "uuid", "p_company_id" "uuid", "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_profile_company_membership"("p_profile_id" "uuid", "p_company_id" "uuid", "p_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.current_user_has_role(public.flux_sysadmin_roles()) then
    raise exception 'routing_admin_required';
  end if;
  if not exists (select 1 from public.profiles where id = p_profile_id and coalesce(active, true)) then
    raise exception 'profile_not_found_or_inactive';
  end if;
  if not exists (select 1 from public.companies where id = p_company_id and coalesce(active, true)) then
    raise exception 'company_not_found_or_inactive';
  end if;

  insert into public.profile_company_memberships(profile_id, company_id, active)
  values (p_profile_id, p_company_id, coalesce(p_active, true))
  on conflict (profile_id, company_id)
  do update set active = excluded.active
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."set_profile_company_membership"("p_profile_id" "uuid", "p_company_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_provider_intake_match"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_expected_current_match" "uuid", "p_proveedor_id" "uuid", "p_reason" "text", "p_reason_code" "text", "p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor jsonb;
  v_actor_profile_id uuid;
  v_actor_type text;
  v_intake public.payment_intake%rowtype;
  v_provider public.proveedores%rowtype;
  v_reason text;
  v_reason_code text;
  v_action_kind text;
  v_action_fingerprint text;
  v_score integer := 0;
  v_confidence text := 'none';
  v_existing_event record;
begin
  if p_payment_intake_id is null
     or p_expected_status is null
     or p_expected_updated_at is null
     or p_reason_code is null
     or p_action_id is null then
    raise exception 'provider_intake_match_fields_required';
  end if;

  v_actor := public.provider_intake_actor_context();
  v_actor_profile_id := (v_actor ->> 'profile_id')::uuid;
  v_actor_type := v_actor ->> 'actor_type';
  v_reason := nullif(regexp_replace(btrim(coalesce(p_reason, '')), '[[:space:]]+', ' ', 'g'), '');
  v_reason_code := lower(btrim(p_reason_code));

  if p_expected_current_match is null and p_proveedor_id is not null then
    v_action_kind := 'match_set';
  elsif p_expected_current_match is not null and p_proveedor_id is null then
    v_action_kind := 'match_clear';
  elsif p_expected_current_match is not null
        and p_proveedor_id is not null
        and p_expected_current_match is distinct from p_proveedor_id then
    v_action_kind := 'match_replace';
  else
    raise exception 'provider_intake_match_unchanged';
  end if;

  if v_reason_code not in (
    'candidate_selected',
    'manual_search',
    'duplicate_resolution',
    'match_corrected',
    'no_longer_matches',
    'other'
  ) then
    raise exception 'provider_intake_match_reason_code_invalid';
  end if;

  if v_action_kind in ('match_replace', 'match_clear')
     and (v_reason is null or length(v_reason) < 10 or length(v_reason) > 500) then
    raise exception 'provider_intake_match_reason_required';
  end if;
  if v_reason is not null and (
    length(v_reason) > 500
    or v_reason ~ '[[:cntrl:]]'
    or v_reason ~ '<[^>]*>'
    or v_reason ~ '@'
    or v_reason ~ '[0-9]{8,}'
    or upper(v_reason) ~ '[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}'
  ) then
    raise exception 'provider_intake_match_reason_sensitive';
  end if;

  v_action_fingerprint := public.provider_intake_match_fingerprint(
    3,
    v_action_kind,
    p_payment_intake_id,
    v_actor_profile_id,
    p_expected_status,
    p_expected_updated_at,
    p_expected_current_match,
    p_proveedor_id,
    v_reason_code,
    v_reason
  );

  select *
    into v_intake
  from public.payment_intake
  where id = p_payment_intake_id
  for update;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  select
    pie.id,
    pie.actor_profile_id,
    pie.metadata ->> 'action_fingerprint' as action_fingerprint,
    pie.metadata ->> 'action_kind' as action_kind,
    pie.metadata ->> 'contract_version' as contract_version
    into v_existing_event
  from public.payment_intake_events pie
  where pie.payment_intake_id = p_payment_intake_id
    and pie.metadata ->> 'action_id' = p_action_id::text
  limit 1;

  if found then
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from v_action_kind
       or v_existing_event.contract_version is distinct from '3'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;
    return jsonb_build_object(
      'payment_intake_id', v_intake.id,
      'status', v_intake.status,
      'matched_proveedor_id', v_intake.matched_proveedor_id,
      'updated_at', v_intake.updated_at,
      'action_kind', v_action_kind,
      'idempotent', true
    );
  end if;

  if v_intake.status is distinct from p_expected_status
     or v_intake.updated_at is distinct from p_expected_updated_at
     or v_intake.matched_proveedor_id is distinct from p_expected_current_match then
    raise exception 'provider_intake_conflict';
  end if;

  if v_intake.status <> 'in_review' then
    raise exception 'provider_intake_match_status_invalid';
  end if;
  if v_intake.created_payment_request_id is not null then
    raise exception 'provider_intake_match_converted';
  end if;

  if p_proveedor_id is not null then
    select *
      into v_provider
    from public.proveedores
    where id = p_proveedor_id;

    if not found then
      raise exception 'provider_intake_provider_not_found';
    end if;
    if not coalesce(v_provider.activo, true) then
      raise exception 'provider_intake_provider_inactive';
    end if;

    v_score := least(
      100,
      (case when nullif(v_intake.provider_rfc, '') is not null
                   and upper(regexp_replace(v_intake.provider_rfc, '[[:space:]-]+', '', 'g'))
                     = upper(regexp_replace(coalesce(v_provider.rfc, ''), '[[:space:]-]+', '', 'g'))
             then 70 else 0 end)
      + (case when public.normalize_provider_match_digits(v_intake.bank_clabe) is not null
                   and public.normalize_provider_match_digits(v_intake.bank_clabe)
                     = public.normalize_provider_match_digits(v_provider.clabe)
              then 45 else 0 end)
      + (case when public.normalize_provider_match_digits(v_intake.bank_account) is not null
                   and public.normalize_provider_match_digits(v_intake.bank_account)
                     = public.normalize_provider_match_digits(v_provider.cuenta_bancaria)
              then 30 else 0 end)
      + (case
          when public.normalize_provider_match_text(v_intake.provider_name)
            = public.normalize_provider_match_text(v_provider.nombre_completo) then 25
          when length(public.normalize_provider_match_text(v_intake.provider_name)) >= 4
               and (
                 public.normalize_provider_match_text(v_provider.nombre_completo)
                   like public.normalize_provider_match_text(v_intake.provider_name) || '%'
                 or public.normalize_provider_match_text(v_intake.provider_name)
                   like public.normalize_provider_match_text(v_provider.nombre_completo) || '%'
               ) then 12
          else 0
        end)
      + (case
          when public.normalize_provider_match_text(v_intake.provider_name)
            = public.normalize_provider_match_text(v_provider.alias) then 15
          when length(public.normalize_provider_match_text(v_intake.provider_name)) >= 4
               and (
                 public.normalize_provider_match_text(v_provider.alias)
                   like public.normalize_provider_match_text(v_intake.provider_name) || '%'
                 or public.normalize_provider_match_text(v_intake.provider_name)
                   like public.normalize_provider_match_text(v_provider.alias) || '%'
               ) then 8
          else 0
        end)
      + (case when lower(btrim(v_intake.provider_email)) = lower(btrim(coalesce(v_provider.email, '')))
              then 5 else 0 end)
      + (case when length(public.normalize_provider_match_digits(v_intake.provider_phone)) >= 7
                   and public.normalize_provider_match_digits(v_intake.provider_phone)
                     = public.normalize_provider_match_digits(v_provider.telefono)
              then 5 else 0 end)
    );
    v_confidence := case
      when v_score >= 70 then 'high'
      when v_score >= 40 then 'medium'
      else 'low'
    end;
  end if;

  update public.payment_intake
     set matched_proveedor_id = p_proveedor_id,
         updated_at = now()
   where id = v_intake.id
     and status = p_expected_status
     and updated_at = p_expected_updated_at
     and matched_proveedor_id is not distinct from p_expected_current_match
     and created_payment_request_id is null
  returning * into v_intake;

  if not found then
    raise exception 'provider_intake_conflict';
  end if;

  insert into public.payment_intake_events (
    payment_intake_id,
    event_type,
    actor_profile_id,
    actor_type,
    from_status,
    to_status,
    notes,
    metadata
  ) values (
    v_intake.id,
    'provider_matched',
    v_actor_profile_id,
    v_actor_type,
    v_intake.status,
    v_intake.status,
    v_reason,
    jsonb_build_object(
      'action_id', p_action_id,
      'action_fingerprint', v_action_fingerprint,
      'action_kind', v_action_kind,
      'contract_version', 3,
      'previous_match_present', p_expected_current_match is not null,
      'new_match_present', p_proveedor_id is not null,
      'previous_proveedor_id', p_expected_current_match,
      'new_proveedor_id', p_proveedor_id,
      'match_confidence', v_confidence,
      'match_score', v_score,
      'reason_code', v_reason_code
    )
  );

  return jsonb_build_object(
    'payment_intake_id', v_intake.id,
    'status', v_intake.status,
    'matched_proveedor_id', v_intake.matched_proveedor_id,
    'updated_at', v_intake.updated_at,
    'action_kind', v_action_kind,
    'match_confidence', v_confidence,
    'match_score', v_score,
    'idempotent', false
  );
exception
  when unique_violation then
    select
      pie.id,
      pie.actor_profile_id,
      pie.metadata ->> 'action_fingerprint' as action_fingerprint,
      pie.metadata ->> 'action_kind' as action_kind,
      pie.metadata ->> 'contract_version' as contract_version
      into v_existing_event
    from public.payment_intake_events pie
    where pie.payment_intake_id = p_payment_intake_id
      and pie.metadata ->> 'action_id' = p_action_id::text
    limit 1;

    if not found then
      raise;
    end if;
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from v_action_kind
       or v_existing_event.contract_version is distinct from '3'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;

    select *
      into v_intake
    from public.payment_intake
    where id = p_payment_intake_id;

    return jsonb_build_object(
      'payment_intake_id', v_intake.id,
      'status', v_intake.status,
      'matched_proveedor_id', v_intake.matched_proveedor_id,
      'updated_at', v_intake.updated_at,
      'action_kind', v_action_kind,
      'idempotent', true
    );
end
$$;


ALTER FUNCTION "public"."set_provider_intake_match"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_expected_current_match" "uuid", "p_proveedor_id" "uuid", "p_reason" "text", "p_reason_code" "text", "p_action_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_provider_intake_match"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_expected_current_match" "uuid", "p_proveedor_id" "uuid", "p_reason" "text", "p_reason_code" "text", "p_action_id" "uuid") IS 'Explicit set, replace, or clear of matched_proveedor_id with optimistic concurrency, material idempotency, and one append-only provider_matched event.';



