CREATE OR REPLACE FUNCTION "public"."submit_approval_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid;
  v_batch public.approval_batches%rowtype;
  v_count integer;
  v_invalid record;
begin
  v_actor := public.approval_batch_require_finance();
  select * into v_batch
  from public.approval_batches
  where id = p_batch_id
  for update;
  if not found then raise exception 'batch_not_found'; end if;
  if v_batch.status <> 'draft' then raise exception 'batch_must_be_draft'; end if;

  select count(*) into v_count
  from public.approval_batch_items abi
  where abi.batch_id = p_batch_id and abi.removed_at is null;
  if v_count = 0 then raise exception 'batch_requires_items'; end if;

  for v_invalid in
    select
      abi.payment_request_id,
      pr.request_number,
      public.approval_batch_request_eligibility(abi.payment_request_id, p_batch_id) as result
    from public.approval_batch_items abi
    join public.payment_requests pr on pr.id = abi.payment_request_id
    where abi.batch_id = p_batch_id
      and abi.removed_at is null
      and not coalesce(
        (public.approval_batch_request_eligibility(abi.payment_request_id, p_batch_id) ->> 'eligible')::boolean,
        false
      )
    order by abi.payment_request_id
  loop
    raise exception 'batch_contains_ineligible_request:%', jsonb_build_object(
      'payment_request_id', v_invalid.payment_request_id,
      'request_number', v_invalid.request_number,
      'classification', v_invalid.result ->> 'classification',
      'reason', v_invalid.result ->> 'reason'
    )::text;
  end loop;

  update public.approval_batches
  set status = 'submitted', submitted_by = v_actor, submitted_at = now()
  where id = p_batch_id;

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'status', 'submitted',
    'item_count', v_count
  );
end
$$;


ALTER FUNCTION "public"."submit_approval_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_cash_reconciliation"("p_reconciliation_id" "uuid", "p_returned_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reconciliation public.cash_reconciliations%rowtype;
  v_fund public.cash_funds%rowtype;
  v_total_tickets numeric := 0;
  v_returned_amount numeric := 0;
  v_accounted_amount numeric := 0;
  v_difference numeric := 0;
begin
  if p_reconciliation_id is null then
    raise exception 'reconciliation_required';
  end if;

  v_returned_amount := coalesce(p_returned_amount, 0);

  if v_returned_amount < 0 then
    raise exception 'returned_amount_cannot_be_negative';
  end if;

  select *
  into v_reconciliation
  from public.cash_reconciliations
  where id = p_reconciliation_id
  for update;

  if not found then
    raise exception 'reconciliation_not_found';
  end if;

  if v_reconciliation.status not in ('draft', 'correction_requested') then
    raise exception 'only_draft_or_correction_can_be_submitted';
  end if;

  select *
  into v_fund
  from public.cash_funds
  where id = v_reconciliation.cash_fund_id
  for update;

  if not found then
    raise exception 'cash_fund_not_found';
  end if;

  select coalesce(sum(amount), 0)
  into v_total_tickets
  from public.cash_reconciliation_items
  where reconciliation_id = p_reconciliation_id
    and status = 'valid';

  v_accounted_amount := v_total_tickets + v_returned_amount;
  v_difference := v_fund.assigned_amount - v_accounted_amount;

  if v_total_tickets <= 0 and v_returned_amount <= 0 then
    raise exception 'reconciliation_has_no_amounts';
  end if;

  if v_accounted_amount > v_fund.assigned_amount then
    raise exception 'reconciliation_exceeds_assigned_amount';
  end if;

  update public.cash_reconciliations
  set
    total_tickets = v_total_tickets,
    returned_amount = v_returned_amount,
    difference_amount = v_difference,
    status = 'submitted'
  where id = p_reconciliation_id;

  update public.cash_funds
  set
    status = 'receipt_review'
  where id = v_fund.id;

  return jsonb_build_object(
    'message', 'cash_reconciliation_submitted',
    'reconciliation_id', p_reconciliation_id,
    'cash_fund_id', v_fund.id,
    'total_tickets', v_total_tickets,
    'returned_amount', v_returned_amount,
    'difference_amount', v_difference,
    'status', 'submitted'
  );
end;
$$;


ALTER FUNCTION "public"."submit_cash_reconciliation"("p_reconciliation_id" "uuid", "p_returned_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_payment_document_extractions"("p_batch_id" "uuid", "p_parser_version" "text", "p_pages" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_batch public.payment_ingestion_batches%rowtype;
  v_document public.payment_documents%rowtype;
  v_actor uuid;
  v_payload jsonb;
  v_hash text;
  v_replay jsonb;
  v_page jsonb;
  v_page_number integer;
  v_amount numeric;
  v_amount_minor bigint;
  v_currency text;
  v_currency_input text;
  v_application_date date;
  v_source_account text;
  v_destination_account text;
  v_source_account_material text;
  v_destination_account_material text;
  v_source_account_hash text;
  v_source_account_last4 text;
  v_destination_account_hash text;
  v_destination_account_last4 text;
  v_bank_name text;
  v_bank_unique_folio text;
  v_bank_status text;
  v_status text;
  v_count integer := 0;
  v_result jsonb;
begin
  select * into v_batch from public.payment_ingestion_batches where id = p_batch_id for update;
  if not found then raise exception 'payment_batch_not_found'; end if;
  v_actor := public.payment_reconciliation_require_finance(v_batch.company_id);
  v_payload := jsonb_build_object(
    'batch_id', p_batch_id,
    'pages', p_pages,
    'parser_version', nullif(btrim(p_parser_version), '')
  );
  v_hash := public.payment_reconciliation_payload_hash(v_payload);
  v_replay := public.payment_reconciliation_command_replay(
    v_batch.company_id, 'payment_batch.submit_extractions', p_idempotency_key, v_hash, v_actor
  );
  if v_replay is not null then return v_replay; end if;
  if p_parser_version is null or char_length(btrim(p_parser_version)) not between 3 and 80 then
    raise exception 'invalid_parser_version';
  end if;
  if p_pages is null
     or jsonb_typeof(p_pages) is distinct from 'array'
     or coalesce(jsonb_array_length(p_pages), 0) not between 1 and 500 then
    raise exception 'invalid_extraction_pages';
  end if;
  if v_batch.page_count is null or jsonb_array_length(p_pages) <> v_batch.page_count then
    raise exception 'extraction_page_count_mismatch';
  end if;
  if v_batch.status <> 'extracting' then raise exception 'payment_batch_not_extracting'; end if;
  select * into v_document from public.payment_documents where batch_id = p_batch_id;

  for v_page in select value from jsonb_array_elements(p_pages)
  loop
    v_page_number := coalesce((v_page->>'page_number')::integer, (v_page->>'pagina')::integer);
    if v_page_number is null or v_page_number not between 1 and v_batch.page_count then
      raise exception 'invalid_extraction_page_number';
    end if;
    v_amount := coalesce((v_page->>'amount')::numeric, (v_page->>'importe')::numeric);
    v_currency_input := nullif(btrim(coalesce(v_page->>'currency', v_page->>'moneda')), '');
    v_currency := case when v_currency_input is null then null
      else public.payment_reconciliation_normalize_currency(v_currency_input) end;
    v_amount_minor := case when v_amount is null or v_amount <= 0 or v_currency is null then null
      else public.payment_amount_to_minor(v_amount, v_currency) end;
    v_application_date := case
      when coalesce(v_page->>'application_date', v_page->>'fecha_aplicacion') ~ '^\d{4}-\d{2}-\d{2}$'
        then coalesce(v_page->>'application_date', v_page->>'fecha_aplicacion')::date
      else null
    end;
    v_source_account := coalesce(v_page->>'source_account', v_page->>'cuenta_retiro');
    v_destination_account := coalesce(v_page->>'destination_account', v_page->>'cuenta_deposito');
    if char_length(coalesce(v_source_account, '')) > 100
       or char_length(coalesce(v_destination_account, '')) > 100 then
      raise exception 'invalid_extracted_account_length';
    end if;
    v_source_account_material := public.payment_reconciliation_account_material(v_source_account);
    v_destination_account_material := public.payment_reconciliation_account_material(v_destination_account);
    v_source_account_hash := null;
    v_destination_account_hash := null;
    if v_source_account_material ~ '^[0-9]{10,18}$' then
      v_source_account_hash := public.payment_reconciliation_account_hash(v_source_account);
    end if;
    if v_destination_account_material ~ '^[0-9]{10,18}$' then
      v_destination_account_hash := public.payment_reconciliation_account_hash(v_destination_account);
    end if;
    v_source_account_last4 := case
      when v_source_account_hash is not null then right(v_source_account_material, 4)
      else upper(nullif(btrim(coalesce(
        v_page->>'source_account_last4',
        public.payment_reconciliation_account_last4(v_source_account)
      )), ''))
    end;
    v_destination_account_last4 := case
      when v_destination_account_hash is not null then right(v_destination_account_material, 4)
      else upper(nullif(btrim(coalesce(
        v_page->>'destination_account_last4',
        public.payment_reconciliation_account_last4(v_destination_account)
      )), ''))
    end;
    if (v_source_account_last4 is not null and v_source_account_last4 !~ '^[A-Z0-9]{1,4}$')
       or (v_destination_account_last4 is not null and v_destination_account_last4 !~ '^[A-Z0-9]{1,4}$') then
      raise exception 'invalid_extracted_account_last4';
    end if;
    v_bank_unique_folio := upper(nullif(btrim(coalesce(
      v_page->>'bank_unique_folio',
      v_page->>'folio_unico'
    )), ''));
    v_bank_name := upper(coalesce(nullif(btrim(coalesce(
      v_page->>'bank_name',
      v_page->>'banco_origen'
    )), ''), 'UNKNOWN'));
    if char_length(v_bank_name) > 80 or v_bank_name ~ '[[:cntrl:]]' then
      raise exception 'invalid_extracted_bank_name';
    end if;
    v_bank_status := nullif(btrim(coalesce(v_page->>'bank_status', v_page->>'estado')), '');
    if (v_bank_status is not null and (
      char_length(v_bank_status) > 40 or v_bank_status ~ '[[:cntrl:]]'
    )) or (v_bank_unique_folio is not null and (
      char_length(v_bank_unique_folio) > 120 or v_bank_unique_folio ~ '[[:cntrl:]]'
    )) then
      raise exception 'invalid_extracted_bank_field';
    end if;
    if v_bank_unique_folio !~ '^[A-Z0-9-]{8,120}$' then
      v_bank_unique_folio := null;
    end if;
    v_status := case
      when v_bank_name = 'BBVA'
        and lower(coalesce(v_bank_status, '')) = 'operado'
        and v_amount_minor is not null and v_currency is not null and v_application_date is not null
        and v_bank_unique_folio is not null
        and v_source_account_hash is not null
        then 'review_required'
      else 'blocked'
    end;

    insert into public.payment_document_extractions(
      document_id, batch_id, company_id, page_number, status, parser_version,
      parser_confidence, bank_name, bank_status, bank_unique_folio,
      application_date, amount_minor, currency, source_account_hash,
      source_account_last4, destination_account_hash, destination_account_last4,
      beneficiary_name, payment_reason, extracted_evidence
    ) values (
      v_document.id, v_batch.id, v_batch.company_id, v_page_number, v_status,
      btrim(p_parser_version), nullif(v_page->>'confidence', '')::numeric,
      v_bank_name,
      v_bank_status, v_bank_unique_folio,
      v_application_date,
      v_amount_minor, v_currency,
      v_source_account_hash,
      v_source_account_last4,
      v_destination_account_hash,
      v_destination_account_last4,
      public.payment_reconciliation_redact_free_text(
        coalesce(v_page->>'beneficiary_name', v_page->>'beneficiario'), 180
      ),
      public.payment_reconciliation_redact_free_text(
        coalesce(v_page->>'payment_reason', v_page->>'motivo_pago'), 500
      ),
      jsonb_strip_nulls(jsonb_build_object(
        'amount_minor', v_amount_minor,
        'application_date', v_application_date,
        'bank_status', v_bank_status,
        'beneficiary_name', public.payment_reconciliation_redact_free_text(
          coalesce(v_page->>'beneficiary_name', v_page->>'beneficiario'), 180
        ),
        'currency', v_currency,
        'destination_account_last4', v_destination_account_last4,
        'page_number', v_page_number,
        'payment_reason', public.payment_reconciliation_redact_free_text(
          coalesce(v_page->>'payment_reason', v_page->>'motivo_pago'), 500
        ),
        'source_account_last4', v_source_account_last4
      ))
    );
    v_count := v_count + 1;
  end loop;

  update public.payment_ingestion_batches
  set status = 'review_required', extraction_count = v_count, error_code = null
  where id = p_batch_id;
  v_result := jsonb_build_object('batch_id', p_batch_id, 'status', 'review_required', 'extraction_count', v_count);
  return public.payment_reconciliation_store_command(
    v_batch.company_id, 'payment_batch.submit_extractions', p_idempotency_key, v_hash, v_actor, v_result
  );
end
$_$;


ALTER FUNCTION "public"."submit_payment_document_extractions"("p_batch_id" "uuid", "p_parser_version" "text", "p_pages" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_payment_request_extraordinary_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_state text;
begin
  v_state := case new.status
    when 'draft' then 'extraordinary_draft'
    when 'active' then 'extraordinary_active'
    when 'consumed_pending_ratification' then 'consumed_pending_ratification'
    when 'ratified' then 'ratified'
    when 'disputed' then 'disputed'
    when 'revoked' then 'revoked'
    when 'expired' then 'expired'
    when 'materially_invalidated' then 'materially_invalidated'
    else null
  end;
  if v_state is not null then
    update public.payment_requests
    set extraordinary_state = v_state,
        updated_at = clock_timestamp()
    where id = new.payment_request_id
      and extraordinary_state is distinct from v_state;
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."sync_payment_request_extraordinary_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_provider_intake"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_to_status" "text", "p_notes" "text", "p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor jsonb;
  v_actor_profile_id uuid;
  v_actor_type text;
  v_intake public.payment_intake%rowtype;
  v_notes text;
  v_event_type text;
  v_action_fingerprint text;
  v_existing_event record;
begin
  if p_payment_intake_id is null
     or p_expected_status is null
     or p_expected_updated_at is null
     or p_to_status is null
     or p_action_id is null then
    raise exception 'provider_intake_transition_fields_required';
  end if;

  v_actor := public.provider_intake_actor_context();
  v_actor_profile_id := (v_actor ->> 'profile_id')::uuid;
  v_actor_type := v_actor ->> 'actor_type';
  v_notes := nullif(btrim(coalesce(p_notes, '')), '');
  v_action_fingerprint := public.provider_intake_action_fingerprint(
    2,
    'transition',
    p_payment_intake_id,
    v_actor_profile_id,
    p_expected_status,
    p_expected_updated_at,
    p_to_status,
    v_notes
  );

  select *
    into v_intake
  from public.payment_intake
  where id = p_payment_intake_id
  for update;

  if not found then
    raise exception 'provider_intake_not_found';
  end if;

  perform public.provider_intake_assert_company_access(v_intake.company_id);

  select
    pie.id,
    pie.actor_profile_id,
    pie.metadata ->> 'action_fingerprint' as action_fingerprint,
    pie.metadata ->> 'action_kind' as action_kind,
    pie.metadata ->> 'contract_version' as contract_version
    into v_existing_event
  from public.payment_intake_events pie
  where pie.payment_intake_id = p_payment_intake_id
    and pie.metadata ->> 'action_id' = p_action_id::text
  limit 1;

  if found then
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from 'transition'
       or v_existing_event.contract_version is distinct from '2'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;
    return jsonb_build_object(
      'payment_intake_id', v_intake.id,
      'public_folio', v_intake.public_folio,
      'status', v_intake.status,
      'updated_at', v_intake.updated_at,
      'idempotent', true
    );
  end if;

  if v_intake.status is distinct from p_expected_status
     or v_intake.updated_at is distinct from p_expected_updated_at then
    raise exception 'provider_intake_conflict';
  end if;

  if not (
    (v_intake.status = 'received' and p_to_status = 'in_review')
    or (v_intake.status = 'in_review' and p_to_status in ('needs_correction', 'rejected'))
    or (v_intake.status = 'needs_correction' and p_to_status in ('in_review', 'rejected'))
  ) then
    raise exception 'provider_intake_invalid_transition';
  end if;

  if p_to_status in ('needs_correction', 'rejected') then
    if v_notes is null or length(v_notes) < 10 or length(v_notes) > 2000 then
      raise exception 'provider_intake_comment_length';
    end if;
    if v_notes ~ '[[:cntrl:]]' or v_notes ~ '<[^>]*>' then
      raise exception 'provider_intake_comment_invalid';
    end if;
  elsif v_notes is not null then
    if length(v_notes) > 2000 or v_notes ~ '[[:cntrl:]]' or v_notes ~ '<[^>]*>' then
      raise exception 'provider_intake_comment_invalid';
    end if;
  end if;

  v_event_type := case p_to_status
    when 'needs_correction' then 'correction_requested'
    when 'rejected' then 'rejected'
    else 'status_changed'
  end;

  update public.payment_intake
     set status = p_to_status,
         triaged_by = coalesce(triaged_by, v_actor_profile_id),
         triaged_at = coalesce(triaged_at, now()),
         rejection_reason = case when p_to_status = 'rejected' then v_notes else null end,
         updated_at = now()
   where id = v_intake.id
     and status = p_expected_status
     and updated_at = p_expected_updated_at
  returning * into v_intake;

  if not found then
    raise exception 'provider_intake_conflict';
  end if;

  insert into public.payment_intake_events (
    payment_intake_id,
    event_type,
    actor_profile_id,
    actor_type,
    from_status,
    to_status,
    notes,
    metadata
  ) values (
    v_intake.id,
    v_event_type,
    v_actor_profile_id,
    v_actor_type,
    p_expected_status,
    p_to_status,
    v_notes,
    jsonb_build_object(
      'action_id', p_action_id,
      'action_fingerprint', v_action_fingerprint,
      'action_kind', 'transition',
      'contract_version', 2
    )
  );

  return jsonb_build_object(
    'payment_intake_id', v_intake.id,
    'public_folio', v_intake.public_folio,
    'status', v_intake.status,
    'updated_at', v_intake.updated_at,
    'idempotent', false
  );
exception
  when unique_violation then
    select
      pie.id,
      pie.actor_profile_id,
      pie.metadata ->> 'action_fingerprint' as action_fingerprint,
      pie.metadata ->> 'action_kind' as action_kind,
      pie.metadata ->> 'contract_version' as contract_version
      into v_existing_event
    from public.payment_intake_events pie
    where pie.payment_intake_id = p_payment_intake_id
      and pie.metadata ->> 'action_id' = p_action_id::text
    limit 1;

    if not found then
      raise;
    end if;
    if v_existing_event.actor_profile_id is distinct from v_actor_profile_id then
      raise exception 'provider_intake_action_id_conflict';
    end if;
    if v_existing_event.action_fingerprint is null
       or v_existing_event.action_kind is null
       or v_existing_event.contract_version is null then
      raise exception 'provider_intake_action_id_legacy_conflict';
    end if;
    if v_existing_event.action_kind is distinct from 'transition'
       or v_existing_event.contract_version is distinct from '2'
       or v_existing_event.action_fingerprint is distinct from v_action_fingerprint then
      raise exception 'provider_intake_action_id_material_conflict';
    end if;

    select *
      into v_intake
    from public.payment_intake
    where id = p_payment_intake_id;

    return jsonb_build_object(
      'payment_intake_id', v_intake.id,
      'public_folio', v_intake.public_folio,
      'status', v_intake.status,
      'updated_at', v_intake.updated_at,
      'idempotent', true
    );
end
$$;


ALTER FUNCTION "public"."transition_provider_intake"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_to_status" "text", "p_notes" "text", "p_action_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transition_provider_intake"("p_payment_intake_id" "uuid", "p_expected_status" "text", "p_expected_updated_at" timestamp with time zone, "p_to_status" "text", "p_notes" "text", "p_action_id" "uuid") IS 'Allowlisted optimistic transition with one append-only event and contract-v2 material idempotency. Conversion remains unsupported.';



CREATE OR REPLACE FUNCTION "public"."update_payment_layout_line_pagosint_reference"("p_line_id" "uuid", "p_payment_reference" "text", "p_beneficiary_name" "text" DEFAULT NULL::"text", "p_payment_concept" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "payment_reference" "text", "beneficiary_name" "text", "payment_concept" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reference text := nullif(regexp_replace(coalesce(p_payment_reference, ''), '\D', '', 'g'), '');
  v_beneficiary text := nullif(btrim(coalesce(p_beneficiary_name, '')), '');
  v_concept text := nullif(btrim(coalesce(p_payment_concept, '')), '');
  v_destination_type text;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if not current_user_has_role(flux_member_roles()) then
    raise exception 'not_authorized_to_update_layout_lines';
  end if;

  if v_reference is null then
    raise exception 'pagosint_reference_required';
  end if;

  if length(v_reference) > 5 then
    raise exception 'pagosint_reference_too_long';
  end if;

  select pll.destination_type
    into v_destination_type
  from public.payment_layout_lines pll
  where pll.id = p_line_id
  for update;

  if not found then
    raise exception 'payment_layout_line_not_found';
  end if;

  if coalesce(v_destination_type, '') <> 'clabe' then
    raise exception 'pagosint_reference_only_for_interbank_lines';
  end if;

  return query
  update public.payment_layout_lines pll
     set payment_reference = v_reference,
         beneficiary_name = coalesce(v_beneficiary, pll.beneficiary_name),
         payment_concept = coalesce(v_concept, pll.payment_concept),
         updated_at = now()
   where pll.id = p_line_id
   returning pll.id, pll.payment_reference, pll.beneficiary_name, pll.payment_concept, pll.updated_at;
end;
$$;


ALTER FUNCTION "public"."update_payment_layout_line_pagosint_reference"("p_line_id" "uuid", "p_payment_reference" "text", "p_beneficiary_name" "text", "p_payment_concept" "text") OWNER TO "postgres";


