CREATE OR REPLACE FUNCTION "public"."validate_approval_batch_final_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_pending integer;
  v_approved integer;
  v_rejected integer;
begin
  if new.status not in ('approved', 'partially_approved', 'closed') then
    return new;
  end if;

  select count(*) filter (where director_status = 'pending'),
         count(*) filter (where director_status = 'approved'),
         count(*) filter (where director_status = 'rejected')
    into v_pending, v_approved, v_rejected
  from public.approval_batch_items
  where batch_id = new.id
    and removed_at is null;

  if v_pending > 0 or (v_approved = 0 and v_rejected = 0) then
    raise exception 'invalid_batch_final_item_mix';
  end if;

  if new.status = 'approved' and (v_approved = 0 or v_rejected > 0) then
    raise exception 'approved_batch_requires_only_approved_items';
  end if;

  if new.status = 'partially_approved' and v_rejected = 0 then
    raise exception 'partial_batch_requires_rejected_items';
  end if;

  if new.status = 'closed' and v_approved = 0 then
    raise exception 'batch_requires_at_least_one_approved_item';
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."validate_approval_batch_final_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_approval_batch_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch_company uuid;
  v_request_company uuid;
begin
  select company_id into v_batch_company
  from public.approval_batches where id = new.batch_id;
  select company_id into v_request_company
  from public.payment_requests where id = new.payment_request_id;

  if v_batch_company is null or v_request_company is null then
    raise exception 'batch_or_request_company_required';
  end if;
  if v_batch_company <> v_request_company then
    raise exception 'batch_request_company_mismatch';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."validate_approval_batch_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_approver_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.requester_id = new.approver_id then
    raise exception 'requester_cannot_be_own_pool_approver';
  end if;

  if new.active then
    if not public.has_active_company_membership(new.requester_id, new.company_id) then
      raise exception 'requester_company_membership_required';
    end if;
    if not public.has_active_company_membership(new.approver_id, new.company_id) then
      raise exception 'approver_company_membership_required';
    end if;
    if not exists (
      select 1
      from public.user_roles ur
      join public.roles r on r.id = ur.role_id
      where ur.profile_id = new.approver_id
        and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
    ) then
      raise exception 'approver_role_required';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_approver_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payment_request_approver_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_assignment public.approver_assignments%rowtype;
  v_assignment_changed boolean;
  v_legacy_assignment_snapshot boolean := false;
begin
  if new.approver_id is null then
    if tg_op = 'INSERT' then
      raise exception 'payment_request_approver_required';
    end if;
    if old.approver_id is not null
       or new.company_id is distinct from old.company_id
       or new.requested_by is distinct from old.requested_by then
      raise exception 'payment_request_approver_required';
    end if;
    return new;
  end if;

  if new.requested_by is null then
    raise exception 'payment_request_requester_required';
  end if;
  if new.requested_by = new.approver_id then
    raise exception 'requester_cannot_be_own_approver';
  end if;
  if tg_op = 'UPDATE' and (
    new.approver_id is distinct from old.approver_id
    or new.approver_assignment_id is distinct from old.approver_assignment_id
    or new.approver_selection_source is distinct from old.approver_selection_source
  ) then
    raise exception 'payment_request_approver_selection_immutable';
  end if;
  v_assignment_changed := tg_op = 'INSERT';
  if tg_op = 'UPDATE' then
    v_assignment_changed := new.approver_assignment_id is distinct from old.approver_assignment_id;
  end if;

  if new.approver_assignment_id is not null then
    if new.approver_selection_source is distinct from 'assigned' then
      raise exception 'approver_assignment_source_mismatch';
    end if;
    select * into v_assignment
    from public.approver_assignments aa
    where aa.id = new.approver_assignment_id;

    if not found
       or v_assignment.company_id <> new.company_id
       or v_assignment.requester_id <> new.requested_by
       or v_assignment.approver_id <> new.approver_id then
      raise exception 'approver_assignment_snapshot_mismatch';
    end if;
    if v_assignment_changed and not v_assignment.active then
      raise exception 'approver_assignment_not_active';
    end if;
    if v_assignment_changed then
      if not public.has_active_company_membership(new.requested_by, new.company_id) then
        raise exception 'requester_company_membership_required';
      end if;
      if not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
        raise exception 'approver_not_eligible_for_company';
      end if;
    end if;
  else
    if new.approver_selection_source = 'assigned' then
      raise exception 'approver_assignment_id_required';
    end if;
    if tg_op = 'INSERT' and new.approver_selection_source is distinct from 'approval_rules' then
      raise exception 'approver_selection_source_required';
    end if;
    if new.approver_selection_source = 'approval_rules'
       and public.payment_request_has_active_approver_pool(new.requested_by, new.company_id) then
      raise exception 'approver_must_come_from_configured_pool';
    end if;

    -- Migration 018 stored only approver_id. If the same assignment already
    -- existed when the request was created, preserve that historical snapshot
    -- when other editable request fields change.
    if tg_op = 'UPDATE'
       and new.approver_selection_source is null
       and new.company_id is not distinct from old.company_id
       and new.requested_by is not distinct from old.requested_by then
      select exists (
        select 1
        from public.approver_assignments aa
        where aa.company_id = new.company_id
          and aa.requester_id = new.requested_by
          and aa.approver_id = new.approver_id
          and aa.created_at <= old.created_at
      ) into v_legacy_assignment_snapshot;
    end if;

    if not v_legacy_assignment_snapshot then
      if not public.has_active_company_membership(new.requested_by, new.company_id) then
        raise exception 'requester_company_membership_required';
      end if;
      if not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
        raise exception 'approver_not_eligible_for_company';
      end if;
      if not public.payment_request_rule_allows(
        new.approver_id,
        new.company_id,
        new.cost_center_id,
        new.amount_requested,
        'approved'
      ) then
        raise exception 'approver_not_allowed_by_approval_rules';
      end if;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payment_request_approver_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_budget_availability"("p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount" numeric, "p_is_extraordinary_adjustment" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_budgeted numeric;
  v_available numeric;
  v_match boolean;
begin
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object(
      'status', 'bloqueado',
      'motivo', 'monto_invalido',
      'disponible_actual', 0,
      'disponible_despues', null,
      'faltante', coalesce(p_amount, 0)
    );
  end if;

  if p_is_extraordinary_adjustment then
    return jsonb_build_object(
      'status', 'bloqueado',
      'motivo', 'ajuste_extraordinario',
      'disponible_actual', 0,
      'disponible_despues', null,
      'faltante', p_amount
    );
  end if;

  select exists (
    select 1
    from public.company_cost_center_budget_categories rel
    where rel.active = true
      and rel.company_id = p_company_id
      and rel.cost_center_id = p_cost_center_id
      and rel.budget_category_id = p_budget_category_id
  ) into v_match;

  if not v_match then
    return jsonb_build_object(
      'status', 'bloqueado',
      'motivo', 'sin_match_presupuesto',
      'disponible_actual', 0,
      'disponible_despues', null,
      'faltante', p_amount
    );
  end if;

  select budgeted, available
  into v_budgeted, v_available
  from public.budget_availability
  where company_id = p_company_id
    and cost_center_id = p_cost_center_id
    and budget_category_id = p_budget_category_id
    and budget_month = date_trunc('month', p_budget_month)::date;

  if v_budgeted is null then
    return jsonb_build_object(
      'status', 'bloqueado',
      'motivo', 'partida_no_presupuestada',
      'disponible_actual', 0,
      'disponible_despues', null,
      'faltante', p_amount
    );
  end if;

  if v_available >= p_amount then
    return jsonb_build_object(
      'status', 'aprobable',
      'motivo', null,
      'disponible_actual', v_available,
      'disponible_despues', v_available - p_amount,
      'faltante', 0
    );
  end if;

  return jsonb_build_object(
    'status', 'bloqueado',
    'motivo', 'sin_disponible',
    'disponible_actual', v_available,
    'disponible_despues', v_available - p_amount,
    'faltante', p_amount - v_available
  );
end;
$$;


ALTER FUNCTION "public"."verify_budget_availability"("p_company_id" "uuid", "p_cost_center_id" "uuid", "p_budget_category_id" "uuid", "p_budget_month" "date", "p_amount" numeric, "p_is_extraordinary_adjustment" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_cash_block"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_overdue_count integer := 0;
  v_total_pending numeric := 0;
  v_funds jsonb := '[]'::jsonb;
begin
  if p_profile_id is null then
    raise exception 'profile_required';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_profile_id
      and coalesce(active, true) = true
  ) then
    raise exception 'profile_not_found';
  end if;

  -- Marcar como blocked los fondos vencidos con saldo pendiente
  update public.cash_funds
  set status = 'blocked'
  where responsible_profile_id = p_profile_id
    and status in ('active', 'pending_receipt')
    and pending_amount > 0
    and due_date < current_date;

  select
    count(*),
    coalesce(sum(pending_amount), 0)
  into
    v_overdue_count,
    v_total_pending
  from public.cash_funds
  where responsible_profile_id = p_profile_id
    and status in ('active', 'pending_receipt', 'blocked', 'receipt_review')
    and pending_amount > 0
    and due_date < current_date;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'cash_fund_id', cf.id,
        'payment_request_id', cf.payment_request_id,
        'assigned_amount', cf.assigned_amount,
        'verified_amount', cf.verified_amount,
        'pending_amount', cf.pending_amount,
        'due_date', cf.due_date,
        'status', cf.status
      )
      order by cf.due_date asc
    ),
    '[]'::jsonb
  )
  into v_funds
  from public.cash_funds cf
  where cf.responsible_profile_id = p_profile_id
    and cf.status in ('active', 'pending_receipt', 'blocked', 'receipt_review')
    and cf.pending_amount > 0
    and cf.due_date < current_date;

  return jsonb_build_object(
    'blocked', v_overdue_count > 0,
    'overdue_count', v_overdue_count,
    'total_pending', v_total_pending,
    'funds', v_funds
  );
end;
$$;


ALTER FUNCTION "public"."verify_cash_block"("p_profile_id" "uuid") OWNER TO "postgres";


