    "finance_reviewed_by" "uuid" NOT NULL,
    "finance_reviewed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "director_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "director_reject_reason" "text",
    "rebatch_status" "text" DEFAULT 'not_applicable'::"text" NOT NULL,
    "rebatch_released_by" "uuid",
    "rebatch_released_at" timestamp with time zone,
    "rebatch_release_note" "text",
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "removed_by" "uuid",
    "removed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "previous_item_id" "uuid",
    "review_sequence" integer DEFAULT 1 NOT NULL,
    "resubmitted_at" timestamp with time zone,
    "resubmitted_by" "uuid",
    "resubmission_note" "text",
    "finance_release_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "finance_release_reason" "text",
    "finance_released_by" "uuid",
    "finance_released_at" timestamp with time zone,
    CONSTRAINT "approval_batch_items_decision_check" CHECK (((("director_status" = 'pending'::"text") AND ("decided_by" IS NULL) AND ("decided_at" IS NULL) AND ("director_reject_reason" IS NULL)) OR (("director_status" = 'approved'::"text") AND ("decided_by" IS NOT NULL) AND ("decided_at" IS NOT NULL) AND ("director_reject_reason" IS NULL)) OR (("director_status" = 'rejected'::"text") AND ("decided_by" IS NOT NULL) AND ("decided_at" IS NOT NULL) AND (NULLIF("btrim"("director_reject_reason"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "approval_batch_items_finance_release_lifecycle_check" CHECK (((("finance_release_status" = 'pending'::"text") AND ("finance_release_reason" IS NULL) AND ("finance_released_by" IS NULL) AND ("finance_released_at" IS NULL)) OR (("finance_release_status" = 'released'::"text") AND ("director_status" = 'approved'::"text") AND ("finance_release_reason" IS NULL) AND ("finance_released_by" IS NOT NULL) AND ("finance_released_at" IS NOT NULL)) OR (("finance_release_status" = 'blocked'::"text") AND (NULLIF("btrim"("finance_release_reason"), ''::"text") IS NOT NULL) AND ("finance_released_by" IS NOT NULL) AND ("finance_released_at" IS NOT NULL)))),
    CONSTRAINT "approval_batch_items_finance_release_status_check" CHECK (("finance_release_status" = ANY (ARRAY['pending'::"text", 'released'::"text", 'blocked'::"text"]))),
    CONSTRAINT "approval_batch_items_rebatch_check" CHECK (((("director_status" <> 'rejected'::"text") AND ("rebatch_status" = 'not_applicable'::"text") AND ("rebatch_released_by" IS NULL) AND ("rebatch_released_at" IS NULL) AND ("rebatch_release_note" IS NULL)) OR (("director_status" = 'rejected'::"text") AND ("rebatch_status" = 'blocked'::"text") AND ("rebatch_released_by" IS NULL) AND ("rebatch_released_at" IS NULL) AND ("rebatch_release_note" IS NULL)) OR (("director_status" = 'rejected'::"text") AND ("rebatch_status" = 'released'::"text") AND ("rebatch_released_by" IS NOT NULL) AND ("rebatch_released_at" IS NOT NULL) AND (NULLIF("btrim"("rebatch_release_note"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "approval_batch_items_rebatch_status_check" CHECK (("rebatch_status" = ANY (ARRAY['not_applicable'::"text", 'blocked'::"text", 'released'::"text"]))),
    CONSTRAINT "approval_batch_items_removal_check" CHECK (((("removed_at" IS NULL) AND ("removed_by" IS NULL)) OR (("removed_at" IS NOT NULL) AND ("removed_by" IS NOT NULL) AND ("director_status" = 'pending'::"text")))),
    CONSTRAINT "approval_batch_items_review_sequence_check" CHECK ((("review_sequence" >= 1) AND ("previous_item_id" IS DISTINCT FROM "id"))),
    CONSTRAINT "approval_batch_items_status_check" CHECK (("director_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."approval_batch_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."approval_batch_items"."finance_reviewed_by" IS 'Compatibilidad historica: en el modelo 023 identifica a quien preparo/incorporo la solicitud al corte; no representa una aprobacion humana individual.';



COMMENT ON COLUMN "public"."approval_batch_items"."finance_reviewed_at" IS 'Compatibilidad historica: fecha de preparacion/incorporacion operativa al corte.';



COMMENT ON COLUMN "public"."approval_batch_items"."previous_item_id" IS 'Revision previa de la misma solicitud. Las decisiones historicas nunca se sobrescriben.';



COMMENT ON COLUMN "public"."approval_batch_items"."review_sequence" IS 'Numero secuencial de revision por Direccion para la solicitud.';



