    "extraction_id" "uuid" NOT NULL,
    "bank_name" "text" NOT NULL,
    "fingerprint_version" integer DEFAULT 1 NOT NULL,
    "operation_fingerprint" "text" NOT NULL,
    "bank_unique_folio" "text" NOT NULL,
    "application_date" "date" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "currency" "text" NOT NULL,
    "source_account_hash" "text" NOT NULL,
    "source_account_last4" "text" NOT NULL,
    "destination_account_hash" "text",
    "destination_account_last4" "text",
    "beneficiary_name" "text",
    "payment_reason" "text",
    "status" "text" DEFAULT 'available'::"text" NOT NULL,
    "reviewed_by" "uuid" NOT NULL,
    "reviewed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bank_payment_operations_amount_check" CHECK ((("amount_minor" >= 1) AND ("amount_minor" <= '9007199254740991'::bigint))),
    CONSTRAINT "bank_payment_operations_bank_check" CHECK (("upper"("btrim"("bank_name")) = 'BBVA'::"text")),
    CONSTRAINT "bank_payment_operations_bank_fields_check" CHECK (((("char_length"("bank_name") >= 1) AND ("char_length"("bank_name") <= 80)) AND ("bank_name" !~ '[[:cntrl:]]'::"text") AND (("char_length"("bank_unique_folio") >= 8) AND ("char_length"("bank_unique_folio") <= 120)) AND ("bank_unique_folio" = "upper"("bank_unique_folio")) AND ("bank_unique_folio" ~ '^[A-Z0-9-]+$'::"text") AND ("bank_unique_folio" !~ '[[:cntrl:]]'::"text"))),
    CONSTRAINT "bank_payment_operations_currency_check" CHECK ((("currency" = "upper"("currency")) AND ("currency" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "bank_payment_operations_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "bank_payment_operations_fingerprint_version_check" CHECK (("fingerprint_version" = 1)),
    CONSTRAINT "bank_payment_operations_folio_check" CHECK (("bank_unique_folio" = "btrim"("bank_unique_folio"))),
    CONSTRAINT "bank_payment_operations_free_text_check" CHECK (((("beneficiary_name" IS NULL) OR (("char_length"("beneficiary_name") <= 180) AND ("beneficiary_name" !~ '[[:cntrl:]]'::"text") AND ("beneficiary_name" !~ '([0-9][^[:alnum:]]*){9,19}[0-9]'::"text") AND ("beneficiary_name" !~* '[A-Z0-9]{24,}'::"text"))) AND (("payment_reason" IS NULL) OR (("char_length"("payment_reason") <= 500) AND ("payment_reason" !~ '[[:cntrl:]]'::"text") AND ("payment_reason" !~ '([0-9][^[:alnum:]]*){9,19}[0-9]'::"text") AND ("payment_reason" !~* '[A-Z0-9]{24,}'::"text"))))),
    CONSTRAINT "bank_payment_operations_hash_check" CHECK ((("source_account_hash" ~ '^[0-9a-f]{64}$'::"text") AND (("destination_account_hash" IS NULL) OR ("destination_account_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "bank_payment_operations_last4_check" CHECK (((("source_account_last4" IS NULL) OR ("source_account_last4" ~ '^[A-Z0-9]{1,4}$'::"text")) AND (("destination_account_last4" IS NULL) OR ("destination_account_last4" ~ '^[A-Z0-9]{1,4}$'::"text")))),
    CONSTRAINT "bank_payment_operations_status_check" CHECK (("status" = ANY (ARRAY['available'::"text", 'reserved'::"text", 'cancelled'::"text"])))
);


