    "token_hash" "text" NOT NULL,
    "token_prefix" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "expires_at" timestamp with time zone,
    "max_submissions_per_day" integer DEFAULT 20 NOT NULL,
    "allowed_file_types" "text"[] DEFAULT ARRAY['application/pdf'::"text", 'application/xml'::"text", 'text/xml'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"] NOT NULL,
    "max_file_mb" integer DEFAULT 10 NOT NULL,
    "created_by" "uuid" NOT NULL,
