    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revoked_by" "uuid",
    "revoked_at" timestamp with time zone,
    "regenerated_from_id" "uuid",
    CONSTRAINT "intake_links_allowed_file_types_check" CHECK ((("cardinality"("allowed_file_types") > 0) AND ("array_position"("allowed_file_types", NULL::"text") IS NULL) AND ("allowed_file_types" <@ ARRAY['application/pdf'::"text", 'application/xml'::"text", 'text/xml'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "intake_links_file_limit_check" CHECK ((("max_file_mb" >= 1) AND ("max_file_mb" <= 10))),
    CONSTRAINT "intake_links_label_check" CHECK ((NULLIF("btrim"("label"), ''::"text") IS NOT NULL)),
    CONSTRAINT "intake_links_regeneration_check" CHECK ((("regenerated_from_id" IS NULL) OR ("regenerated_from_id" <> "id"))),
    CONSTRAINT "intake_links_revocation_check" CHECK (((("status" = 'revoked'::"text") AND ("revoked_by" IS NOT NULL) AND ("revoked_at" IS NOT NULL)) OR (("status" <> 'revoked'::"text") AND ("revoked_by" IS NULL) AND ("revoked_at" IS NULL)))),
    CONSTRAINT "intake_links_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'revoked'::"text", 'expired'::"text"]))),
    CONSTRAINT "intake_links_submission_limit_check" CHECK ((("max_submissions_per_day" >= 1) AND ("max_submissions_per_day" <= 10000))),
    CONSTRAINT "intake_links_token_hash_check" CHECK (("token_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "intake_links_token_prefix_check" CHECK (("token_prefix" ~ '^[A-Za-z0-9_-]{6,16}$'::"text"))
);


ALTER TABLE "public"."intake_links" OWNER TO "postgres";


