    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "audience" "text" DEFAULT 'internal'::"text" NOT NULL,
    "event_version" smallint DEFAULT 1 NOT NULL,
    "rollout_id" "text",
