    CONSTRAINT "notification_events_channel_check" CHECK (("channel" = 'email'::"text")),
    CONSTRAINT "notification_events_event_version_check" CHECK (("event_version" > 0)),
    CONSTRAINT "notification_events_lane_contract_check" CHECK (((("audience" = 'internal'::"text") AND ("rollout_id" IS NULL) AND ("external_subject_type" IS NULL) AND ("external_subject_id" IS NULL) AND ("terminal_reason" IS NULL) AND ("status" <> 'no_recipient'::"text")) OR (("audience" = 'external'::"text") AND ("rollout_id" IS NOT NULL) AND ("external_subject_type" = 'payment_intake'::"text") AND ("external_subject_id" IS NOT NULL) AND ("channel" = 'email'::"text") AND ("recipient_type" = 'external_provider'::"text") AND ("recipient_profile_id" IS NULL) AND ("recipient_role" IS NULL) AND ("source_table" = 'payment_intake_events'::"text") AND ("source_id" IS NOT NULL) AND "public"."notification_external_event_type_allowed"("event_type") AND ("event_version" = 1) AND ("max_attempts" = 3) AND ("subject" IS NULL) AND "public"."notification_external_idempotency_valid"("event_type", "external_subject_id", "event_version", "idempotency_key") AND "public"."notification_external_payload_valid"("event_type", "event_version", "payload") AND ((("status" = 'no_recipient'::"text") AND ("terminal_reason" = 'no_recipient'::"text") AND ("recipient_email" IS NULL) AND ("next_attempt_at" IS NULL) AND ("attempt_count" = 0) AND ("locked_at" IS NULL) AND ("locked_by" IS NULL)) OR (("status" <> 'no_recipient'::"text") AND ("terminal_reason" IS NULL) AND ("recipient_email" = "lower"("btrim"("recipient_email"))) AND ("recipient_email" ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::"text")))))),
    CONSTRAINT "notification_events_max_attempts_check" CHECK (("max_attempts" > 0)),
    CONSTRAINT "notification_events_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "notification_events_recipient_type_check" CHECK (("recipient_type" = ANY (ARRAY['usuario_solicitante'::"text", 'administrador_sistema'::"text", 'external_provider'::"text", 'proveedor'::"text"]))),
    CONSTRAINT "notification_events_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'sent'::"text", 'failed'::"text", 'dead_letter'::"text", 'cancelled'::"text", 'no_recipient'::"text"])))
);


