COMMENT ON TABLE "public"."payment_intake" IS 'Provider-declared intake pending internal triage; it is not a payment_request and never enters approval batches directly.';



COMMENT ON COLUMN "public"."payment_intake"."bank_clabe" IS 'Provider-declared sensitive value. It is not an operational payment destination until internally validated.';



COMMENT ON COLUMN "public"."payment_intake"."expected_file_count" IS 'Known by the public submission handler before intake creation; populated only by a future authorized producer.';



COMMENT ON COLUMN "public"."payment_intake"."submission_completed_at" IS 'Future atomic submission completion marker. Migration 041 performs no historical backfill; current upload issues are terminal for the intake until a separately authorized correction flow exists.';



CREATE TABLE IF NOT EXISTS "public"."payment_intake_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "payment_intake_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "actor_profile_id" "uuid",
    "actor_type" "text" NOT NULL,
    "from_status" "text",
    "to_status" "text",
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_message" "text",
    "external_field_codes" "text"[],
    "external_contract_version" smallint,
    CONSTRAINT "payment_intake_events_actor_check" CHECK (((("actor_type" = ANY (ARRAY['public_provider'::"text", 'system'::"text"])) AND ("actor_profile_id" IS NULL)) OR (("actor_type" = ANY (ARRAY['finance'::"text", 'admin'::"text", 'sysadmin'::"text"])) AND ("actor_profile_id" IS NOT NULL)))),
    CONSTRAINT "payment_intake_events_actor_type_check" CHECK (("actor_type" = ANY (ARRAY['public_provider'::"text", 'finance'::"text", 'admin'::"text", 'sysadmin'::"text", 'system'::"text"]))),
    CONSTRAINT "payment_intake_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['received'::"text", 'submission_completed'::"text", 'status_changed'::"text", 'file_uploaded'::"text", 'file_reviewed'::"text", 'provider_matched'::"text", 'correction_requested'::"text", 'rejected'::"text", 'converted'::"text", 'internal_note'::"text"]))),
    CONSTRAINT "payment_intake_events_external_contract_check" CHECK (((("external_message" IS NULL) AND ("external_field_codes" IS NULL) AND ("external_contract_version" IS NULL)) OR (("event_type" = ANY (ARRAY['correction_requested'::"text", 'rejected'::"text"])) AND ("external_contract_version" = 1) AND "public"."notification_external_message_valid"("external_message") AND (("notes" IS NULL) OR ("lower"("btrim"("notes")) IS DISTINCT FROM "lower"("btrim"("external_message")))) AND ((("event_type" = 'correction_requested'::"text") AND "public"."notification_external_field_codes_valid"("external_field_codes")) OR (("event_type" = 'rejected'::"text") AND (("external_field_codes" IS NULL) OR ("cardinality"("external_field_codes") = 0))))))),
    CONSTRAINT "payment_intake_events_from_status_check" CHECK ((("from_status" IS NULL) OR ("from_status" = ANY (ARRAY['received'::"text", 'in_review'::"text", 'needs_correction'::"text", 'rejected'::"text", 'converted'::"text", 'cancelled'::"text"])))),
    CONSTRAINT "payment_intake_events_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "payment_intake_events_metadata_sensitive_keys_check" CHECK ((NOT ("metadata" ?| ARRAY['bank_clabe'::"text", 'clabe'::"text", 'captcha'::"text", 'captcha_token'::"text", 'public_token'::"text", 'token'::"text", 'raw_payload'::"text", 'client_ip'::"text", 'user_agent'::"text", 'cookies'::"text", 'headers'::"text", 'secrets'::"text"]))),
    CONSTRAINT "payment_intake_events_provider_matched_internal_check" CHECK ((("event_type" <> 'provider_matched'::"text") OR (("external_message" IS NULL) AND ("external_field_codes" IS NULL) AND ("external_contract_version" IS NULL)))),
    CONSTRAINT "payment_intake_events_to_status_check" CHECK ((("to_status" IS NULL) OR ("to_status" = ANY (ARRAY['received'::"text", 'in_review'::"text", 'needs_correction'::"text", 'rejected'::"text", 'converted'::"text", 'cancelled'::"text"]))))
);


