    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "alias" "text" NOT NULL,
    "nombre_completo" "text",
    "metodo_pago" "public"."metodo_pago_enum",
    "tipo_cuenta" "text",
    "clabe" "text",
    "cuenta_bancaria" "text",
    "banco" "text",
    "es_personal_eventual" boolean DEFAULT false,
    "csf_url" "text",
    "acta_constitutiva_url" "text",
    "identificacion_url" "text",
    "comprobante_domicilio_url" "text",
    "estado_cuenta_url" "text",
    "creado_por" "text",
    "creado_el" timestamp with time zone,
    "airtable_alias" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "rfc" "text",
    "email" "text",
    "telefono" "text",
    "tipo_proveedor" "text",
    "notas" "text",
    "activo" boolean DEFAULT true,
    "destination_type" "text",
    "convenio_number" "text",
    "beneficiary_name" "text",
    "csf_file_path" "text",
    "csf_uploaded_at" timestamp with time zone,
    "csf_uploaded_by" "uuid",
    CONSTRAINT "proveedores_destination_type_check" CHECK ((("destination_type" IS NULL) OR ("destination_type" = ANY (ARRAY['clabe'::"text", 'cuenta'::"text", 'convenio'::"text"])))),
    CONSTRAINT "proveedores_tipo_cuenta_check" CHECK (("tipo_cuenta" = ANY (ARRAY['CLABE'::"text", 'Cuenta'::"text"])))
);


